+  <script>
+    (() => {
+      const viewport = document.getElementById('cafe-map');
+      const needsFallback = !CSS.supports('scroll-axis-lock', 'none');
+      let pointer = null;
+
+      function recenter() {
+        viewport.scrollLeft = (viewport.scrollWidth - viewport.clientWidth) / 2;
+        viewport.scrollTop = (viewport.scrollHeight - viewport.clientHeight) / 2;
+      }
+
+      recenter();
+      document.getElementById('map-reset').addEventListener('click', recenter);
+      const directions = { left: [-180, 0], right: [180, 0], up: [0, -180], down: [0, 180] };
+      document.querySelectorAll('[data-pan]').forEach((button) => {
+        button.addEventListener('click', () => {
+          const [left, top] = directions[button.dataset.pan];
+          viewport.scrollBy({ left, top, behavior: 'instant' });
+        });
+      });
+
+      if (needsFallback) {
+        viewport.classList.add('has-pan-fallback');
+        viewport.addEventListener('wheel', (event) => {
+          if (event.ctrlKey) return; // Preserve browser and trackpad pinch zoom.
+          event.preventDefault();
+          const unitX = event.deltaMode === 1 ? 16 : event.deltaMode === 2 ? viewport.clientWidth : 1;
+          const unitY = event.deltaMode === 1 ? 16 : event.deltaMode === 2 ? viewport.clientHeight : 1;
+          viewport.scrollLeft += (event.shiftKey && !event.deltaX ? event.deltaY : event.deltaX) * unitX;
+          viewport.scrollTop += (event.shiftKey && !event.deltaX ? 0 : event.deltaY) * unitY;
+        }, { passive: false });
+      }
+
+      viewport.addEventListener('pointerdown', (event) => {
+        // Touch stays native where unrestricted scrolling is supported.
+        if (!needsFallback && event.pointerType !== 'mouse') return;
+        if (!event.isPrimary || event.button !== 0) return;
+        const bounds = viewport.getBoundingClientRect();
+        const x = event.clientX - bounds.left - viewport.clientLeft;
+        const y = event.clientY - bounds.top - viewport.clientTop;
+        if (x < 0 || y < 0 || x >= viewport.clientWidth || y >= viewport.clientHeight) return;
+        viewport.focus({ preventScroll: true });
+        pointer = { id: event.pointerId, x: event.clientX, y: event.clientY };
+        viewport.setPointerCapture(event.pointerId);
+        viewport.classList.add('is-panning');
+        event.preventDefault();
+      });
+
+      viewport.addEventListener('pointermove', (event) => {
+        if (!pointer || pointer.id !== event.pointerId) return;
+        viewport.scrollLeft -= event.clientX - pointer.x;
+        viewport.scrollTop -= event.clientY - pointer.y;
+        pointer.x = event.clientX;
+        pointer.y = event.clientY;
+      });
+
+      function endPan(event) {
+        if (!pointer || pointer.id !== event.pointerId) return;
+        pointer = null;
+        viewport.classList.remove('is-panning');
