+
+    function resetMap() {
+      map.scrollLeft = (map.scrollWidth - map.clientWidth) / 2;
+      map.scrollTop = (map.scrollHeight - map.clientHeight) / 2;
+    }
+
+    map.addEventListener('pointerdown', (event) => {
+      if (!event.isPrimary || event.button !== 0 || gesture) return;
+      dragged = false;
+      gesture = {
+        id: event.pointerId, x: event.clientX, y: event.clientY,
+        left: map.scrollLeft, top: map.scrollTop, target: event.target
+      };
+      event.target.setPointerCapture(event.pointerId);
+      map.classList.add('is-dragging');
+    });
+
+    map.addEventListener('pointermove', (event) => {
+      if (!gesture || event.pointerId !== gesture.id) return;
+      const dx = event.clientX - gesture.x;
+      const dy = event.clientY - gesture.y;
+      if (Math.hypot(dx, dy) > 4) dragged = true;
+      // Always apply both coordinates; never choose or lock a gesture axis.
+      map.scrollLeft = gesture.left - dx;
+      map.scrollTop = gesture.top - dy;
+    });
+
+    function endGesture(event) {
+      if (!gesture || event.pointerId !== gesture.id) return;
+      const { target, id } = gesture;
+      gesture = null;
+      map.classList.remove('is-dragging');
+      if (target.hasPointerCapture(id)) target.releasePointerCapture(id);
+    }
+    map.addEventListener('pointerup', endGesture);
+    map.addEventListener('pointercancel', endGesture);
+    map.addEventListener('lostpointercapture', endGesture);
