+      if (dragged) {
+        event.preventDefault();
+        event.stopPropagation();
+        dragged = false;
+      }
+    }, true);
+
+    map.addEventListener('wheel', (event) => {
+      if (event.ctrlKey) return; // Preserve browser pinch-to-zoom.
+      event.preventDefault();
+      const unit = event.deltaMode === 1 ? 16 : event.deltaMode === 2 ? map.clientHeight : 1;
+      map.scrollLeft += (event.shiftKey && !event.deltaX ? event.deltaY : event.deltaX) * unit;
+      map.scrollTop += (event.shiftKey && !event.deltaX ? 0 : event.deltaY) * unit;
