+// One submission path for visitors and declarative WebMCP tool invocations.
+const form = document.getElementById('coffee-finder-form');
+const status = document.getElementById('finder-status');
+const matches = document.getElementById('coffee-matches');
+
+const coffees = [
+  { name: 'Maple Oat Latte', flavor: 'sweet', temperature: 'hot', decaf: true,
+    description: 'Creamy oat milk with a hint of Vermont maple syrup.' },
+  { name: 'Dark Roast Espresso', flavor: 'bold', temperature: 'hot', decaf: true,
+    description: 'Bold, smoky, and perfect for a morning boost.' },
+  { name: 'Cold Brew', flavor: 'smooth', temperature: 'iced', decaf: false,
+    description: 'Steeped for 18 hours for maximum smoothness.' },
+  { name: 'Iced Maple Oat Latte', flavor: 'sweet', temperature: 'iced', decaf: true,
+    description: 'Our maple and oat milk favorite, poured over ice.' },
+  { name: 'Iced Americano', flavor: 'bold', temperature: 'iced', decaf: true,
+    description: 'Rich espresso with chilled water for a crisp, bold cup.' },
+  { name: 'Caffè Latte', flavor: 'smooth', temperature: 'hot', decaf: true,
+    description: 'Balanced espresso and silky steamed milk, with a soft finish.' },
+];
+
+form.addEventListener('submit', (event) => {
+  event.preventDefault();
+  const reply = (result) => {
+    if (event.agentInvoked && typeof event.respondWith === 'function') {
+      event.respondWith(Promise.resolve(result));
+    }
+  };
+
+  if (!form.reportValidity()) {
+    reply({ success: false, message: 'Choose a valid option for each coffee preference.' });
+    return;
+  }
+
+  const data = new FormData(form);
+  const preferences = Object.fromEntries(data);
+  const allowed = {
+    flavor: ['any', 'sweet', 'bold', 'smooth'],
+    temperature: ['any', 'hot', 'iced'],
+    caffeine: ['any', 'regular', 'decaf'],
+  };
+  if (Object.entries(allowed).some(([key, values]) => !values.includes(preferences[key]))) {
+    matches.replaceChildren();
+    status.textContent = 'Please choose one of the listed options for each preference.';
+    reply({ success: false, message: status.textContent });
+    return;
+  }
+
+  const recommendations = coffees
+    .filter((coffee) => (preferences.flavor === 'any' || coffee.flavor === preferences.flavor)
+      && (preferences.temperature === 'any' || coffee.temperature === preferences.temperature)
+      && (preferences.caffeine !== 'decaf' || coffee.decaf))
+    .map((coffee) => ({
+      name: coffee.name,
+      description: coffee.description,
+      temperature: coffee.temperature,
+      caffeine: preferences.caffeine === 'decaf' ? 'decaf' : 'regular',
+    }));
+
+  matches.replaceChildren(...recommendations.map((coffee) => {
+    const item = document.createElement('li');
+    item.className = 'coffee-match';
+    const title = document.createElement('h4');
+    title.textContent = coffee.name;
+    const description = document.createElement('p');
+    description.textContent = coffee.description;
+    const details = document.createElement('p');
+    details.className = 'coffee-meta';
+    details.textContent = `${coffee.temperature === 'hot' ? 'Served hot' : 'Served over ice'} · ${coffee.caffeine === 'decaf' ? 'Made with decaf espresso' : 'Regular caffeine'}`;
+    item.append(title, description, details);
+    return item;
+  }));
+
+  const message = recommendations.length
+    ? `Found ${recommendations.length} ${recommendations.length === 1 ? 'coffee' : 'coffees'} for you. Your next favorite is below.`
+    : 'No exact match this time. Try a different flavor, temperature, or caffeine preference.';
+  status.textContent = message;
+  reply({ success: true, preferences, recommendations, message });
+});
