+(() => {
+  'use strict';
+
+  const form = document.getElementById('coffee-finder-form');
+  const result = document.getElementById('coffee-result');
+  const coffees = [
+    {
+      name: 'Maple Oat Latte', temperature: 'hot', flavor: 'sweet', milk: 'oat',
+      description: 'Creamy oat milk with a hint of Vermont maple syrup.',
+      menuUrl: '/menu/seasonal'
+    },
+    {
+      name: 'Dark Roast Espresso', temperature: 'hot', flavor: 'bold', milk: 'none',
+      description: 'Bold, smoky, and perfect for a morning boost.',
+      menuUrl: '/menu/espresso'
+    },
+    {
+      name: 'Cold Brew', temperature: 'iced', flavor: 'smooth', milk: 'none',
+      description: 'Steeped for 18 hours for maximum smoothness.',
+      menuUrl: '/menu/cold-brew'
+    }
+  ];
+  const allowed = {
+    temperature: ['any', 'hot', 'iced'],
+    flavor: ['any', 'bold', 'smooth', 'sweet'],
+    milk: ['any', 'oat', 'none']
+  };
+  const preferenceLabels = {
+    temperature: { hot: 'hot', iced: 'iced' },
+    flavor: { bold: 'bold flavor', smooth: 'smooth flavor', sweet: 'a little sweetness' },
+    milk: { oat: 'oat milk', none: 'no milk' }
+  };
+
+  function findCoffee(preferences) {
+    const keys = Object.keys(allowed);
+    if (keys.some(key => !allowed[key].includes(preferences[key]))) {
+      return { status: 'error', message: 'Please choose a valid option for each preference.' };
+    }
+
+    // Milk takes priority, followed by temperature, then flavor. Stable menu order breaks ties.
+    const weights = { milk: 4, temperature: 2, flavor: 1 };
+    const ranked = coffees.map(coffee => ({
+      coffee,
+      score: keys.reduce((score, key) => score +
+        (preferences[key] !== 'any' && preferences[key] === coffee[key] ? weights[key] : 0), 0)
+    })).sort((a, b) => b.score - a.score);
+    const coffee = ranked[0].coffee;
+    const selected = keys.filter(key => preferences[key] !== 'any');
+    const matched = selected.filter(key => preferences[key] === coffee[key]);
+    const unmatched = selected.filter(key => preferences[key] !== coffee[key]);
+
+    return {
+      status: 'success',
+      recommendation: { ...coffee },
+      preferences,
+      exactMatch: unmatched.length === 0,
+      matchedPreferences: matched.map(key => preferenceLabels[key][preferences[key]]),
+      unmatchedPreferences: unmatched.map(key => preferenceLabels[key][preferences[key]]),
+      message: selected.length === 0 ? 'An easy place to start: our seasonal favorite.' :
+        unmatched.length === 0 ? 'A match for all your preferences.' :
+          'Our closest match. No coffee on this menu matches every preference.'
+    };
+  }
+
+  function showResult(response) {
+    result.replaceChildren();
+    result.className = 'coffee-result';
+    if (response.status === 'error') {
+      result.textContent = response.message;
+      return;
+    }
+    const eyebrow = document.createElement('p');
+    eyebrow.className = 'eyebrow';
+    eyebrow.textContent = response.exactMatch ? 'Your coffee match' : 'Your closest match';
+    const title = document.createElement('h3');
+    title.textContent = response.recommendation.name;
+    const description = document.createElement('p');
+    description.textContent = response.recommendation.description;
+    const note = document.createElement('p');
+    note.className = 'match-note';
+    note.textContent = response.message;
+    if (response.unmatchedPreferences.length) {
+      note.textContent += ` Doesn’t match: ${response.unmatchedPreferences.join(', ')}.`;
+    }
+    const link = document.createElement('a');
+    link.className = 'btn';
+    link.href = response.recommendation.menuUrl;
+    link.textContent = 'View coffee details';
+    result.append(eyebrow, title, description, note, link);
+  }
+
+  form.addEventListener('submit', event => {
+    event.preventDefault();
+    const response = findCoffee(Object.fromEntries(new FormData(form)));
+    showResult(response);
+    // The declarative browser tool and normal form submission share this handler.
+    if (event.agentInvoked && typeof event.respondWith === 'function') {
+      event.respondWith(Promise.resolve(response));
+    }
+  });
+
+  form.addEventListener('reset', () => {
+    result.replaceChildren();
+    result.className = '';
+  });
+  form.addEventListener('input', () => {
+    result.replaceChildren();
+    result.className = '';
+  });
+})();
