diff --git a/src/hooks/useAuthForm.ts b/src/hooks/useAuthForm.ts
new file mode 100644
index 0000000..d8fe85a
--- /dev/null
+++ b/src/hooks/useAuthForm.ts
@@ -0,0 +1,68 @@
+import { useCallback, useEffect, useRef, useState, type FormEvent } from 'react';
+import { isCredentials, submitAuth, type AuthAction, type AuthResult } from '../lib/auth';
+import { registerAgentTool } from '../lib/webmcp';
+
+export function useAuthForm(action: AuthAction) {
+  const [username, setUsername] = useState('');
+  const [password, setPassword] = useState('');
+  const [error, setError] = useState<string | null>(null);
+  const [success, setSuccess] = useState<string | null>(null);
+  const [loading, setLoading] = useState(false);
+  const pending = useRef(false);
+
+  const submit = useCallback(async (input: unknown): Promise<AuthResult> => {
+    // A ref also protects against calls arriving before React renders loading.
+    if (pending.current) return { ok: false, message: 'A submission is already in progress.' };
+    setError(null);
+    setSuccess(null);
+    if (isCredentials(input)) {
+      setUsername(input.username);
+      setPassword(input.password);
+    }
+    pending.current = true;
+    setLoading(true);
+    try {
+      const result = await submitAuth(action, input);
+      if (result.ok) {
+        setSuccess(result.message);
+        if (action === 'register') {
+          setUsername('');
+          setPassword('');
+        }
+      } else {
+        setError(result.message);
+      }
+      return result;
+    } finally {
+      pending.current = false;
+      setLoading(false);
+    }
+  }, [action]);
+
+  useEffect(() => registerAgentTool({
+    name: action === 'login' ? 'sign_in' : 'sign_up',
+    description: action === 'login'
+      ? 'Sign in to The DevTools Times using the sign-in form. Submits credentials and returns the login result.'
+      : 'Create a DevTools Times account using the sign-up form. Submits registration and returns the result. On success, sign in separately. Passwords must be at least 8 characters and contain a number.',
+    inputSchema: {
+      type: 'object',
+      properties: {
+        username: { type: 'string', minLength: 1, description: 'Account username.' },
+        password: { type: 'string', minLength: 1, description: 'Account password.' },
+      },
+      required: ['username', 'password'],
+      additionalProperties: false,
+    },
+    execute: async (input) => {
+      const result = await submit(input);
+      return { content: [{ type: 'text', text: result.message }], isError: !result.ok };
+    },
+  }), [action, submit]);
+
+  const handleSubmit = async (event: FormEvent) => {
+    event.preventDefault();
+    await submit({ username, password });
+  };
+
+  return { username, setUsername, password, setPassword, error, success, loading, handleSubmit };
+}
diff --git a/src/lib/auth.ts b/src/lib/auth.ts
new file mode 100644
index 0000000..17b6911
--- /dev/null
+++ b/src/lib/auth.ts
@@ -0,0 +1,47 @@
+export type AuthAction = 'login' | 'register';
+export interface Credentials {
+  username: string;
+  password: string;
+}
+export interface AuthResult {
+  ok: boolean;
+  message: string;
+}
+
+export const authMessages = {
+  login: { success: 'Login successful!', failure: 'Login failed' },
+  register: {
+    success: 'User registered successfully! You can now sign in.',
+    failure: 'Registration failed',
+  },
+};
+
+export function isCredentials(input: unknown): input is Credentials {
+  if (!input || typeof input !== 'object') return false;
+  const value = input as Record<string, unknown>;
+  return typeof value.username === 'string' && value.username.length > 0 &&
+    typeof value.password === 'string' && value.password.length > 0;
+}
+
+// Both human submissions and agent tools use this request and validation path.
+export async function submitAuth(action: AuthAction, input: unknown): Promise<AuthResult> {
+  if (!isCredentials(input)) {
+    return { ok: false, message: 'Username and password are required.' };
+  }
+  try {
+    const response = await fetch(
+      `https://us-central1-web-devrel-apps.cloudfunctions.net/times_cdn/api/${action}`,
+      {
+        method: 'POST',
+        headers: { 'Content-Type': 'application/json' },
+        body: JSON.stringify({ username: input.username, password: input.password }),
+      },
+    );
+    const data = await response.json();
+    return response.ok
+      ? { ok: true, message: authMessages[action].success }
+      : { ok: false, message: `${authMessages[action].failure}: ${data?.error || 'Unknown error'}` };
+  } catch {
+    return { ok: false, message: 'An unexpected error occurred. Please try again later.' };
+  }
+}
