+export interface AgentTool {
+  name: string;
+  description: string;
+  inputSchema: Record<string, unknown>;
+  execute: (input: unknown) => Promise<{
+    content: { type: 'text'; text: string }[];
+    isError?: boolean;
+  }>;
+}
+
+// Local types keep the experimental API optional without changing DOM globals.
+export interface ModelContext {
+  registerTool: (tool: AgentTool, options?: { signal: AbortSignal }) => void | Promise<void>;
+  unregisterTool?: (name: string) => void;
+}
+
+export function registerAgentTool(tool: AgentTool): () => void {
+  if (typeof document === 'undefined' || typeof navigator === 'undefined') return () => {};
+  const current = (document as Document & { modelContext?: ModelContext }).modelContext;
+  const legacy = (navigator as Navigator & { modelContext?: ModelContext }).modelContext;
+  const context = current ?? legacy;
+  if (!context) return () => {};
+
+  const controller = new AbortController();
+  try {
+    const registration = current
+      ? context.registerTool(tool, { signal: controller.signal })
+      : context.registerTool(tool);
+    Promise.resolve(registration).catch(() => {
+      // Registration failure must not prevent normal form use.
+      if (!controller.signal.aborted) console.warn(`Could not register agent tool: ${tool.name}`);
+    });
+  } catch {
+    console.warn(`Could not register agent tool: ${tool.name}`);
+  }
+  return () => {
+    controller.abort();
+    if (!current) context.unregisterTool?.(tool.name);
+  };
+}
