+import assert from 'node:assert/strict';
+import { afterEach, test } from 'node:test';
+import { submitAuth } from '../src/lib/auth.ts';
+import { registerAgentTool } from '../src/lib/webmcp.ts';
+
+const originalFetch = globalThis.fetch;
+const originalNavigator = Object.getOwnPropertyDescriptor(globalThis, 'navigator');
+afterEach(() => {
+  globalThis.fetch = originalFetch;
+  delete globalThis.document;
+  Object.defineProperty(globalThis, 'navigator', originalNavigator);
+});
+
+for (const [action, message] of [
+  ['login', 'Login successful!'],
+  ['register', 'User registered successfully! You can now sign in.'],
+]) {
+  test(`${action} submits credentials and returns only the outcome`, async () => {
+    globalThis.fetch = async (url, options) => {
+      assert.ok(url.endsWith(`/api/${action}`));
+      assert.equal(options.method, 'POST');
+      assert.deepEqual(JSON.parse(options.body), { username: 'reader', password: 'password1' });
+      return Response.json({ token: 'secret-token' });
+    };
+    assert.deepEqual(await submitAuth(action, { username: 'reader', password: 'password1' }), {
+      ok: true, message,
+    });
+  });
+}
+
+test('invalid tool arguments never send a request', async () => {
+  globalThis.fetch = () => { throw new Error('Must not fetch'); };
+  for (const input of [null, {}, { username: 123, password: 'x' }, { username: 'reader', password: '' }]) {
+    assert.deepEqual(await submitAuth('login', input), {
+      ok: false, message: 'Username and password are required.',
+    });
+  }
+});
+
+test('API errors preserve the form error message', async () => {
+  globalThis.fetch = async () => Response.json({ error: 'APP_ERR_1001' }, { status: 400 });
+  assert.deepEqual(await submitAuth('register', { username: 'reader', password: 'x' }), {
+    ok: false, message: 'Registration failed: APP_ERR_1001',
+  });
+});
+
+test('network failures and malformed responses return actionable errors', async () => {
+  for (const fetcher of [
+    async () => { throw new Error('offline'); },
+    async () => new Response('not JSON'),
+  ]) {
+    globalThis.fetch = fetcher;
+    assert.deepEqual(await submitAuth('login', { username: 'reader', password: 'x' }), {
+      ok: false, message: 'An unexpected error occurred. Please try again later.',
+    });
+  }
+});
+
+const tool = { name: 'sign_in', description: 'Sign in', inputSchema: {}, execute: async () => ({ content: [] }) };
+
+test('unsupported browsers and server environments are no-ops', () => {
+  registerAgentTool(tool)();
+  globalThis.document = {};
+  registerAgentTool(tool)();
+});
+
+test('current API registers with an abort signal and cleans up on unmount', () => {
+  let signal;
+  globalThis.document = { modelContext: {
+    registerTool(received, options) {
+      assert.equal(received, tool);
+      signal = options.signal;
+    },
+  } };
+  const cleanup = registerAgentTool(tool);
+  assert.equal(signal.aborted, false);
+  cleanup();
+  assert.equal(signal.aborted, true);
+});
+
+test('legacy API unregisters only the owned tool on unmount', () => {
+  const calls = [];
+  globalThis.document = {};
+  Object.defineProperty(globalThis, 'navigator', { configurable: true, value: { modelContext: {
+    registerTool(received) { calls.push(received.name); },
+    unregisterTool(name) { calls.push(`remove:${name}`); },
+  } } });
+  const cleanup = registerAgentTool(tool);
+  cleanup();
+  assert.deepEqual(calls, ['sign_in', 'remove:sign_in']);
+});

