+import { x25519 } from '@noble/curves/ed25519.js';
+import { ml_kem768 } from '@noble/post-quantum/ml-kem.js';
+import { ml_kem768_x25519 } from '@noble/post-quantum/hybrid.js';
+
+const encoder = new TextEncoder();
+export const protectionNames = { classical: 'Standard · X25519', hybrid: 'Hybrid · X25519 + ML-KEM-768', pq: 'Post-quantum · ML-KEM-768' };
+const schemes = { hybrid: ml_kem768_x25519, pq: ml_kem768 };
+const b64 = bytes => btoa(String.fromCharCode(...bytes));
+const bytes = value => Uint8Array.from(atob(value), c => c.charCodeAt(0));
+function scheme(mode) {
+  if (!Object.hasOwn(protectionNames, mode)) throw new Error('Unknown protection mode');
+  return schemes[mode];
+}
+export function createRecipient(mode) {
+  const kem = scheme(mode);
+  if (kem) return { mode, ...kem.keygen() };
+  const secretKey = x25519.utils.randomSecretKey();
+  return { mode, secretKey, publicKey: x25519.getPublicKey(secretKey) };
+}
+function header(envelope) {
+  // Bind the algorithm, recipient, encapsulation, KDF salt, and nonce to the GCM tag.
+  return encoder.encode(JSON.stringify({ version: envelope.version, mode: envelope.mode, recipient: envelope.recipient, encapsulation: envelope.encapsulation, salt: envelope.salt, iv: envelope.iv }));
+}
+async function aesKey(secret, salt, context, usage) {
+  const material = await crypto.subtle.importKey('raw', secret, 'HKDF', false, ['deriveKey']);
+  const contextHash = await crypto.subtle.digest('SHA-256', context);
+  return crypto.subtle.deriveKey({ name: 'HKDF', hash: 'SHA-256', salt, info: contextHash }, material, { name: 'AES-GCM', length: 256 }, false, [usage]);
+}
+export async function encryptNote(note, recipient) {
+  if (!note.trim() || note.length > 500) throw new Error('Enter a note between 1 and 500 characters.');
+  const kem = scheme(recipient.mode);
+  let secret, encapsulation;
+  if (kem) {
+    const result = kem.encapsulate(recipient.publicKey);
+    secret = result.sharedSecret;
+    encapsulation = result.cipherText;
+  } else {
+    const ephemeral = x25519.utils.randomSecretKey();
+    try {
+      encapsulation = x25519.getPublicKey(ephemeral);
+      secret = x25519.getSharedSecret(ephemeral, recipient.publicKey);
+    } finally { ephemeral.fill(0); }
+  }
+  try {
+    const salt = crypto.getRandomValues(new Uint8Array(32));
+    const iv = crypto.getRandomValues(new Uint8Array(12));
+    const envelope = { version: 'daily-grind-note-v1', mode: recipient.mode, recipient: b64(recipient.publicKey), encapsulation: b64(encapsulation), salt: b64(salt), iv: b64(iv) };
+    const additionalData = header(envelope);
+    const key = await aesKey(secret, salt, additionalData, 'encrypt');
+    envelope.ciphertext = b64(new Uint8Array(await crypto.subtle.encrypt({ name: 'AES-GCM', iv, additionalData, tagLength: 128 }, key, encoder.encode(note))));
+    return envelope;
+  } finally { secret.fill(0); }
+}
+export async function decryptNote(envelope, recipient) {
+  if (envelope.version !== 'daily-grind-note-v1' || envelope.mode !== recipient.mode || envelope.recipient !== b64(recipient.publicKey)) throw new Error('The note does not match this recipient.');
+  const kem = scheme(envelope.mode);
+  const secret = kem ? kem.decapsulate(bytes(envelope.encapsulation), recipient.secretKey) : x25519.getSharedSecret(recipient.secretKey, bytes(envelope.encapsulation));
+  try {
+    const additionalData = header(envelope);
+    const key = await aesKey(secret, bytes(envelope.salt), additionalData, 'decrypt');
+    const plaintext = await crypto.subtle.decrypt({ name: 'AES-GCM', iv: bytes(envelope.iv), additionalData, tagLength: 128 }, key, bytes(envelope.ciphertext));
+    return new TextDecoder().decode(plaintext);
+  } finally { secret.fill(0); }
+}
