+import test from 'node:test';
+import assert from 'node:assert/strict';
+import { createRecipient, encryptNote, decryptNote } from './crypto.js';
+for (const mode of ['classical', 'hybrid', 'pq']) {
+  test(`${mode}: round trip, unique encryption, tampering and wrong recipient rejection`, async () => {
+    const recipient = createRecipient(mode);
+    const note = 'Gate code 1234. Please leave by the side door ☕';
+    const envelope = await encryptNote(note, recipient);
+    assert.equal(await decryptNote(envelope, recipient), note);
+    assert.ok(!JSON.stringify(envelope).includes('Gate code'));
+    const next = await encryptNote(note, recipient);
+    assert.notEqual(envelope.iv, next.iv);
+    assert.notEqual(envelope.ciphertext, next.ciphertext);
+    const tampered = { ...envelope, ciphertext: (envelope.ciphertext[0] === 'A' ? 'B' : 'A') + envelope.ciphertext.slice(1) };
+    await assert.rejects(decryptNote(tampered, recipient));
+    await assert.rejects(decryptNote({ ...envelope, salt: next.salt }, recipient));
+    await assert.rejects(decryptNote({ ...envelope, encapsulation: next.encapsulation }, recipient));
+    await assert.rejects(decryptNote({ ...envelope, mode: 'invalid' }, recipient));
+    await assert.rejects(decryptNote(envelope, createRecipient(mode)));
+    recipient.secretKey.fill(0);
+  });
+}
+test('rejects empty, oversized notes and unknown algorithms', async () => {
+  const recipient = createRecipient('hybrid');
+  await assert.rejects(encryptNote('   ', recipient));
+  await assert.rejects(encryptNote('x'.repeat(501), recipient));
+  assert.throws(() => createRecipient('invalid'));
+});
