--- /dev/null
+++ b/src/scripts/page-transitions.ts
@@ -0,0 +1,71 @@
+import type {
+  TransitionBeforePreparationEvent,
+  TransitionBeforeSwapEvent,
+} from "astro:transitions/client";
+
+// Astro's loader already waits for incoming stylesheets. Extend that phase,
+// while the current page is still visible, rather than making swap() async
+// (the router deliberately expects a synchronous swap).
+const unreadyDocuments = new WeakSet<Document>();
+
+async function prepareImages(event: TransitionBeforePreparationEvent) {
+  // History and fragment navigation may reveal any part of the destination.
+  // Normal navigation only needs the eager images in the initial viewport.
+  const selector = event.navigationType === "traverse" || event.to.hash
+    ? "img"
+    : 'img[loading="eager"]';
+  const images = Array.from(event.newDocument.querySelectorAll<HTMLImageElement>(selector));
+  const probes = images.map((image) => {
+    const probe = new Image();
+    // Match request mode and responsive selection so the swapped image can
+    // reuse the prepared resource, including credentialed article images.
+    if (image.hasAttribute("crossorigin")) probe.crossOrigin = image.crossOrigin;
+    probe.referrerPolicy = image.referrerPolicy;
+    probe.loading = "eager";
+    probe.decoding = "async";
+    probe.sizes = image.sizes;
+    probe.srcset = image.srcset;
+    probe.src = new URL(image.getAttribute("src")!, event.to).href;
+    return probe;
+  });
+
+  const ready = Promise.all([
+    ...probes.map((image) => image.decode()),
+    document.fonts.load('500 48px "Grenze"'),
+    document.fonts.ready,
+  ]).then(() => true, () => false);
+
+  // A failed or slow external resource must never trap navigation. If the
+  // budget expires, navigate without animating an incomplete destination.
+  return new Promise<boolean>((resolve) => {
+    const finish = (complete: boolean) => {
+      clearTimeout(timer);
+      event.signal.removeEventListener("abort", aborted);
+      resolve(complete);
+    };
+    const aborted = () => finish(false);
+    const timer = window.setTimeout(() => finish(false), 4000);
+    event.signal.addEventListener("abort", aborted, { once: true });
+    if (event.signal.aborted) finish(false);
+    else void ready.then(finish);
+  });
+}
+
+document.addEventListener("astro:before-preparation", (event) => {
+  const preparation = event as TransitionBeforePreparationEvent;
+  const load = preparation.loader;
+  preparation.loader = async () => {
+    await load();
+    if (preparation.signal.aborted || preparation.defaultPrevented) return;
+    if (!(await prepareImages(preparation))) {
+      unreadyDocuments.add(preparation.newDocument);
+    }
+  };
+});
+
+document.addEventListener("astro:before-swap", (event) => {
+  const swap = event as TransitionBeforeSwapEvent;
+  if (unreadyDocuments.has(swap.newDocument)) {
+    swap.viewTransition.skipTransition();
+  }
+});
