+    // Polyfill contrast-color() while keeping theme changes driven by CSS.
+    if (!CSS.supports('color', 'contrast-color(red)')) {
+      const root = document.documentElement;
+      const context = document.createElement('canvas').getContext('2d', { willReadFrequently: true });
+
+      function contrastingText(background) {
+        context.clearRect(0, 0, 1, 1);
+        context.fillStyle = background;
+        context.fillRect(0, 0, 1, 1);
+        const channels = Array.from(context.getImageData(0, 0, 1, 1).data).slice(0, 3);
+        const [r, g, b] = channels.map(channel => {
+          const value = channel / 255;
+          return value <= 0.04045 ? value / 12.92 : ((value + 0.055) / 1.055) ** 2.4;
+        });
+        const luminance = 0.2126 * r + 0.7152 * g + 0.0722 * b;
+        return (luminance + 0.05) / 0.05 >= 1.05 / (luminance + 0.05) ? '#000' : '#fff';
+      }
