diff --git a/README.md b/README.md
new file mode 100644
index 0000000..c27e0e9
--- /dev/null
+++ b/README.md
@@ -0,0 +1,17 @@
+# smallpt · The web experiment
+
+Kevin Beason's smallpt C++ path tracer, compiled to WebAssembly with Emscripten. Open `index.html` through a static HTTP host. The renderer runs locally in a module Web Worker; it requires no backend, GPU API, or cross-origin isolation headers.
+
+The page automatically renders a Cornell box. Randomize & render changes the two foreground spheres' colors and starts a new render. Color inputs, sample count, resolution, and PNG downloads are available. An original smallpt reference render is shown while the first four-sample pass is computed.
+
+## Build
+
+Install Emscripten (`em++` on PATH), then run `npm run build`. This recompiles `public/smallpt.js` and `public/smallpt.wasm` and copies the static site into `dist/`. Compiled assets are included for hosting without Emscripten.
+
+Run `npm run check:wasm` to execute the shipped Wasm in Node and verify progressive RGBA rendering, deterministic seeds, and material color changes. No browser or server is needed.
+
+## Source and license
+
+Original: https://www.kevinbeason.com/smallpt/ (Kevin Beason, MIT). The unmodified source is in `src/smallpt.original.cpp`; the upstream license is in `src/LICENSE.smallpt.txt`. `public/reference.png` is the upstream distribution's `result_25k.png`.
+
+`src/smallpt.cpp` preserves the original scene and radiance integrator, adding exported initialization, material color setters, progressive four-sample passes, an RGBA buffer, and a recursion safety bound. The browser transfers a frame buffer after each pass and reports progress between row batches. A new render cancels the previous one at the next batch boundary.
diff --git a/app.js b/app.js
new file mode 100644
index 0000000..8c0a091
--- /dev/null
+++ b/app.js
@@ -0,0 +1,76 @@
+const $ = id => document.getElementById(id);
+const canvas = $('render');
+const context = canvas.getContext('2d');
+const sampleOptions = [16, 32, 64, 128, 256];
+let worker;
+let jobId = 0;
+let rendered = false;
+const colorInputs = [$('mirror-color'), $('glass-color')];
+const setText = (id, value) => { $(id).textContent = value; };
+function showError(message) {
+  setText('status', `Render unavailable: ${message}`);
+  setText('render-state', 'ERROR');
+  $('status-dot').style.background = '#c56b48';
+}
+function render() {
+  if (!worker) return;
+  const width = Number($('resolution').value);
+  const samples = sampleOptions[Number($('samples').value)];
+  setText('sample-total', samples);
+  setText('sample-count', '0');
+  setText('render-state', 'TRACING LIGHT');
+  setText('status', 'Rendering in your browser');
+  setText('elapsed', '0.0s');
+  $('progress').style.width = '0%';
+  $('status-dot').style.background = '#7f986b';
+  const colors = colorInputs.map(input => [1, 3, 5].map(i => Math.min(.999, parseInt(input.value.slice(i, i + 2), 16) / 255)));
+  worker.postMessage({ id: ++jobId, width, height: width * .75, samples, colors,
+    seed: crypto.getRandomValues(new Uint32Array(1))[0] });
+}
+$('randomize').addEventListener('click', () => {
+  colorInputs.forEach(input => {
+    const rgb = Array.from(crypto.getRandomValues(new Uint8Array(3)), v => 100 + v % 156);
+    input.value = '#' + rgb.map(v => v.toString(16).padStart(2, '0')).join('');
+  });
+  render();
+});
+$('render-again').addEventListener('click', render);
+colorInputs.forEach(input => input.addEventListener('change', render));
+$('samples').addEventListener('input', () => setText('samples-value', sampleOptions[Number($('samples').value)]));
+$('download').addEventListener('click', () => {
+  if (!rendered) {
+    const a = document.createElement('a'); a.href = 'public/reference.png'; a.download = 'smallpt-reference.png'; a.click(); return;
+  }
+  canvas.toBlob(blob => {
+    if (!blob) return;
+    const url = URL.createObjectURL(blob);
+    const a = document.createElement('a'); a.href = url; a.download = `smallpt-${Date.now()}.png`; a.click();
+    setTimeout(() => URL.revokeObjectURL(url), 1000);
+  }, 'image/png');
+});
+$('status').setAttribute('role', 'status');
+try {
+  if (typeof WebAssembly === 'undefined') throw new Error('WebAssembly is not supported');
+  worker = new Worker(new URL('./worker.js', import.meta.url), { type: 'module' });
+  worker.onmessage = ({ data }) => {
+    if (data.id !== jobId) return;
+    if (data.error) { showError(data.error); return; }
+    if (data.pixels) {
+      if (canvas.width !== data.width || canvas.height !== data.height) {
+        canvas.width = data.width; canvas.height = data.height;
+      }
+      context.putImageData(new ImageData(data.pixels, data.width, data.height), 0, 0);
+      canvas.classList.add('has-frame');
+      rendered = true;
+      setText('sample-count', data.samples);
+    }
+    setText('elapsed', `${(data.elapsed / 1000).toFixed(1)}s`);
+    $('progress').style.width = `${data.progress * 100}%`;
+    if (data.done) {
+          setText('status', 'Render complete');
+      setText('render-state', 'RENDER COMPLETE');
+    }
+  };
+  worker.onerror = event => showError(event.message || 'Could not load the WebAssembly worker');
+  render();
+} catch (error) { showError(error.message); }
