new file mode 100644
index 0000000..4eae5eb
--- /dev/null
+++ b/scripts/check-wasm.mjs
@@ -0,0 +1,29 @@
+// Execute the shipped WebAssembly without a browser or HTTP server.
+import { readFile } from 'node:fs/promises';
+import assert from 'node:assert/strict';
+import createSmallpt from '../public/smallpt.js';
+const originalFetch = globalThis.fetch;
+globalThis.fetch = async url => new Response(await readFile(new URL(url)), {
+  headers: { 'Content-Type': 'application/wasm' },
+});
+let wasm;
+try { wasm = await createSmallpt(); } finally { globalThis.fetch = originalFetch; }
+function frame(color) {
+  const width = 48, height = 36;
+  wasm._init_render(width, height, 42);
+  wasm._set_color(6, ...color);
+  wasm._set_color(7, ...color);
+  let ptr;
+  for (let pass = 0; pass < 2; pass++) {
+    for (let row = 0; row < height; row += 12) ptr = wasm._render_rows(row, row + 12);
+  }
+  const pixels = wasm.HEAPU8.slice(ptr, ptr + width * height * 4);
+  assert.equal(pixels.length, width * height * 4);
+  assert.ok(pixels.every((v, i) => i % 4 !== 3 || v === 255), 'All alpha values must be opaque');
+  assert.ok(pixels.some((v, i) => i % 4 !== 3 && v > 0), 'Render must contain light');
+  return pixels;
+}
+const neutral = frame([.999, .999, .999]);
+assert.deepEqual(frame([.999, .999, .999]), neutral, 'Same seed should reproduce the frame');
+assert.notDeepEqual(frame([.9, .3, .2]), neutral, 'Sphere colors should change rendered pixels');
+console.log('Wasm checks passed: progressive rendering, RGBA output, deterministic seed, color changes.');
