@@ -0,0 +1,34 @@
+import createSmallpt from './public/smallpt.js';
+let modulePromise;
+let generation = 0;
+const yieldToMessages = () => new Promise(resolve => setTimeout(resolve, 0));
+self.onmessage = async ({ data }) => {
+  const current = ++generation;
+  try {
+    modulePromise ??= createSmallpt();
+    const wasm = await modulePromise;
+    if (current !== generation) return;
+    const { width, height, samples, colors, seed } = data;
+    wasm._init_render(width, height, seed);
+    colors.forEach((color, i) => wasm._set_color(i + 6, ...color));
+    const started = performance.now();
+    for (let pass = 0; pass < samples / 4; pass++) {
+      for (let row = 0; row < height; row += 12) {
+        if (current !== generation) return;
+        const end = Math.min(row + 12, height);
+        const ptr = wasm._render_rows(row, end);
+        const progress = (pass + end / height) / (samples / 4);
+        if (end === height) {
+          const pixels = new Uint8ClampedArray(wasm.HEAPU8.buffer, ptr, width * height * 4).slice();
+          self.postMessage({ id: data.id, pixels, width, height, progress, samples: (pass + 1) * 4,
+            elapsed: performance.now() - started, done: pass + 1 === samples / 4 }, [pixels.buffer]);
+        } else {
+          self.postMessage({ id: data.id, progress, elapsed: performance.now() - started });
+        }
+        await yieldToMessages();
+      }
+    }
+  } catch (error) {
+    self.postMessage({ id: data.id, error: error.message || String(error) });
+  }
+};

