+const $ = selector => document.querySelector(selector);
+const canvas = $('#render');
+const context = canvas.getContext('2d');
+const preview = new Image();
+let hasFrame = false;
+preview.onload = () => { if (!hasFrame) context.drawImage(preview, 0, 0, canvas.width, canvas.height); };
+preview.src = './public/preview.png';
+const colorInputs = [$('#color-0'), $('#color-1')];
+let worker;
+let currentJob = 0;
+let completed = false;
+const timeLabel = ms => `${(ms / 1000).toFixed(1)}s`;
+function showColors() {
+  colorInputs.forEach((input, i) => {
+    $(`#hex-${i}`).textContent = input.value.toUpperCase();
+    $(`#swatch-${i}`).style.background = input.value;
+  });
+}
+function reportError(message) {
+  document.body.classList.remove('rendering');
+  $('#status').textContent = 'Render unavailable';
+  $('#status').title = message;
+  $('#render-dot').style.background = '#d98062';
+  $('#view-label').textContent = 'RENDER PREVIEW';
+  completed = false;
+  console.error(message);
+}
+function render() {
+  if (!worker) return;
+  const width = Number($('#resolution').value);
+  const height = width * .75;
+  const samples = Number($('#samples').value);
+  const colors = colorInputs.map(input => [1, 3, 5].map(offset => Math.min(.999, parseInt(input.value.slice(offset, offset + 2), 16) / 255)));
+  completed = false;
+  document.body.classList.add('rendering');
+  $('#render-dot').style.background = '';
+  $('#status').textContent = 'Tracing light…';
+  $('#view-label').textContent = 'LIVE RENDER';
+  $('#progress').style.width = '0%';
+  $('#dimensions').textContent = `${width} × ${height}`;
+  $('#sample-count').textContent = `0 / ${samples} spp`;
+  $('#elapsed').textContent = '0.0s';
+  worker.postMessage({ id: ++currentJob, width, height, samples, colors, seed: crypto.getRandomValues(new Uint32Array(1))[0] });
+}
+try {
+  if (!('WebAssembly' in window)) throw new Error('WebAssembly is required to render this scene.');
+  worker = new Worker(new URL('./public/render-worker.js', import.meta.url), { type: 'module' });
+  worker.onmessage = ({ data }) => {
+    if (data.job !== currentJob) return;
+    if (data.type === 'error') return reportError(data.message);
+    if (data.type === 'frame') {
+      hasFrame = true;
+      if (canvas.width !== data.width || canvas.height !== data.height) { canvas.width = data.width; canvas.height = data.height; }
+      context.putImageData(new ImageData(new Uint8ClampedArray(data.pixels), data.width, data.height), 0, 0);
+      $('#progress').style.width = `${data.progress * 100}%`;
+      $('#status').textContent = `Tracing light… ${Math.round(data.progress * 100)}%`;
+      $('#sample-count').textContent = `${data.samples} / ${$('#samples').value} spp`;
+      $('#elapsed').textContent = timeLabel(data.elapsed);
+    }
+    if (data.type === 'done') {
+      completed = true;
+      document.body.classList.remove('rendering');
+      $('#status').textContent = 'Render complete';
+      $('#sample-count').textContent = `${$('#samples').value} spp`;
+      $('#elapsed').textContent = timeLabel(data.elapsed);
+      $('#progress').style.width = '100%';
+    }
+  };
+  worker.onerror = event => reportError(event.message || 'Could not load the WebAssembly renderer.');
+  render();
+} catch (error) { reportError(error.message); }
+function randomColor() {
+  // Pale tints keep the original mirror and glass materials bright enough to see.
+  const hue = Math.random() * 360;
+  const saturation = 45 + Math.random() * 35;
+  const lightness = 70 + Math.random() * 13;
+  const a = saturation * Math.min(lightness, 100 - lightness) / 100;
+  const channel = n => {
+    const k = (n + hue / 30) % 12;
+    return Math.round((lightness - a * Math.max(-1, Math.min(k - 3, 9 - k, 1))) * 2.55).toString(16).padStart(2, '0');
