--- /dev/null
+++ b/public/render-worker.js
@@ -0,0 +1,30 @@
+import createSmallpt from './smallpt.js';
+const ready = createSmallpt();
+let activeJob = 0;
+self.onmessage = async ({ data }) => {
+  const job = ++activeJob;
+  try {
+    const engine = await ready;
+    if (job !== activeJob) return;
+    const { width, height, samples, colors, seed } = data;
+    engine._setup(width, height, seed);
+    colors.forEach((color, index) => engine._set_color(6 + index, ...color));
+    const started = performance.now();
+    for (let pass = 0; pass < samples / 4; pass++) {
+      for (let row = 0; row < height; row += 12) {
+        if (job !== activeJob) return;
+        engine._render_rows(row, 12, pass);
+        const progress = (pass * height + Math.min(row + 12, height)) / (samples / 4 * height);
+        if ((pass > 0 && row % 48 === 0) || row + 12 >= height) {
+          const pixels = engine.HEAPU8.slice(engine._get_pixels(), engine._get_pixels() + width * height * 4);
+          self.postMessage({ type: 'frame', job: data.id, pixels, width, height, progress, samples: (pass + 1) * 4, elapsed: performance.now() - started }, [pixels.buffer]);
+        }
+        // Yield so a new render can cancel this one between small batches.
+        await new Promise(resolve => setTimeout(resolve, 0));
+      }
+    }
+    self.postMessage({ type: 'done', job: data.id, elapsed: performance.now() - started });
+  } catch (error) {
+    self.postMessage({ type: 'error', job: data.id, message: error.message });
+  }
+};
