@@ -0,0 +1,51 @@
+// Browser adapter for Kevin Beason's smallpt (MIT); see vendor/LICENSE.txt.
+#define main smallpt_original_main
+#include "../vendor/smallpt.cpp"
+#undef main
+#include <stdint.h>
+#include <vector>
+
+static int width, height;
+static unsigned int sceneSeed;
+static std::vector<Vec> accumulation;
+static std::vector<unsigned char> pixels;
+extern "C" {
+void setup(int w, int h, unsigned int seed) {
+  width=w; height=h; sceneSeed=seed;
+  accumulation.assign(w*h, Vec()); pixels.assign(w*h*4, 0);
+}
+void set_color(int sphere, double r, double g, double b) {
+  if (sphere==6 || sphere==7) spheres[sphere].c=Vec(r,g,b);
+}
+unsigned char* get_pixels() { return pixels.data(); }
+void render_rows(int start, int count, int pass) {
+  Ray cam(Vec(50,52,295.6), Vec(0,-0.042612,-1).norm());
+  Vec cx=Vec(width*.5135/height), cy=(cx%cam.d).norm()*.5135;
+  for(int y=start; y<height && y<start+count; ++y) {
+    uint32_t seed=sceneSeed ^ ((y+1)*2654435761u) ^ ((pass+1)*2246822519u);
+    unsigned short Xi[3]={(unsigned short)seed,(unsigned short)(seed>>16),(unsigned short)(y+pass*719)};
+    for(int x=0; x<width; ++x) {
+      Vec sample;
+      for(int sy=0; sy<2; ++sy) for(int sx=0; sx<2; ++sx) {
+        double r1=2*erand48(Xi), dx=r1<1?sqrt(r1)-1:1-sqrt(2-r1);
+        double r2=2*erand48(Xi), dy=r2<1?sqrt(r2)-1:1-sqrt(2-r2);
+        Vec d=cx*(((sx+.5+dx)/2+x)/width-.5)+cy*(((sy+.5+dy)/2+y)/height-.5)+cam.d;
+        sample=sample+radiance(Ray(cam.o+d*140,d.norm()),0,Xi)*.25;
+      }
+      int i=(height-y-1)*width+x;
+      accumulation[i]=accumulation[i]+sample;
+      Vec color=accumulation[i]*(1.0/(pass+1));
+      pixels[i*4]=toInt(color.x); pixels[i*4+1]=toInt(color.y); pixels[i*4+2]=toInt(color.z); pixels[i*4+3]=255;
+    }
+  }
+}
+}
+#ifdef NATIVE_PREVIEW
+int main() {
+  setup(640,480,42);
+  for(int pass=0; pass<32; ++pass) render_rows(0,480,pass);
+  FILE* f=fopen("public/preview.ppm","wb"); fprintf(f,"P6\n640 480\n255\n");
+  for(int i=0;i<640*480;++i) fwrite(pixels.data()+i*4,1,3,f);
+  fclose(f);
+}
+#endif
