@@ -0,0 +1,56 @@
+// Browser adapter for Kevin Beason's MIT-licensed smallpt.
+#define SMALLPT_LIBRARY
+#include "../vendor/smallpt/smallpt.cpp"
+#include <stdint.h>
+
+extern "C" {
+int scene_color(int id) {
+  if (id<0 || id>8) return 0;
+  Vec c=spheres[id].c;
+  return (int(c.x*255)<<16)|(int(c.y*255)<<8)|int(c.z*255);
+}
+void set_scene(uint32_t seed, int randomize) {
+  spheres[0].c = Vec(.75,.25,.25);
+  spheres[1].c = Vec(.25,.25,.75);
+  spheres[6].c = spheres[7].c = Vec(.999,.999,.999);
+  if (!randomize) return;
+  unsigned short state[3] = {static_cast<unsigned short>(seed),
+    static_cast<unsigned short>(seed >> 16), 0x330e};
+  // Tint the mirror and glass, as well as the two sphere-based side walls.
+  const int ids[] = {0,1,6,7};
+  for (int id : ids) {
+    double r=.25+.65*erand48(state), g=.25+.65*erand48(state), b=.25+.65*erand48(state);
+    if (id >= 6) { r=.65+.35*r; g=.65+.35*g; b=.65+.35*b; }
+    spheres[id].c = Vec(r,g,b);
+  }
+}
+
+void render_rows(unsigned char *pixels, int w, int h, int samples,
+                 int start, int count, uint32_t seed) {
+  if (!pixels || w<1 || h<1 || samples<4 || start<0) return;
+  const int samps = samples/4;
+  Ray cam(Vec(50,52,295.6),Vec(0,-.042612,-1).norm());
+  Vec cx=Vec(w*.5135/h), cy=(cx%cam.d).norm()*.5135;
+  for (int row=start; row<start+count && row<h; ++row) {
+    int y=h-row-1;
+    unsigned short Xi[3]={static_cast<unsigned short>(seed),
+      static_cast<unsigned short>(seed>>16), static_cast<unsigned short>(y*y*y+1)};
+    for (int x=0; x<w; ++x) {
+      Vec color;
+      for (int sy=0; sy<2; ++sy) for (int sx=0; sx<2; ++sx) {
+        Vec r;
+        for (int s=0; s<samps; ++s) {
+          double r1=2*erand48(Xi), dx=r1<1?sqrt(r1)-1:1-sqrt(2-r1);
+          double r2=2*erand48(Xi), dy=r2<1?sqrt(r2)-1:1-sqrt(2-r2);
+          Vec d=cx*(((sx+.5+dx)/2+x)/w-.5)+cy*(((sy+.5+dy)/2+y)/h-.5)+cam.d;
+          r=r+radiance(Ray(cam.o+d*140,d.norm()),0,Xi)*(1./samps);
+        }
+        color=color+Vec(clamp(r.x),clamp(r.y),clamp(r.z))*.25;
+      }
+      int i=(row*w+x)*4;
+      pixels[i]=toInt(color.x); pixels[i+1]=toInt(color.y);
+      pixels[i+2]=toInt(color.z); pixels[i+3]=255;
+    }
+  }
+}
+}
