index 0000000..cb8f9ae
--- /dev/null
+++ b/public/wasm/render-worker.js
@@ -0,0 +1,33 @@
+import createSmallpt from './smallpt.js';
+
+let renderer;
+self.onmessage = async ({ data }) => {
+  const { width, height, samples, seed, randomize } = data;
+  let pointer = 0;
+  try {
+    renderer ??= await createSmallpt();
+    const length = width * height * 4;
+    pointer = renderer._malloc(length);
+    if (!pointer) throw new Error('Not enough memory for this image. Try a smaller resolution.');
+    renderer.HEAPU8.fill(0, pointer, pointer + length);
+    renderer._set_scene(seed, randomize ? 1 : 0);
+    self.postMessage({ type: 'palette', colors: [0,1,2,6,7].map(id => '#' + renderer._scene_color(id).toString(16).padStart(6, '0')) });
+    const started = performance.now();
+    let lastUpdate = 0;
+    for (let row = 0; row < height; row += 4) {
+      renderer._render_rows(pointer, width, height, samples, row, 4, seed);
+      const completed = Math.min(row + 4, height);
+      if (performance.now() - lastUpdate > 120 || completed === height) {
+        // Read the heap again: memory growth can invalidate older views.
+        const pixels = new Uint8ClampedArray(renderer.HEAPU8.buffer, pointer, length).slice();
+        self.postMessage({ type: completed === height ? 'done' : 'progress', pixels,
+          width, height, completed, elapsed: performance.now() - started }, [pixels.buffer]);
+        lastUpdate = performance.now();
+      }
+    }
+  } catch (error) {
+    self.postMessage({ type: 'error', message: error instanceof Error ? error.message : String(error) });
+  } finally {
+    if (pointer) renderer._free(pointer);
+  }
+};
