+#!/usr/bin/env bash
+set -euo pipefail
+cd "$(dirname "$0")/.."
+mkdir -p public/wasm
+em++ native/renderer.cpp -o public/wasm/smallpt.js \
+  --no-entry -fno-exceptions -fno-rtti -nostdlib++ -O3 -flto -Wall -Werror -Wno-dangling-else \
+  -sSTRICT -sEXPORT_ES6 -sENVIRONMENT=worker -sALLOW_MEMORY_GROWTH \
+  -sSTACK_SIZE=1MB -sFILESYSTEM=0 \
+  -sINCOMING_MODULE_JS_API=wasmBinary \
+  -sEXPORTED_FUNCTIONS=_set_scene,_scene_color,_render_rows,_malloc,_free \
+  -sEXPORTED_RUNTIME_METHODS=HEAPU8
+cp vendor/smallpt/LICENSE.txt public/wasm/LICENSE.txt
