@@ -0,0 +1,72 @@
+import assert from "node:assert/strict";
+import { readFile } from "node:fs/promises";
+import createSmallpt from "../public/wasm/smallpt.js";
+
+// Execute the exact browser binary without starting a server or browser.
+const wasmBinary = await readFile(
+  new URL("../public/wasm/smallpt.wasm", import.meta.url),
+);
+assert(WebAssembly.validate(wasmBinary), "Binary must be valid WebAssembly");
+const m = await createSmallpt({ wasmBinary });
+const width = 64,
+  height = 48,
+  size = width * height * 4;
+function render(seed, randomized, chunkSize = height) {
+  m._set_scene(seed, randomized ? 1 : 0);
+  const ptr = m._malloc(size);
+  assert(ptr > 0);
+  try {
+    m.HEAPU8.fill(0, ptr, ptr + size);
+    for (let row = 0; row < height; row += chunkSize)
+      m._render_rows(ptr, width, height, 16, row, chunkSize, seed);
+    return m.HEAPU8.slice(ptr, ptr + size);
+  } finally {
+    m._free(ptr);
+  }
+}
+const original = render(42, false);
+assert.deepEqual(
+  render(42, false, 4),
+  original,
+  "Progressive batches must match a full render",
+);
+assert(
+  original.every((v, i) => i % 4 !== 3 || v === 255),
+  "Every pixel must be opaque",
+);
+const channels = original.filter((_, i) => i % 4 !== 3);
+assert(
+  Math.max(...channels) > 200 && Math.min(...channels) < 30,
+  "The scene must have highlights and shadows",
+);
+assert(
+  new Set(channels).size > 100,
+  "The image must contain meaningful color variation",
+);
+const random = render(3381, true);
+assert.notDeepEqual(random, original, "Randomization must change the output");
+assert.deepEqual(render(3381, true), random, "A seed must reproduce its image");
+assert.notDeepEqual(
+  render(8920, true),
+  random,
+  "Different seeds must produce different images",
+);
+m._set_scene(3381, 1);
+assert.notEqual(
+  m._scene_color(6),
+  0xfefefe,
+  "Mirror sphere must receive a new color",
+);
+assert.notEqual(
+  m._scene_color(7),
+  0xfefefe,
+  "Glass sphere must receive a new color",
+);
+assert.deepEqual(
+  render(42, false),
+  original,
+  "Reset must restore the original scene",
+);
+console.log(
+  "PASS: valid WASM, actual ray-traced pixels, progressive equivalence, seeded color changes, and original scene reset.",
+);
