+import { readFile } from "node:fs/promises";
+import sharp from "sharp";
+import createSmallpt from "../public/wasm/smallpt.js";
+const renderer = await createSmallpt({
+  wasmBinary: await readFile(
+    new URL("../public/wasm/smallpt.wasm", import.meta.url),
+  ),
+});
+const width = 640,
+  height = 480,
+  size = width * height * 4;
+for (const [name, seed] of [
+  ["warm", 39475],
+  ["cool", 34546],
+]) {
+  const started = performance.now();
+  renderer._set_scene(seed, 1);
+  const ptr = renderer._malloc(size);
+  try {
+    renderer._render_rows(ptr, width, height, 128, 0, height, seed);
+    const pixels = Buffer.from(renderer.HEAPU8.subarray(ptr, ptr + size));
+    await sharp(pixels, { raw: { width, height, channels: 4 } })
+      .png()
+      .toFile(
+        new URL(`../public/wasm/study-${name}.png`, import.meta.url).pathname,
+      );
+    console.log(
+      `Rendered ${name}, seed ${seed}, 128 spp, ${((performance.now() - started) / 1000).toFixed(1)}s`,
+    );
+  } finally {
+    renderer._free(ptr);
+  }
+}
