+const $ = <T extends HTMLElement>(selector: string) =>
+  document.querySelector<T>(selector)!;
+const canvas = $<HTMLCanvasElement>("#render-canvas");
+const context = canvas.getContext("2d")!;
+const samples = $<HTMLSelectElement>("#samples");
+const resolution = $<HTMLSelectElement>("#resolution");
+const status = $("#render-status");
+const dot = $("#status-dot");
+const progress = $("#progress-bar");
+const progressTrack = $(".progress-track");
+const download = $<HTMLButtonElement>("#download");
+const preview = $<HTMLImageElement>("#render-preview");
+const panel = $(".render-panel");
+const base = $(".site-shell").dataset.base!;
+let worker: Worker | undefined;
+let seed = 42;
+let randomized = false;
+let hasOutput = false;
+let busy = false;
+function fail(message: string) {
+  busy = false;
+  status.textContent = message;
+  status.classList.add("error");
+  dot.className = "status-dot error";
+  download.disabled = !hasOutput;
+  progress.style.width = "0%";
+  progressTrack.setAttribute("aria-valuenow", "0");
+  worker?.terminate();
+}
+function render(nextSeed = seed, randomize = randomized) {
+  if (!("WebAssembly" in window) || !("Worker" in window)) {
+    fail("This browser needs WebAssembly and Web Workers to render.");
+    return;
+  }
+  worker?.terminate();
+  seed = nextSeed;
+  randomized = randomize;
+  busy = true;
+  const width = Number(resolution.value);
+  const height = (width * 3) / 4;
+  const spp = Number(samples.value);
+  // Keep the last image in unrendered rows while the new frame arrives.
+  const previous = document.createElement("canvas");
+  previous.width = canvas.width;
+  previous.height = canvas.height;
+  if (hasOutput) previous.getContext("2d")!.drawImage(canvas, 0, 0);
+  canvas.width = width;
+  canvas.height = height;
+  if (hasOutput) context.drawImage(previous, 0, 0, width, height);
+  status.textContent = "Tracing light…";
+  status.classList.remove("error");
+  dot.className = "status-dot busy";
+  progress.style.width = "0%";
+  progressTrack.setAttribute("aria-valuenow", "0");
+  $("#render-time").textContent = "—";
+  $("#dimensions").textContent = `${width} × ${height}`;
+  $("#sample-count").textContent = `${spp} spp`;
+  $("#palette-name").textContent = randomize ? `Seed ${seed}` : "The original";
+  $("#scene-name").textContent = randomize
+    ? `Cornell box / Seed ${seed}`
+    : "Cornell box / Original";
+  download.disabled = true;
+  let lastRow = 0;
+  try {
+    worker = new Worker(
+      new URL(`${base}wasm/render-worker.js`, window.location.origin),
+      { type: "module" },
+    );
+    worker.onmessage = ({ data }) => {
+      if (data.type === "error") {
+        fail(`Render failed. ${data.message}`);
+        return;
+      }
+      if (data.type === "palette") {
+        document
+          .querySelectorAll<HTMLElement>(".palette > span")
+          .forEach((swatch, i) =>
+            swatch.style.setProperty("--swatch", data.colors[i]),
+          );
+        return;
+      }
+      const image = new ImageData(data.pixels, data.width, data.height);
+      context.putImageData(
+        image,
+        0,
+        0,
+        0,
+        lastRow,
+        data.width,
+        data.completed - lastRow,
+      );
+      lastRow = data.completed;
+      const percent = Math.round((data.completed / data.height) * 100);
+      progress.style.width = `${percent}%`;
+      progressTrack.setAttribute("aria-valuenow", String(percent));
+      $("#render-time").textContent = `${(data.elapsed / 1000).toFixed(1)}s`;
+      if (data.type === "done") {
+        busy = false;
+        hasOutput = true;
+        status.textContent = "Render complete";
+        dot.className = "status-dot";
+        download.disabled = false;
+        worker?.terminate();
+        worker = undefined;
+      }
+    };
+    worker.onerror = (event) => {
+      event.preventDefault();
+      fail("Could not load the renderer. Click render to retry.");
+    };
+    worker.postMessage({ width, height, samples: spp, seed, randomize });
+  } catch (error) {
+    fail(
+      error instanceof Error ? error.message : "The renderer could not start.",
+    );
+  }
+}
+function randomize() {
+  render(crypto.getRandomValues(new Uint32Array(1))[0], true);
+}
+function showWorkspace() {
+  $(".workspace").scrollIntoView({
+    behavior: matchMedia("(prefers-reduced-motion: reduce)").matches
+      ? "instant"
+      : "smooth",
+    block: "center",
+  });
+}
+$("#randomize").addEventListener("click", randomize);
+$("#make-new").addEventListener("click", () => {
+  randomize();
+  showWorkspace();
+});
+$("#reset").addEventListener("click", () => render(42, false));
+samples.addEventListener("change", () => render());
+resolution.addEventListener("change", () => render());
