+/* Later layers take precedence without increasing selector specificity. */
+@layer reset, tokens, base, layout, components, states;
+
+@layer reset {
+  :where(*, *::before, *::after) {
+    box-sizing: border-box;
+    margin: 0;
+    padding: 0;
+  }
+}
+
+@layer tokens {
+  :root {
+    --color-primary: #4e342e;
+    --color-secondary: #d7ccc8;
+    --color-accent: #ffab40;
+    --color-text: #3e2723;
+    --color-page: #fafafa;
+    --color-surface: #fff;
+    --color-on-primary: #fff;
+    --color-primary-hover: var(--color-text);
+    --color-hero-overlay: rgb(0 0 0 / 50%);
+
+    --font-family-body: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
+    --font-size-small: 0.85rem;
+    --font-size-nav: 0.9rem;
+    --font-size-logo: 1.5rem;
+    --font-size-hero: 3rem;
+    --font-weight-bold: 700;
+    --line-height-body: 1.6;
+    --letter-spacing-logo: 1px;
+
+    --space-1: 0.3125rem;
+    --space-2: 0.625rem;
+    --space-3: 0.75rem;
+    --space-4: 0.9375rem;
+    --space-5: 1rem;
+    --space-6: 1.25rem;
+    --space-7: 2.5rem;
+    --page-gutter: 5%;
+
+    --radius-small: 0.25rem;
+    --radius-button: 0.3125rem;
+    --radius-card: 0.5rem;
+    --border-thin: 1px;
+    --shadow-card: 0 2px 5px rgb(0 0 0 / 10%);
+    --duration-interaction: 0.3s;
+    --layer-sticky: 1000;
+    --content-max-size: 68.75rem;
+    --card-min-size: 15.625rem;
+    --hero-block-size: 60vh;
+    --hero-image: url('https://images.unsplash.com/photo-1495474472287-4d71bcdd2085?auto=format&fit=crop&w=1350&q=80');
+  }
+}
+
+@layer base {
+  body {
+    font-family: var(--font-family-body);
+    line-height: var(--line-height-body);
+    color: var(--color-text);
+    background-color: var(--color-page);
+  }
+
+  :where(.site-nav, .footer-links) a {
+    text-decoration: none;
+  }
+}
+
+@layer layout {
+  .site-nav {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    padding-block: var(--space-5);
+    padding-inline: var(--page-gutter);
+    position: sticky;
+    inset-block-start: 0;
+    z-index: var(--layer-sticky);
+  }
+
+  .site-nav ul {
+    display: flex;
+    gap: var(--space-6);
+    list-style: none;
+  }
+
+  .hero {
+    block-size: var(--hero-block-size);
+    display: flex;
+    flex-direction: column;
+    justify-content: center;
+    align-items: center;
+    padding-inline: var(--space-6);
+  }
+
+  .container {
+    max-inline-size: var(--content-max-size);
+    margin-block: var(--space-7);
+    margin-inline: auto;
+    padding-inline: var(--space-6);
+  }
+
+  .grid {
+    display: grid;
+    grid-template-columns: repeat(auto-fit, minmax(min(100%, var(--card-min-size)), 1fr));
+    gap: var(--space-6);
+    margin-block-start: var(--space-6);
+  }
+
+  .site-footer {
+    padding-block: var(--space-7);
+    padding-inline: var(--space-6);
+    margin-block-start: var(--space-7);
+  }
+}
+
+@layer components {
+  :where(.site-nav, .btn) {
+    background-color: var(--color-primary);
+    color: var(--color-on-primary);
+  }
+
+  :where(.hero, .card, .section-title, .site-footer) {
+    text-align: center;
+  }
+
+  .logo {
+    font-size: var(--font-size-logo);
+    font-weight: var(--font-weight-bold);
+    letter-spacing: var(--letter-spacing-logo);
+  }
+
+  .site-nav a {
+    color: var(--color-on-primary);
+    font-size: var(--font-size-nav);
+    transition: color var(--duration-interaction);
+  }
+
+  .logout-link {
+    border: var(--border-thin) solid var(--color-accent);
+    padding-block: var(--space-1);
+    padding-inline: var(--space-3);
+    border-radius: var(--radius-small);
+  }
+
+  .hero {
+    background-image: linear-gradient(var(--color-hero-overlay), var(--color-hero-overlay)), var(--hero-image);
+    background-size: cover;
+    background-position: center;
+    color: var(--color-on-primary);
+  }
+
+  .hero h1 {
+    font-size: var(--font-size-hero);
+    margin-block-end: var(--space-5);
+  }
+
+  .card {
+    background-color: var(--color-surface);
+    padding-block: var(--space-6);
+    padding-inline: var(--space-6);
+    border-radius: var(--radius-card);
+    box-shadow: var(--shadow-card);
+  }
+
+  .card h3 {
+    margin-block-end: var(--space-2);
+    color: var(--color-primary);
+  }
+
+  .btn {
+    display: inline-block;
+    padding-block: var(--space-2);
+    padding-inline: var(--space-6);
+    text-decoration: none;
+    border-radius: var(--radius-button);
+    margin-block-start: var(--space-4);
+    transition: background-color var(--duration-interaction);
+  }
+
+  .site-footer {
+    background-color: var(--color-secondary);
+  }
+
+  .footer-links {
+    margin-block-end: var(--space-6);
+  }
+
+  .footer-links a {
+    margin-inline: var(--space-2);
+    color: var(--color-text);
+    font-size: var(--font-size-small);
+  }
+}
+
+@layer states {
+  .site-nav a:where(:hover, :focus-visible) {
+    color: var(--color-accent);
+  }
+
+  .btn:where(:hover, :focus-visible) {
+    background-color: var(--color-primary-hover);
+  }
+
+  @media (prefers-reduced-motion: reduce) {
+    :where(.site-nav a, .btn) {
+      transition: none;
+    }
+  }
+}

