+import assert from 'node:assert/strict';
+import { readFile } from 'node:fs/promises';
+import test from 'node:test';
+import { Window } from 'happy-dom';
+
+const window = new Window({ url: 'https://daily-grind.example/' });
+for (const key of ['document', 'HTMLElement', 'customElements', 'CustomEvent']) {
+  globalThis[key] = window[key];
+}
+
+const earlyCard = document.createElement('coffee-card');
+earlyCard.name = 'Assigned before upgrade';
+earlyCard.price = 4.5;
+earlyCard.featured = true;
+document.body.append(earlyCard);
+const { CoffeeCard } = await import('./coffee-card.js');
+
+function makeCard() {
+  const card = document.createElement('coffee-card');
+  document.body.append(card);
+  return card;
+}
+
+test('upgrades existing markup and replays properties assigned before registration', () => {
+  assert.ok(earlyCard instanceof CoffeeCard);
+  assert.equal(earlyCard.getAttribute('name'), 'Assigned before upgrade');
+  assert.equal(earlyCard.getAttribute('price'), '4.5');
+  assert.equal(earlyCard.hasAttribute('featured'), true);
+  assert.equal(earlyCard.shadowRoot.querySelector('h3').textContent, earlyCard.name);
+});
+
+test('page cards retain their content and working links after upgrade', async () => {
+  const source = await readFile(new URL('./index.html', import.meta.url), 'utf8');
+  const container = document.createElement('div');
+  container.innerHTML = source.match(/<div class="grid">([\s\S]*?)<\/section>/)[1];
+  document.body.append(container);
+  const cards = [...container.querySelectorAll('coffee-card')];
+  assert.equal(cards.length, 3);
+  for (const card of cards) {
+    const root = card.shadowRoot;
+    assert.equal(root.querySelector('h3').textContent, card.querySelector('h3').textContent);
+    assert.equal(root.querySelector('.description').textContent, card.querySelector('p').textContent);
+    assert.equal(root.querySelector('a').getAttribute('href'), card.querySelector('a').getAttribute('href'));
+    assert.equal(root.querySelector('.price').hidden, true);
+    assert.equal(root.querySelector('.featured').hidden, true);
+  }
+});
+
+test('string attributes and properties reflect both ways without parsing HTML', () => {
+  const card = makeCard();
+  for (const property of ['name', 'description', 'href']) {
+    card[property] = 'first';
+    assert.equal(card.getAttribute(property), 'first');
+    card.setAttribute(property, 'second');
+    assert.equal(card[property], 'second');
+    card[property] = null;
+    assert.equal(card.hasAttribute(property), false);
+    assert.equal(card[property], '');
+  }
+  card.name = '<img src=x onerror=alert(1)>';
+  assert.equal(card.shadowRoot.querySelector('h3').textContent, card.name);
+  assert.equal(card.shadowRoot.querySelector('img'), null);
+  card.href = 'javascript:alert(1)';
+  assert.equal(card.shadowRoot.querySelector('a').hasAttribute('href'), false);
+});
+
+test('numeric reflection handles zero, decimals, invalid input, and removal', () => {
+  const card = makeCard();
+  const price = card.shadowRoot.querySelector('.price');
+  assert.equal(card.price, 0);
+  assert.equal(price.hidden, true);
+  card.price = 4.75;
+  assert.equal(card.getAttribute('price'), '4.75');
+  assert.equal(price.textContent, '$4.75');
+  assert.equal(price.hidden, false);
+  card.setAttribute('price', '2.50');
+  assert.equal(card.price, 2.5);
+  for (const value of ['invalid', '-1', 'Infinity', 'NaN', '']) {
+    card.setAttribute('price', value);
+    assert.equal(card.price, 0);
+    assert.equal(price.textContent, '$0.00');
+  }
+  card.price = Infinity;
+  assert.equal(card.getAttribute('price'), '0');
+  card.price = 0;
+  assert.equal(price.hidden, false);
+  card.removeAttribute('price');
+  assert.equal(price.hidden, true);
+});
+
+test('boolean reflection uses attribute presence, including featured="false"', () => {
+  const card = makeCard();
+  const badge = card.shadowRoot.querySelector('.featured');
+  assert.equal(card.featured, false);
+  assert.equal(window.getComputedStyle(badge).display, 'none');
+  card.featured = true;
+  assert.equal(card.getAttribute('featured'), '');
+  assert.equal(badge.hidden, false);
+  assert.equal(window.getComputedStyle(badge).display, 'inline-block');
+  card.featured = false;
+  assert.equal(card.hasAttribute('featured'), false);
+  assert.equal(badge.hidden, true);
+  card.setAttribute('featured', 'false');
+  assert.equal(card.featured, true);
+  assert.equal(badge.hidden, false);
+  card.removeAttribute('featured');
+  assert.equal(card.featured, false);
+});
+
+test('updates preserve link identity and keep instances independent', () => {
+  const first = makeCard();
+  const second = makeCard();
+  const link = first.shadowRoot.querySelector('a');
+  first.name = 'Latte';
+  first.price = 5;
+  first.featured = true;
+  assert.equal(first.shadowRoot.querySelector('a'), link);
+  assert.equal(link.getAttribute('aria-label'), 'View details for Latte');
+  assert.equal(second.name, '');
+  assert.equal(second.price, 0);
+  assert.equal(second.featured, false);
+});
+
+test('disconnect cleans listeners and reconnect restores exactly one listener', () => {
+  const card = makeCard();
+  card.href = '/menu/seasonal';
+  card.name = 'Latte';
+  const link = card.shadowRoot.querySelector('a');
+  let selections = 0;
+  card.addEventListener('coffee-select', event => {
+    selections += 1;
+    assert.deepEqual(event.detail, { name: 'Latte', href: '/menu/seasonal', price: 0, featured: false });
+    assert.equal(event.bubbles, true);
+    assert.equal(event.composed, true);
+  });
+  const click = () => link.dispatchEvent(new window.MouseEvent('click', { cancelable: true }));
+  click();
+  assert.equal(selections, 1);
+  for (let index = 0; index < 3; index += 1) {
+    card.remove();
+    click();
+    assert.equal(selections, index + 1);
+    document.body.append(card);
+    click();
+    assert.equal(selections, index + 2);
+  }
+});
+
+test('detached attribute changes are rendered when the card is reconnected', () => {
+  const card = makeCard();
+  card.remove();
+  card.name = 'Cold Brew';
+  card.price = 3.25;
+  document.body.append(card);
+  assert.equal(card.shadowRoot.querySelector('h3').textContent, 'Cold Brew');
+  assert.equal(card.shadowRoot.querySelector('.price').textContent, '$3.25');
+});
