+  disconnectedCallback() {
+    this._link.removeEventListener('click', this._onClick);
+  }
+
+  attributeChangedCallback(name, oldValue, newValue) {
+    if (oldValue !== newValue) this._render();
+  }
+
+  get name() { return this.getAttribute('name') ?? ''; }
+  set name(value) { this._setString('name', value); }
+
+  get description() { return this.getAttribute('description') ?? ''; }
+  set description(value) { this._setString('description', value); }
+
+  get href() { return this.getAttribute('href') ?? ''; }
+  set href(value) { this._setString('href', value); }
+
+  get price() {
+    const raw = this.getAttribute('price');
+    if (raw === null || raw.trim() === '') return null;
+    const value = Number(raw);
+    return Number.isFinite(value) && value >= 0 ? value : null;
+  }
+
+  set price(value) {
+    if (value == null) {
+      this.removeAttribute('price');
+      return;
+    }
+    if (typeof value !== 'number' || !Number.isFinite(value) || value < 0) {
+      throw new TypeError('price must be a finite, non-negative number or null');
+    }
+    this.setAttribute('price', String(value));
+  }
+
+  get disabled() { return this.hasAttribute('disabled'); }
+  set disabled(value) { this.toggleAttribute('disabled', Boolean(value)); }
+
+  _setString(attribute, value) {
+    if (value == null) this.removeAttribute(attribute);
+    else this.setAttribute(attribute, String(value));
+  }
+
+  _render() {
+    this._heading.textContent = this.name;
+    this._description.textContent = this.description;
+    const price = this.price;
+    this._price.hidden = price === null;
+    this._price.textContent = price === null ? '' : `$${price.toFixed(2)}`;
+    if (this.disabled || !this.href) this._link.removeAttribute('href');
+    else this._link.setAttribute('href', this.href);
+    this._link.setAttribute('aria-disabled', String(this.disabled));
+    if (this.disabled) this._link.setAttribute('tabindex', '-1');
+    else this._link.removeAttribute('tabindex');
+  }
+}
