+const { test } = require('node:test');
+const assert = require('node:assert/strict');
+const { readFileSync } = require('node:fs');
+const { JSDOM } = require('jsdom');
+
+const source = readFileSync(`${__dirname}/coffee-card.js`, 'utf8');
+
+function setup(t, markup = '<coffee-card></coffee-card>', beforeUpgrade) {
+  const dom = new JSDOM(markup, { runScripts: 'outside-only' });
+  t.after(() => dom.window.close());
+  const card = dom.window.document.querySelector('coffee-card');
+  beforeUpgrade?.(card);
+  dom.window.eval(source);
+  return { card, window: dom.window };
+}
+
+test('existing page upgrades all three cards with their content and links', (t) => {
+  const { window } = setup(t, readFileSync(`${__dirname}/index.html`, 'utf8'));
+  const cards = [...window.document.querySelectorAll('coffee-card')];
+  assert.equal(cards.length, 3);
+  for (const card of cards) {
+    assert.equal(card.shadowRoot.querySelector('h3').textContent, card.name);
+    assert.equal(card.shadowRoot.querySelector('.description').textContent, card.description);
+    assert.equal(card.shadowRoot.querySelector('a').getAttribute('href'), card.href);
+    assert.equal(card.shadowRoot.querySelector('.price').hidden, true);
+  }
+});
+
+test('string properties and attributes reflect both ways and render as text', (t) => {
+  const { card } = setup(t);
+  for (const property of ['name', 'description', 'href']) {
+    card[property] = 'Latte';
+    assert.equal(card.getAttribute(property), 'Latte');
+    card.setAttribute(property, 'Espresso');
+    assert.equal(card[property], 'Espresso');
+    card[property] = null;
+    assert.equal(card.hasAttribute(property), false);
+    assert.equal(card[property], '');
+  }
+  card.name = '<img src=x onerror=alert(1)>';
+  assert.equal(card.shadowRoot.querySelector('h3').textContent, card.name);
+  assert.equal(card.shadowRoot.querySelector('img'), null);
+});
+
+test('numeric prices reflect, format, clear, and reject invalid property values', (t) => {
+  const { card } = setup(t);
+  const price = card.shadowRoot.querySelector('.price');
+  card.price = 4.5;
+  assert.equal(card.getAttribute('price'), '4.5');
+  assert.equal(price.textContent, '$4.50');
+  assert.equal(price.hidden, false);
+  card.setAttribute('price', '0');
+  assert.equal(card.price, 0);
+  assert.equal(price.textContent, '$0.00');
+  for (const invalid of ['', 'nope', '-1', 'Infinity']) {
+    card.setAttribute('price', invalid);
+    assert.equal(card.price, null);
+    assert.equal(price.hidden, true);
+  }
+  for (const invalid of [-1, Infinity, NaN, '4.50']) {
+    assert.throws(() => { card.price = invalid; }, { name: 'TypeError' });
+  }
+  card.price = null;
+  assert.equal(card.hasAttribute('price'), false);
+});
+
+test('boolean attributes use presence and restore links when enabled', (t) => {
+  const { card } = setup(t, '<coffee-card href="/menu" disabled="false"></coffee-card>');
+  const link = card.shadowRoot.querySelector('a');
+  assert.equal(card.disabled, true);
+  assert.equal(link.hasAttribute('href'), false);
+  assert.equal(link.getAttribute('aria-disabled'), 'true');
+  assert.equal(link.tabIndex, -1);
+  card.disabled = false;
+  assert.equal(card.hasAttribute('disabled'), false);
+  assert.equal(link.getAttribute('href'), '/menu');
+  assert.equal(link.hasAttribute('tabindex'), false);
+  card.disabled = true;
+  assert.equal(card.getAttribute('disabled'), '');
+});
+
+test('disconnect removes listeners and reconnect restores behavior and current state', (t) => {
+  const { card, window } = setup(t);
+  const link = card.shadowRoot.querySelector('a');
+  const click = () => link.dispatchEvent(new window.MouseEvent('click', { cancelable: true }));
+  card.disabled = true;
+  assert.equal(click(), false);
+  card.remove();
+  assert.equal(click(), true);
+  card.name = 'Updated while detached';
+  window.document.body.append(card);
+  assert.equal(click(), false);
+  assert.equal(card.shadowRoot.querySelector('h3').textContent, card.name);
+  assert.equal(card.shadowRoot.querySelectorAll('h3').length, 1);
+});
+
+test('properties assigned before registration survive element upgrade', (t) => {
+  const { card } = setup(t, '<coffee-card name="Original"></coffee-card>', (element) => {
+    element.name = 'Pre-upgrade latte';
+    element.description = 'Oat milk';
+    element.href = '/menu/latte';
+    element.price = 5;
+    element.disabled = true;
+  });
+  assert.equal(card.name, 'Pre-upgrade latte');
+  assert.equal(card.getAttribute('description'), 'Oat milk');
+  assert.equal(card.getAttribute('href'), '/menu/latte');
+  assert.equal(card.getAttribute('price'), '5');
+  assert.equal(card.hasAttribute('disabled'), true);
+  card.name = 'Updated after upgrade';
+  assert.equal(card.getAttribute('name'), 'Updated after upgrade');
+});
