+      focusOption(selected);
+    }
+
+    function selectRoast(index) {
+      selected = index;
+      options.forEach((option, i) => option.setAttribute('aria-selected', String(i === index)));
+      const option = options[index];
+      document.getElementById('roast-value').textContent = option.querySelector('strong').textContent + ' roast';
+      document.getElementById('roast-notes').textContent = option.dataset.notes;
+      document.getElementById('order-now').href = '/order-online?roast=' + option.dataset.value;
+      closePicker(true);
+    }
+
+    trigger.addEventListener('click', () => menu.hidden ? openPicker() : closePicker());
+    trigger.addEventListener('keydown', event => {
+      if (['ArrowDown', 'ArrowUp'].includes(event.key)) {
+        event.preventDefault();
+        openPicker();
+      }
+    });
+    options.forEach((option, index) => {
+      option.addEventListener('click', () => selectRoast(index));
+      option.addEventListener('keydown', event => {
+        const offsets = { ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1 };
+        if (event.key in offsets) {
+          event.preventDefault();
+          focusOption((index + offsets[event.key] + options.length) % options.length);
+        } else if (event.key === 'Home' || event.key === 'End') {
+          event.preventDefault();
+          focusOption(event.key === 'Home' ? 0 : options.length - 1);
+        } else if (event.key === 'Enter' || event.key === ' ') {
+          event.preventDefault();
+          selectRoast(index);
+        } else if (event.key === 'Escape') {
+          event.preventDefault();
+          closePicker(true);
+        } else if (/^[lmd]$/i.test(event.key)) {
+          focusOption(options.findIndex(item => item.dataset.value.startsWith(event.key.toLowerCase())));
+        }
+      });
+    });
+    document.addEventListener('click', event => {
+      if (!picker.contains(event.target)) closePicker();
+    });
+    picker.addEventListener('focusout', event => {
+      if (!picker.contains(event.relatedTarget)) closePicker();
+    });
+  </script>
 </body>

 </html>

