+    <title>Load data</title>
+  </head>
+  <body>
+    <button type="button" id="load">Load data</button>
+    <pre id="result" role="status"></pre>
+
+    <script type="module">
+      const button = document.querySelector('#load');
+      const result = document.querySelector('#result');
+
+      button.addEventListener('click', () => {
+        button.disabled = true;
+        result.textContent = 'Loading…';
+
+        // Start both requests immediately; analytics never gates the data.
+        const dataRequest = fetch('/api/data', { priority: 'high' });
+        fetch('/api/analytics', {
+          method: 'POST',
+          headers: { 'Content-Type': 'application/json' },
+          body: JSON.stringify({ click: 1 }),
+          priority: 'low',
+        }).then((response) => {
+          if (!response.ok) throw new Error(`Analytics: HTTP ${response.status}`);
+        }).catch((error) => console.warn('Analytics request failed:', error));
+
+        dataRequest.then(async (response) => {
+          if (!response.ok) throw new Error(`HTTP ${response.status}`);
+          result.textContent = JSON.stringify(await response.json(), null, 2);
+        }).catch((error) => {
+          result.textContent = `Unable to load data: ${error.message}`;
+        }).finally(() => {
+          button.disabled = false;
+        });
+      });
+    </script>
+  </body>
+</html>

