+  const node = $(id);
+  node.textContent = message;
+  node.classList.toggle('error', error);
+  node.hidden = false;
+}
+function switchPanel(create) {
+  $('create-panel').hidden = !create;
+  $('verify-panel').hidden = create;
+  $('show-create').setAttribute('aria-pressed', String(create));
+  $('show-verify').setAttribute('aria-pressed', String(!create));
+}
+$('show-create').addEventListener('click', () => switchPanel(true));
+$('show-verify').addEventListener('click', () => switchPanel(false));
+function values() {
+  const isVoucher = kind() === 'voucher';
+  const option = $('coffee').selectedOptions[0];
+  const quantity = Number($('quantity').value);
+  const unitPriceCents = Math.round(Number(option.dataset.price) * 100);
+  return { isVoucher, quantity, unitPriceCents, amountCents: isVoucher ? Math.round(Number($('amount').value) * 100) : quantity * unitPriceCents };
+}
+function updatePreview() {
+  revision++;
+  const { isVoucher, quantity, amountCents } = values();
+  $('coffee-field').hidden = isVoucher;
+  $('quantity-field').hidden = isVoucher;
+  $('quantity').disabled = isVoucher;
+  $('amount-field').hidden = !isVoucher;
+  $('amount').disabled = !isVoucher;
+  $('preview-title').textContent = isVoucher ? 'A gift of good coffee' : 'Coffee order receipt';
+  $('preview-name').textContent = $('customer').value.trim() || 'Your name';
+  $('preview-item-label').textContent = isVoucher ? 'Gift' : 'Coffee';
+  $('preview-item').textContent = isVoucher ? 'Daily Grind gift voucher' : $('coffee').value;
+  $('preview-quantity-row').hidden = isVoucher;
+  $('preview-quantity').textContent = quantity;
+  $('preview-total').textContent = Number.isFinite(amountCents) ? money(amountCents) : '—';
+  $('sign-button').textContent = isVoucher ? 'Sign gift voucher  →' : 'Sign receipt  →';
