+  const bytes = encoder.encode(canonical({ version, algorithm, document }));
+  if (algorithm.startsWith('ML-DSA')) return bytes;
+  const framed = new Uint8Array(1 + CONTEXT.length + bytes.length);
+  framed[0] = CONTEXT.length;
+  framed.set(CONTEXT, 1);
+  framed.set(bytes, 1 + CONTEXT.length);
+  return framed;
