+  candidates.push('Ed25519', 'ECDSA-P256-SHA256');
+  for (const algorithm of candidates) {
+    try {
+      const suite = suiteFor(algorithm);
+      const keyPair = await crypto.subtle.generateKey(suite.key, false, ['sign', 'verify']);
+      // Verify the complete supported path, including the selected public-key format.
+      const publicKey = base64(await crypto.subtle.exportKey(suite.format, keyPair.publicKey));
+      const identity = { algorithm, keyPair, publicKey };
+      const challenge = encoder.encode('daily-grind-key-check');
+      const signature = await crypto.subtle.sign(suite.operation, keyPair.privateKey, challenge);
+      if (!await crypto.subtle.verify(suite.operation, keyPair.publicKey, signature, challenge)) continue;
