+export async function exportIdentity(identity) {
+  return { version: 1, algorithm: identity.algorithm, publicKey: identity.publicKey, fingerprint: await fingerprint(identity.publicKey) };
+}
+function validateDocument(doc) {
+  if (!doc || !['receipt', 'voucher'].includes(doc.type) || doc.issuer !== 'The Daily Grind (local signer)' ||
