+}
+export async function signDocument(identity, input) {
+  const document = structuredClone(input);
+  validateDocument(document);
+  const envelope = { version: 1, algorithm: identity.algorithm, document };
+  const signature = await crypto.subtle.sign(suiteFor(identity.algorithm).operation, identity.keyPair.privateKey, bytesFor(envelope));
+  return { ...envelope, signature: base64(signature) };
+}
+export async function verifyDocument(envelope, trusted) {
+  if (!envelope || envelope.version !== 1 || !envelope.document || typeof envelope.signature !== 'string' || Object.keys(envelope).sort().join(',') !== 'algorithm,document,signature,version') throw new Error('Not a supported Daily Grind signed document.');
