+  const actualFingerprint = await fingerprint(trusted.publicKey);
+  if (trusted.fingerprint && trusted.fingerprint !== actualFingerprint) throw new Error('The public key fingerprint does not match. Check your trusted key.');
+  let key;
+  try {
+    key = await crypto.subtle.importKey(suite.format, unbase64(trusted.publicKey), suite.key, false, ['verify']);
+  } catch (error) {
+    if (error.name === 'NotSupportedError') throw new Error('This browser cannot verify this algorithm. Use a browser that supports ' + envelope.algorithm + '.');
+    throw new Error('The trusted public key is invalid or unsupported.');
+  }
+  const valid = await crypto.subtle.verify(suite.operation, key, unbase64(envelope.signature), bytesFor(envelope));
+  return { valid, fingerprint: actualFingerprint };
+}
