+import test from 'node:test';
+import assert from 'node:assert/strict';
+import { webcrypto } from 'node:crypto';
+import { generateIdentity, exportIdentity, signDocument, verifyDocument, base64, canonical } from '../signatures.mjs';
+if (!globalThis.crypto) globalThis.crypto = webcrypto;
+const receipt = {
+  type: 'receipt', issuer: 'The Daily Grind (local signer)', id: 'test-receipt',
+  issuedAt: '2026-11-15T12:00:00.000Z', customer: 'Alex ☕', reference: 'Morning coffee',
+  currency: 'USD', item: 'Maple Oat Latte', quantity: 2, unitPriceCents: 650, amountCents: 1300,
+};
+const voucher = {
+  type: 'voucher', issuer: 'The Daily Grind (local signer)', id: 'test-voucher',
+  issuedAt: '2026-11-15T12:00:00.000Z', customer: 'Sam', reference: 'Enjoy!', currency: 'USD', amountCents: 2500,
+};
+async function identityFor(algorithm, key, format) {
+  const keyPair = await crypto.subtle.generateKey(key, false, ['sign', 'verify']);
+  return { algorithm, keyPair, publicKey: base64(await crypto.subtle.exportKey(format, keyPair.publicKey)) };
+}
+test('generated identity signs receipts and vouchers with a separately exported public key', async () => {
+  const identity = await generateIdentity();
+  const trusted = await exportIdentity(identity);
+  assert.equal(identity.keyPair.privateKey.extractable, false);
+  await assert.rejects(crypto.subtle.exportKey('pkcs8', identity.keyPair.privateKey));
+  for (const document of [receipt, voucher]) {
+    const signed = await signDocument(identity, document);
+    assert.equal((await verifyDocument(JSON.parse(JSON.stringify(signed)), JSON.parse(JSON.stringify(trusted)))).valid, true);
+    assert.equal('publicKey' in signed, false);
+    const tampered = structuredClone(signed);
+    tampered.document.customer = 'Different recipient';
+    assert.equal((await verifyDocument(tampered, trusted)).valid, false);
+    signed.document.reference = 'Changed after signing';
+    assert.notEqual(document.reference, signed.document.reference);
+    assert.equal((await verifyDocument(signed, trusted)).valid, false);
+  }
+});
+for (const [algorithm, key, format] of [
+  ['Ed25519', 'Ed25519', 'raw'],
+  ['ECDSA-P256-SHA256', { name: 'ECDSA', namedCurve: 'P-256' }, 'raw'],
+]) {
+  test(`${algorithm} rejects tampering and a different issuer`, async () => {
+    const identity = await identityFor(algorithm, key, format);
+    const trusted = await exportIdentity(identity);
+    const signed = await signDocument(identity, voucher);
+    assert.equal((await verifyDocument(signed, trusted)).valid, true);
+    for (const patch of [{ customer: 'Mallory' }, { amountCents: 10000 }, { reference: 'Rewritten' }, { id: 'replacement' }, { issuedAt: '2026-11-16T12:00:00.000Z' }]) {
+      const changed = structuredClone(signed);
+      Object.assign(changed.document, patch);
+      assert.equal((await verifyDocument(changed, trusted)).valid, false);
+    }
+    const wrongKey = await exportIdentity(await identityFor(algorithm, key, format));
+    assert.equal((await verifyDocument(signed, wrongKey)).valid, false);
+    const flipped = structuredClone(signed);
+    const bytes = Uint8Array.from(atob(flipped.signature), c => c.charCodeAt(0));
+    bytes[0] ^= 1;
+    flipped.signature = base64(bytes);
+    assert.equal((await verifyDocument(flipped, trusted)).valid, false);
+    const typeChanged = await signDocument(identity, receipt);
+    typeChanged.document.type = 'voucher';
+    assert.equal((await verifyDocument(typeChanged, trusted)).valid, false);
+    // Domain separation must prevent an unframed signature from verifying.
+    const raw = { version: signed.version, algorithm, document: signed.document };
+    const operation = algorithm === 'Ed25519' ? algorithm : { name: 'ECDSA', hash: 'SHA-256' };
+    signed.signature = base64(await crypto.subtle.sign(operation, identity.keyPair.privateKey, new TextEncoder().encode(canonical(raw))));
+    assert.equal((await verifyDocument(signed, trusted)).valid, false);
+  });
+}
+test('fails closed for malformed documents, unsupported algorithms, mismatched keys and fingerprints', async () => {
+  const identity = await generateIdentity();
+  const trusted = await exportIdentity(identity);
+  const signed = await signDocument(identity, voucher);
+  for (const malformed of [null, {}, { ...signed, version: 2 }, { ...signed, publicKey: trusted.publicKey }, { ...signed, algorithm: 'HMAC' }, { ...signed, signature: '???' }]) {
+    await assert.rejects(verifyDocument(malformed, trusted));
+  }
+  await assert.rejects(verifyDocument(signed, { ...trusted, fingerprint: 'forged' }), /fingerprint/);
+  await assert.rejects(verifyDocument(signed, { ...trusted, algorithm: 'wrong' }), /same algorithm/);
+  await assert.rejects(signDocument(identity, { ...voucher, amountCents: 0 }));
+  await assert.rejects(signDocument(identity, { ...receipt, amountCents: 1 }));
+  await assert.rejects(signDocument(identity, { ...voucher, amountCents: 50100 }));
+  const reordered = { ...signed, document: Object.fromEntries(Object.entries(signed.document).reverse()) };
+  assert.equal((await verifyDocument(reordered, trusted)).valid, true);
+});

