+import { loadIdentity, signDocument, verifyDocument } from './signing.mjs';
+
+const $ = selector => document.querySelector(selector);
+const result = $('#document-result');
+const money = cents => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(cents / 100);
+let activeTab = 'receipt';
+let toastTimeout;
+let signingError = '';
+
+const identityPromise = loadIdentity().then(identity => {
+  $('#key-status').textContent = 'Browser signing ready · ECDSA P-256';
+  $('#key-fingerprint').textContent = 'Key fingerprint: ' + identity.id;
+  return identity;
+}).catch(error => {
+  signingError = error.message || 'Browser key storage is unavailable. Allow site storage and reload.';
+  $('#key-status').textContent = 'Browser signing unavailable';
+  $('#key-fingerprint').textContent = signingError;
+  return null;
+});
+
+function notify(message) {
+  clearTimeout(toastTimeout);
+  $('#toast').textContent = message;
+  $('#toast').hidden = false;
+  toastTimeout = setTimeout(() => { $('#toast').hidden = true; }, 4000);
+}
+
+function switchTab(tab, focus = false) {
+  activeTab = tab;
+  document.querySelectorAll('[data-tab]').forEach(button => {
+    const selected = button.dataset.tab === tab;
+    button.classList.toggle('active', selected);
+    button.setAttribute('aria-selected', String(selected));
+    button.tabIndex = selected ? 0 : -1;
+    if (selected && focus) button.focus();
+  });
+  document.querySelectorAll('.tab-panel').forEach(panel => { panel.hidden = panel.id !== tab + '-panel'; });
+  result.hidden = true;
+}
+
+document.querySelectorAll('[data-tab]').forEach(button => {
+  button.addEventListener('click', () => switchTab(button.dataset.tab));
+  button.addEventListener('keydown', event => {
+    const tabs = ['receipt', 'voucher', 'verify'];
+    const index = tabs.indexOf(activeTab);
+    let next;
+    if (event.key === 'ArrowRight') next = tabs[(index + 1) % 3];
+    if (event.key === 'ArrowLeft') next = tabs[(index + 2) % 3];
+    if (event.key === 'Home') next = tabs[0];
+    if (event.key === 'End') next = tabs[2];
+    if (next) { event.preventDefault(); switchTab(next, true); }
+  });
+});
+document.querySelectorAll('[data-open]').forEach(link => link.addEventListener('click', () => switchTab(link.dataset.open)));
+
+function updateTotal() {
+  const quantity = Number($('#receipt-form').elements.quantity.value);
+  $('#receipt-total').textContent = Number.isInteger(quantity) && quantity >= 1 && quantity <= 20
+    ? money(Number($('#coffee-select').value) * quantity) : '—';
+}
+$('#receipt-form').addEventListener('input', updateTotal);
+
+document.querySelectorAll('[data-order]').forEach(button => button.addEventListener('click', () => {
+  switchTab('receipt');
+  $('#coffee-select').value = button.dataset.price;
+  $('#receipt-form').elements.quantity.value = '1';
+  updateTotal();
+  $('#documents').scrollIntoView({ behavior: matchMedia('(prefers-reduced-motion: reduce)').matches ? 'instant' : 'smooth' });
+  notify(button.dataset.order + ' selected. Create your signed demo receipt below.');
+}));
+
+function showResult(title, description, error = false) {
+  result.replaceChildren();
+  result.className = 'document-result' + (error ? ' error' : '');
+  const heading = document.createElement('strong');
+  heading.textContent = (error ? 'ⓘ ' : '✓ ') + title;
+  const text = document.createElement('p');
+  text.textContent = description;
+  result.append(heading, text);
+  result.hidden = false;
+}
+
+function documentSummary(payload) {
+  const details = payload.type === 'receipt' ? `${payload.quantity} × ${payload.coffee} · ${money(payload.total)}` : `${money(payload.amount)} for ${payload.recipient}`;
+  return `${details} · ${new Date(payload.createdAt).toLocaleString()} · ${payload.id} · Browser demo, no monetary value.`;
+}
+
+function showSigned(document) {
+  const name = document.payload.type === 'receipt' ? 'Receipt' : 'Gift voucher';
+  showResult(name + ' signed and ready.', documentSummary(document.payload));
+  const actions = window.document.createElement('div');
+  actions.className = 'result-actions';
+  const download = window.document.createElement('button');
+  download.type = 'button';
+  download.textContent = 'Download signed ' + document.payload.type + ' ↓';
+  download.addEventListener('click', () => {
+    const url = URL.createObjectURL(new Blob([JSON.stringify(document, null, 2)], { type: 'application/json' }));
+    const link = window.document.createElement('a');
+    link.href = url;
+    link.download = `${document.payload.type}-${document.payload.id}.json`;
+    link.click();
+    setTimeout(() => URL.revokeObjectURL(url), 1000);
+    notify('Your signed document has been downloaded.');
+  });
+  const verify = window.document.createElement('button');
+  verify.type = 'button';
+  verify.textContent = 'Verify this document ↗';
+  verify.addEventListener('click', () => {
+    switchTab('verify');
+    $('#document-upload').value = '';
+    $('#upload-name').textContent = 'Upload a Daily Grind .json file · up to 1 MB';
+    $('#document-json').value = JSON.stringify(document, null, 2);
+    $('#verify-panel details').open = true;
+    $('#verify-form').requestSubmit();
+  });
+  actions.append(download, verify);
+  result.append(actions);
+}
+
+async function withBusy(form, operation) {
+  const button = form.querySelector('button[type="submit"]');
+  button.disabled = true;
+  form.setAttribute('aria-busy', 'true');
+  result.hidden = true;
+  try {
+    const identity = await identityPromise;
+    if (!identity) throw new Error(signingError);
+    await operation(identity);
+  } catch (error) {
+    showResult('We couldn’t complete that.', error.message || 'Please try again.', true);
+  } finally {
+    button.disabled = false;
+    form.removeAttribute('aria-busy');
+  }
+}
+
+for (const type of ['receipt', 'voucher']) {
+  $('#' + type + '-form').addEventListener('submit', event => {
+    event.preventDefault();
+    const form = event.currentTarget;
+    const fields = new FormData(form);
+    const payload = {
+      version: 1, type, issuer: 'The Daily Grind · Browser Demo',
+      createdAt: new Date().toISOString(), currency: 'USD', demo: true
+    };
+    if (type === 'receipt') {
+      const unitPrice = Number(fields.get('coffee'));
+      const quantity = Number(fields.get('quantity'));
+      const coffee = $('#coffee-select').selectedOptions[0].textContent.split(' — ')[0];
+      Object.assign(payload, { coffee, quantity, unitPrice, total: unitPrice * quantity });
+    } else {
+      Object.assign(payload, { recipient: fields.get('recipient').trim(), message: fields.get('message').trim(), amount: Number(fields.get('amount')) });
+    }
+    withBusy(form, async identity => {
+      payload.id = 'DG-' + crypto.randomUUID();
+      const signed = await signDocument(payload, identity);
+      if (activeTab === type) showSigned(signed);
+    });
+  });
+}
+
+$('#document-upload').addEventListener('change', event => {
+  const file = event.target.files[0];
+  $('#upload-name').textContent = file ? file.name : 'Upload a Daily Grind .json file · up to 1 MB';
+  if (file) $('#document-json').value = '';
+  result.hidden = true;
+});
+$('#document-json').addEventListener('input', () => {
+  $('#document-upload').value = '';
+  $('#upload-name').textContent = 'Upload a Daily Grind .json file · up to 1 MB';
+  result.hidden = true;
+});
+$('#verify-form').addEventListener('submit', event => {
+  event.preventDefault();
+  const file = $('#document-upload').files[0];
+  const pasted = $('#document-json').value.trim();
+  withBusy(event.currentTarget, async identity => {
+    if (file && file.size > 1048576) throw new Error('Please choose a document smaller than 1 MB.');
+    const source = file ? await file.text() : pasted;
+    if (!source) throw new Error('Choose a signed document or paste its JSON to get started.');
+    if (new TextEncoder().encode(source).length > 1048576) throw new Error('Please use a document smaller than 1 MB.');
+    let document;
+    try { document = JSON.parse(source); } catch { throw new Error('This file is not valid JSON. Use the signed .json document downloaded from Daily Grind.'); }
+    const verification = await verifyDocument(document, identity);
+    if (activeTab !== 'verify') return;
+    showResult(verification.valid ? 'Signature verified.' : 'Document not verified.', verification.reason, !verification.valid);
+    if (verification.valid) {
+      const details = window.document.createElement('p');
+      details.textContent = documentSummary(document.payload);
+      result.append(details);
+    }
+  });
+});
