diff --git a/signing.mjs b/signing.mjs
new file mode 100644
index 0000000..3644295
--- /dev/null
+++ b/signing.mjs
@@ -0,0 +1,127 @@
+const encoder = new TextEncoder();
+export const ALGORITHM = 'ECDSA-P256-SHA256';
+const parameters = { name: 'ECDSA', namedCurve: 'P-256' };
+const signatureParameters = { name: 'ECDSA', hash: 'SHA-256' };
+
+export function canonicalize(value) {
+  if (value === null || typeof value === 'string' || typeof value === 'boolean') return JSON.stringify(value);
+  if (typeof value === 'number' && Number.isFinite(value)) return JSON.stringify(value);
+  if (Array.isArray(value)) return '[' + value.map(canonicalize).join(',') + ']';
+  if (typeof value === 'object' && Object.getPrototypeOf(value) === Object.prototype) {
+    return '{' + Object.keys(value).sort().map(key => JSON.stringify(key) + ':' + canonicalize(value[key])).join(',') + '}';
+  }
+  throw new Error('Unsupported document data.');
+}
+
+function base64url(bytes) {
+  let binary = '';
+  for (const byte of bytes) binary += String.fromCharCode(byte);
+  return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
+}
+
+export async function keyId(publicKey) {
+  const raw = await crypto.subtle.exportKey('raw', publicKey);
+  return base64url(new Uint8Array(await crypto.subtle.digest('SHA-256', raw)));
+}
+
+export async function generateIdentity() {
+  // Web Crypto keeps the private key non-exportable; only the public key is exportable.
+  const pair = await crypto.subtle.generateKey(parameters, false, ['sign', 'verify']);
+  return { ...pair, id: await keyId(pair.publicKey) };
+}
+
+export async function loadIdentity() {
+  if (!globalThis.isSecureContext || !globalThis.crypto?.subtle || !globalThis.indexedDB) {
+    throw new Error('Signing needs a secure connection and browser storage. Open this page over HTTPS or localhost.');
+  }
+  const database = await new Promise((resolve, reject) => {
+    const request = indexedDB.open('daily-grind-signing', 1);
+    request.onupgradeneeded = () => request.result.createObjectStore('identity');
+    request.onsuccess = () => resolve(request.result);
+    request.onerror = () => reject(new Error('Browser key storage is unavailable. Allow site storage and try again.'));
+    request.onblocked = () => reject(new Error('Close other Daily Grind tabs and reload to prepare signing.'));
+  });
+  const read = () => new Promise((resolve, reject) => {
+    const transaction = database.transaction('identity', 'readonly');
+    const request = transaction.objectStore('identity').get('local-issuer');
+    transaction.oncomplete = () => resolve(request.result);
+    transaction.onerror = () => reject(transaction.error);
+    transaction.onabort = () => reject(transaction.error);
+  });
+  try {
+    let identity = await read();
+    if (!identity) {
+      const candidate = await generateIdentity();
+      // Read and write in one transaction so simultaneous first visits share one key.
+      identity = await new Promise((resolve, reject) => {
+        const transaction = database.transaction('identity', 'readwrite');
+        const store = transaction.objectStore('identity');
+        const request = store.get('local-issuer');
+        let chosen;
+        request.onsuccess = () => {
+          chosen = request.result || candidate;
+          if (!request.result) store.add(candidate, 'local-issuer');
+        };
+        transaction.oncomplete = () => resolve(chosen);
+        transaction.onerror = () => reject(transaction.error);
+        transaction.onabort = () => reject(transaction.error);
+      });
+    }
+    if (!identity.privateKey || identity.privateKey.extractable || identity.id !== await keyId(identity.publicKey)) {
+      throw new Error('Your saved signing key could not be loaded.');
+    }
+    return identity;
+  } finally {
+    database.close();
+  }
+}
+
+function exactKeys(value, names) {
+  return value && typeof value === 'object' && !Array.isArray(value) &&
+    Object.keys(value).sort().join(',') === [...names].sort().join(',');
+}
+
+export function validatePayload(payload) {
+  const common = ['version', 'type', 'id', 'issuer', 'createdAt', 'currency', 'demo'];
+  const receipt = ['coffee', 'quantity', 'unitPrice', 'total'];
+  const voucher = ['recipient', 'message', 'amount'];
+  const isReceipt = payload?.type === 'receipt';
+  if (!['receipt', 'voucher'].includes(payload?.type) || !exactKeys(payload, [...common, ...(isReceipt ? receipt : voucher)])) return false;
+  if (payload.version !== 1 || payload.issuer !== 'The Daily Grind · Browser Demo' || payload.currency !== 'USD' || payload.demo !== true) return false;
+  if (typeof payload.id !== 'string' || !/^DG-[0-9a-f-]{36}$/i.test(payload.id)) return false;
+  if (typeof payload.createdAt !== 'string' || !Number.isFinite(Date.parse(payload.createdAt))) return false;
+  if (isReceipt) {
+    return typeof payload.coffee === 'string' && payload.coffee.length > 0 && payload.coffee.length <= 80 &&
+      Number.isInteger(payload.quantity) && payload.quantity >= 1 && payload.quantity <= 20 &&
+      Number.isSafeInteger(payload.unitPrice) && payload.unitPrice > 0 && payload.unitPrice <= 100000 &&
+      payload.total === payload.unitPrice * payload.quantity;
+  }
+  return typeof payload.recipient === 'string' && payload.recipient.trim().length > 0 && payload.recipient.length <= 80 &&
+    typeof payload.message === 'string' && payload.message.length <= 200 && [1000, 2500, 5000, 10000].includes(payload.amount);
+}
+
+export async function signDocument(payload, identity) {
+  if (!validatePayload(payload)) throw new Error('Please check the document details and try again.');
+  const unsigned = { format: 'daily-grind-signed-document', algorithm: ALGORITHM, keyId: identity.id, payload };
+  const signature = await crypto.subtle.sign(signatureParameters, identity.privateKey, encoder.encode(canonicalize(unsigned)));
+  return { ...unsigned, signature: base64url(new Uint8Array(signature)) };
+}
+
+export async function verifyDocument(document, identity) {
+  if (!exactKeys(document, ['format', 'algorithm', 'keyId', 'payload', 'signature']) ||
+    document.format !== 'daily-grind-signed-document' || document.algorithm !== ALGORITHM || !validatePayload(document.payload) ||
+    typeof document.signature !== 'string' || !/^[A-Za-z0-9_-]{86}$/.test(document.signature)) {
+    return { valid: false, reason: 'This is not a supported Daily Grind signed document, or its contents have been changed.' };
+  }
+  if (document.keyId !== identity.id) {
+    return { valid: false, reason: 'Unknown signing key. This document was not signed by this browser’s saved key. Try the browser where it was created.' };
+  }
+  const { signature, ...unsigned } = document;
+  try {
+    const bytes = Uint8Array.from(atob(signature.replace(/-/g, '+').replace(/_/g, '/') + '=='), char => char.charCodeAt(0));
+    const valid = await crypto.subtle.verify(signatureParameters, identity.publicKey, bytes, encoder.encode(canonicalize(unsigned)));
+    return { valid, reason: valid ? 'Signature matches this browser’s trusted key. The signed details have not changed.' : 'Signature does not match. This document may have been altered. Its authenticity cannot be confirmed.' };
+  } catch {
+    return { valid: false, reason: 'The signature could not be verified. Check the file and try again.' };
+  }
+}
diff --git a/signing.test.mjs b/signing.test.mjs
new file mode 100644
index 0000000..fad172d
--- /dev/null
+++ b/signing.test.mjs
@@ -0,0 +1,74 @@
+import test from 'node:test';
+import assert from 'node:assert/strict';
+import { generateIdentity, signDocument, verifyDocument, canonicalize } from './signing.mjs';
+
+const identity = await generateIdentity();
+function payload(type = 'receipt') {
+  return {
+    version: 1, type, id: 'DG-' + crypto.randomUUID(), issuer: 'The Daily Grind · Browser Demo',
+    createdAt: new Date().toISOString(), currency: 'USD', demo: true,
+    ...(type === 'receipt' ? { coffee: 'Maple Oat Latte', quantity: 2, unitPrice: 575, total: 1150 }
+      : { recipient: 'Sam', message: 'Coffee is on me.', amount: 2500 })
+  };
+}
+
+test('private signing key cannot be exported', async () => {
+  assert.equal(identity.privateKey.extractable, false);
+  await assert.rejects(crypto.subtle.exportKey('jwk', identity.privateKey));
+});
+
+for (const type of ['receipt', 'voucher']) {
+  test(`${type} survives JSON download and verifies with a persisted key clone`, async () => {
+    const document = JSON.parse(JSON.stringify(await signDocument(payload(type), identity)));
+    const persisted = structuredClone(identity);
+    assert.equal((await verifyDocument(document, persisted)).valid, true);
+  });
+}
+
+test('changing signed receipt details fails verification even if totals are consistent', async () => {
+  const document = await signDocument(payload(), identity);
+  document.payload.unitPrice = 100;
+  document.payload.total = 200;
+  assert.equal((await verifyDocument(document, identity)).valid, false);
+});
+
+test('changing gift recipient, note, or amount fails verification', async () => {
+  const document = await signDocument(payload('voucher'), identity);
+  for (const [field, value] of [['recipient', 'Mallory'], ['message', 'Different note'], ['amount', 5000]]) {
+    const altered = structuredClone(document);
+    altered.payload[field] = value;
+    assert.equal((await verifyDocument(altered, identity)).valid, false);
+  }
+});
+
+test('another signer is rejected even if they claim the trusted key ID', async () => {
+  const other = await generateIdentity();
+  const document = await signDocument(payload(), other);
+  assert.match((await verifyDocument(document, identity)).reason, /Unknown signing key/);
+  const forged = await signDocument(payload(), { ...other, id: identity.id });
+  assert.equal((await verifyDocument(forged, identity)).valid, false);
+});
+
+test('damaged signatures and untrusted envelope extensions fail closed', async () => {
+  const document = await signDocument(payload(), identity);
+  const damaged = structuredClone(document);
+  damaged.signature = (damaged.signature[0] === 'A' ? 'B' : 'A') + damaged.signature.slice(1);
+  assert.equal((await verifyDocument(damaged, identity)).valid, false);
+  assert.equal((await verifyDocument({ ...document, publicKey: {} }, identity)).valid, false);
+  assert.equal((await verifyDocument({ ...document, algorithm: 'none' }, identity)).valid, false);
+});
+
+test('malformed documents and invalid amounts are rejected', async () => {
+  for (const document of [null, [], {}, { payload: { type: 'receipt' } }]) {
+    assert.equal((await verifyDocument(document, identity)).valid, false);
+  }
+  await assert.rejects(signDocument({ ...payload(), quantity: -1 }, identity));
+  await assert.rejects(signDocument({ ...payload('voucher'), amount: 1 }, identity));
+});
+
+test('reordering JSON object keys preserves signature validity', async () => {
+  const document = await signDocument(payload(), identity);
+  document.payload = Object.fromEntries(Object.entries(document.payload).reverse());
+  assert.equal((await verifyDocument(document, identity)).valid, true);
+  assert.equal(canonicalize({ b: 1, a: { d: 2, c: 3 } }), '{"a":{"c":3,"d":2},"b":1}');
+});
