+      const colors = document.querySelectorAll('input[name="gift-color"]');
+      let revision = 0;
+      let renderedRevision = -1;
+      let rendering = false;
+      let downloading = false;
+      let renderTimer;
+
+      function updateCard() {
+        cardMessage.textContent = message.value;
+        // Limit line breaks so every allowed message remains inside the card.
+        cardMessage.style.fontSize = (message.value.length > 65 || message.value.split('\n').length > 2) ? '16px' : '20px';
