+        document.getElementById('message-count').textContent = `${message.value.length} / 100`;
+        canvas.setAttribute('aria-label', `Daily Grind coffee gift card. ${message.value}`);
+        revision++;
+        button.disabled = true;
+        status.textContent = '';
+        clearTimeout(renderTimer);
+        renderTimer = setTimeout(renderCard, 120);
+      }
+
+      function setColor(hex) {
+        card.style.backgroundColor = hex;
+        const rgb = hex.match(/[a-f\d]{2}/gi).map(value => parseInt(value, 16) / 255)
