+          if (typeof html2canvas !== 'function') throw new Error('Renderer unavailable');
+          const rendered = await html2canvas(card, { scale: 2, backgroundColor: null, logging: false });
+          if (currentRevision !== revision) return;
+          canvas.getContext('2d').clearRect(0, 0, canvas.width, canvas.height);
+          canvas.getContext('2d').drawImage(rendered, 0, 0);
+          renderedRevision = currentRevision;
+          button.disabled = downloading;
+        } catch (error) {
+          button.disabled = true;
+          status.textContent = 'The card could not be rendered. Please reload and try again.';
+        } finally {
+          rendering = false;
+          if (currentRevision !== revision) renderCard();
+        }
+      }
+
+      message.addEventListener('input', updateCard);
+      colors.forEach(input => input.addEventListener('change', () => {
+        customColor.value = input.value;
+        setColor(input.value);
+      }));
+      customColor.addEventListener('input', () => {
+        colors.forEach(input => { input.checked = input.value === customColor.value; });
+        setColor(customColor.value);
+      });
+      button.addEventListener('click', () => {
+        if (renderedRevision !== revision || downloading) return;
+        downloading = true;
+        button.disabled = true;
