+(() => {
+  const outlet = document.querySelector('#views');
+  const views = new Map([['/', outlet.querySelector('[data-view]')]]);
+  const scrollPositions = new Map();
+  const titles = {
+    '/': 'Artisanal Coffee',
+    '/menu': 'Menu',
+    '/locations': 'Locations',
+    '/rewards': 'Rewards',
+    '/account': 'My Account',
+  };
+  let currentRoute = null;
+
+  // Initialize each view once. Its nodes and event listeners survive navigation.
+  function createView(route) {
+    const view = document.createElement('div');
+    view.dataset.view = route;
+    view.hidden = true;
+    view.append(document.querySelector(`#view-${route.slice(1)}`).content.cloneNode(true));
+    outlet.append(view);
+
+    if (route === '/menu') {
+      view.querySelector('#menu-category').addEventListener('change', (event) => {
+        view.querySelectorAll('[data-category]').forEach((card) => {
+          card.hidden = event.target.value !== 'all' && card.dataset.category !== event.target.value;
+        });
+      });
+    }
+    if (route === '/locations') {
+      view.querySelector('#location-search').addEventListener('input', (event) => {
+        const query = event.target.value.trim().toLowerCase();
+        const cards = [...view.querySelectorAll('[data-location]')];
+        cards.forEach((card) => { card.hidden = !card.textContent.toLowerCase().includes(query); });
+        view.querySelector('#location-empty').hidden = cards.some((card) => !card.hidden);
+      });
+    }
+    view.querySelectorAll('form').forEach((form) => {
+      form.addEventListener('submit', (event) => {
+        event.preventDefault();
+        form.querySelector('[role="status"]').textContent = route === '/account'
+          ? 'Preferences saved for this visit.'
+          : 'Interest saved for this visit. You have not been enrolled.';
+      });
+    });
+    views.set(route, view);
+    return view;
+  }
+
+  // Hash routes also work on static hosting without a server fallback.
+  function navigate() {
+    const requestedRoute = window.location.hash.slice(1) || '/';
+    const route = Object.hasOwn(titles, requestedRoute) ? requestedRoute : '/';
+    if (route === currentRoute) return;
+
+    if (currentRoute !== null) {
+      scrollPositions.set(currentRoute, window.scrollY);
+    }
+    const view = views.get(route) || createView(route);
+    views.forEach((cachedView) => { cachedView.hidden = cachedView !== view; });
+    const isInitialVisit = currentRoute === null;
+    currentRoute = route;
+    document.title = `The Daily Grind | ${titles[route]}`;
+    document.querySelectorAll('nav a').forEach((link) => {
+      if (link.getAttribute('href') === `#${route}`) link.setAttribute('aria-current', 'page');
+      else link.removeAttribute('aria-current');
+    });
+    if (!isInitialVisit) outlet.focus({ preventScroll: true });
+    window.scrollTo(0, scrollPositions.get(route) || 0);
+  }
+
+  // Route-specific restoration avoids browser restoration racing view switching.
+  if ('scrollRestoration' in history) history.scrollRestoration = 'manual';
+  window.addEventListener('hashchange', navigate);
+  navigate();
+})();
