+// This cache is deliberately limited to the five main sections. Article and
+// category routes remain normal document navigations, so it cannot grow forever.
+class SectionViews extends HTMLElement {
+  connectedCallback() {
+    const views = Array.from(this.querySelectorAll<HTMLElement>('[data-section-view]'));
+    const normalize = (path: string) => path.replace(/\/+$/, '') || '/';
+    const findView = (path: string) => views.find(view =>
+      normalize(new URL(view.dataset.viewPath!, location.origin).pathname) === normalize(path));
+    let active = findView(location.pathname);
+    if (!active) return;
+
+    const controller = new AbortController();
+    this.cleanup = () => {
+      controller.abort();
+      history.scrollRestoration = previousRestoration;
+    };
+    const previousRestoration = history.scrollRestoration;
+    history.scrollRestoration = 'manual';
+    const scrollPositions = new Map<HTMLElement, [number, number]>();
+    let pendingScroll = 0;
+
+    const updateLinks = () => {
+      document.querySelectorAll<HTMLAnchorElement>('[data-section-link]').forEach(link => {
+        if (findView(new URL(link.href).pathname) === active) {
+          link.setAttribute('aria-current', 'page');
+        } else {
+          link.removeAttribute('aria-current');
+        }
+      });
+    };
+
+    const activate = (next: HTMLElement) => {
+      cancelAnimationFrame(pendingScroll);
+      for (const view of views) {
+        const inactive = view !== next;
+        view.classList.toggle('inactive', inactive);
+        view.inert = inactive;
+        if (inactive) view.setAttribute('aria-hidden', 'true');
+        else view.removeAttribute('aria-hidden');
+      }
+      active = next;
+      this.dataset.activeView = next.dataset.sectionView;
+      document.title = next.dataset.viewTitle!;
+      updateLinks();
+      // Focus the revealed region without losing its saved reading position.
+      next.focus({ preventScroll: true });
+      const position = scrollPositions.get(next) ?? [0, 0];
+      pendingScroll = requestAnimationFrame(() => {
+        window.scrollTo({ left: position[0], top: position[1], behavior: 'instant' });
+        pendingScroll = 0;
+      });
+    };
+
+    document.addEventListener('click', event => {
+      if (event.defaultPrevented || event.button !== 0 || event.metaKey ||
+          event.ctrlKey || event.shiftKey || event.altKey) return;
+      const link = event.target instanceof Element
+        ? event.target.closest<HTMLAnchorElement>('a[href]') : null;
+      if (!link || link.hasAttribute('download') ||
+          (link.target && link.target !== '_self') || link.relList.contains('external')) return;
+      const url = new URL(link.href);
+      if (url.origin !== location.origin || url.search || url.hash) return;
+      const next = findView(url.pathname);
+      if (!next) return;
+      event.preventDefault();
+      if (next === active) return;
+      scrollPositions.set(active!, [window.scrollX, window.scrollY]);
+      history.pushState(null, '', url);
+      activate(next);
+    }, { signal: controller.signal });
+
+    window.addEventListener('scroll', () => {
+      if (active && !pendingScroll) {
+        scrollPositions.set(active, [window.scrollX, window.scrollY]);
+      }
+    }, { passive: true, signal: controller.signal });
+
+    window.addEventListener('popstate', () => {
+      const next = findView(location.pathname);
+      if (next && next !== active) activate(next);
+    }, { signal: controller.signal });
+    controller.signal.addEventListener('abort', () => cancelAnimationFrame(pendingScroll));
+    updateLinks();
+  }
+
+  private cleanup?: () => void;
+
+  disconnectedCallback() {
+    this.cleanup?.();
+  }
+}
+
+if (!customElements.get('section-views')) {
+  customElements.define('section-views', SectionViews);
+}
