+---
+import { getCollection } from 'astro:content';
+import NewsView from './NewsView.astro';
+
+const { initialSection } = Astro.props;
+const baseUrl = import.meta.env.BASE_URL;
+const sections = ['top-news', 'world', 'politics', 'multimedia', 'reports'];
+const requestedSection = Astro.url.searchParams.get('section');
+const selected = initialSection === 'top-news' && sections.includes(requestedSection ?? '')
+  ? requestedSection! : initialSection;
+const [multimedia, reports] = await Promise.all([
+  getCollection('multimedia'), getCollection('reports'),
+]);
+---
+
+<section-views data-base={baseUrl} data-active={selected}>
+  {['top-news', 'world', 'politics'].map(section => (
+    <section data-view={section} aria-label={section === 'top-news' ? 'Top News' : section === 'world' ? 'World' : 'Politics'} hidden={section !== selected}>
+      <NewsView section={section} />
+    </section>
+  ))}
+  <section data-view="multimedia" aria-label="Multimedia" hidden={selected !== 'multimedia'}>
+    <div class="max-w-3xl mx-auto px-4 py-8 md:py-12">
