+  <section data-view="reports" aria-label="Reports" hidden={selected !== 'reports'}>
+    <div class="max-w-3xl mx-auto px-4 py-8 md:py-12">
+      <h1 class="text-3xl md:text-4xl font-bold text-gray-900 mb-6 pb-2 border-b-2">Reports</h1>
+      <div class="prose max-w-none">
+        <p>Read our latest reports.</p>
+        <ul>{reports.map(report => <li><a href={`${baseUrl}reports/${report.id}`}>{report.data.title}</a></li>)}</ul>
+      </div>
+    </div>
+  </section>
+</section-views>
+
+<style>
+  section-views { display: block; }
+  /* Hidden views retain their nodes, hydrated islands, and local DOM state. */
+  [data-view][hidden] { display: none !important; }
+</style>
+
+<script>
+  import { sectionFromUrl, sectionTitles } from '../utils/sections';
+
+  class SectionViews extends HTMLElement {
+    private cleanup?: AbortController;
+    private positions = new Map<string, number>();
+    private previousScrollRestoration: ScrollRestoration = 'auto';
+    private frame = 0;
+
+    connectedCallback() {
+      this.cleanup = new AbortController();
+      const { signal } = this.cleanup;
+      const base = this.dataset.base!;
+      this.previousScrollRestoration = history.scrollRestoration;
+      history.scrollRestoration = 'manual';
+
+      const show = (url: URL, focus = false) => {
+        const section = sectionFromUrl(url, base);
+        if (!section) return;
+        cancelAnimationFrame(this.frame);
+        if (this.dataset.active !== section) {
+          this.positions.set(this.dataset.active!, window.scrollY);
+        }
+        this.dataset.active = section;
+        // Toggle visibility only; never replace, detach, or rebuild a view.
+        this.querySelectorAll<HTMLElement>('[data-view]').forEach(view => {
+          view.hidden = view.dataset.view !== section;
+        });
+        document.title = sectionTitles[section];
+        document.querySelectorAll<HTMLAnchorElement>('[data-section-link]').forEach(link => {
+          if (link.dataset.sectionLink === section) link.setAttribute('aria-current', 'page');
+          else link.removeAttribute('aria-current');
+        });
+        if (focus) {
+          const heading = this.querySelector<HTMLElement>(`[data-view="${section}"] h1, [data-view="${section}"] h2`);
+          heading?.setAttribute('tabindex', '-1');
+          heading?.focus({ preventScroll: true });
+        }
+        if (!focus) return;
+        this.frame = requestAnimationFrame(() => {
+          const anchor = url.hash && document.getElementById(decodeURIComponent(url.hash.slice(1)));
+          if (anchor && this.querySelector(`[data-view="${section}"]`)?.contains(anchor)) anchor.scrollIntoView();
+          else window.scrollTo(0, this.positions.get(section) ?? 0);
+        });
+      };
+
+      // Capture before Astro's page router, leaving normal link behavior intact
+      // for article pages, external links, downloads, and modified clicks.
+      document.addEventListener('click', event => {
+        if (event.defaultPrevented || event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
+        const link = event.target instanceof Element ? event.target.closest<HTMLAnchorElement>('a[href]') : null;
+        if (!link || link.hasAttribute('download') || (link.target && link.target !== '_self') || link.hasAttribute('data-astro-reload')) return;
+        const url = new URL(link.href);
+        if (url.origin !== location.origin || !sectionFromUrl(url, base)) return;
+        event.preventDefault();
+        event.stopImmediatePropagation();
+        if (url.href !== location.href) history.pushState(history.state, '', url);
+        show(url, true);
+      }, { capture: true, signal });
+      window.addEventListener('popstate', event => {
+        const url = new URL(location.href);
+        if (!sectionFromUrl(url, base)) return;
+        // Keep Astro from fetching and swapping the already-mounted section shell.
+        event.stopImmediatePropagation();
+        show(url, true);
+      }, { capture: true, signal });
+      // Astro may insert the shell when navigating here from an article.
+      document.addEventListener('astro:page-load', () => show(new URL(location.href)), { signal });
+      show(new URL(location.href));
+    }
+
+    disconnectedCallback() {
+      this.cleanup?.abort();
+      cancelAnimationFrame(this.frame);
+      history.scrollRestoration = this.previousScrollRestoration;
+    }
+  }
+
+  if (!customElements.get('section-views')) customElements.define('section-views', SectionViews);
+</script>
