@@ -0,0 +1,22 @@
+export const sectionTitles = {
+  'top-news': 'The DevTools Times',
+  world: 'World | The DevTools Times',
+  politics: 'Politics | The DevTools Times',
+  multimedia: 'Multimedia',
+  reports: 'Reports',
+};
+
+export type Section = keyof typeof sectionTitles;
+
+/** Resolve only section URLs; article/detail links stay with Astro's router. */
+export function sectionFromUrl(url: URL, base: string): Section | null {
+  const root = `/${base.split('/').filter(Boolean).join('/')}`.replace(/\/$/, '');
+  const path = url.pathname.replace(/\/$/, '');
+  if (path === root) {
+    const section = url.searchParams.get('section') ?? 'top-news';
+    return Object.hasOwn(sectionTitles, section) ? section as Section : null;
+  }
+  if (path === `${root}/multimedia`) return 'multimedia';
+  if (path === `${root}/reports`) return 'reports';
+  return null;
+}
