+import assert from 'node:assert/strict';
+import { readFile } from 'node:fs/promises';
+import { stripTypeScriptTypes } from 'node:module';
+import test from 'node:test';
+import { sectionFromUrl } from '../src/utils/sections.ts';
+
+test('section URLs respect the configured base and leave detail pages alone', () => {
+  const resolve = path => sectionFromUrl(new URL(path, 'https://example.com'), '/devtools-times/');
+  for (const [path, section] of [
+    ['/devtools-times/', 'top-news'],
+    ['/devtools-times/?section=world', 'world'],
+    ['/devtools-times/?section=politics', 'politics'],
+    ['/devtools-times/multimedia', 'multimedia'],
+    ['/devtools-times/reports/', 'reports'],
+    ['/devtools-times/?section=missing', null],
+    ['/devtools-times/?section=toString', null],
+    ['/devtools-times/articles/story', null],
+    ['/devtools-times/multimedia/story', null],
+    ['/devtools-times/reports/story', null],
+    ['/reports', null],
+  ]) assert.equal(resolve(path), section, path);
+  assert.equal(sectionFromUrl(new URL('https://example.com/?section=world'), '/'), 'world');
+});
+
+test('switching views and history retains DOM identity and local state', async () => {
+  // A small DOM harness exercises the real controller without a browser or server.
+  const listeners = new Map();
+  const windowListeners = new Map();
+  const names = ['top-news', 'world', 'politics', 'multimedia', 'reports'];
+  const views = names.map(name => ({ dataset: { view: name }, hidden: name !== 'top-news', value: '' }));
+  const links = names.map(name => ({
+    dataset: { sectionLink: name },
+    setAttribute(name, value) { this[name] = value; },
+    removeAttribute(name) { delete this[name]; },
+  }));
+  let ViewShell;
+  const addListener = registry => (name, callback, options) => {
+    registry.set(name, { callback, options });
+    options.signal.addEventListener('abort', () => registry.delete(name));
+  };
+  class Element {
+    closest() { return this; }
+  }
+  class HTMLElement extends Element {
+    dataset = { base: '/devtools-times/', active: 'top-news' };
+    querySelectorAll() { return views; }
+    querySelector() { return null; }
+  }
+  const location = { origin: 'https://example.com', href: 'https://example.com/devtools-times/' };
+  const history = {
+    state: { index: 0 }, scrollRestoration: 'auto', entries: [],
+    pushState(state, title, url) { this.entries.push(String(url)); location.href = String(url); },
+  };
+  const window = {
+    scrollY: 0,
+    scrollTo(x, y) { this.scrollY = y; },
+    addEventListener: addListener(windowListeners),
+  };
+  const document = {
+    title: '', addEventListener: addListener(listeners),
+    querySelectorAll() { return links; },
+    getElementById() { return null; },
+  };
+  const source = await readFile(new URL('../src/components/SectionViews.astro', import.meta.url), 'utf8');
+  const script = source.match(/<script>([\s\S]*?)<\/script>/)[1]
+    .replace(/import .*?from .*?;/, '');
+  const run = new Function('HTMLElement', 'Element', 'document', 'window', 'history', 'location',
+    'customElements', 'requestAnimationFrame', 'cancelAnimationFrame', 'sectionFromUrl', 'sectionTitles',
+    stripTypeScriptTypes(script));
+  run(HTMLElement, Element, document, window, history, location,
+    { get() {}, define(name, element) { ViewShell = element; } },
+    callback => { callback(); return 1; }, () => {}, sectionFromUrl,
+    Object.fromEntries(names.map(name => [name, name])));
+  const shell = new ViewShell();
+  shell.connectedCallback();
+  const click = (path, extra = {}) => {
+    const link = Object.assign(new Element(), {
+      href: new URL(path, location.origin).href, target: '', hasAttribute() { return false; },
+    });
+    const event = {
+      target: link, button: 0, defaultPrevented: false,
+      preventDefault() { this.defaultPrevented = true; }, stopImmediatePropagation() {}, ...extra,
+    };
+    listeners.get('click').callback(event);
+    return event;
+  };
+  views[0].value = 'retained input state';
+  window.scrollY = 480;
+  assert.equal(click('/devtools-times/?section=world').defaultPrevented, true);
+  assert.equal(views[0].hidden, true);
+  assert.equal(views[1].hidden, false);
+  assert.equal(window.scrollY, 0);
+  assert.equal(links[1]['aria-current'], 'page');
+  window.scrollY = 210;
+  click('/devtools-times/multimedia');
+  click('/devtools-times/reports');
+  click('/devtools-times/?section=politics');
+  click('/devtools-times/');
+  assert.equal(shell.querySelectorAll()[0], views[0]);
+  assert.equal(views[0].value, 'retained input state');
+  assert.equal(window.scrollY, 480);
+  assert.equal(views.filter(view => !view.hidden).length, 1);
+  assert.equal(click('/devtools-times/reports', { ctrlKey: true }).defaultPrevented, false);
+  assert.equal(click('/devtools-times/articles/story').defaultPrevented, false);
+  assert.equal(click('https://elsewhere.example/devtools-times/reports').defaultPrevented, false);
+  location.href = 'https://example.com/devtools-times/?section=world';
+  let stopped = false;
+  assert.equal(windowListeners.get('popstate').options.capture, true);
+  windowListeners.get('popstate').callback({ stopImmediatePropagation() { stopped = true; } });
+  assert.equal(stopped, true);
+  assert.equal(views[1].hidden, false);
+  assert.equal(window.scrollY, 210);
+  shell.disconnectedCallback();
+  assert.equal(listeners.size, 0);
+  assert.equal(windowListeners.size, 0);
+  assert.equal(history.scrollRestoration, 'auto');
+});

