+        label:hover { background: #fff4e3; }
+        :host(:disabled) { opacity: 0.6; }
+        :host(:disabled) label { cursor: default; }
+        p { margin: 8px 0 0; font: inherit; }
+        #error { color: #a02020; font-weight: 600; }
+        [hidden] { display: none; }
+        @media (forced-colors: active) {
+          svg { stroke: ButtonText; }
+          label[data-filled] svg { fill: Highlight; }
+        }
+      </style>
+      <div class="stars">
+        ${[1, 2, 3, 4, 5].map(value => `
+          <label>
+            <input type="radio" name="stars" value="${value}" aria-label="${value} ${value === 1 ? 'star' : 'stars'}">
+            <svg viewBox="0 0 24 24" aria-hidden="true"><path d="m12 2 3.09 6.26L22 9.27l-5 4.87L18.18 21 12 17.77 5.82 21 7 14.14 2 9.27l6.91-1.01Z"/></svg>
