diff --git a/feedback.js b/feedback.js
new file mode 100644
index 0000000..f6d1bee
--- /dev/null
+++ b/feedback.js
@@ -0,0 +1,21 @@
+const feedbackForm = document.querySelector('#coffee-feedback');
+const feedbackStatus = document.querySelector('#feedback-status');
+
+feedbackForm.addEventListener('submit', event => {
+  event.preventDefault();
+  // Native constraint validation runs before the submit event, including the
+  // custom element's required constraint. FormData includes its rating value.
+  const feedback = Object.fromEntries(new FormData(feedbackForm));
+  try {
+    localStorage.setItem('daily-grind-feedback', JSON.stringify({ ...feedback, savedAt: new Date().toISOString() }));
+    feedbackStatus.textContent = 'Thanks for sharing a little of your day! Your feedback has been saved on this device.';
+  } catch {
+    feedbackStatus.textContent = 'Your browser couldn’t save your feedback. Please allow local storage and try again.';
+  }
+  feedbackStatus.hidden = false;
+});
+
+feedbackForm.addEventListener('reset', () => {
+  feedbackStatus.hidden = true;
+  feedbackStatus.textContent = '';
+});
