+        .rating { display:flex; align-items:center; gap:16px; flex-wrap:wrap; }
+        .stars { display:flex; gap:7px; }
+        .option { position:relative; display:flex; }
+        input { position:absolute; opacity:0; width:1px; height:1px; margin:0; }
+        label { cursor:pointer; display:flex; padding:3px 0; border-radius:3px; }
+        svg { width:32px; height:32px; fill:transparent; stroke:#a9ae9b; stroke-width:1.2; transition:fill .12s,stroke .12s; }
