+        <div class="stars" role="radiogroup" aria-label="Overall experience">
+          ${[1, 2, 3, 4, 5].map(value => `<span class="option"><input type="radio" name="stars" id="star-${value}" value="${value}" aria-label="${value} ${value === 1 ? 'star' : 'stars'} out of 5"><label for="star-${value}" title="${value} out of 5"><svg viewBox="0 0 32 32" aria-hidden="true"><path d="m16 2.8 4.1 8.3 9.2 1.4-6.6 6.5 1.5 9.2L16 23.9l-8.2 4.3 1.5-9.2-6.6-6.5 9.2-1.4Z"/></svg></label></span>`).join('')}
+        </div>
