diff --git a/src/components/Modal.tsx b/src/components/Modal.tsx
new file mode 100644
index 0000000..9958ced
--- /dev/null
+++ b/src/components/Modal.tsx
@@ -0,0 +1,37 @@
+import { useEffect, useRef, type ReactNode } from 'react';
+
+interface Props {
+  id: string;
+  title: string;
+  children: ReactNode;
+  onOpen?: () => void;
+  focusClose?: boolean;
+}
+
+// Keep the dialog mounted so the browser owns focus containment and restoration.
+export default function Modal({ id, title, children, onOpen, focusClose = false }: Props) {
+  const ref = useRef<HTMLDialogElement>(null);
+  const onOpenRef = useRef(onOpen);
+  onOpenRef.current = onOpen;
+  useEffect(() => {
+    const dialog = ref.current!;
+    if (dialog.open) onOpenRef.current?.();
+    const observer = new MutationObserver(() => {
+      if (dialog.open) onOpenRef.current?.();
+    });
+    observer.observe(dialog, { attributes: true, attributeFilter: ['open'] });
+    return () => observer.disconnect();
+  }, []);
+  return (
+    <dialog ref={ref} id={id} className="site-dialog bg-white shadow-xl" aria-labelledby={`${id}-title`}
+      closedby="any">
+      <div className="flex items-center justify-between gap-4 p-4 border-b border-gray-200">
+        <h2 id={`${id}-title`} className="text-lg font-semibold text-gray-800">{title}</h2>
+        <form method="dialog">
+          <button type="submit" autoFocus={focusClose} className="p-2 text-gray-700 hover:text-amber-700">Close</button>
+        </form>
+      </div>
+      {children}
+    </dialog>
+  );
+}
