+(() => {
+  'use strict';
+
+  if (window.dailyGrindPerformance) return;
+
+  const supported = typeof PerformanceObserver === 'undefined'
+    ? [] : PerformanceObserver.supportedEntryTypes || [];
+  const reports = [];
+  const inputs = [];
+  const actions = new Map();
+  const observers = [];
+  const limit = 200;
+  let activeNavigation = null;
+  let largestPaint = null;
+
+  // Bounded local reports and an integration event; no network requests or DOM nodes.
+  function report(metric) {
+    reports.push(Object.freeze(metric));
+    if (reports.length > limit) reports.shift();
+    window.dispatchEvent(new CustomEvent('daily-grind:performance', { detail: metric }));
+  }
+
+  function actionFor(entry) {
+    if (actions.has(entry.interactionId)) return actions.get(entry.interactionId);
+    // ICP starts at the initiating input, which can be pointerdown or keydown,
+    // rather than click. Capture those timestamps without changing event behavior.
+    const input = inputs.findLast((item) => Math.abs(item.startTime - entry.startTime) < 1);
+    if (!input) return null;
+    actions.set(entry.interactionId, input.action);
+    if (actions.size > limit) actions.delete(actions.keys().next().value);
+    return input.action;
+  }
+
+  function captureInput(event) {
+    const element = event.target instanceof Element
+      ? event.target.closest('[data-performance-action]') : null;
+    if (!element) return;
+    inputs.push({ startTime: event.timeStamp, action: element.dataset.performanceAction });
+    if (inputs.length > limit) inputs.shift();
+  }
+
+  function finalizeNavigation() {
+    if (!activeNavigation) return;
+    const navigation = activeNavigation;
+    const paint = largestPaint;
+    activeNavigation = null;
+    largestPaint = null;
+    report({
+      type: 'soft-navigation',
+      action: actionFor(navigation),
+      url: navigation.name,
+      navigationId: navigation.navigationId,
+      interactionId: navigation.interactionId,
+      startTime: navigation.startTime,
+      fcpDuration: navigation.duration,
+      lcpDuration: paint ? paint.presentationTime - navigation.startTime : null,
+      lcpSize: paint?.largestContentfulPaint?.size ?? null,
+    });
+  }
+
+  function handlePaints(entries) {
+    for (const entry of entries) {
+      // navigationId can change after an early paint; interactionId is causal.
+      if (activeNavigation && entry.interactionId === activeNavigation.interactionId &&
+          (!largestPaint || entry.largestContentfulPaint.size >= largestPaint.largestContentfulPaint.size)) {
+        largestPaint = entry;
+      }
+      const action = actionFor(entry);
+      if (!action) continue;
+      report({
+        type: 'interaction-contentful-paint',
+        action,
+        interactionId: entry.interactionId,
+        startTime: entry.startTime,
+        duration: entry.duration,
+        paintTime: entry.paintTime,
+        presentationTime: entry.presentationTime,
+        size: entry.largestContentfulPaint?.size ?? null,
+      });
+    }
+  }
+
+  function handleNavigations(entries) {
+    for (const entry of entries) {
+      finalizeNavigation();
+      activeNavigation = entry;
+      // Include content painted before pushState/replaceState changed the URL.
+      largestPaint = entry.getLargestInteractionContentfulPaint();
+    }
+  }
+
+  function observe(type, handle) {
+    if (!supported.includes(type)) return null;
+    const observer = new PerformanceObserver((list) => handle(list.getEntries()));
+    observer.observe({ type, buffered: true });
+    observers.push(observer);
+    return observer;
+  }
+
+  const events = ['pointerdown', 'pointerup', 'keydown', 'keyup', 'click'];
+  if (supported.includes('interaction-contentful-paint') || supported.includes('soft-navigation')) {
+    for (const type of events) document.addEventListener(type, captureInput, { capture: true, passive: true });
+  }
+  const navigationObserver = observe('soft-navigation', handleNavigations);
+  const paintObserver = observe('interaction-contentful-paint', handlePaints);
+
+  function flush() {
+    // Drain pending callbacks before finalizing, including at pagehide.
+    if (navigationObserver) handleNavigations(navigationObserver.takeRecords());
+    if (paintObserver) handlePaints(paintObserver.takeRecords());
+    finalizeNavigation();
+  }
+
+  function onVisibilityChange() {
+    if (document.visibilityState === 'hidden') flush();
+  }
+  document.addEventListener('visibilitychange', onVisibilityChange);
+  window.addEventListener('pagehide', flush);
+
+  window.dailyGrindPerformance = Object.freeze({
+    supported: Object.freeze({
+      interactionPaint: supported.includes('interaction-contentful-paint'),
+      softNavigation: supported.includes('soft-navigation'),
+    }),
+    getReports: () => reports.slice(),
+    disconnect() {
+      flush();
+      for (const observer of observers) observer.disconnect();
+      for (const type of events) document.removeEventListener(type, captureInput, true);
+      document.removeEventListener('visibilitychange', onVisibilityChange);
+      window.removeEventListener('pagehide', flush);
+      inputs.length = 0;
+      actions.clear();
+    },
+  });
+})();
