--- /dev/null
+++ b/tests/performance-monitor.test.cjs
@@ -0,0 +1,111 @@
+const { test } = require('node:test');
+const assert = require('node:assert/strict');
+const { readFileSync } = require('node:fs');
+const vm = require('node:vm');
+
+const source = readFileSync(require('node:path').join(__dirname, '../performance-monitor.js'), 'utf8');
+
+function setup(types = ['soft-navigation', 'interaction-contentful-paint']) {
+  const observers = new Map();
+  const listeners = new Map();
+  const emitted = [];
+  const document = {
+    visibilityState: 'visible',
+    addEventListener: (type, callback) => listeners.set(type, callback),
+    removeEventListener: (type) => listeners.delete(type),
+  };
+  const window = {
+    addEventListener: (type, callback) => listeners.set(type, callback),
+    removeEventListener: (type) => listeners.delete(type),
+    dispatchEvent: (event) => emitted.push(event.detail),
+  };
+  class Element {
+    constructor(action) { this.dataset = { performanceAction: action }; }
+    closest() { return this; }
+  }
+  class PerformanceObserver {
+    static supportedEntryTypes = types;
+    constructor(callback) { this.callback = callback; this.pending = []; }
+    observe(options) { assert.equal(options.buffered, true); observers.set(options.type, this); }
+    takeRecords() { return this.pending.splice(0); }
+    disconnect() { this.disconnected = true; }
+    deliver(entries) { this.callback({ getEntries: () => entries }); }
+  }
+  const context = vm.createContext({ window, document, PerformanceObserver, Element,
+    CustomEvent: class { constructor(type, options) { this.type = type; this.detail = options.detail; } },
+  });
+  vm.runInContext(source, context);
+  return { window, document, observers, listeners, emitted, context,
+    input(action, timeStamp, type = 'pointerdown') {
+      listeners.get(type)({ target: new Element(action), timeStamp });
+    },
+  };
+}
+
+const paint = (interactionId, startTime, presentationTime, size = 100) => ({
+  interactionId, startTime, presentationTime, paintTime: presentationTime - 1,
+  duration: presentationTime - startTime, largestContentfulPaint: { size },
+});
+const navigation = (interactionId, startTime, seed = null) => ({
+  interactionId, startTime, navigationId: 99, name: 'https://example.test/menu',
+  duration: 40, getLargestInteractionContentfulPaint: () => seed,
+});
+
+test('attributes asynchronous paint candidates to initiating inputs for each requested area', () => {
+  const app = setup();
+  ['navigation:menu', 'order-now', 'seasonal:cold-brew'].forEach((action, index) => {
+    app.input(action, 100 + index * 100, index === 1 ? 'keydown' : 'pointerdown');
+    app.observers.get('interaction-contentful-paint').deliver([
+      paint(index + 1, 100 + index * 100, 180 + index * 100),
+      paint(index + 1, 100 + index * 100, 250 + index * 100, 200),
+    ]);
+    assert.equal(app.emitted.at(-1).action, action);
+    assert.equal(app.emitted.at(-1).duration, 150);
+  });
+  app.observers.get('interaction-contentful-paint').deliver([paint(999, 1000, 1100)]);
+  assert.equal(app.emitted.length, 6);
+});
+
+test('seeds paints before URL updates, matches interaction IDs, and flushes pending paints when hidden', () => {
+  const app = setup();
+  const early = { ...paint(1, 100, 180), navigationId: 1 };
+  app.observers.get('soft-navigation').deliver([navigation(1, 100, early)]);
+  app.observers.get('interaction-contentful-paint').deliver([
+    { ...paint(2, 200, 900, 1000), navigationId: 99 },
+  ]);
+  app.observers.get('soft-navigation').deliver([navigation(3, 300)]);
+  assert.equal(app.emitted.at(-1).lcpDuration, 80);
+  app.observers.get('interaction-contentful-paint').pending.push(paint(3, 300, 550, 200));
+  app.document.visibilityState = 'hidden';
+  app.listeners.get('visibilitychange')();
+  assert.equal(app.emitted.at(-1).lcpDuration, 250);
+  assert.equal(app.emitted.at(-1).fcpDuration, 40);
+  app.listeners.get('pagehide')();
+  assert.equal(app.emitted.length, 2);
+});
+
+test('unsupported APIs degrade safely, including a missing PerformanceObserver', () => {
+  const app = setup([]);
+  assert.equal(app.observers.size, 0);
+  assert.equal(app.window.dailyGrindPerformance.supported.interactionPaint, false);
+  assert.equal(app.listeners.has('click'), false);
+  vm.runInNewContext(source, {
+    window: { addEventListener() {} }, document: { addEventListener() {} },
+  });
+});
+
+test('bounds stored reports, prevents duplicate setup, and disconnects listeners', () => {
+  const app = setup();
+  app.input('order-now', 100);
+  for (let index = 0; index < 250; index++) {
+    app.observers.get('interaction-contentful-paint').deliver([paint(1, 100, 200 + index)]);
+  }
+  assert.equal(app.window.dailyGrindPerformance.getReports().length, 200);
+  app.window.dailyGrindPerformance.getReports().pop();
+  assert.equal(app.window.dailyGrindPerformance.getReports().length, 200);
+  vm.runInContext(source, app.context);
+  assert.equal(app.observers.size, 2);
+  app.window.dailyGrindPerformance.disconnect();
+  assert.equal(app.listeners.size, 0);
+  for (const observer of app.observers.values()) assert.equal(observer.disconnected, true);
+});

