+(() => {
+  'use strict';
+
+  const samples = [];
+  const pending = new Set();
+  let sequence = 0;
+  let eventTimingAvailable = false;
+
+  function report(sample, endTime, source) {
+    if (!pending.delete(sample)) return;
+    cancelAnimationFrame(sample.frame);
+    clearTimeout(sample.timer);
+    clearTimeout(sample.expiry);
+    const metric = Object.freeze({
+      id: sample.id,
+      type: sample.type,
+      target: sample.target,
+      startTime: sample.startTime,
+      duration: Math.max(0, endTime - sample.startTime),
+      source,
+    });
+    samples.push(metric);
+    if (samples.length > 100) {
+      const oldest = samples.shift();
+      performance.clearMeasures(`daily-grind:${oldest.type}:${oldest.target}`);
+    }
+    // Keep the Performance timeline bounded as well as the in-memory history.
+    const name = `daily-grind:${metric.type}:${metric.target}`;
+    try {
+      performance.clearMeasures(name);
+      performance.measure(name, {
+        start: metric.startTime,
+        duration: metric.duration,
+        detail: metric,
+      });
+    } catch { /* Older browsers may not support measure options. */ }
+    window.dispatchEvent(new CustomEvent('daily-grind:performance', { detail: metric }));
+  }
+
+  function begin(type, target, startTime = performance.now()) {
+    if (document.visibilityState !== 'visible') return null;
+    const sample = { id: ++sequence, type, target, startTime };
+    pending.add(sample);
+    // Drop work that never commits, including rejected/abandoned async views.
+    sample.expiry = setTimeout(() => discard(sample), 30000);
+    return sample;
+  }
+
+  function discard(sample) {
+    if (!sample) return;
+    pending.delete(sample);
+    cancelAnimationFrame(sample.frame);
+    clearTimeout(sample.timer);
+    clearTimeout(sample.expiry);
+  }
+
+  function afterPaint(sample) {
+    if (!sample || !pending.has(sample)) return;
+    // rAF alone runs BEFORE paint. A task queued inside it runs after the
+    // rendering opportunity; it is an estimate, not a compositor timestamp.
+    sample.frame = requestAnimationFrame(() => {
+      sample.timer = setTimeout(() => {
+        const endTime = performance.now();
+        // Give Event Timing a chance to supply the actual presentation duration.
+        // This reporting delay is deliberately excluded from the measurement.
+        if (sample.type === 'click' && eventTimingAvailable) {
+          sample.timer = setTimeout(() => report(sample, endTime, 'after-paint-estimate'), 100);
+        } else {
+          report(sample, endTime, 'after-paint-estimate');
+        }
+      }, 0);
+    });
+  }
+
+  try {
+    const observer = new PerformanceObserver((list) => {
+      for (const entry of list.getEntries()) {
+        if (entry.name !== 'click') continue;
+        for (const sample of pending) {
+          if (sample.type === 'click' && Math.abs(entry.startTime - sample.startTime) < 1) {
+            report(sample, entry.startTime + entry.duration, 'event-timing');
+            break;
+          }
+        }
+      }
+    });
+    if (PerformanceObserver.supportedEntryTypes.includes('event')) {
+      observer.observe({ type: 'event', durationThreshold: 16 });
+      eventTimingAvailable = true;
+    }
+  } catch { /* Event Timing is optional; retain the after-paint fallback. */ }
+
+  document.addEventListener('click', (event) => {
+    if (!(event.target instanceof Element)) return;
+    const element = event.target.closest('nav a, [data-performance="order-now"], [data-performance="seasonal-favorites"] .card');
+    if (!element) return;
+    const target = element.matches('nav a')
+      ? `navigation:${element.getAttribute('href')}`
+      : element.matches('.card')
+        ? `seasonal:${element.querySelector('a')?.getAttribute('href') || 'card'}`
+        : 'order-now';
+    // Legacy event timestamps may use epoch time instead of the performance origin.
+    const timestamp = event.timeStamp > performance.timeOrigin
+      ? event.timeStamp - performance.timeOrigin : event.timeStamp;
+    afterPaint(begin('click', target, timestamp || performance.now()));
+  }, { capture: true, passive: true });
+
+  // History API calls cover synchronous client-side routers without changing
+  // their return values, arguments, or navigation behavior.
+  for (const method of ['pushState', 'replaceState']) {
+    const original = history[method];
+    history[method] = function (...args) {
+      const sample = begin('view-switch', method);
+      try {
+        const result = Reflect.apply(original, this, args);
+        afterPaint(sample);
+        return result;
+      } catch (error) {
+        discard(sample);
+        throw error;
+      }
+    };
+  }
+  let lastURL = location.href;
+  for (const eventName of ['popstate', 'hashchange']) {
+    window.addEventListener(eventName, () => {
+      // A hash traversal can dispatch both events for one view change.
+      if (eventName === 'hashchange' && lastURL === location.href) return;
+      lastURL = location.href;
+      afterPaint(begin('view-switch', eventName));
+    });
+  }
+
+  // Do not report background time or an unloaded document as completed paint.
+  document.addEventListener('visibilitychange', () => {
+    if (document.visibilityState === 'hidden') {
+      for (const sample of pending) discard(sample);
+    }
+  });
+  window.addEventListener('pagehide', () => {
+    for (const sample of pending) discard(sample);
+  });
+
+  window.dailyGrindPerformance = Object.freeze({
+    getSamples: () => samples.slice(),
+    // Call before a view update; invoke the returned completion callback once
+    // async data and DOM updates have committed. Each callback completes once.
+    startViewSwitch(target) {
+      const sample = begin('view-switch', String(target));
+      let completed = false;
+      return () => {
+        if (completed) return;
+        completed = true;
+        afterPaint(sample);
+      };
+    },
+  });
+})();
diff --git a/performance-monitor.test.cjs b/performance-monitor.test.cjs
new file mode 100644
index 0000000..92412b9
--- /dev/null
+++ b/performance-monitor.test.cjs
@@ -0,0 +1,147 @@
+const { test } = require('node:test');
+const assert = require('node:assert/strict');
+const { readFileSync } = require('node:fs');
+const vm = require('node:vm');
+
+function setup(eventTiming = false) {
+  let now = 10;
+  let id = 0;
+  let observe;
+  const frames = new Map();
+  const timers = new Map();
+  const listeners = {};
+  const metrics = [];
+  const measures = [];
+  const document = { visibilityState: 'visible', addEventListener: (name, fn) => { listeners[name] = fn; } };
+  class Element {
+    constructor(kind) { this.kind = kind; }
+    closest() { return this; }
+    matches(selector) { return selector === this.kind; }
+    getAttribute() { return '/menu'; }
+    querySelector() { return { getAttribute: () => '/menu/seasonal' }; }
+  }
+  class PerformanceObserver {
+    static supportedEntryTypes = eventTiming ? ['event'] : [];
+    constructor(callback) { observe = callback; }
+    observe() {}
+  }
+  const context = {
+    document, Element, PerformanceObserver,
+    performance: { now: () => now, timeOrigin: 1000000, clearMeasures() {}, measure: (...args) => measures.push(args) },
+    history: {
+      pushState(value) { if (value === 'throw') throw new Error('invalid'); return value; },
+      replaceState(value) { return value; },
+    },
+    location: { href: 'https://example.test/' },
+    requestAnimationFrame: (fn) => { frames.set(++id, fn); return id; },
+    cancelAnimationFrame: (key) => frames.delete(key),
+    setTimeout: (fn, delay) => { timers.set(++id, { fn, delay }); return id; },
+    clearTimeout: (key) => timers.delete(key),
+    CustomEvent: class { constructor(type, options) { this.type = type; this.detail = options.detail; } },
+    addEventListener: (name, fn) => { listeners[name] = fn; },
+    dispatchEvent: (event) => metrics.push(event.detail),
+  };
+  context.window = context;
+  vm.runInNewContext(readFileSync(require.resolve('./performance-monitor.js'), 'utf8'), context);
+  return {
+    context, listeners, metrics, measures,
+    click: (kind) => listeners.click({ target: new Element(kind), timeStamp: now }),
+    frame: () => { now += 16; for (const [key, fn] of [...frames]) { frames.delete(key); fn(); } },
+    task: (delay = 0) => { now += delay; for (const [key, timer] of [...timers]) { if (timer.delay === delay) { timers.delete(key); timer.fn(); } } },
+    entry: (startTime, duration) => observe({ getEntries: () => [{ name: 'click', startTime, duration }] }),
+  };
+}
+
+test('all homepage click targets wait through a rendering opportunity', () => {
+  for (const [kind, target] of [['nav a', 'navigation:/menu'], ['.card', 'seasonal:/menu/seasonal'], ['button', 'order-now']]) {
+    const env = setup();
+    env.click(kind);
+    assert.equal(env.metrics.length, 0);
+    env.frame();
+    assert.equal(env.metrics.length, 0);
+    env.task();
+    assert.equal(env.metrics[0].target, target);
+    assert.equal(env.metrics[0].duration, 16);
+    assert.equal(env.metrics[0].source, 'after-paint-estimate');
+    assert.equal(env.measures.length, 1);
+  }
+});
+
+test('native Event Timing takes precedence and reports once', () => {
+  const env = setup(true);
+  env.click('nav a');
+  env.frame();
+  env.task();
+  env.entry(10, 24);
+  env.task(100);
+  assert.equal(env.metrics.length, 1);
+  assert.equal(env.metrics[0].duration, 24);
+  assert.equal(env.metrics[0].source, 'event-timing');
+});
+
+test('subthreshold events fall back without counting the reporting wait', () => {
+  const env = setup(true);
+  env.click('.card');
+  env.frame();
+  env.task();
+  env.task(100);
+  assert.equal(env.metrics[0].duration, 16);
+});
+
+test('async views wait for explicit commit and complete only once', () => {
+  const env = setup();
+  const complete = env.context.dailyGrindPerformance.startViewSwitch('menu');
+  env.frame();
+  env.task();
+  assert.equal(env.metrics.length, 0);
+  complete();
+  complete();
+  env.frame();
+  env.task();
+  assert.equal(env.metrics.length, 1);
+  assert.equal(env.metrics[0].duration, 32);
+});
+
+test('history methods preserve results and exceptions, and traversal is measured', () => {
+  const env = setup();
+  assert.equal(env.context.history.pushState('result'), 'result');
+  assert.equal(env.context.history.replaceState('replacement'), 'replacement');
+  assert.throws(() => env.context.history.pushState('throw'), /invalid/);
+  env.frame();
+  env.task();
+  assert.equal(env.metrics.length, 2);
+  env.context.location.href += '#menu';
+  env.listeners.popstate();
+  env.listeners.hashchange();
+  env.frame();
+  env.task();
+  assert.equal(env.metrics.length, 3);
+  assert.equal(env.metrics[2].target, 'popstate');
+});
+
+test('hidden and unloaded documents discard unfinished paints', () => {
+  for (const event of ['visibilitychange', 'pagehide']) {
+    const env = setup();
+    env.click('nav a');
+    if (event === 'visibilitychange') env.context.document.visibilityState = 'hidden';
+    env.listeners[event]();
+    env.frame();
+    env.task();
+    assert.equal(env.metrics.length, 0);
+  }
+});
+
+test('sample history is bounded and callers cannot mutate stored metrics', () => {
+  const env = setup();
+  for (let index = 0; index < 105; index++) {
+    env.click('nav a');
+    env.frame();
+    env.task();
+  }
+  const samples = env.context.dailyGrindPerformance.getSamples();
+  assert.equal(samples.length, 100);
+  assert.equal(samples[0].id, 6);
+  assert.ok(Object.isFrozen(samples[0]));
+  samples.pop();
+  assert.equal(env.context.dailyGrindPerformance.getSamples().length, 100);
+});

