+        if (className) node.className = className;
+        return node;
+      }
+
+      function readURL() {
+        const params = new URLSearchParams(window.location.search);
+        const requestedCategory = params.get('category');
+        const requestedSort = params.get('sort');
+        state = {
+          category: categories.has(requestedCategory) ? requestedCategory : 'all',
+          sort: ['price-asc', 'price-desc'].includes(requestedSort) ? requestedSort : 'featured',
+          reverse: params.get('reverse') === 'true',
+          group: params.get('group') === 'true'
+        };
+        category.value = state.category;
+        sort.value = state.sort;
+        reverse.checked = state.reverse;
+        group.checked = state.group;
+      }
+
+      function syncURL() {
