+      }
+
+      function milkSelect(id, value) {
+        const select = element('select');
+        select.id = id;
+        select.name = id;
+        for (const choice of ['Whole', 'Oat']) {
+          const option = element('option', choice);
+          option.value = choice;
+          select.append(option);
+        }
+        select.value = value;
+        return select;
+      }
+
+      function renderOrder() {
+        const content = document.createDocumentFragment();
+        for (const item of order.items) {
+          const row = element('li', undefined, 'order-item');
+          const time = element('time', `Added ${item.addedAt.toLocaleString()}`);
+          time.dateTime = item.addedAt.toISOString();
+          const fields = element('div', undefined, 'order-settings');
+          const milkField = element('div', undefined, 'field');
+          const milkLabel = element('label', `Milk for ${item.name}`);
+          milkLabel.htmlFor = `milk-${item.id}`;
+          const select = milkSelect(milkLabel.htmlFor, item.options.milk);
+          select.addEventListener('change', () => { item.options.milk = select.value; });
+          milkField.append(milkLabel, select);
+          const noteField = element('div', undefined, 'field');
+          const noteLabel = element('label', `Note for ${item.name}`);
+          noteLabel.htmlFor = `note-${item.id}`;
+          const input = element('input');
+          input.type = 'text';
+          input.id = noteLabel.htmlFor;
+          input.name = input.id;
+          input.maxLength = 300;
+          input.value = item.options.note;
+          input.addEventListener('input', () => { item.options.note = input.value; });
+          noteField.append(noteLabel, input);
+          fields.append(milkField, noteField);
+          row.append(element('h3', `${item.name} · ${money.format(item.price)}`), time, fields);
+          content.append(row);
+        }
+        if (!order.items.length) content.append(element('li', 'Your draft is empty. Add a drink to get started.'));
+        byId('order-items').replaceChildren(content);
+        byId('order-total').textContent = `${order.items.length} drink${order.items.length === 1 ? '' : 's'} · Total ${money.format(order.items.reduce((total, item) => total + item.price, 0))}`;
+      }
+
+      controls.addEventListener('change', () => {
+        state = { category: category.value, sort: sort.value, reverse: reverse.checked, group: group.checked };
+        syncURL();
+        renderMenu();
+      });
+      window.addEventListener('popstate', () => { readURL(); renderMenu(); });
+      milk.addEventListener('change', () => { order.options.milk = milk.value; });
+      note.addEventListener('input', () => { order.note = note.value; });
+      byId('menu-items').addEventListener('click', event => {
+        const button = event.target.closest('button[data-add]');
+        if (!button) return;
+        const drink = menu.find(item => item.id === button.dataset.add);
+        if (!drink) return;
+        order.items.push({ ...drink, id: ++nextItemId, menuId: drink.id,
+          options: { milk: order.options.milk, note: order.note }, addedAt: new Date() });
+        renderOrder();
+        byId('order-status').textContent = `${drink.name} added to your draft.`;
+      });
+      byId('save-snapshot').addEventListener('click', () => {
+        snapshot = structuredClone(order);
+        byId('restore-snapshot').disabled = false;
+        byId('snapshot-status').textContent = `Snapshot saved with ${snapshot.items.length} drink(s). Saving again replaces it.`;
+        byId('order-status').textContent = 'Snapshot saved.';
+      });
+      byId('restore-snapshot').addEventListener('click', () => {
+        if (!snapshot) return;
+        // Clone in both directions so repeated restores never share nested objects.
+        order = structuredClone(snapshot);
