+        byId('restore-snapshot').disabled = false;
+        byId('order-status').textContent = `Snapshot saved with ${snapshot.length} ${snapshot.length === 1 ? 'drink' : 'drinks'}.`;
+      });
+      byId('restore-snapshot').addEventListener('click', () => {
+        if (snapshot === null) return;
+        order = copy(snapshot);
+        renderOrder();
+        byId('order-status').textContent = 'Saved snapshot restored.';
+      });
+      byId('clear-order').addEventListener('click', () => {
+        order = [];
+        renderOrder();
+        byId('order-status').textContent = 'Draft order cleared. Your saved snapshot is still available.';
+      });
+      window.addEventListener('popstate', () => { state = readURL(); applyState(); });
+      state = readURL();
+      applyState();
+      renderOrder();
+    })();
