diff --git a/media.js b/media.js
new file mode 100644
index 0000000..a849a5f
--- /dev/null
+++ b/media.js
@@ -0,0 +1,50 @@
+// URLs start in data attributes, protecting posters and metadata from the HTML
+// preload scanner as well as browsers that ignore media loading="lazy".
+const deferredMedia = document.querySelectorAll('[data-lazy-media]');
+
+function loadMedia(media) {
+  if (!media.hasAttribute('data-lazy-media')) return;
+  media.removeAttribute('data-lazy-media');
+
+  if (media.dataset.poster) {
+    media.poster = media.dataset.poster;
+    delete media.dataset.poster;
+  }
+  for (const source of media.querySelectorAll('source[data-src]')) {
+    source.src = source.dataset.src;
+    delete source.dataset.src;
+  }
+  media.preload = media.dataset.preload || 'metadata';
+  delete media.dataset.preload;
+  media.load();
+}
+
+if ('IntersectionObserver' in window) {
+  // Gate URLs in every browser for a consistent, conservative download boundary.
+  const observer = new IntersectionObserver((entries) => {
+    for (const entry of entries) {
+      if (!entry.isIntersecting) continue;
+      loadMedia(entry.target);
+      observer.unobserve(entry.target);
+    }
+  }, { rootMargin: '200px 0px' });
+
+  deferredMedia.forEach((media) => observer.observe(media));
+} else {
+  // Older browsers still defer downloads until the player is nearby.
+  const checkMedia = () => {
+    for (const media of deferredMedia) {
+      const bounds = media.getBoundingClientRect();
+      if (bounds.top <= window.innerHeight + 200 && bounds.bottom >= -200) {
+        loadMedia(media);
+      }
+    }
+    if (![...deferredMedia].some((media) => media.hasAttribute('data-lazy-media'))) {
+      window.removeEventListener('scroll', checkMedia);
+      window.removeEventListener('resize', checkMedia);
+    }
+  };
+  window.addEventListener('scroll', checkMedia, { passive: true });
+  window.addEventListener('resize', checkMedia);
+  checkMedia();
+}
diff --git a/tests/media.test.cjs b/tests/media.test.cjs
new file mode 100644
index 0000000..7bdea1a
--- /dev/null
+++ b/tests/media.test.cjs
@@ -0,0 +1,98 @@
+const { test } = require('node:test');
+const assert = require('node:assert/strict');
+const { readFileSync } = require('node:fs');
+const { runInNewContext } = require('node:vm');
+
+const script = readFileSync(new URL('../media.js', `file://${__filename}`), 'utf8');
+const html = readFileSync(new URL('../index.html', `file://${__filename}`), 'utf8');
+
+function player(poster = false) {
+  let pending = true;
+  const source = { dataset: { src: 'episode.mp4' } };
+  return {
+    dataset: { preload: 'metadata', ...(poster ? { poster: 'poster.jpg' } : {}) },
+    source,
+    preload: 'none',
+    loads: 0,
+    hasAttribute: () => pending,
+    removeAttribute: () => { pending = false; },
+    querySelectorAll: () => [source],
+    load() { this.loads++; },
+    getBoundingClientRect: () => ({ top: 2000, bottom: 2450 }),
+  };
+}
+
+test('offscreen URLs are inert in the original HTML; hero stays eager', () => {
+  const media = [...html.matchAll(/<(video|audio)\b([^>]*)>([\s\S]*?)<\/\1>/g)];
+  assert.equal(media.length, 3);
+  assert.doesNotMatch(media[0][2], /loading="lazy"/);
+  assert.match(media[0][2], /poster="https:/);
+  for (const [, tag, attributes, content] of media.slice(1)) {
+    assert.match(attributes, /loading="lazy"/);
+    assert.match(attributes, /preload="none"/);
+    assert.match(attributes, /\bcontrols\b/);
+    assert.doesNotMatch(attributes, /\sposter=/);
+    assert.doesNotMatch(content, /\ssrc=/);
+    assert.match(content, /data-src=/);
+    if (tag === 'video') {
+      assert.match(attributes, /width="\d+" height="\d+"/);
+      assert.match(attributes, /data-poster=/);
+    }
+  }
+});
+
+test('poster, sources and metadata stay deferred until intersection, then load once', () => {
+  const video = player(true);
+  const audio = player();
+  const observed = [];
+  const unobserved = [];
+  let callback;
+  class IntersectionObserver {
+    constructor(handler, options) {
+      callback = handler;
+      assert.equal(options.rootMargin, '200px 0px');
+    }
+    observe(media) { observed.push(media); }
+    unobserve(media) { unobserved.push(media); }
+  }
+  runInNewContext(script, {
+    document: { querySelectorAll: () => [video, audio] },
+    window: { IntersectionObserver }, IntersectionObserver,
+  });
+  assert.equal(observed.length, 2);
+  callback([{ target: video, isIntersecting: false }]);
+  assert.equal(video.poster, undefined);
+  assert.equal(video.source.src, undefined);
+  assert.equal(video.preload, 'none');
+  assert.equal(audio.loads, 0);
+  callback([{ target: video, isIntersecting: true }]);
+  assert.equal(video.poster, 'poster.jpg');
+  assert.equal(video.source.src, 'episode.mp4');
+  assert.equal(video.preload, 'metadata');
+  assert.equal(video.loads, 1);
+  assert.equal(audio.source.src, undefined);
+  callback([{ target: video, isIntersecting: true }, { target: audio, isIntersecting: true }]);
+  assert.equal(video.loads, 1);
+  assert.equal(audio.loads, 1);
+  assert.equal(audio.preload, 'metadata');
+  assert.ok(unobserved.includes(video));
+  assert.ok(unobserved.includes(audio));
+});
+
+test('fallback also waits for proximity and removes listeners after loading', () => {
+  const media = player(true);
+  const listeners = new Map();
+  runInNewContext(script, {
+    document: { querySelectorAll: () => [media] },
+    window: {
+      innerHeight: 800,
+      addEventListener: (name, handler) => listeners.set(name, handler),
+      removeEventListener: (name) => listeners.delete(name),
+    },
+  });
+  assert.equal(media.loads, 0);
+  media.getBoundingClientRect = () => ({ top: 999, bottom: 1449 });
+  listeners.get('scroll')();
+  assert.equal(media.loads, 1);
+  assert.equal(listeners.size, 0);
+});

