@@ -0,0 +1,62 @@
+(() => {
+  const players = new Set(document.querySelectorAll('[data-media-player]'));
+  let observer;
+
+  function activate(player) {
+    if (!players.delete(player)) return;
+    observer?.unobserve(player);
+
+    // No fetchable source, poster, or artwork URL exists until this point.
+    player.querySelectorAll('[data-poster]').forEach(video => {
+      video.poster = video.dataset.poster;
+      video.removeAttribute('data-poster');
+    });
+    player.querySelectorAll('[data-src]').forEach(asset => {
+      asset.src = asset.dataset.src;
+      asset.removeAttribute('data-src');
+    });
+    player.querySelectorAll('video, audio').forEach(media => {
+      media.preload = 'metadata';
+      media.load();
+    });
+  }
+
+  // Interaction also activates a player when keyboard focus or a fast scroll
+  // reaches it before the observer's next callback.
+  players.forEach(player => {
+    player.addEventListener('focusin', () => activate(player), { once: true });
+    player.addEventListener('pointerdown', () => activate(player), { once: true });
+  });
+
+  if ('IntersectionObserver' in window) {
+    observer = new IntersectionObserver(entries => {
+      entries.forEach(entry => {
+        if (entry.isIntersecting) activate(entry.target);
+      });
+    }, { rootMargin: '200px 0px', threshold: 0 });
+    players.forEach(player => observer.observe(player));
+  } else {
+    // Preserve deferral in older browsers instead of eagerly loading everything.
+    let scheduled = false;
+    function checkViewport() {
+      scheduled = false;
+      players.forEach(player => {
+        const bounds = player.getBoundingClientRect();
+        if (bounds.bottom >= -200 && bounds.top <= window.innerHeight + 200 &&
+            bounds.right >= 0 && bounds.left <= window.innerWidth) activate(player);
+      });
+      if (!players.size) {
+        window.removeEventListener('scroll', scheduleCheck);
+        window.removeEventListener('resize', scheduleCheck);
+      }
+    }
+    function scheduleCheck() {
+      if (scheduled) return;
+      scheduled = true;
+      window.requestAnimationFrame(checkViewport);
+    }
+    window.addEventListener('scroll', scheduleCheck, { passive: true });
+    window.addEventListener('resize', scheduleCheck);
+    checkViewport();
+  }
+})();

