+// All equipment requests run in the page, never through the shop's server.
+document.querySelectorAll('.connection-card').forEach((form) => {
+  const space = form.dataset.space;
+  const permissionName = space === 'local' ? 'local-network' : 'loopback-network';
+  const permissionLabel = space === 'local' ? 'Local network' : 'Loopback network';
+  const input = form.querySelector('input');
+  const button = form.querySelector('[data-connect]');
+  const cancel = form.querySelector('[data-cancel]');
+  const badge = form.querySelector('[data-badge]');
+  const status = form.querySelector('[role="status"]');
+  const permissionNote = form.querySelector('[data-permission]');
+  const initialButton = button.textContent;
+  let permissionStatus;
+  let permissionCheck;
+  let controller;
+
+  function show(state, label, message) {
+    badge.dataset.state = state;
+    badge.textContent = label;
+    status.textContent = message;
+  }
+
+  function updatePermission() {
+    const state = permissionStatus?.state || 'prompt';
+    permissionNote.textContent = state === 'denied'
+      ? `${permissionLabel} access is blocked. Open this browser’s site settings, allow ${permissionLabel}, then try again.`
+      : state === 'granted'
+        ? `${permissionLabel} permission is allowed.`
+        : `${permissionLabel} access may be requested when you connect.`;
+    if (state === 'denied') {
+      controller?.abort();
+      show('error', 'Access blocked', permissionNote.textContent);
+    }
+  }
+
+  async function checkPermission() {
+    if (!permissionCheck) {
+      permissionCheck = (async () => {
+        try {
+          if (!navigator.permissions?.query) return;
+          permissionStatus = await navigator.permissions.query({ name: permissionName });
+          permissionStatus.addEventListener('change', updatePermission);
+        } catch {
+          // Unknown granular permissions: keep requests gated behind a user action.
+        }
+      })();
+    }
+    await permissionCheck;
+    updatePermission();
+    return permissionStatus?.state || 'prompt';
+  }
