+    show('', 'Connecting', 'Checking permission and contacting your equipment…');
+    let timedOut = false;
+    let timeout;
+    try {
+      if (await checkPermission() === 'denied') return;
+      if (attempt.signal.aborted) return;
+      timeout = setTimeout(() => {
+        timedOut = true;
+        attempt.abort();
+      }, 12000);
+      const response = await fetch(url.href, {
+        method: 'GET',
+        mode: 'cors',
+        targetAddressSpace: space,
+        credentials: 'omit',
+        cache: 'no-store',
+        redirect: 'error',
+        referrerPolicy: 'no-referrer',
+        signal: attempt.signal,
+      });
+      if (!response.ok) {
+        show('error', 'Device responded', `The endpoint returned HTTP ${response.status}. Check its status path and device configuration, then try again.`);
+        return;
+      }
+      show('success', 'Reachable', `Connection check succeeded at ${new Date().toLocaleTimeString()}. Your ${space === 'local' ? 'brewer' : 'helper'} responded with HTTP ${response.status}.`);
+      button.textContent = 'Check again';
+    } catch {
+      if (permissionStatus?.state === 'denied') {
+        updatePermission();
+      } else if (attempt.signal.aborted && !timedOut) {
+        show('', 'Not connected', 'Connection check canceled. You can try again.');
+      } else {
+        const deviceHelp = space === 'local'
+          ? 'Check that the brewer is on and you are on the same private Wi-Fi.'
+          : 'Check that the desktop helper is running on this computer at the entered port.';
+        show('error', timedOut ? 'Timed out' : 'Unable to connect', `${timedOut ? 'No response within 12 seconds.' : 'The browser could not read the endpoint.'} ${deviceHelp} Check the URL, browser site permissions, and endpoint CORS settings. Your browser may not support local connections.`);
+      }
+    } finally {
+      clearTimeout(timeout);
+      if (attempt.signal.aborted && !timedOut && permissionStatus?.state !== 'denied') {
+        show('', 'Not connected', 'Connection check canceled. You can try again.');
+      }
+      controller = undefined;
+      button.disabled = false;
+      input.readOnly = false;
+      cancel.hidden = true;
+      form.removeAttribute('aria-busy');
+    }
+  });
+
+  // Permission inspection never contacts either device on page load.
+  checkPermission();
+});
