+++ b/tests/equipment.test.cjs
@@ -0,0 +1,142 @@
+const { test } = require('node:test');
+const assert = require('node:assert/strict');
+const { readFileSync } = require('node:fs');
+const vm = require('node:vm');
+const source = readFileSync(require('node:path').join(__dirname, '../equipment.js'), 'utf8');
+
+function element(value = '') {
+  return {
+    value, textContent: '', dataset: {}, listeners: {}, attributes: {},
+    addEventListener(name, handler) { this.listeners[name] = handler; },
+    setAttribute(name, value) { this.attributes[name] = value; },
+    removeAttribute(name) { delete this.attributes[name]; },
+    setCustomValidity(message) { this.validationMessage = message; },
+    reportValidity() { this.reported = true; },
+  };
+}
+
+async function setup({ permission = 'prompt', secure = true, fetchImpl, unsupported = false } = {}) {
+  const calls = [];
+  const permissions = [];
+  const statuses = [];
+  const forms = ['local', 'loopback'].map((space) => {
+    const form = element();
+    form.dataset.space = space;
+    form.parts = {
+      input: element(space === 'local' ? 'http://192.168.1.100/api/status' : 'http://127.0.0.1:45678/health'),
+      '[data-connect]': element(), '[data-cancel]': element(),
+      '[data-badge]': element(), '[role="status"]': element(), '[data-permission]': element(),
+    };
+    form.querySelector = (selector) => form.parts[selector];
+    return form;
+  });
+  let timeout;
+  vm.runInNewContext(source, {
+    document: { querySelectorAll: () => forms },
+    navigator: { permissions: { query: async ({ name }) => {
+      permissions.push(name);
+      if (unsupported) throw new TypeError('Unknown permission');
+      const status = element();
+      status.state = permission;
+      statuses.push(status);
+      return status;
+    } } },
+    window: { isSecureContext: secure }, URL, AbortController, Date,
+    setTimeout: (callback) => { timeout = callback; return 1; },
+    clearTimeout() {},
+    fetch: async (...args) => {
+      calls.push(args);
+      return fetchImpl ? fetchImpl(...args) : { ok: true, status: 200 };
+    },
+  });
+  await new Promise(setImmediate);
+  return {
+    forms, calls, permissions, statuses,
+    expire: () => timeout(),
+    submit: (index = 0) => forms[index].listeners.submit({ preventDefault() {} }),
+  };
+}
+
+test('no initial requests; each button targets its own address space', async () => {
+  const app = await setup();
+  assert.equal(app.calls.length, 0);
+  assert.deepEqual(app.permissions, ['local-network', 'loopback-network']);
+  await app.submit();
+  await app.submit(1);
+  for (const [index, space] of ['local', 'loopback'].entries()) {
+    const [url, options] = app.calls[index];
+    assert.equal(url, app.forms[index].parts.input.value);
+    assert.equal(options.targetAddressSpace, space);
+    assert.equal(options.mode, 'cors');
+    assert.equal(options.credentials, 'omit');
+    assert.equal(options.redirect, 'error');
+    assert.equal(app.forms[index].parts['[data-badge]'].textContent, 'Reachable');
+  }
+});
+
+test('denied permissions and insecure pages make no requests', async () => {
+  for (const options of [{ permission: 'denied' }, { secure: false }]) {
+    const app = await setup(options);
+    await app.submit();
+    assert.equal(app.calls.length, 0);
+    assert.equal(app.forms[0].parts['[data-badge]'].dataset.state, 'error');
+  }
+});
+
+test('unknown permissions still allow an explicit connection attempt', async () => {
+  const app = await setup({ unsupported: true });
+  assert.equal(app.calls.length, 0);
+  await app.submit(1);
+  assert.equal(app.calls.length, 1);
+});
+
+test('wrong address spaces and unsafe URLs fail validation', async () => {
+  const app = await setup();
+  for (const [index, url] of [
+    [0, 'http://127.0.0.1/health'], [1, 'http://192.168.1.100/status'],
+    [0, 'https://example.com/status'], [0, 'http://user:pass@192.168.1.100/status'],
+    [0, 'ftp://192.168.1.100/status'],
+  ]) {
+    app.forms[index].parts.input.value = url;
+    await app.submit(index);
+    assert.ok(app.forms[index].parts.input.validationMessage);
+  }
+  assert.equal(app.calls.length, 0);
+});
+
+test('HTTP and network failures never show reachable', async () => {
+  for (const fetchImpl of [
+    async () => ({ ok: false, status: 503 }),
+    async () => { throw new TypeError('Failed to fetch'); },
+  ]) {
+    const app = await setup({ fetchImpl });
+    await app.submit();
+    assert.equal(app.forms[0].parts['[data-badge]'].dataset.state, 'error');
+    assert.equal(app.forms[0].parts['[data-connect]'].disabled, false);
+  }
+});
+
+test('cancel and timeout abort pending requests and restore controls', async () => {
+  for (const timedOut of [false, true]) {
+    const app = await setup({ fetchImpl: (_, { signal }) => new Promise((_, reject) => {
+      signal.addEventListener('abort', () => reject(new Error('aborted')));
+    }) });
+    const pending = app.submit();
+    await new Promise(setImmediate);
+    assert.equal(app.calls.length, 1);
+    if (timedOut) app.expire();
+    else app.forms[0].parts['[data-cancel]'].listeners.click();
+    await pending;
+    assert.equal(app.forms[0].parts['[data-badge]'].textContent, timedOut ? 'Timed out' : 'Not connected');
+    assert.equal(app.forms[0].parts['[data-connect]'].disabled, false);
+    assert.equal(app.forms[0].parts.input.readOnly, false);
+  }
+});
+
+test('permission revocation clears a previous successful status', async () => {
+  const app = await setup({ permission: 'granted' });
+  await app.submit();
+  app.statuses[0].state = 'denied';
+  app.statuses[0].listeners.change();
+  assert.equal(app.forms[0].parts['[data-badge]'].textContent, 'Access blocked');
+});

