+++ b/equipment.js
@@ -0,0 +1,110 @@
+(() => {
+  'use strict';
+
+  function equipmentURL(value, kind) {
+    let url;
+    try { url = new URL(value); } catch {
+      throw new Error('Enter a full status URL, including http:// or https://.');
+    }
+    if (!['http:', 'https:'].includes(url.protocol) || url.username || url.password || url.hash) {
+      throw new Error('Use an HTTP or HTTPS URL without a username, password, or fragment.');
+    }
+    const host = url.hostname;
+    const loopback = host === 'localhost' || host === '[::1]' || host === '127.0.0.1';
+    const octets = host.split('.').map(Number);
+    const ipv4 = octets.length === 4 && octets.every(n => Number.isInteger(n) && n >= 0 && n <= 255);
+    const privateLAN = ipv4 && (octets[0] === 10 ||
+      (octets[0] === 192 && octets[1] === 168) ||
+      (octets[0] === 172 && octets[1] >= 16 && octets[1] <= 31));
+    if (kind === 'helper' && !loopback) {
+      throw new Error('Use 127.0.0.1, localhost, or [::1] for the helper on this computer.');
+    }
+    if (kind === 'brewer' && !privateLAN) {
+      throw new Error('Use the brewer’s private Wi-Fi IP address: 192.168.x.x, 10.x.x.x, or 172.16–31.x.x.');
+    }
+    return url;
+  }
+
+  // Export validation for the Node checks; the page itself has no dependencies.
+  if (typeof module !== 'undefined') module.exports = { equipmentURL };
+  if (typeof document === 'undefined') return;
+
+  const count = document.getElementById('connection-count');
+  const cards = ['brewer', 'helper'].map(kind => document.getElementById(`${kind}-card`));
+  const updateCount = () => {
+    count.textContent = `${cards.filter(card => card.dataset.state === 'connected').length} of 2 connected`;
+  };
+
+  for (const kind of ['brewer', 'helper']) {
+    const card = document.getElementById(`${kind}-card`);
+    const input = document.getElementById(`${kind}-address`);
+    const status = document.getElementById(`${kind}-status`);
+    const message = document.getElementById(`${kind}-message`);
+    const buttonLabel = card.querySelector('button span');
+    let request = null;
+
+    function setState(state, detail) {
+      card.dataset.state = state;
+      input.disabled = state === 'connecting' || state === 'connected';
+      input.setAttribute('aria-invalid', 'false');
+      status.textContent = { disconnected: 'Not connected', connecting: 'Connecting…', connected: 'Connected', error: 'Connection failed' }[state];
+      buttonLabel.textContent = state === 'connecting' ? 'Cancel connection' : state === 'connected' ? 'Disconnect' : state === 'error' ? 'Try again' : `Connect ${kind}`;
+      message.textContent = detail;
+      updateCount();
+    }
+
+    card.addEventListener('submit', async event => {
+      event.preventDefault();
+      if (card.dataset.state === 'connecting' || card.dataset.state === 'connected') {
+        const previous = request;
+        request = null;
+        if (previous) previous.abort();
+        setState('disconnected', 'Disconnected. Connect again whenever you’re ready.');
+        return;
+      }
+      let url;
+      try { url = equipmentURL(input.value.trim(), kind); } catch (error) {
+        setState('error', error.message);
+        input.setAttribute('aria-invalid', 'true');
+        input.focus();
+        return;
+      }
+      if (!window.isSecureContext) {
+        setState('error', 'Open this page over HTTPS (or localhost) to connect to local equipment.');
+        return;
+      }
+      const controller = new AbortController();
+      request = controller;
+      let timedOut = false;
+      setState('connecting', 'Contacting your equipment. Allow local network access if prompted.');
+      const timeout = setTimeout(() => { timedOut = true; controller.abort(); }, 12000);
+      try {
+        const response = await fetch(url.href, {
+          method: 'GET',
+          mode: 'cors',
+          credentials: 'omit',
+          cache: 'no-store',
+          redirect: 'error',
+          referrerPolicy: 'no-referrer',
+          targetAddressSpace: kind === 'brewer' ? 'local' : 'loopback',
+          signal: controller.signal
+        });
+        if (request !== controller) return;
+        if (!response.ok) throw new Error(`Equipment replied with HTTP ${response.status}. Check the status URL and try again.`);
+        if (response.type === 'opaque') throw new Error('The response could not be read. Allow this website’s origin in your equipment’s CORS settings.');
+        setState('connected', `Status endpoint reached. Last checked at ${new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}.`);
+      } catch (error) {
+        if (request !== controller) return;
+        const troubleshooting = kind === 'brewer' ? 'Check the brewer is on and you’re on the same Wi-Fi.' : 'Check the desktop helper is running on this computer.';
+        setState('error', timedOut
+          ? `No response after 12 seconds. ${troubleshooting} Allow browser network access, then retry.`
+          : error instanceof TypeError
+            ? `Couldn’t reach the equipment. ${troubleshooting} Allow local network access in site settings and ensure the equipment allows this site through CORS.`
+            : error.message);
+      } finally {
+        clearTimeout(timeout);
+        if (request === controller) request = null;
+      }
+    });
+  }
+})();
