+++ b/tests/equipment.test.cjs
@@ -0,0 +1,103 @@
+const { test } = require('node:test');
+const assert = require('node:assert/strict');
+const fs = require('node:fs');
+const vm = require('node:vm');
+const { equipmentURL } = require('../equipment.js');
+
+function page(fetchImpl, secure = true) {
+  const elements = new Map();
+  for (const id of ['connection-count', ...['brewer', 'helper'].flatMap(k => ['card', 'address', 'status', 'message'].map(s => `${k}-${s}`))]) {
+    elements.set(id, {
+      dataset: { state: 'disconnected' }, textContent: '', disabled: false,
+      attributes: {}, setAttribute(k, v) { this.attributes[k] = v; }, focus() {},
+      label: {}, querySelector() { return this.label; },
+      addEventListener(event, handler) { this.submit = handler; }
+    });
+  }
+  elements.get('brewer-address').value = 'http://192.168.1.100/api/status';
+  elements.get('helper-address').value = 'http://127.0.0.1:8765/api/status';
+  vm.runInNewContext(fs.readFileSync(require.resolve('../equipment.js'), 'utf8'), {
+    document: { getElementById: id => elements.get(id) }, window: { isSecureContext: secure },
+    URL, AbortController, TypeError, setTimeout, clearTimeout, fetch: fetchImpl
+  });
+  return { get: id => elements.get(id), submit: kind => elements.get(`${kind}-card`).submit({ preventDefault() {} }) };
+}
+
+test('allows private LAN and loopback endpoints, including ports and paths', () => {
+  for (const host of ['192.168.1.8', '10.2.3.4', '172.16.0.1', '172.31.255.254']) {
+    assert.equal(equipmentURL(`http://${host}:8080/status`, 'brewer').port, '8080');
+  }
+  for (const host of ['127.0.0.1', 'localhost', '[::1]']) {
+    assert.equal(equipmentURL(`http://${host}:8765/api/status`, 'helper').pathname, '/api/status');
+  }
+});
+
+test('rejects public, wrong-device, malformed and credential-bearing URLs', () => {
+  for (const url of ['http://172.32.0.1', 'http://8.8.8.8', 'http://localhost', 'http://example.com', 'ftp://192.168.1.1', 'http://u:p@192.168.1.1', 'http://192.168.1.1/#secret', 'bad']) {
+    assert.throws(() => equipmentURL(url, 'brewer'));
+  }
+  assert.throws(() => equipmentURL('http://192.168.1.1', 'helper'));
+  assert.throws(() => equipmentURL('http://127.0.0.1.example.com', 'helper'));
+});
+
+test('no initial requests; independent user-triggered CORS checks target both address spaces', async () => {
+  const calls = [];
+  const p = page(async (url, options) => { calls.push({ url, options }); return { ok: true, type: 'cors' }; });
+  assert.equal(calls.length, 0);
+  await p.submit('brewer');
+  await p.submit('helper');
+  assert.equal(p.get('connection-count').textContent, '2 of 2 connected');
+  assert.deepEqual(calls.map(c => c.options.targetAddressSpace), ['local', 'loopback']);
+  for (const { options } of calls) {
+    assert.equal(options.mode, 'cors');
+    assert.equal(options.credentials, 'omit');
+    assert.equal(options.redirect, 'error');
+  }
+  await p.submit('helper');
+  assert.equal(p.get('connection-count').textContent, '1 of 2 connected');
+  assert.equal(p.get('helper-address').disabled, false);
+  assert.equal(calls.length, 2);
+});
+
+test('failed HTTP responses can retry without reporting a connection', async () => {
+  let success = false;
+  const p = page(async () => ({ ok: success, status: 404 }));
+  await p.submit('brewer');
+  assert.equal(p.get('brewer-card').dataset.state, 'error');
+  assert.match(p.get('brewer-message').textContent, /HTTP 404/);
+  success = true;
+  await p.submit('brewer');
+  assert.equal(p.get('brewer-card').dataset.state, 'connected');
+});
+
+test('cancelling ignores a late response and aborts the request', async () => {
+  let finish, signal;
+  const p = page((url, options) => { signal = options.signal; return new Promise(resolve => { finish = resolve; }); });
+  const pending = p.submit('helper');
+  assert.equal(p.get('helper-card').dataset.state, 'connecting');
+  await p.submit('helper');
+  assert.equal(signal.aborted, true);
+  finish({ ok: true });
+  await pending;
+  assert.equal(p.get('helper-card').dataset.state, 'disconnected');
+});
+
+test('insecure pages and invalid addresses do not send requests', async () => {
+  let calls = 0;
+  const p = page(async () => { calls++; }, false);
+  await p.submit('brewer');
+  assert.match(p.get('brewer-message').textContent, /HTTPS/);
+  p.get('helper-address').value = 'http://example.com';
+  await p.submit('helper');
+  assert.equal(p.get('helper-address').attributes['aria-invalid'], 'true');
+  assert.equal(calls, 0);
+});
+
+test('network restrictions show actionable feedback without claiming success', async () => {
+  const p = page(async () => { throw new TypeError('Failed to fetch'); });
+  await p.submit('helper');
+  assert.equal(p.get('helper-card').dataset.state, 'error');
+  assert.match(p.get('helper-message').textContent, /CORS/);
+  assert.match(p.get('helper-message').textContent, /helper is running/);
+  assert.equal(p.get('connection-count').textContent, '0 of 2 connected');
+});

