+
+function Connection({ space }: { space: AddressSpace }) {
+  const lan = space === 'local';
+  const name = lan ? 'Hardware test device' : 'Companion CLI';
+  const permissionName = lan ? 'local-network' : 'loopback-network';
+  const id = useId();
+  const [endpoint, setEndpoint] = useState(lan ? 'http://192.168.1.100:8080/health' : 'http://127.0.0.1:45678/health');
+  const [permission, setPermission] = useState<PermissionState | 'unknown'>('unknown');
+  const [state, setState] = useState<'idle' | 'loading' | 'success' | 'error'>('idle');
+  const [message, setMessage] = useState('Ready when you are.');
+  const [invalid, setInvalid] = useState(false);
+  const [response, setResponse] = useState('');
+  const [secure, setSecure] = useState(true);
+  const [supported, setSupported] = useState(true);
+  const active = useRef<AbortController | null>(null);
+  const permissionStatus = useRef<PermissionStatus | null>(null);
+
+  useEffect(() => {
+    setSecure(window.isSecureContext);
+    setSupported('targetAddressSpace' in Request.prototype);
+    let disposed = false;
+    const update = () => {
+      const current = permissionStatus.current?.state;
+      if (current) setPermission(current);
+      if (current === 'denied') {
+        active.current?.abort();
+        setState('error');
+        setResponse('');
+        setMessage('Access is blocked. Allow access in browser site settings, then try again.');
+      }
+    };
+    // Unknown names are unsupported in some browsers; never query the legacy alias.
+    navigator.permissions?.query({ name: permissionName as PermissionName }).then(status => {
+      if (disposed) return;
+      permissionStatus.current = status;
+      update();
+      status.addEventListener('change', update);
+    }).catch(() => { /* Keep manual connection available on unsupported browsers. */ });
+    return () => {
+      disposed = true;
+      active.current?.abort();
+      permissionStatus.current?.removeEventListener('change', update);
+    };
+  }, [permissionName]);
+
+  async function connect(event: FormEvent<HTMLFormElement>) {
+    event.preventDefault();
+    if (active.current) return;
+    let url: URL;
+    try {
+      url = diagnosticsUrl(endpoint, space);
+    } catch (error) {
+      setInvalid(true);
+      setState('error');
+      setMessage((error as Error).message);
+      event.currentTarget.querySelector('input')?.focus();
+      return;
+    }
+    if (!window.isSecureContext || permissionStatus.current?.state === 'denied') {
+      setState('error');
+      setMessage(!window.isSecureContext ? 'Open The DevTools Times over HTTPS to connect.' : 'Access is blocked. Allow access in browser site settings, then try again.');
+      return;
+    }
+    const controller = new AbortController();
+    active.current = controller;
+    setState('loading');
+    setResponse('');
+    setMessage('Connecting… Allow browser access if prompted.');
+    let timedOut = false;
+    const timeout = window.setTimeout(() => { timedOut = true; controller.abort(); }, 20000);
