+      setState('error');
+      setMessage(controller.signal.aborted
+        ? (timedOut ? 'Connection timed out. Check the endpoint and retry; allow browser access if prompted.' : 'Connection cancelled or permission changed. You can try again.')
+        : error instanceof TypeError
+          ? `Could not connect. ${lan ? 'Power on the device and join the same Wi-Fi network.' : 'Start your companion CLI and check its listening port.'} Check browser site permissions and endpoint CORS settings. Your browser may require an HTTPS endpoint.`
+          : (error as Error).message);
+    } finally {
+      window.clearTimeout(timeout);
+      active.current = null;
+    }
+  }
