+        </div>
+        <span className={`rounded-full px-2 py-1 text-xs font-medium ${state === 'success' ? 'bg-green-50 text-green-800' : state === 'error' ? 'bg-red-50 text-red-800' : 'bg-gray-100 text-gray-600'}`}>
