+        </span>
+      </div>
+      <p className="mb-4 text-sm text-gray-600">{lan ? 'Check a test device on the same network as your browser.' : 'Check a companion service running on your own computer.'}</p>
+      <label htmlFor={`${id}-url`} className="mb-1 block text-sm font-medium text-gray-800">Endpoint URL <span className="font-normal text-gray-500">(required)</span></label>
