+import test from 'node:test';
+import assert from 'node:assert/strict';
+import { diagnosticsUrl, diagnosticsRequest } from '../src/utils/diagnostics.ts';
+
+test('LAN endpoints accept private addresses and preserve ports and paths', () => {
+  for (const endpoint of ['http://192.168.1.100:8080/health', 'https://10.0.0.2/status', 'http://172.16.0.1/health', 'http://172.31.255.255/health', 'http://device.local/health']) {
+    assert.equal(diagnosticsUrl(endpoint, 'local').href, endpoint);
+  }
+});
+
+test('companion endpoints accept loopback addresses', () => {
+  for (const endpoint of ['http://127.0.0.1:45678/health', 'http://localhost/health', 'http://[::1]/health']) {
+    assert.equal(diagnosticsUrl(endpoint, 'loopback').href, endpoint);
+  }
+});
+
+test('rejects unrelated hosts, unsafe URLs, and mismatched address spaces', () => {
+  for (const space of ['local', 'loopback']) {
+    for (const endpoint of ['not a URL', 'https://example.com/health', 'http://192.168.1.100.example.com/health', 'file:///health', 'javascript:alert(1)', 'http://user:password@127.0.0.1/health', 'http://127.0.0.1/health#fragment']) {
+      assert.throws(() => diagnosticsUrl(endpoint, space));
+    }
+  }
+  assert.throws(() => diagnosticsUrl('http://127.0.0.1/health', 'local'));
+  assert.throws(() => diagnosticsUrl('http://192.168.1.1/health', 'loopback'));
+  assert.throws(() => diagnosticsUrl('http://172.32.0.1/health', 'local'));
+});
+
+test('requests declare their address space, read via CORS, and omit credentials', () => {
+  for (const space of ['local', 'loopback']) {
+    const signal = new AbortController().signal;
+    const options = diagnosticsRequest(space, signal);
+    assert.equal(options.targetAddressSpace, space);
+    assert.equal(options.mode, 'cors');
+    assert.equal(options.method, 'GET');
+    assert.equal(options.credentials, 'omit');
+    assert.equal(options.redirect, 'error');
+    assert.equal(options.referrerPolicy, 'no-referrer');
+    assert.equal(options.signal, signal);
+    assert.equal(options.headers, undefined);
+  }
+});

