+type NetworkPermission = 'local-network' | 'loopback-network';
+type Check = { state: 'idle' | 'pending' | 'success' | 'error'; message: string };
+
+function ConnectionCard({ space, title, description, initialUrl, number }: {
+  space: AddressSpace; title: string; description: string; initialUrl: string; number: string;
+}) {
+  const [url, setUrl] = useState(initialUrl);
+  const [permission, setPermission] = useState<PermissionState | 'unknown'>('unknown');
+  const [check, setCheck] = useState<Check>({ state: 'idle', message: 'Ready when you are. No connection attempted.' });
+  const active = useRef<AbortController | null>(null);
+  const permissionName: NetworkPermission = space === 'local' ? 'local-network' : 'loopback-network';
+  const inputId = `diagnostics-${space}`;
+
+  useEffect(() => {
+    let disposed = false;
+    let status: PermissionStatus | undefined;
+    const update = () => {
+      if (!disposed && status) setPermission(status.state);
+    };
+    // Older browsers may not recognize these granular permission names.
+    navigator.permissions?.query({ name: permissionName as PermissionName }).then(result => {
+      if (disposed) return;
+      status = result;
+      update();
+      status.addEventListener('change', update);
+    }).catch(() => { /* The explicit connection attempt remains available. */ });
+    return () => {
+      disposed = true;
+      status?.removeEventListener('change', update);
+      active.current?.abort();
+      active.current = null;
+    };
+  }, [permissionName]);
+
+  async function connect(event: FormEvent) {
+    event.preventDefault();
+    if (active.current) return;
+    let endpoint: URL;
+    try {
+      endpoint = parseEndpoint(url, space);
+      if (!window.isSecureContext) throw new Error('Open The DevTools Times over HTTPS to connect to local services.');
+      if (permission === 'denied') throw new Error(`Allow ${space === 'local' ? 'Local network' : 'Loopback network'} access in your browser’s site settings, then retry.`);
+    } catch (error) {
+      setCheck({ state: 'error', message: (error as Error).message });
+      return;
+    }
+    const controller = new AbortController();
+    active.current = controller;
+    let timedOut = false;
+    const timeout = window.setTimeout(() => { timedOut = true; controller.abort(); }, 15000);
+    const start = performance.now();
+    setCheck({ state: 'pending', message: 'Connecting… Allow browser access if prompted.' });
+    try {
+      const options: RequestInit & { targetAddressSpace: AddressSpace } = {
+        method: 'GET', mode: 'cors', credentials: 'omit', cache: 'no-store',
+        redirect: 'error', referrerPolicy: 'no-referrer', signal: controller.signal,
+        targetAddressSpace: space,
+      };
+      const response = await fetch(endpoint.href, options);
+      // A readable successful response establishes reachability; no payload is collected.
+      void response.body?.cancel().catch(() => {});
+      if (!response.ok) throw new Error(`Service responded with HTTP ${response.status}. Check the endpoint path and service configuration.`);
+      if (active.current === controller) setCheck({ state: 'success', message: `Reachable · HTTP ${response.status} · ${Math.round(performance.now() - start)} ms. Check complete; no persistent connection.` });
+    } catch (error) {
+      if (active.current !== controller) return;
+      let message = error instanceof Error && error.name !== 'TypeError' ? error.message
+        : 'Could not connect. Check the address, service, browser site permissions, and CORS settings. This browser may not support HTTP local connections from HTTPS.';
