+      setCheck({ state: 'error', message });
+    } finally {
+      window.clearTimeout(timeout);
+      if (active.current === controller) active.current = null;
+    }
+  }
+
+  return (
+    <form onSubmit={connect} className="flex flex-col rounded-lg border border-slate-200 bg-white p-5 sm:p-6">
+      <div className="mb-4 flex items-center justify-between gap-3">
+        <span className="font-mono text-xs tracking-widest text-slate-500">{number} / {space === 'local' ? 'PRIVATE LAN' : 'THIS MACHINE'}</span>
+        <span className={`rounded-full px-2.5 py-1 text-xs font-medium ${check.state === 'success' ? 'bg-emerald-50 text-emerald-800' : check.state === 'error' ? 'bg-amber-50 text-amber-900' : 'bg-slate-100 text-slate-600'}`}>
+          {check.state === 'success' ? 'Reachable' : check.state === 'pending' ? 'Connecting' : check.state === 'error' ? 'Needs attention' : 'Not connected'}
+        </span>
+      </div>
+      <h3 className="text-xl font-bold tracking-tight text-slate-900">{title}</h3>
+      <p className="mb-5 mt-2 text-sm leading-relaxed text-slate-600">{description}</p>
+      <label htmlFor={inputId} className="mb-2 text-xs font-semibold text-slate-700">Health endpoint URL</label>
+      <input id={inputId} type="url" required value={url} disabled={check.state === 'pending'} onChange={event => {
+        setUrl(event.target.value);
+        setCheck({ state: 'idle', message: 'Address changed. Connect to check this endpoint.' });
+      }} spellCheck={false} autoComplete="off" aria-describedby={`${inputId}-status ${inputId}-permission`}
+        className="min-w-0 w-full rounded border border-slate-300 bg-slate-50 px-3 py-3 font-mono text-sm text-slate-800 outline-none focus:border-slate-800 focus:ring-2 focus:ring-slate-300 disabled:opacity-60" />
+      <p id={`${inputId}-permission`} className="mt-2 text-xs text-slate-500">Browser permission: {permission === 'unknown' ? 'checked when connecting' : permission === 'prompt' ? 'ask on connect' : permission}.</p>
+      {permission === 'denied' && <p className="mt-2 text-sm text-amber-900">Enable {space === 'local' ? 'Local network' : 'Loopback network'} access in this site’s browser settings, then retry.</p>}
+      <div className="mt-5 flex gap-2">
+        <button type="submit" disabled={check.state === 'pending'} className="rounded bg-slate-900 px-4 py-2.5 text-sm font-semibold text-white transition hover:bg-slate-700 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-slate-800 disabled:cursor-wait disabled:opacity-50">
