+      </div>
+      <p id={`${inputId}-status`} role="status" aria-live="polite" className={`mt-4 min-h-10 text-xs leading-relaxed ${check.state === 'error' ? 'text-amber-900' : 'text-slate-600'}`}>{check.message}</p>
+    </form>
+  );
+}
+
+export default function DiagnosticsWidget() {
+  return (
+    <section aria-labelledby="diagnostics-title" className="my-8 border-y border-slate-300 bg-slate-50 px-4 py-7 sm:px-6 sm:py-8">
