@@ -0,0 +1,23 @@
+export function normalizeOrigin(value, source) {
+  let url;
+  try { url = new URL(value.trim()); } catch { throw new Error('Enter a complete origin, for example https://app.example.com.'); }
+  if (url.protocol !== 'https:') throw new Error('Use a secure origin beginning with https://.');
+  if (url.username || url.password || url.pathname !== '/' || url.search || url.hash) throw new Error('Enter only a protocol and domain, without credentials, a path, or query parameters.');
+  if (url.origin === source) throw new Error('Choose a different origin from your current installation.');
+  return url.origin;
+}
+export function createPackage({ source, destination, configuration, preferences, shortcuts }) {
+  return {
+    format: 'waypoint-transfer', version: 1, app: 'Orbit', createdAt: new Date().toISOString(),
+    source, destination: normalizeOrigin(destination, source),
+    configuration: configuration ? { ...preferences } : null,
+    shortcuts: shortcuts ? [{ name: 'Orbit', url: new URL('/', destination).href }] : [],
+    instructions: 'Import at the destination origin. Install the destination web app through your browser and replace OS shortcuts manually. The current installation is unchanged.'
+  };
+}
+export function validateImport(data, origin) {
+  if (!data || data.format !== 'waypoint-transfer' || data.version !== 1 || data.app !== 'Orbit') throw new Error('Choose a valid Waypoint transfer package for Orbit.');
+  if (data.destination !== origin) throw new Error('Open Waypoint at the package’s destination origin before importing.');
+  if (data.configuration !== null && (!data.configuration || !['system', 'light', 'dark'].includes(data.configuration.appearance) || typeof data.configuration.notifications !== 'boolean')) throw new Error('This package contains invalid preferences.');
+  return data.configuration === null ? null : { appearance: data.configuration.appearance, notifications: data.configuration.notifications };
+}
diff --git a/transfer.test.js b/transfer.test.js
new file mode 100644
index 0000000..f0ebae2
--- /dev/null
+++ b/transfer.test.js
@@ -0,0 +1,30 @@
+import test from 'node:test';
+import assert from 'node:assert/strict';
+import { normalizeOrigin, createPackage, validateImport } from './transfer.js';
+const source = 'https://old.example.com';
+const destination = 'https://new.example.com';
+test('normalizes an HTTPS origin and rejects unsafe or ambiguous destinations', () => {
+  assert.equal(normalizeOrigin(' https://NEW.example.com:443/ ', source), destination);
+  for (const input of [source, 'http://example.com', 'javascript:alert(1)', 'https://a.com/path', 'https://a.com/?a=b', 'https://a.com/#hash', 'https://user:secret@a.com', 'invalid']) assert.throws(() => normalizeOrigin(input, source));
+});
+test('packages selected configuration and rewrites shortcut destinations', () => {
+  const preferences = { appearance: 'dark', notifications: false };
+  const result = createPackage({ source, destination, configuration: true, preferences, shortcuts: true });
+  assert.deepEqual(result.configuration, preferences);
+  assert.notEqual(result.configuration, preferences);
+  assert.equal(result.shortcuts[0].url, destination + '/');
+  assert.deepEqual(validateImport(JSON.parse(JSON.stringify(result)), destination), preferences);
+  assert.throws(() => validateImport(result, source));
+});
+test('excluded preferences and shortcuts are not exported', () => {
+  const result = createPackage({ source, destination, configuration: false, preferences: { appearance: 'dark', notifications: true }, shortcuts: false });
+  assert.equal(result.configuration, null);
+  assert.deepEqual(result.shortcuts, []);
+  assert.equal(validateImport(result, destination), null);
+});
+test('import rejects invalid formats and invalid preference values', () => {
+  assert.throws(() => validateImport({}, destination));
+  const data = createPackage({ source, destination, configuration: true, preferences: { appearance: 'dark', notifications: true }, shortcuts: false });
+  assert.throws(() => validateImport({ ...data, configuration: { appearance: 'bad', notifications: true } }, destination));
