+  <script>
+    const track = document.getElementById('drink-track');
+    const previous = document.getElementById('previous-drink');
+    const next = document.getElementById('next-drink');
+    const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)');
+
+    function updateControls() {
+      previous.disabled = track.scrollLeft <= 1;
+      next.disabled = track.scrollLeft >= track.scrollWidth - track.clientWidth - 1;
+    }
+
+    function moveDrinks(direction) {
+      const step = track.querySelector('.card').getBoundingClientRect().width + 20;
+      track.scrollBy({ left: direction * step, behavior: reducedMotion.matches ? 'instant' : 'smooth' });
+    }
+
+    previous.addEventListener('click', () => moveDrinks(-1));
+    next.addEventListener('click', () => moveDrinks(1));
+    track.addEventListener('scroll', updateControls, { passive: true });
+    new ResizeObserver(updateControls).observe(track);
+    track.addEventListener('keydown', (event) => {
+      if (event.target !== track) return;
+      if (event.key === 'ArrowLeft' || event.key === 'ArrowRight') {
+        event.preventDefault();
+        moveDrinks(event.key === 'ArrowLeft' ? -1 : 1);
+      }
+    });
+    updateControls();
+
+    document.querySelectorAll('.detail-toggle').forEach((button) => {
+      const panel = document.getElementById(button.getAttribute('aria-controls'));
+      const drinkName = button.closest('.card').querySelector('h3').textContent;
+      let animation;
+
+      function setExpanded(expanded) {
+        // Capture the current frame so reversing an animation stays smooth.
+        const current = panel.getBoundingClientRect();
+        const currentStyle = getComputedStyle(panel);
+        const currentOpacity = currentStyle.opacity;
+        const currentMargin = currentStyle.marginTop;
+        const currentRadius = currentStyle.borderRadius;
+        const wasHidden = panel.hidden;
+        animation?.cancel();
+        button.setAttribute('aria-expanded', String(expanded));
+        button.textContent = expanded ? 'Hide Details' : 'View Details';
+        button.setAttribute('aria-label', `${expanded ? 'Hide' : 'View'} details for ${drinkName}`);
+        panel.inert = !expanded;
+        panel.hidden = false;
+
+        if (reducedMotion.matches) {
+          panel.hidden = !expanded;
+          return;
+        }
+
+        const full = panel.getBoundingClientRect();
+        const buttonWidth = button.getBoundingClientRect().width;
+        const collapsed = { height: '0px', width: `${buttonWidth}px`, opacity: 0, marginTop: '0px', borderRadius: '5px' };
+        const opened = { height: `${full.height}px`, width: `${full.width}px`, opacity: 1, marginTop: '12px', borderRadius: '8px' };
+        const start = wasHidden ? collapsed : {
+          height: `${current.height}px`, width: `${current.width}px`,
+          opacity: currentOpacity, marginTop: currentMargin, borderRadius: currentRadius
+        };
+        animation = panel.animate([start, expanded ? opened : collapsed], {
+          duration: 320, easing: 'cubic-bezier(0.22, 1, 0.36, 1)', fill: 'both'
+        });
+        const activeAnimation = animation;
+        activeAnimation.onfinish = () => {
+          panel.hidden = !expanded;
+          activeAnimation.cancel();
+          animation = undefined;
+        };
+      }
+
+      button.addEventListener('click', () => setExpanded(button.getAttribute('aria-expanded') !== 'true'));
+      panel.addEventListener('keydown', (event) => {
+        if (event.key === 'Escape') {
