+const $ = selector => document.querySelector(selector);
+// Omit passkey-api to use the static preview. Production must provide authenticated endpoints.
+const apiBase = $('meta[name="passkey-api"]')?.content || '';
+let storage;
+try { storage = window.localStorage; } catch { /* Show actionable errors when a user tries to persist. */ }
+const repository = createRepository({ apiBase, storage, csrfToken: $('meta[name="csrf-token"]')?.content || '' });
+const list = $('#credential-list');
+const status = $('#status');
+let snapshot = { credentials: [] };
+let selectedId = null;
+let busy = false;
+const providers = {
+  'dd4ec289-e01d-41c9-bb89-70fa845d4bf2': { name: 'iCloud Keychain', icon: 'cloud' },
+  'ea9b8d66-4d01-1d21-3ce4-b6b48cb575d4': { name: 'Google Password Manager', icon: 'key' },
+  'bada5566-a7aa-401f-bd96-45619a55120d': { name: '1Password', icon: 'key' },
+};
+const dateFormat = new Intl.DateTimeFormat('en', { month: 'short', day: 'numeric', year: 'numeric' });
+function icon(name, className) {
+  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
+  const use = document.createElementNS(svg.namespaceURI, 'use');
+  use.setAttribute('href', `#${name}`);
+  svg.setAttribute('aria-hidden', 'true');
+  if (className) svg.setAttribute('class', className);
+  svg.append(use);
+  return svg;
+}
+function element(tag, className, text) {
+  const node = document.createElement(tag);
+  if (className) node.className = className;
+  if (text !== undefined) node.textContent = text;
+  return node;
+}
+function announce(message, error = false) {
+  status.textContent = message;
+  status.classList.toggle('error', error);
+}
+function dateNode(timestamp) {
+  const date = element('time', '', dateFormat.format(timestamp));
+  date.dateTime = new Date(timestamp).toISOString();
+  return date;
+}
+function render() {
+  list.replaceChildren();
+  $('#key-count').textContent = snapshot.credentials.length;
+  if (!snapshot.credentials.length) {
+    const empty = element('div', 'empty-state');
+    empty.append(icon('key'), element('strong', '', 'A fresh start.'), element('p', '', 'You don’t have any registered passkeys. Use another sign-in method to access your account.'));
+    list.append(empty);
+    return;
+  }
+  for (const credential of snapshot.credentials) {
+    const row = element('article', 'credential-row');
+    const device = ['laptop', 'phone', 'key'].includes(credential.device) ? credential.device : 'key';
+    const image = element('span', 'device-icon');
+    image.append(icon(device));
+    const info = element('div', 'credential-info');
+    const title = element('div', 'credential-title');
+    const heading = element('h4', '', credential.name || 'Unnamed passkey');
+    title.append(heading);
+    const provider = providers[credential.aaguid] || { name: 'Unknown passkey provider', icon: 'key' };
+    const dates = element('div', 'credential-dates');
+    const registered = element('span', '', 'Added ');
+    registered.append(dateNode(credential.registeredAt));
+    const lastUsed = element('span', '', 'Last used ');
+    lastUsed.append(credential.lastUsedAt == null ? document.createTextNode('Not used yet') : dateNode(credential.lastUsedAt));
+    dates.append(registered, element('span', '', '·'), lastUsed);
+    const providerLabel = element('p', 'credential-provider');
+    providerLabel.append(icon(provider.icon), document.createTextNode(provider.name));
+    info.append(title, providerLabel, dates);
+    const actions = element('div', 'credential-actions');
+    for (const [action, symbol] of [['Rename', 'edit'], ['Delete', 'trash']]) {
+      const button = element('button', `icon-button ${action.toLowerCase()}`);
+      button.type = 'button';
+      button.title = `${action} passkey`;
+      button.setAttribute('aria-label', `${action} ${credential.name}`);
