+      actions.append(button);
+    }
+    row.append(image, info, actions);
+    list.append(row);
+  }
+}
+async function synchronize() {
+  const result = await syncCredentials(snapshot, { demo: repository.demo });
+  const messages = {
+    demo: 'In a connected account, supported browsers can update saved passkeys automatically. Preview changes never affect your real passkeys.',
+    unsupported: 'Your account list is up to date. This browser doesn’t support automatic passkey updates; remove deleted keys from your password manager manually.',
+    failed: 'Your account list is up to date. We couldn’t notify your authenticator. You can remove deleted keys from your password manager manually.',
+    sent: 'We’ve sent your latest passkey list to your browser. Your password manager decides how to apply these updates.',
+  };
+  $('#sync-message').textContent = messages[result];
+}
+async function load({ signal = true } = {}) {
+  list.setAttribute('aria-busy', 'true');
+  try {
+    snapshot = await repository.list();
+    render();
+    if (signal) await synchronize();
+    return true;
+  } catch (error) {
+    $('#key-count').textContent = '—';
+    list.replaceChildren(element('p', 'empty-state', error.message));
+    const retry = element('button', 'retry-button', 'Try again');
+    retry.type = 'button';
+    retry.addEventListener('click', () => load());
+    list.append(retry);
+    return false;
+  } finally {
+    list.setAttribute('aria-busy', 'false');
+  }
+}
+function openDialog(action, credential) {
+  selectedId = credential.id;
+  if (action === 'Rename') {
+    $('#passkey-name').value = credential.name;
+    $('#passkey-name').setCustomValidity('');
+    $('#rename-error').textContent = '';
+    $('#rename-dialog').showModal();
+  } else {
+    $('#delete-error').textContent = '';
+    $('#delete-description').textContent = `“${credential.name}” will no longer be able to sign in to your Daily Grind account.${snapshot.credentials.length === 1 ? ' This is your last registered passkey.' : ''}`;
+    $('#delete-dialog').showModal();
+  }
+}
+function setBusy(form, value) {
+  busy = value;
+  form.querySelectorAll('button, input').forEach(control => { control.disabled = value; });
+}
+for (const button of document.querySelectorAll('[data-close]')) button.addEventListener('click', () => document.getElementById(button.dataset.close).close());
+for (const dialog of document.querySelectorAll('dialog')) dialog.addEventListener('cancel', event => { if (busy) event.preventDefault(); });
+$('#passkey-name').addEventListener('input', () => $('#passkey-name').setCustomValidity(''));
+$('#rename-form').addEventListener('submit', async event => {
+  event.preventDefault();
+  const form = event.currentTarget;
+  let name;
+  try { name = validateName($('#passkey-name').value); }
+  catch (error) { $('#passkey-name').setCustomValidity(error.message); $('#passkey-name').reportValidity(); return; }
+  setBusy(form, true);
+  try {
+    await repository.rename(selectedId, name);
+    // A credential nickname does not change the WebAuthn account identity.
+    $('#rename-dialog').close();
+    const refreshed = await load({ signal: false });
+    announce(refreshed ? `Passkey renamed to “${name}”.` : 'Name saved. The list couldn’t refresh. Select Try again to reload it.', !refreshed);
+    // The row is replaced after refresh, so place focus on its replacement control.
+    const index = snapshot.credentials.findIndex(c => c.id === selectedId);
+    list.querySelectorAll('.rename')[index]?.focus();
+  } catch (error) { $('#rename-error').textContent = error.message; }
+  finally { setBusy(form, false); }
+});
+$('#delete-form').addEventListener('submit', async event => {
+  event.preventDefault();
+  const form = event.currentTarget;
+  setBusy(form, true);
+  try {
+    await repository.remove(selectedId);
+    $('#delete-dialog').close();
+    // Re-fetch the complete server list before signaling, including an empty list.
+    const refreshed = await load();
+    announce(refreshed ? 'Passkey deleted. It can no longer sign in to your account.' : 'Passkey deleted, but the list couldn’t refresh. Select Try again to update it and notify your browser.', !refreshed);
+    $('#passkeys h3').setAttribute('tabindex', '-1');
+    $('#passkeys h3').focus();
+  } catch (error) { $('#delete-error').textContent = error.message; }
+  finally { setBusy(form, false); }
+});
+$('#demo-notice').hidden = !repository.demo;
+await load();
