new file mode 100644
index 0000000..1de7227
--- /dev/null
+++ b/passkey-store.js
@@ -0,0 +1,94 @@
+// No browser credential is created or signaled by demo mode.
+export const DEMO_STORAGE_KEY = 'daily-grind.passkeys.v1';
+export function seedCredentials() {
+  return [
+    { id: 'ZGFpbHktZ3JpbmQtbWFjYm9vaw', name: 'My MacBook Pro', aaguid: 'dd4ec289-e01d-41c9-bb89-70fa845d4bf2', device: 'laptop', registeredAt: Date.UTC(2026, 8, 12), lastUsedAt: Date.UTC(2026, 10, 15) },
+    { id: 'ZGFpbHktZ3JpbmQtaXBob25l', name: 'My iPhone', aaguid: 'dd4ec289-e01d-41c9-bb89-70fa845d4bf2', device: 'phone', registeredAt: Date.UTC(2026, 8, 12), lastUsedAt: Date.UTC(2026, 10, 13) },
+    { id: 'ZGFpbHktZ3JpbmQtc2VjdXJpdHkta2V5', name: 'YubiKey 5C', aaguid: '00000000-0000-0000-0000-000000000000', device: 'key', registeredAt: Date.UTC(2026, 9, 3), lastUsedAt: Date.UTC(2026, 10, 2) },
+  ];
+}
+export function validateName(value) {
+  const name = value.trim();
+  if (!name || name.length > 60) throw new Error('Enter a name between 1 and 60 characters.');
+  return name;
+}
+export function isBase64Url(value) {
+  return typeof value === 'string' && value.length > 0 && value.length % 4 !== 1 && /^[A-Za-z0-9_-]+$/.test(value);
+}
+export function validateSnapshot(data) {
+  if (!data || !Array.isArray(data.credentials) || !data.credentials.every(c =>
+    c && isBase64Url(c.id) && typeof c.name === 'string' && Number.isFinite(c.registeredAt) &&
+    (c.lastUsedAt == null || Number.isFinite(c.lastUsedAt)))) {
+    throw new Error('Unable to read your passkeys. Please try again.');
+  }
+  if (new Set(data.credentials.map(c => c.id)).size !== data.credentials.length) {
+    throw new Error('Unable to read your passkeys. Please try again.');
+  }
+  return data;
+}
+export function createRepository({ apiBase = '', storage, fetcher = globalThis.fetch, csrfToken = '' } = {}) {
+  const demo = !apiBase;
+  const base = apiBase.replace(/\/$/, '');
+  async function request(path, options = {}) {
+    const response = await fetcher(`${base}${path}`, {
+      ...options, credentials: 'same-origin', cache: 'no-store',
+      headers: { Accept: 'application/json', ...(options.body ? { 'Content-Type': 'application/json' } : {}),
+        ...(csrfToken ? { 'X-CSRF-Token': csrfToken } : {}) },
+    });
+    if (!response.ok) {
+      if (response.status === 401 || response.status === 403) throw new Error('Your session has expired. Sign in again to manage your passkeys.');
+      let message = 'We couldn’t update your passkeys. Please try again.';
+      try {
+        const body = await response.json();
+        if (typeof body.error === 'string' && body.error.trim() && body.error.length <= 200) message = body.error;
+      } catch { /* Preserve the generic message for non-JSON server failures. */ }
+      throw new Error(message);
+    }
+    return response.status === 204 ? null : response.json();
+  }
+  function readDemo() {
+    const saved = storage?.getItem(DEMO_STORAGE_KEY);
+    return saved ? validateSnapshot(JSON.parse(saved)).credentials : seedCredentials();
+  }
+  function saveDemo(credentials) {
+    if (!storage) throw new Error('Browser storage is unavailable. Allow site storage to save preview changes.');
+    storage.setItem(DEMO_STORAGE_KEY, JSON.stringify({ credentials }));
+  }
+  return {
+    demo,
+    async list() {
+      return validateSnapshot(demo ? { credentials: readDemo() } : await request('/credentials'));
+    },
+    async rename(id, value) {
+      const name = validateName(value);
+      if (!demo) return request(`/credential/${encodeURIComponent(id)}`, { method: 'PUT', body: JSON.stringify({ name }) });
+      const credentials = readDemo();
+      const credential = credentials.find(c => c.id === id);
+      if (!credential) throw new Error('This passkey no longer exists. Refresh the list.');
+      credential.name = name;
+      saveDemo(credentials);
+      return credential;
+    },
+    async remove(id) {
+      if (!demo) return request(`/credential/${encodeURIComponent(id)}`, { method: 'DELETE' });
+      saveDemo(readDemo().filter(c => c.id !== id));
+    },
+  };
+}
+// Only authoritative, complete server snapshots may reach the Signal API.
+export async function syncCredentials(snapshot, { demo = false, authenticator = globalThis.PublicKeyCredential } = {}) {
+  if (demo) return 'demo';
+  if (typeof authenticator?.signalAllAcceptedCredentials !== 'function') return 'unsupported';
+  const ids = snapshot.credentials.map(c => c.id);
+  if (typeof snapshot.rpId !== 'string' || !snapshot.rpId || !isBase64Url(snapshot.userId) || !ids.every(isBase64Url)) {
+    console.warn('Passkey sync skipped: invalid server-provided RP or credential identifiers.');
+    return 'failed';
+  }
+  try {
+    await authenticator.signalAllAcceptedCredentials({ rpId: snapshot.rpId, userId: snapshot.userId, allAcceptedCredentialIds: ids });
+    return 'sent';
+  } catch (error) {
+    console.warn('Passkey synchronization is unavailable:', error);
+    return 'failed';
+  }
+}
diff --git a/tests/passkeys.test.js b/tests/passkeys.test.js
new file mode 100644
index 0000000..2c108d5
--- /dev/null
+++ b/tests/passkeys.test.js
@@ -0,0 +1,95 @@
+import test from 'node:test';
+import assert from 'node:assert/strict';
+import { createRepository, seedCredentials, syncCredentials, isBase64Url, validateName, validateSnapshot } from '../passkey-store.js';
+
+function memoryStorage() {
+  const data = new Map();
+  return { getItem: key => data.get(key) ?? null, setItem: (key, value) => data.set(key, value) };
+}
+const serverSnapshot = () => ({ rpId: 'coffee.example', userId: 'Y3VzdG9tZXI', credentials: seedCredentials() });
+
+test('demo nicknames and deletions persist independently of real credentials', async () => {
+  const storage = memoryStorage();
+  const repo = createRepository({ storage });
+  const { credentials } = await repo.list();
+  await repo.rename(credentials[0].id, '  Home laptop  ');
+  await repo.remove(credentials[1].id);
+  const reopened = await createRepository({ storage }).list();
+  assert.equal(reopened.credentials.length, 2);
+  assert.equal(reopened.credentials[0].name, 'Home laptop');
+  assert.equal(reopened.credentials[0].registeredAt, credentials[0].registeredAt);
+  assert.equal(seedCredentials()[0].name, 'My MacBook Pro');
+});
+
+test('demo can remove every credential and retains the empty state', async () => {
+  const repo = createRepository({ storage: memoryStorage() });
+  for (const credential of (await repo.list()).credentials) await repo.remove(credential.id);
+  assert.deepEqual((await repo.list()).credentials, []);
+});
+
+test('names reject blank and overlong input; IDs use actual unpadded Base64URL', () => {
+  assert.throws(() => validateName('   '));
+  assert.throws(() => validateName('a'.repeat(61)));
+  assert.equal(validateName('  My key  '), 'My key');
+  assert.ok(seedCredentials().every(c => isBase64Url(c.id)));
+  for (const invalid of ['', 'a', 'cHJldmlldw==', 'not:base64']) assert.equal(isBase64Url(invalid), false);
+  assert.throws(() => validateSnapshot({ credentials: [seedCredentials()[0], seedCredentials()[0]] }));
+});
+
+test('Signal API receives authoritative RP ID, account ID and remaining credentials, including none', async () => {
+  const calls = [];
+  const authenticator = { signalAllAcceptedCredentials: async value => calls.push(value) };
+  const snapshot = serverSnapshot();
+  snapshot.credentials.splice(1, 1);
+  assert.equal(await syncCredentials(snapshot, { authenticator }), 'sent');
+  assert.deepEqual(calls[0], { rpId: 'coffee.example', userId: 'Y3VzdG9tZXI', allAcceptedCredentialIds: snapshot.credentials.map(c => c.id) });
+  await syncCredentials({ ...snapshot, credentials: [] }, { authenticator });
+  assert.deepEqual(calls[1].allAcceptedCredentialIds, []);
+});
+
+test('demo and unsupported browsers never call an authenticator', async () => {
+  const authenticator = { signalAllAcceptedCredentials: () => assert.fail('Demo data must never be signaled') };
+  assert.equal(await syncCredentials(serverSnapshot(), { demo: true, authenticator }), 'demo');
+  assert.equal(await syncCredentials(serverSnapshot(), { authenticator: {} }), 'unsupported');
+});
+
+test('malformed server data and provider rejection are non-fatal synchronization failures', async t => {
+  const warnings = [];
+  t.mock.method(console, 'warn', (...args) => warnings.push(args));
+  const authenticator = { signalAllAcceptedCredentials: async () => { throw new Error('Provider unavailable'); } };
+  assert.equal(await syncCredentials({ ...serverSnapshot(), userId: 'invalid=' }, { authenticator }), 'failed');
+  assert.equal(await syncCredentials(serverSnapshot(), { authenticator }), 'failed');
+  assert.equal(warnings.length, 2);
+});
+
+test('API adapter preserves authentication, CSRF protection, and server ownership of RP data', async () => {
+  const calls = [];
+  const fetcher = async (url, options) => {
+    calls.push({ url, options });
+    return { ok: true, status: options.method === 'DELETE' ? 204 : 200, json: async () => serverSnapshot() };
+  };
+  const repo = createRepository({ apiBase: '/api/', fetcher, csrfToken: 'session-token' });
+  const snapshot = await repo.list();
+  await repo.rename(snapshot.credentials[0].id, 'Work laptop');
+  await repo.remove(snapshot.credentials[0].id);
+  assert.equal(repo.demo, false);
+  assert.equal(snapshot.rpId, 'coffee.example');
+  assert.equal(calls[0].url, '/api/credentials');
+  assert.equal(calls[1].options.method, 'PUT');
+  assert.deepEqual(JSON.parse(calls[1].options.body), { name: 'Work laptop' });
+  assert.equal(calls[2].options.method, 'DELETE');
+  assert.ok(calls.every(c => c.options.credentials === 'same-origin' && c.options.headers['X-CSRF-Token'] === 'session-token'));
+});
+
+test('unauthenticated API responses never fall back to demo or overwrite data', async () => {
+  const repo = createRepository({ apiBase: '/api', fetcher: async () => ({ ok: false, status: 401 }) });
+  await assert.rejects(repo.list(), /session has expired/);
+  await assert.rejects(repo.remove('dGVzdA'), /session has expired/);
+});
+
+test('server can block deletion with an actionable recovery-method message', async () => {
+  const repo = createRepository({ apiBase: '/api', fetcher: async () => ({
+    ok: false, status: 409, json: async () => ({ error: 'Add another sign-in method before deleting your last passkey.' }),
+  }) });
+  await assert.rejects(repo.remove('dGVzdA'), /Add another sign-in method/);
+});

