+      {snapshot.credentials.map(key => {
+        return <li key={key.id} className="py-6"><div className="flex flex-wrap gap-4">
+          <div className="flex h-11 w-11 shrink-0 items-center justify-center rounded-sm border border-gray-200 bg-stone-50">{key.providerIcon ? <img src={key.providerIcon} alt="" className="h-6 w-6" /> : <KeyIcon className="h-6 w-6 text-gray-600" aria-hidden="true" />}</div>
+          <div className="min-w-0 flex-1"><h4 className="break-words font-semibold text-gray-900">{key.name || key.providerName || 'Passkey'}</h4><p className="mt-1 text-xs text-gray-500">{key.providerName || 'Unknown passkey provider'}</p><p className="mt-2 text-xs leading-5 text-gray-500">Added {date(key.registeredAt)} <span className="mx-1" aria-hidden="true">·</span> {key.lastUsedAt ? `Last used ${date(key.lastUsedAt)}` : 'Not used yet'}</p></div>
+          <div className="flex items-start gap-4"><button className="settings-link" disabled={busy} aria-label={`Rename ${key.name}`} onClick={() => { setEditing(key.id); setName(key.name); }}><PencilSquareIcon className="h-4 w-4" aria-hidden="true" />Rename</button><button className="settings-link text-red-700" disabled={busy} aria-label={`Remove ${key.name}`} onClick={() => { setRemoving(key); dialog.current?.showModal(); }}><TrashIcon className="h-4 w-4" aria-hidden="true" />Remove</button></div>
+        </div>{editing === key.id && <form onSubmit={event => rename(event, key.id)} className="mt-5 flex flex-wrap items-end gap-3 rounded-sm bg-stone-50 p-4"><div className="min-w-0 flex-1"><label htmlFor={`name-${key.id}`} className="mb-2 block text-xs font-semibold">Passkey display name</label><input autoFocus id={`name-${key.id}`} required maxLength={80} value={name} onChange={e => setName(e.target.value)} className="w-full rounded-sm border border-gray-300 bg-white px-3 py-2 text-sm" /></div><button className="settings-primary" disabled={busy || !name.trim()} type="submit">Save name</button><button type="button" className="settings-link py-2" disabled={busy} onClick={() => { setEditing(null); panel.current?.focus(); }}>Cancel</button></form>}</li>;
+      })}
+    </ul>}
+    {snapshot && <p className="mt-4 text-xs leading-5 text-gray-500">{syncState}</p>}
+    <div className="mt-10 border-t border-gray-200 pt-6"><h3 className="text-sm font-semibold text-gray-900">You’re in control</h3><p className="mt-2 text-sm leading-6 text-gray-500">Removing a passkey revokes its access to your account. You can still sign in with your password or another registered passkey. A passkey’s display name is only a label in your account.</p></div>
+
+    <dialog ref={dialog} onCancel={event => { if (busy) event.preventDefault(); }} onClose={() => setRemoving(null)} aria-labelledby="remove-title" aria-describedby="remove-description" className="m-auto w-[calc(100%-2rem)] max-w-md rounded-sm border border-gray-200 bg-white p-7 shadow-xl backdrop:bg-black/40"><h3 id="remove-title" className="font-brand text-3xl">Remove this passkey?</h3><p id="remove-description" className="mt-3 break-words text-sm leading-6 text-gray-600">“{removing?.name}” will no longer work with your account. You can continue signing in with your password. {snapshot?.credentials.length === 1 && 'This is your last registered passkey.'}</p><div className="mt-6 flex justify-end gap-5"><button autoFocus className="settings-link" disabled={busy} onClick={() => dialog.current?.close()}>Keep passkey</button><button className="settings-primary bg-red-700 hover:bg-red-800" disabled={busy} onClick={remove}>{busy ? 'Removing…' : 'Remove passkey'}</button></div></dialog>
+  </section>;
+}
