diff --git a/src/lib/account.ts b/src/lib/account.ts
new file mode 100644
index 0000000..dbbbcb8
--- /dev/null
+++ b/src/lib/account.ts
@@ -0,0 +1,60 @@
+import { DatabaseSync } from 'node:sqlite';
+import { randomBytes, createHash } from 'node:crypto';
+import { mkdirSync } from 'node:fs';
+import { dirname, resolve } from 'node:path';
+import type { AstroCookies } from 'astro';
+import providers from '../data/passkey-providers.json';
+
+// This store supports a single Node deployment with a persistent local volume.
+let database: DatabaseSync;
+export function db() {
+  if (database) return database;
+  const path = resolve(process.env.ACCOUNT_DATABASE_PATH || '.data/accounts.sqlite');
+  mkdirSync(dirname(path), { recursive: true, mode: 0o700 });
+  database = new DatabaseSync(path);
+  database.exec(`
+    PRAGMA journal_mode = WAL;
+    CREATE TABLE IF NOT EXISTS readers (id TEXT PRIMARY KEY, username TEXT UNIQUE NOT NULL);
+    CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, readerId TEXT NOT NULL, expires INTEGER NOT NULL);
+    CREATE TABLE IF NOT EXISTS passkeys (id TEXT PRIMARY KEY, readerId TEXT NOT NULL, rpId TEXT NOT NULL, name TEXT NOT NULL, aaguid TEXT NOT NULL, registeredAt INTEGER NOT NULL, lastUsedAt INTEGER, publicKey TEXT NOT NULL, counter INTEGER NOT NULL, transports TEXT NOT NULL, deviceType TEXT NOT NULL, backedUp INTEGER NOT NULL);
+    CREATE TABLE IF NOT EXISTS challenges (sessionId TEXT PRIMARY KEY, challenge TEXT NOT NULL, expires INTEGER NOT NULL);
+  `);
+  return database;
+}
+
+export const sessionCookie = 'times_account';
+export const sessionHash = (token: string) => createHash('sha256').update(token).digest('hex');
+export type Reader = { id: string; username: string };
+export function getReader(cookies: AstroCookies): Reader | undefined {
+  const token = cookies.get(sessionCookie)?.value;
+  if (!token) return;
+  return db().prepare('SELECT readers.* FROM sessions JOIN readers ON readers.id = sessions.readerId WHERE sessions.id = ? AND sessions.expires > ?').get(sessionHash(token), Date.now()) as Reader | undefined;
+}
+
+export function startSession(cookies: AstroCookies, username: string, secure: boolean) {
+  const store = db();
+  store.prepare('INSERT OR IGNORE INTO readers (id, username) VALUES (?, ?)').run(randomBytes(32).toString('base64url'), username);
+  const reader = store.prepare('SELECT * FROM readers WHERE username = ?').get(username) as Reader;
+  const oldToken = cookies.get(sessionCookie)?.value;
+  if (oldToken) store.prepare('DELETE FROM sessions WHERE id = ?').run(sessionHash(oldToken));
+  const token = randomBytes(32).toString('base64url');
+  store.prepare('DELETE FROM sessions WHERE expires < ?').run(Date.now());
+  store.prepare('INSERT INTO sessions VALUES (?, ?, ?)').run(sessionHash(token), reader.id, Date.now() + 7 * 86400000);
+  cookies.set(sessionCookie, token, { httpOnly: true, secure, sameSite: 'lax', path: import.meta.env.BASE_URL, maxAge: 7 * 86400 });
+  return reader;
+}
+
+export type Passkey = { id: string; name: string; aaguid: string; registeredAt: number; lastUsedAt: number | null; providerName?: string; providerIcon?: string };
+export function listPasskeys(readerId: string, rpId: string): Passkey[] {
+  const keys = db().prepare('SELECT id, name, aaguid, registeredAt, lastUsedAt FROM passkeys WHERE readerId = ? AND rpId = ? ORDER BY registeredAt DESC').all(readerId, rpId) as Passkey[];
+  const registry = providers as Record<string, { name: string; icon_light?: string }>;
+  return keys.map(key => {
+    const provider = key.aaguid === '00000000-0000-0000-0000-000000000000' ? undefined : registry[key.aaguid.toLowerCase()];
+    return { ...key, providerName: provider?.name, providerIcon: provider?.icon_light };
+  });
+}
+
+export function relyingParty(url: URL) {
+  const origin = process.env.PASSKEY_ORIGIN || url.origin;
+  return { origin, rpId: process.env.PASSKEY_RP_ID || new URL(origin).hostname };
+}
diff --git a/src/lib/passkey-sync.ts b/src/lib/passkey-sync.ts
new file mode 100644
index 0000000..050f070
--- /dev/null
+++ b/src/lib/passkey-sync.ts
@@ -0,0 +1,19 @@
+export type CredentialSummary = { id: string; name: string; aaguid: string; registeredAt: number; lastUsedAt: number | null; providerName?: string; providerIcon?: string };
+export type CredentialSnapshot = { rpId: string; userId: string; credentials: CredentialSummary[] };
+export const validBase64Url = (value: unknown): value is string => typeof value === 'string' && value.length > 0 && value.length % 4 !== 1 && /^[A-Za-z0-9_-]+$/.test(value);
+
+export async function syncPasskeys(snapshot: CredentialSnapshot): Promise<'synced' | 'unsupported' | 'failed'> {
+  if (!window.PublicKeyCredential || !PublicKeyCredential.signalAllAcceptedCredentials) return 'unsupported';
+  const ids = snapshot.credentials.map(({ id }) => id);
+  if (!snapshot.rpId || !validBase64Url(snapshot.userId) || !ids.every(validBase64Url)) {
+    console.warn('Passkey synchronization skipped: invalid server credential identifiers.');
+    return 'failed';
+  }
+  try {
+    await PublicKeyCredential.signalAllAcceptedCredentials({ rpId: snapshot.rpId, userId: snapshot.userId, allAcceptedCredentialIds: ids });
+    return 'synced';
+  } catch (error) {
+    console.warn('Passkey synchronization could not complete:', error);
+    return 'failed';
+  }
+}
diff --git a/src/pages/account/settings.astro b/src/pages/account/settings.astro
new file mode 100644
index 0000000..c6bbcf5
--- /dev/null
+++ b/src/pages/account/settings.astro
@@ -0,0 +1,50 @@
+---
+import Layout from '../../layouts/Layout.astro';
+import PasskeySettings from '../../components/PasskeySettings';
+import { getReader } from '../../lib/account';
+
+const reader = getReader(Astro.cookies);
+Astro.response.headers.set('Cache-Control', 'private, no-store');
+const base = import.meta.env.BASE_URL;
+---
+
+<Layout title="Account settings | The DevTools Times">
+  <div class="px-5 py-10 sm:px-10 sm:py-12">
+    <p class="text-xs text-gray-500"><a class="hover:underline" href={base}>Home</a><span class="mx-2" aria-hidden="true">/</span>Account settings</p>
+    <h1 class="font-brand mt-5 text-5xl text-gray-950">Account settings</h1>
+    <p class="mt-3 text-sm text-gray-500">Your account. Your preferences. Your peace of mind.</p>
+    <div class="mt-9 grid gap-9 border-t border-gray-900 pt-8 md:grid-cols-[210px_1fr] md:gap-12">
+      <aside>
+        <nav aria-label="Account settings"><a href="#passkeys" aria-current="page" class="flex items-center justify-between border-l-2 border-gray-950 bg-stone-100 px-4 py-3 text-sm font-semibold text-gray-950">Sign-in & security <span aria-hidden="true">→</span></a></nav>
+        {reader && <div class="mt-7 px-4"><p class="text-xs text-gray-500">Signed in as</p><p class="mt-1 break-words text-sm font-medium text-gray-900">{reader.username}</p><form method="post" action={`${base}api/account/logout`} id="signout-form"><button type="submit" class="mt-4 text-xs text-gray-600 underline underline-offset-4">Sign out</button></form></div>}
+        <p class="mt-9 px-4 text-xs leading-5 text-gray-500">Independent journalism.<br />A personal reading experience.</p>
+      </aside>
+      <div id="passkeys" class="min-w-0 pb-8">
+        {reader ? <PasskeySettings client:load /> : <section class="border border-gray-200 p-8"><p class="text-xs font-semibold uppercase tracking-widest text-gray-500">Sign-in & security</p><h2 class="font-brand mt-3 text-4xl">Your passkeys</h2><p class="mt-4 text-sm leading-6 text-gray-600">Sign in to view your registered passkeys, update their display names, and remove keys you no longer use.</p><a href={`${base}signin`} class="settings-primary mt-6 inline-flex">Sign in to manage passkeys <span aria-hidden="true">→</span></a></section>}
+      </div>
+    </div>
+  </div>
+</Layout>
+
+<script>
+  function bindSignout() {
+    const form = document.querySelector<HTMLFormElement>('#signout-form');
+    if (!form || form.dataset.bound) return;
+    form.dataset.bound = 'true';
+    form.addEventListener('submit', async event => {
+      event.preventDefault();
+      const button = form.querySelector('button')!;
+      button.disabled = true;
+      try {
+        const response = await fetch(form.action, { method: 'POST' });
+        if (!response.ok) throw new Error('Sign-out failed');
+        window.location.assign(import.meta.env.BASE_URL);
+      } catch {
+        button.textContent = 'Could not sign out. Try again.';
+        button.disabled = false;
+      }
+    });
+  }
+  bindSignout();
+  document.addEventListener('astro:page-load', bindSignout);
+</script>
diff --git a/src/pages/api/account/[...path].ts b/src/pages/api/account/[...path].ts
new file mode 100644
index 0000000..fe3304f
--- /dev/null
+++ b/src/pages/api/account/[...path].ts
@@ -0,0 +1,105 @@
+import type { APIRoute } from 'astro';
+import { generateAuthenticationOptions, generateRegistrationOptions, verifyAuthenticationResponse, verifyRegistrationResponse } from '@simplewebauthn/server';
+import { randomBytes } from 'node:crypto';
+import { db, getReader, listPasskeys, relyingParty, sessionCookie, sessionHash, startSession } from '../../../lib/account';
+
+export const ALL: APIRoute = async ({ request, cookies, url, params }) => {
+  const json = (data: unknown, status = 200) => new Response(JSON.stringify(data), { status, headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' } });
+  const { origin, rpId } = relyingParty(url);
+  if (request.method !== 'GET' && request.headers.get('Origin') !== origin) return json({ error: 'Please reload this page and try again.' }, 403);
+  const path = params.path || '';
+  try {
+    if (path === 'authenticate/options' && request.method === 'POST') {
+      const options = await generateAuthenticationOptions({ rpID: rpId, allowCredentials: [], userVerification: 'required' });
+      const token = randomBytes(32).toString('base64url');
+      const store = db();
+      store.prepare('DELETE FROM challenges WHERE expires < ?').run(Date.now());
+      store.prepare('INSERT INTO challenges VALUES (?, ?, ?)').run(sessionHash(token), options.challenge, Date.now() + 300000);
+      cookies.set('times_passkey_challenge', token, { httpOnly: true, secure: url.protocol === 'https:', sameSite: 'strict', path: import.meta.env.BASE_URL, maxAge: 300 });
+      return json(options);
+    }
+    if (path === 'authenticate/verify' && request.method === 'POST') {
+      const token = cookies.get('times_passkey_challenge')?.value;
+      cookies.delete('times_passkey_challenge', { path: import.meta.env.BASE_URL });
+      if (!token) return json({ error: 'The sign-in request expired. Please try again.' }, 400);
+      const store = db();
+      const challenge = store.prepare('DELETE FROM challenges WHERE sessionId = ? RETURNING challenge, expires').get(sessionHash(token)) as { challenge: string; expires: number } | undefined;
+      if (!challenge || challenge.expires < Date.now()) return json({ error: 'The sign-in request expired. Please try again.' }, 400);
+      const response = await request.json();
+      if (typeof response.id !== 'string') return json({ error: 'Invalid passkey response.' }, 400);
+      const key = store.prepare('SELECT passkeys.*, readers.username FROM passkeys JOIN readers ON readers.id = passkeys.readerId WHERE passkeys.id = ? AND passkeys.rpId = ?').get(response.id, rpId) as { id: string; readerId: string; username: string; publicKey: string; counter: number; transports: string } | undefined;
+      if (!key) return json({ error: 'This passkey is no longer registered. Sign in with your password.' }, 404);
+      if (response.response?.userHandle !== key.readerId) return json({ error: 'The passkey does not match this account.' }, 401);
+      const result = await verifyAuthenticationResponse({ response, expectedChallenge: challenge.challenge, expectedOrigin: origin, expectedRPID: rpId, requireUserVerification: true, credential: { id: key.id, publicKey: Buffer.from(key.publicKey, 'base64url'), counter: key.counter } });
+      if (!result.verified) return json({ error: 'We could not verify this passkey.' }, 401);
+      // Conditional update prevents an in-flight login from reviving a deleted key.
+      const updated = store.prepare('UPDATE passkeys SET counter = ?, lastUsedAt = ?, backedUp = ? WHERE id = ? AND counter = ?').run(result.authenticationInfo.newCounter, Date.now(), Number(result.authenticationInfo.credentialBackedUp), key.id, key.counter);
+      if (!updated.changes) return json({ error: 'This passkey changed during sign-in. Please try again.' }, 401);
+      startSession(cookies, key.username, url.protocol === 'https:');
+      return json({ success: true });
+    }
+    if (path === 'login' && request.method === 'POST') {
+      const { username, password } = await request.json();
+      if (typeof username !== 'string' || !username.trim() || username.length > 200 || typeof password !== 'string' || !password || password.length > 1024) return json({ error: 'Enter your username and password.' }, 400);
+      const response = await fetch('https://us-central1-web-devrel-apps.cloudfunctions.net/times_cdn/api/login', {
+        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ username: username.trim(), password }), signal: AbortSignal.timeout(15000),
+      });
+      if (!response.ok) return json({ error: response.status >= 500 ? 'Sign-in is temporarily unavailable. Please try again.' : 'Your username or password was not recognized.' }, response.status >= 500 ? 503 : 401);
+      startSession(cookies, username.trim(), url.protocol === 'https:');
+      return json({ success: true });
+    }
+
+    const reader = getReader(cookies);
+    if (!reader) return json({ error: 'Please sign in to manage your passkeys.' }, 401);
+    const sessionId = sessionHash(cookies.get(sessionCookie)!.value);
+    const store = db();
+    const snapshot = () => ({ rpId, userId: reader.id, credentials: listPasskeys(reader.id, rpId) });
+
+    if (path === 'logout' && request.method === 'POST') {
+      store.prepare('DELETE FROM sessions WHERE id = ?').run(sessionId);
+      store.prepare('DELETE FROM challenges WHERE sessionId = ?').run(sessionId);
+      cookies.delete(sessionCookie, { path: import.meta.env.BASE_URL });
+      return json({ success: true });
+    }
+    if (path === 'credentials' && request.method === 'GET') return json(snapshot());
+
+    if (path.startsWith('credentials/')) {
+      const id = path.slice('credentials/'.length);
+      const credential = store.prepare('SELECT id FROM passkeys WHERE id = ? AND readerId = ? AND rpId = ?').get(id, reader.id, rpId);
+      if (!credential) return json({ error: 'This passkey no longer exists. Refresh the list to continue.' }, 404);
+      if (request.method === 'PUT') {
+        const { name } = await request.json();
+        if (typeof name !== 'string' || !name.trim() || name.trim().length > 80) return json({ error: 'Use a display name between 1 and 80 characters.' }, 400);
+        store.prepare('UPDATE passkeys SET name = ? WHERE id = ? AND readerId = ?').run(name.trim(), id, reader.id);
+        return json(snapshot());
+      }
+      if (request.method === 'DELETE') {
+        store.prepare('DELETE FROM passkeys WHERE id = ? AND readerId = ?').run(id, reader.id);
+        return json(snapshot());
+      }
+    }
+
+    if (path === 'register/options' && request.method === 'POST') {
+      const options = await generateRegistrationOptions({
+        rpName: 'The DevTools Times', rpID: rpId, userName: reader.username, userID: Buffer.from(reader.id, 'base64url'), attestationType: 'none',
+        excludeCredentials: listPasskeys(reader.id, rpId).map(({ id }) => ({ id })),
+        authenticatorSelection: { residentKey: 'required', userVerification: 'required' },
+      });
+      store.prepare('INSERT OR REPLACE INTO challenges VALUES (?, ?, ?)').run(sessionId, options.challenge, Date.now() + 300000);
+      return json(options);
+    }
+    if (path === 'register/verify' && request.method === 'POST') {
+      const challenge = store.prepare('DELETE FROM challenges WHERE sessionId = ? RETURNING challenge, expires').get(sessionId) as { challenge: string; expires: number } | undefined;
+      if (!challenge || challenge.expires < Date.now()) return json({ error: 'The passkey request expired. Please try again.' }, 400);
+      const result = await verifyRegistrationResponse({ response: await request.json(), expectedChallenge: challenge.challenge, expectedOrigin: origin, expectedRPID: rpId, requireUserVerification: true });
+      if (!result.verified) return json({ error: 'We could not verify this passkey.' }, 400);
+      const { credential, aaguid, credentialDeviceType, credentialBackedUp } = result.registrationInfo;
+      store.prepare('INSERT INTO passkeys VALUES (?, ?, ?, ?, ?, ?, NULL, ?, ?, ?, ?, ?)').run(credential.id, reader.id, rpId, 'My passkey', aaguid, Date.now(), Buffer.from(credential.publicKey).toString('base64url'), credential.counter, JSON.stringify(credential.transports || []), credentialDeviceType, Number(credentialBackedUp));
+      return json(snapshot(), 201);
+    }
+    return json({ error: 'This account action is not available.' }, 405);
+  } catch (error) {
+    console.warn('Account request failed:', error instanceof Error ? error.message : 'Unknown error');
+    return json({ error: path === 'register/verify' ? 'We could not save this passkey. Please try again.' : 'We could not complete your request. Please try again.' }, 500);
+  }
+};
