diff --git a/src/lib/account-http.ts b/src/lib/account-http.ts
new file mode 100644
index 0000000..8055d01
--- /dev/null
+++ b/src/lib/account-http.ts
@@ -0,0 +1,22 @@
+import type { APIContext } from 'astro';
+import type { Reader } from './accounts';
+
+export function json(data: unknown, status = 200) {
+  return new Response(JSON.stringify(data), { status, headers: {
+    'Content-Type': 'application/json', 'Cache-Control': 'no-store',
+  } });
+}
+export function sameOrigin(request: Request) {
+  return request.headers.get('origin') === new URL(request.url).origin;
+}
+export async function signedIn(session: APIContext['session']): Promise<Reader | null> {
+  const reader = await session?.get('reader') as Reader | undefined;
+  return reader && reader.expires > Date.now() ? reader : null;
+}
+export function relyingParty(request: Request) {
+  const origin = process.env.WEBAUTHN_ORIGIN || new URL(request.url).origin;
+  return { origin, rpID: new URL(origin).hostname };
+}
+export function displayName(value: unknown): string | null {
+  return typeof value === 'string' && value.trim().length > 0 && value.trim().length <= 64 ? value.trim() : null;
+}
