+import { DatabaseSync } from 'node:sqlite';
+import { mkdirSync } from 'node:fs';
+import { dirname, resolve } from 'node:path';
+import { randomBytes } from 'node:crypto';
+import type { WebAuthnCredential } from '@simplewebauthn/server';
+
+export type Reader = { username: string; userId: string; expires: number };
+export type StoredPasskey = {
+  id: string; name: string; createdAt: string; lastUsedAt: string | null;
+  credential: Omit<WebAuthnCredential, 'publicKey'> & { publicKey: number[] }; backedUp: boolean;
+};
+let database: DatabaseSync;
+function db() {
+  if (!database) {
+    const path = resolve(process.env.ACCOUNT_DB_PATH || '.data/accounts.sqlite');
+    mkdirSync(dirname(path), { recursive: true, mode: 0o700 });
+    database = new DatabaseSync(path);
+    database.exec(`PRAGMA journal_mode = WAL;
+      CREATE TABLE IF NOT EXISTS readers (username TEXT PRIMARY KEY, user_id TEXT UNIQUE NOT NULL);
+      CREATE TABLE IF NOT EXISTS passkeys (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, data TEXT NOT NULL);`);
+  }
+  return database;
+}
+export function readerFor(username: string): Reader {
+  const database = db();
+  database.prepare('INSERT OR IGNORE INTO readers VALUES (?, ?)').run(username, randomBytes(32).toString('base64url'));
+  const row = database.prepare('SELECT user_id FROM readers WHERE username = ?').get(username) as { user_id: string };
+  return { username, userId: row.user_id, expires: Date.now() + 86_400_000 };
+}
+export function passkeysFor(userId: string): StoredPasskey[] {
+  return (db().prepare('SELECT data FROM passkeys WHERE user_id = ? ORDER BY rowid DESC').all(userId) as { data: string }[])
+    .map(({ data }) => JSON.parse(data));
+}
+export function addPasskey(userId: string, passkey: StoredPasskey) {
+  db().prepare('INSERT INTO passkeys VALUES (?, ?, ?)').run(passkey.id, userId, JSON.stringify(passkey));
+}
+export function updatePasskey(userId: string, passkey: StoredPasskey) {
+  db().prepare('UPDATE passkeys SET data = ? WHERE id = ? AND user_id = ?').run(JSON.stringify(passkey), passkey.id, userId);
+}
+export function removePasskey(userId: string, id: string) {
+  return db().prepare('DELETE FROM passkeys WHERE user_id = ? AND id = ?').run(userId, id).changes > 0;
+}
+export function publicPasskeys(userId: string) {
+  return passkeysFor(userId).map(({ credential, ...passkey }) => passkey);
+}
+export function findPasskeyOwner(id: unknown): { username: string; userId: string } | null {
+  if (typeof id !== 'string') return null;
+  const row = db().prepare(`SELECT readers.username, readers.user_id FROM readers
+    JOIN passkeys ON readers.user_id = passkeys.user_id WHERE passkeys.id = ?`).get(id) as { username: string; user_id: string } | undefined;
+  return row ? { username: row.username, userId: row.user_id } : null;
+}
