@@ -0,0 +1,19 @@
+export type PasskeySnapshot = {
+  userId: string; rpId: string; passkeys: { id: string }[];
+};
+// Send only a complete, authenticated server snapshot. Never derive this list from UI state.
+export async function syncPasskeys(snapshot: PasskeySnapshot): Promise<string | null> {
+  if (typeof PublicKeyCredential === 'undefined' || !('signalAllAcceptedCredentials' in PublicKeyCredential)) {
+    return 'Your browser cannot automatically update its passkey list. You can remove unused entries in your password manager.';
+  }
+  try {
+    const credentialAPI = PublicKeyCredential as typeof PublicKeyCredential & {
+      signalAllAcceptedCredentials(options: { rpId: string; userId: string; allAcceptedCredentialIds: string[] }): Promise<void>;
+    };
+    await credentialAPI.signalAllAcceptedCredentials({ rpId: snapshot.rpId, userId: snapshot.userId,
+      allAcceptedCredentialIds: snapshot.passkeys.map(key => key.id) });
+    return null;
+  } catch {
+    return 'Your account is updated, but your browser could not update its passkey list. Retry syncing or remove the unused entry in your password manager.';
+  }
+}
