+import type { APIRoute } from 'astro';
+import { generateAuthenticationOptions, verifyAuthenticationResponse } from '@simplewebauthn/server';
+import { findPasskeyOwner, passkeysFor, readerFor, updatePasskey } from '../../../lib/accounts';
+import { json, relyingParty, sameOrigin } from '../../../lib/account-http';
+
+export const POST: APIRoute = async ({ request, session }) => {
+  if (!sameOrigin(request)) return json({ error: 'Invalid request origin.' }, 403);
+  if (!session) return json({ error: 'Account sessions are unavailable.' }, 503);
+  try {
+    const body = await request.json();
+    const { origin, rpID } = relyingParty(request);
+    if (body.action === 'options') {
+      // Discoverable credentials avoid exposing whether a username has an account.
+      const options = await generateAuthenticationOptions({ rpID, userVerification: 'required' });
+      await session.set('loginChallenge', { challenge: options.challenge, expires: Date.now() + 300000 });
+      return json(options);
+    }
+    const pending = await session.get('loginChallenge') as { challenge: string; expires: number } | undefined;
+    await session.delete('loginChallenge');
+    if (!pending || pending.expires < Date.now()) return json({ error: 'Sign-in expired. Please try again.' }, 400);
+    const owner = findPasskeyOwner(body.response?.id);
+    if (!owner) return json({ error: 'This passkey is no longer registered. Sign in with your password.' }, 401);
+    const key = passkeysFor(owner.userId).find(key => key.id === body.response.id)!;
+    if (body.response.response.userHandle !== owner.userId) return json({ error: 'Passkey account does not match.' }, 401);
+    const result = await verifyAuthenticationResponse({ response: body.response, expectedChallenge: pending.challenge,
+      expectedOrigin: origin, expectedRPID: rpID, requireUserVerification: true,
+      credential: { ...key.credential, publicKey: new Uint8Array(key.credential.publicKey) } });
+    if (!result.verified) return json({ error: 'Passkey verification failed.' }, 401);
+    updatePasskey(owner.userId, { ...key, lastUsedAt: new Date().toISOString(), credential: {
+      ...key.credential, counter: result.authenticationInfo.newCounter,
+    } });
+    await session.regenerate();
+    await session.set('reader', readerFor(owner.username));
+    return json({ success: true });
+  } catch { return json({ error: 'Could not sign in with this passkey. Please try again or use your password.' }, 400); }
+};
