+import type { APIRoute } from 'astro';
+import { generateRegistrationOptions, verifyRegistrationResponse } from '@simplewebauthn/server';
+import { addPasskey, passkeysFor, publicPasskeys, removePasskey, updatePasskey } from '../../../lib/accounts';
+import { displayName, json, relyingParty, sameOrigin, signedIn } from '../../../lib/account-http';
+
+export const GET: APIRoute = async ({ session, request }) => {
+  const reader = await signedIn(session);
+  if (!reader) return json({ error: 'Please sign in to manage your passkeys.' }, 401);
+  return json({ passkeys: publicPasskeys(reader.userId), userId: reader.userId, rpId: relyingParty(request).rpID });
+};
+export const POST: APIRoute = async ({ session, request }) => {
+  if (!sameOrigin(request)) return json({ error: 'Invalid request origin.' }, 403);
+  const reader = await signedIn(session);
+  if (!reader || !session) return json({ error: 'Please sign in to manage your passkeys.' }, 401);
+  try {
+    const body = await request.json();
+    const { rpID, origin } = relyingParty(request);
+    if (body.action === 'options') {
+      if (passkeysFor(reader.userId).length >= 20) return json({ error: 'You can register up to 20 passkeys.' }, 400);
+      const options = await generateRegistrationOptions({
+        rpName: 'The DevTools Times', rpID, userName: reader.username,
+        userID: new Uint8Array(Buffer.from(reader.userId, 'base64url')),
+        attestationType: 'none', authenticatorSelection: { residentKey: 'required', userVerification: 'required' },
+        excludeCredentials: passkeysFor(reader.userId).map(({ credential }) => ({ id: credential.id, transports: credential.transports })),
+      });
+      await session.set('passkeyChallenge', { challenge: options.challenge, userId: reader.userId, expires: Date.now() + 300000 });
+      return json(options);
+    }
+    const pending = await session.get('passkeyChallenge') as { challenge: string; userId: string; expires: number } | undefined;
+    await session.delete('passkeyChallenge');
+    const name = displayName(body.name);
+    if (!pending || pending.userId !== reader.userId || pending.expires < Date.now() || !name) return json({ error: 'Registration expired or the name is invalid. Please try again.' }, 400);
+    const result = await verifyRegistrationResponse({ response: body.response, expectedChallenge: pending.challenge,
+      expectedOrigin: origin, expectedRPID: rpID, requireUserVerification: true });
+    if (!result.verified || !result.registrationInfo) return json({ error: 'Passkey verification failed.' }, 400);
+    const { credential, credentialBackedUp } = result.registrationInfo;
+    addPasskey(reader.userId, { id: credential.id, name, createdAt: new Date().toISOString(), lastUsedAt: null,
+      credential: { ...credential, publicKey: Array.from(credential.publicKey) }, backedUp: credentialBackedUp });
+    return json({ success: true }, 201);
+  } catch {
+    return json({ error: 'Could not register this passkey. Please try again.' }, 400);
+  }
+};
+export const PATCH: APIRoute = async ({ session, request }) => {
+  if (!sameOrigin(request)) return json({ error: 'Invalid request origin.' }, 403);
+  const reader = await signedIn(session);
+  if (!reader) return json({ error: 'Please sign in to manage your passkeys.' }, 401);
+  try {
+    const { id, name: value } = await request.json();
+    const name = displayName(value);
+    if (!name) return json({ error: 'Use a display name between 1 and 64 characters.' }, 400);
+    const key = passkeysFor(reader.userId).find(key => key.id === id);
+    if (!key) return json({ error: 'This passkey no longer exists.' }, 404);
+    updatePasskey(reader.userId, { ...key, name });
+    return json({ success: true });
+  } catch { return json({ error: 'Could not update this passkey.' }, 400); }
+};
+export const DELETE: APIRoute = async ({ session, request }) => {
+  if (!sameOrigin(request)) return json({ error: 'Invalid request origin.' }, 403);
+  const reader = await signedIn(session);
+  if (!reader) return json({ error: 'Please sign in to manage your passkeys.' }, 401);
+  try {
+    const { id } = await request.json();
+    if (typeof id !== 'string' || !removePasskey(reader.userId, id)) return json({ error: 'This passkey no longer exists.' }, 404);
+    return json({ success: true });
+  } catch { return json({ error: 'Could not remove this passkey.' }, 400); }
+};
