+import { test, after } from 'node:test';
+import assert from 'node:assert/strict';
+import { mkdtempSync, rmSync } from 'node:fs';
+import { tmpdir } from 'node:os';
+import { join } from 'node:path';
+import { addPasskey, findPasskeyOwner, passkeysFor, publicPasskeys, readerFor, removePasskey, updatePasskey } from '../src/lib/accounts';
+import { displayName, sameOrigin, signedIn } from '../src/lib/account-http';
+import type { APIContext } from 'astro';
+
+const directory = mkdtempSync(join(tmpdir(), 'times-passkeys-'));
+process.env.ACCOUNT_DB_PATH = join(directory, 'test.sqlite');
+after(() => rmSync(directory, { recursive: true, force: true }));
+
+test('account handles persist across sessions and remain distinct between readers', () => {
+  assert.equal(readerFor('alice').userId, readerFor('alice').userId);
+  assert.notEqual(readerFor('alice').userId, readerFor('bob').userId);
+});
+
+test('passkey storage isolates ownership, persists renames, and rejects deleted credentials', () => {
+  const alice = readerFor('alice');
+  const bob = readerFor('bob');
+  const key = { id: 'credential-id', name: 'Laptop', createdAt: new Date().toISOString(), lastUsedAt: null,
+    credential: { id: 'credential-id', publicKey: [1, 2, 3], counter: 0 }, backedUp: false };
+  addPasskey(alice.userId, key);
+  assert.equal(passkeysFor(bob.userId).length, 0);
+  assert.deepEqual(findPasskeyOwner(key.id), { username: 'alice', userId: alice.userId });
+  assert.equal('credential' in publicPasskeys(alice.userId)[0], false);
+  updatePasskey(bob.userId, { ...key, name: 'Unauthorized rename' });
+  assert.equal(passkeysFor(alice.userId)[0].name, 'Laptop');
+  assert.equal(removePasskey(bob.userId, key.id), false);
+  updatePasskey(alice.userId, { ...key, name: 'Personal laptop' });
+  assert.equal(passkeysFor(alice.userId)[0].name, 'Personal laptop');
+  assert.equal(removePasskey(alice.userId, key.id), true);
+  assert.equal(findPasskeyOwner(key.id), null);
+  assert.deepEqual(publicPasskeys(alice.userId), []);
+});
+
+test('display names reject empty, malformed, and oversized input', () => {
+  for (const value of ['', '  ', null, 123, 'x'.repeat(65)]) assert.equal(displayName(value), null);
+  assert.equal(displayName('  Work laptop  '), 'Work laptop');
+});
+
+test('state changes require matching origins', () => {
+  const request = (origin?: string) => new Request('https://times.example/api/account/passkeys', { headers: origin ? { origin } : {} });
+  assert.equal(sameOrigin(request('https://times.example')), true);
+  assert.equal(sameOrigin(request('https://attacker.example')), false);
+  assert.equal(sameOrigin(request()), false);
+});
+
+test('missing and expired reader sessions cannot authorize management', async () => {
+  assert.equal(await signedIn(undefined), null);
+  const session = (expires: number) => ({ get: async () => ({ username: 'alice', userId: 'alice-id', expires }) }) as unknown as APIContext['session'];
+  assert.equal(await signedIn(session(Date.now() - 1)), null);
+  assert.equal((await signedIn(session(Date.now() + 10000)))?.userId, 'alice-id');
+});
