+import { test, afterEach } from 'node:test';
+import assert from 'node:assert/strict';
+import { syncPasskeys } from '../src/lib/passkey-sync';
+const snapshot = { rpId: 'times.example', userId: 'dXNlci1pZA', passkeys: [{ id: 'remaining-key' }] };
+afterEach(() => { Reflect.deleteProperty(globalThis, 'PublicKeyCredential'); });
+
+test('synchronization sends the full server snapshot, including an empty list after the last removal', async () => {
+  const calls: unknown[] = [];
+  Object.assign(globalThis, { PublicKeyCredential: { signalAllAcceptedCredentials: async (options: unknown) => { calls.push(options); } } });
+  assert.equal(await syncPasskeys(snapshot), null);
+  assert.equal(await syncPasskeys({ ...snapshot, passkeys: [] }), null);
+  assert.deepEqual(calls, [
+    { rpId: 'times.example', userId: 'dXNlci1pZA', allAcceptedCredentialIds: ['remaining-key'] },
+    { rpId: 'times.example', userId: 'dXNlci1pZA', allAcceptedCredentialIds: [] },
+  ]);
+});
+
+test('unsupported browsers and signal failures return guidance without rejecting account updates', async () => {
+  assert.match((await syncPasskeys(snapshot))!, /cannot automatically/);
+  Object.assign(globalThis, { PublicKeyCredential: {} });
+  assert.match((await syncPasskeys(snapshot))!, /cannot automatically/);
+  Object.assign(globalThis, { PublicKeyCredential: { signalAllAcceptedCredentials: async () => { throw new Error('Unavailable'); } } });
+  assert.match((await syncPasskeys(snapshot))!, /account is updated/);
+});

