+export function profileInput(input) {
+  if (!input || typeof input !== 'object') throw Object.assign(new Error('Enter your account details.'), { status: 400 });
+  const displayName = String(input.displayName || '').trim();
+  const email = String(input.email || '').trim().toLowerCase();
+  const phone = String(input.phone || '').trim();
+  if (!displayName || displayName.length > 80 || email.length > 254 || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) || phone.length > 30) throw Object.assign(new Error('Please enter a valid name and email address.'), { status: 400 });
+  return { displayName, email, phone };
+}
+export function passkeyName(value) {
+  const name = String(value || '').trim();
+  if (!name || name.length > 60) throw Object.assign(new Error('Use a passkey name between 1 and 60 characters.'), { status: 400 });
+  return name;
+}
+export function consumeChallenge(session, type, now = Date.now()) {
+  const pending = session.pending;
+  delete session.pending;
+  if (!pending || pending.type !== type || pending.expiresAt < now) throw Object.assign(new Error('That passkey request expired. Please try again.'), { status: 400 });
+  return pending;
+}
+export function requireRecentVerification(session, now = Date.now()) {
+  if (!session.verifiedAt || now - session.verifiedAt > 5 * 60_000) throw Object.assign(new Error('Please verify your identity before making this change.'), { status: 403 });
+}
+export function assertCredentialOwner(credential, userId) {
+  if (!credential || credential.userId !== userId) throw Object.assign(new Error('This passkey does not belong to your account.'), { status: 403 });
+}
