@@ -0,0 +1,36 @@
+import { DatabaseSync } from 'node:sqlite';
+import { mkdirSync } from 'node:fs';
+import { dirname } from 'node:path';
+
+export function createStore(filename = './data/accounts.sqlite') {
+  if (filename !== ':memory:') mkdirSync(dirname(filename), { recursive: true });
+  const db = new DatabaseSync(filename);
+  db.exec(`PRAGMA foreign_keys = ON;
+    PRAGMA journal_mode = WAL;
+    CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE COLLATE NOCASE, data TEXT NOT NULL);
+    CREATE TABLE IF NOT EXISTS credentials (id TEXT PRIMARY KEY, userId TEXT NOT NULL REFERENCES users(id), data TEXT NOT NULL);`);
+  const decode = row => row ? JSON.parse(row.data) : null;
+  const user = id => decode(db.prepare('SELECT data FROM users WHERE id = ?').get(id));
+  const emailExists = (email, except = '') => Boolean(db.prepare('SELECT id FROM users WHERE email = ? AND id != ?').get(email, except));
+  const credentials = userId => db.prepare('SELECT data FROM credentials WHERE userId = ?').all(userId).map(decode);
+  const credential = id => decode(db.prepare('SELECT data FROM credentials WHERE id = ?').get(id));
+  const addCredential = c => db.prepare('INSERT INTO credentials (id, userId, data) VALUES (?, ?, ?)').run(c.id, c.userId, JSON.stringify(c));
+  return {
+    user, emailExists, credentials, credential,
+    register(u, c) {
+      db.exec('BEGIN IMMEDIATE');
+      try { db.prepare('INSERT INTO users (id, email, data) VALUES (?, ?, ?)').run(u.id, u.email, JSON.stringify(u)); addCredential(c); db.exec('COMMIT'); }
+      catch (error) { db.exec('ROLLBACK'); throw error; }
+    },
+    addCredential,
+    saveCredential(c) { db.prepare('UPDATE credentials SET data = ? WHERE id = ? AND userId = ?').run(JSON.stringify(c), c.id, c.userId); },
+    removeCredential(userId, id) {
+      const c = credential(id);
+      if (!c || c.userId !== userId) throw Object.assign(new Error('Passkey not found.'), { status: 404 });
+      if (credentials(userId).length <= 1) throw Object.assign(new Error('Add another passkey before removing your last one.'), { status: 409 });
+      db.prepare('DELETE FROM credentials WHERE id = ? AND userId = ?').run(id, userId);
+    },
+    updateUser(u) { db.prepare('UPDATE users SET email = ?, data = ? WHERE id = ?').run(u.email, JSON.stringify(u), u.id); },
+    close() { db.close(); }
+  };
+}
