+import { test } from 'node:test';
+import assert from 'node:assert/strict';
+import { createStore } from '../store.mjs';
+import { consumeChallenge, requireRecentVerification, assertCredentialOwner, profileInput } from '../account-rules.mjs';
+
+test('challenges are single use, ceremony-bound, and expire', () => {
+  const s = { pending: { type: 'auth', challenge: 'challenge', expiresAt: 2000 } };
+  assert.equal(consumeChallenge(s, 'auth', 1000).challenge, 'challenge');
+  assert.throws(() => consumeChallenge(s, 'auth', 1000));
+  const expired = { pending: { type: 'auth', expiresAt: 999 } };
+  assert.throws(() => consumeChallenge(expired, 'auth', 1000));
+  const wrong = { pending: { type: 'register', expiresAt: 2000 } };
+  assert.throws(() => consumeChallenge(wrong, 'auth', 1000));
+  assert.equal(wrong.pending, undefined);
+});
+test('sensitive changes require fresh server-side verification', () => {
+  assert.throws(() => requireRecentVerification({}, 400000));
+  assert.throws(() => requireRecentVerification({ verifiedAt: 1 }, 400000));
+  assert.doesNotThrow(() => requireRecentVerification({ verifiedAt: 350000 }, 400000));
+});
+test('reauthentication cannot switch accounts', () => {
+  assert.throws(() => assertCredentialOwner({ userId: 'other-user' }, 'current-user'));
+  assert.throws(() => assertCredentialOwner(null, 'current-user'));
+  assert.doesNotThrow(() => assertCredentialOwner({ userId: 'current-user' }, 'current-user'));
+});
+test('store enforces ownership, duplicate emails, and preserves the last passkey', () => {
+  const store = createStore(':memory:');
+  const u = { id: 'dXNlcg', displayName: 'Jamie', email: 'jamie@example.com' };
+  const c = { id: 'Y3JlZDE', userId: u.id, name: 'First key' };
+  store.register(u, c);
+  assert.equal(store.emailExists('JAMIE@example.com'), true);
+  assert.equal(store.emailExists(u.email, u.id), false);
+  assert.throws(() => store.removeCredential('another-user', c.id), /not found/);
+  assert.throws(() => store.removeCredential(u.id, c.id), /last one/);
+  store.addCredential({ id: 'Y3JlZDI', userId: u.id, name: 'Backup key' });
+  store.removeCredential(u.id, c.id);
+  assert.equal(store.credentials(u.id).length, 1);
+  assert.equal(store.credential(c.id), null);
