+    <div role="status">{notice && <p className="mb-4 rounded-md bg-green-50 p-3 text-sm text-green-800">{notice}</p>}</div>
+    {loading ? <p role="status">Loading your account…</p> : signedOut ? <div className="rounded-lg border border-gray-200 p-6"><h2 className="text-xl font-semibold">Sign in to your account</h2><p className="my-3 text-sm text-gray-600">Sign in to view your profile and manage your passkeys.</p><a className={button + ' inline-block'} href={`${import.meta.env.BASE_URL}signin`}>Sign in</a></div> : !list ? <button className={secondary} onClick={load}>Try again</button> : <div className="space-y-6" aria-busy={busy}>
+      <section className="rounded-lg border border-gray-200 p-6" aria-labelledby="profile-heading">
+        <h2 id="profile-heading" className="mb-4 text-xl font-semibold">Profile</h2>
+        <p className="mb-4 text-sm text-gray-600">Signed in as <strong className="break-words text-gray-900">{list.user.username}</strong></p>
+        <form onSubmit={event => { event.preventDefault(); profile(); }} className="space-y-3">
+          <label className="block text-sm font-medium" htmlFor="display-name">Display name</label>
+          <input id="display-name" name="displayName" autoComplete="nickname" className={input} maxLength={100} required value={displayName} disabled={busy} onChange={event => setDisplayName(event.target.value)} />
+          <button className={secondary} disabled={busy || !displayName.trim() || displayName.trim() === list.user.displayName}>Save changes</button>
+        </form>
+      </section>
+      <section className="rounded-lg border border-gray-200 p-6" aria-labelledby="passkeys-heading">
+        <div className="flex flex-wrap items-center justify-between gap-3"><h2 id="passkeys-heading" className="text-xl font-semibold">Passkeys <span className="ml-1 text-base font-normal text-gray-500">{list.credentials.length}</span></h2>{support.create && <button className={button} disabled={busy} onClick={add}>Create a passkey</button>}</div>
+        <p className="my-4 text-sm leading-relaxed text-gray-600">Sign in with your fingerprint, face, or device PIN. Passkeys are resistant to phishing, and your biometric information stays on your device.</p>
+        {!support.create && <p className="mb-4 rounded-md bg-gray-50 p-3 text-sm text-gray-600">To create a passkey, use a supported browser and a device with a screen lock. You can continue using your password.</p>}
+        {!list.credentials.length ? <div className="rounded-md border border-dashed border-gray-300 px-4 py-8 text-center"><p className="font-semibold">No passkeys yet</p><p className="mt-1 text-sm text-gray-600">Add a passkey to make your next sign-in easier.</p></div> : <ul className="divide-y divide-gray-200">
+          {list.credentials.map(key => <li key={key.id} className="py-5">
