+                {removing?.id === key.id && <div className="mt-3 rounded-md border border-red-200 bg-red-50 p-3"><p className="mb-3 text-sm text-red-900">Remove “{key.name}”? You won’t be able to sign in with it. {list.credentials.length === 1 ? 'This is your last passkey; you can still sign in with your password.' : 'Your other passkeys will remain available.'}</p><div className="flex flex-wrap gap-2"><button className={button + ' bg-red-700 hover:bg-red-800'} disabled={busy} onClick={() => remove(key)}>Remove passkey</button><button className={secondary} disabled={busy} onClick={() => setRemoving(null)}>Keep passkey</button></div></div>}
