@@ -0,0 +1,102 @@
+import { useEffect, useRef, useState } from 'react';
+import { api, capabilities, authenticatePasskey, registerPasskey, errorMessage } from '../lib/passkeys';
+
+const button = 'w-full rounded-md bg-gray-900 px-4 py-3 text-sm font-semibold text-white hover:bg-gray-700 disabled:cursor-not-allowed disabled:opacity-50 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-gray-900';
+const input = 'w-full rounded-md border border-gray-300 px-3 py-2 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-gray-800';
+export default function AuthForm({ signup = false }: { signup?: boolean }) {
+  const [username, setUsername] = useState('');
+  const [password, setPassword] = useState('');
+  const [error, setError] = useState('');
+  const [notice, setNotice] = useState('');
+  const [busy, setBusy] = useState(false);
+  const [signedIn, setSignedIn] = useState(false);
+  const [created, setCreated] = useState(false);
+  const [support, setSupport] = useState<{ create: boolean; authenticate: boolean; conditional: boolean } | null>(null);
+  const active = useRef<AbortController | null>(null);
+  const mounted = useRef(false);
+  const fallback = useRef(false);
+  const conditionalVersion = useRef(0);
+  const settingsUrl = `${import.meta.env.BASE_URL}account/settings`;
+
+  async function startAutofill() {
+    const version = ++conditionalVersion.current;
+    const detected = await capabilities();
+    if (!mounted.current || version !== conditionalVersion.current || fallback.current || !detected.conditional) return;
+    const controller = new AbortController();
+    active.current = controller;
+    try {
+      await authenticatePasskey('authentication', controller.signal, true, () => { if (mounted.current) setBusy(true); });
+      if (!mounted.current) return;
+      setSignedIn(true);
+      setPassword('');
+      setNotice('You’re signed in with your passkey.');
+    } catch (error) {
+      if (!controller.signal.aborted && mounted.current && !(error instanceof Error && ['NotAllowedError', 'AbortError'].includes(error.name))) setError(errorMessage(error));
+    } finally { if (mounted.current && !controller.signal.aborted) setBusy(false); }
+  }
+  useEffect(() => {
+    mounted.current = true;
+    capabilities().then(setSupport).catch(() => setSupport({ create: false, authenticate: false, conditional: false }));
+    if (!signup) startAutofill().catch(() => {});
+    return () => { mounted.current = false; conditionalVersion.current++; active.current?.abort(); };
+  }, []);
+
+  async function perform(kind: 'password' | 'passkey' | 'register') {
+    fallback.current = true;
+    conditionalVersion.current++;
+    active.current?.abort();
+    const controller = new AbortController();
+    active.current = controller;
+    setBusy(true); setError(''); setNotice('');
+    try {
+      if (kind === 'password') {
+        await api(signup ? 'signup' : 'login', { username, password }, controller.signal);
+        setPassword(''); setSignedIn(true);
+        setNotice(signup ? 'Your account is ready. Add a passkey for faster, safer sign-in.' : 'You’re signed in. Add a passkey to make your next visit easier.');
+      } else if (kind === 'passkey') {
+        await authenticatePasskey('authentication', controller.signal);
+        setSignedIn(true); setPassword(''); setNotice('You’re signed in with your passkey.');
+      } else {
+        await registerPasskey(true, controller.signal);
+        setCreated(true); setNotice('Your passkey is ready. Next time, sign in with your fingerprint, face, or device PIN.');
+      }
+    } catch (error) {
+      setError(errorMessage(error));
+      if (!signup && kind !== 'register') { fallback.current = false; startAutofill().catch(() => {}); }
+    } finally { if (mounted.current) setBusy(false); }
+  }
+
+  return <section className="mx-auto my-6 max-w-md rounded-lg border border-gray-200 bg-white p-6 shadow-sm" aria-labelledby="auth-title" aria-busy={busy}>
+    <p className="mb-2 text-center text-xs font-semibold uppercase tracking-widest text-gray-500">The DevTools Times</p>
+    <h1 id="auth-title" className="mb-3 text-center text-2xl font-bold text-gray-900">{signedIn ? 'Welcome to the Times' : signup ? 'Create your account' : 'Welcome back'}</h1>
+    <p id="auth-description" className="mb-6 text-center text-sm text-gray-600">{signedIn ? 'Your next great read is waiting.' : signup ? 'Stay curious. Make the Times your own.' : 'Sign in to your account to keep reading.'}</p>
+    <div aria-live="polite">{notice && <p className="mb-4 rounded-md bg-green-50 p-3 text-sm text-green-800">{notice}</p>}</div>
+    {error && <p role="alert" className="mb-4 rounded-md bg-red-50 p-3 text-sm text-red-800">{error}</p>}
+    {signedIn ? <div className="space-y-4">
+      {!created && support?.create && <div className="rounded-md border border-gray-200 p-4">
+        <h2 className="font-semibold">Go passwordless with a passkey</h2>
+        <p className="mb-4 mt-2 text-sm text-gray-600">Use your fingerprint, face, or device PIN. Your biometric information stays on your device.</p>
+        <button type="button" className={button} disabled={busy} onClick={() => perform('register')}>{busy ? 'Creating passkey…' : 'Create a passkey'}</button>
+      </div>}
+      <a className="block text-center text-sm font-semibold underline underline-offset-4" href={settingsUrl}>Manage account and passkeys</a>
+      <a className="block text-center text-sm underline underline-offset-4" href={import.meta.env.BASE_URL}>Continue reading</a>
+    </div> : <>
+      {!signup && <>
+        <button type="button" className={button} disabled={busy || !support?.authenticate} onClick={() => perform('passkey')}>{busy ? 'Signing in…' : 'Sign in with a passkey'}</button>
+        <p className="mt-2 text-center text-xs text-gray-500">{support && !support.authenticate ? 'Passkeys aren’t available in this browser. Use your password below.' : 'Use your fingerprint, face, or device PIN.'}</p>
+        <div className="my-5 flex items-center gap-3 text-xs text-gray-500"><span className="h-px flex-1 bg-gray-200" />or use your password<span className="h-px flex-1 bg-gray-200" /></div>
+      </>}
+      <form className="space-y-4" onSubmit={event => { event.preventDefault(); perform('password'); }}>
+        <div><label className="mb-1 block text-sm font-medium" htmlFor="username">Username</label>
+          <input id="username" name="username" className={input} value={username} onChange={event => setUsername(event.target.value)} autoComplete={signup ? 'username' : 'username webauthn'} autoFocus={!signup} aria-describedby="auth-description" required maxLength={100} disabled={busy} autoCapitalize="none" spellCheck={false} />
+        </div>
+        <div><label className="mb-1 block text-sm font-medium" htmlFor="password">Password</label>
+          {signup && <p id="password-help" className="mt-1 text-xs text-gray-500">Use at least 8 characters, including a number. You can add a passkey after creating your account.</p>}
+          <input id="password" name="password" type="password" className={input} value={password} onChange={event => setPassword(event.target.value)} autoComplete={signup ? 'new-password' : 'current-password'} required minLength={signup ? 8 : undefined} pattern={signup ? '.*[0-9].*' : undefined} aria-describedby={signup ? 'password-help' : undefined} disabled={busy} />
+        </div>
+        <button type="submit" disabled={busy} data-skip-tracking="true" className={button}>{busy ? 'Please wait…' : signup ? 'Create account' : 'Sign in with password'}</button>
+      </form>
+      <p className="mt-6 text-center text-sm text-gray-600">{signup ? 'Already have an account?' : 'New to the Times?'} <a className="font-semibold text-gray-900 underline underline-offset-4" href={`${import.meta.env.BASE_URL}${signup ? 'signin' : 'signup'}`}>{signup ? 'Sign in' : 'Create an account'}</a></p>
+    </>}
+  </section>;
+}
