new file mode 100644
index 0000000..7433408
--- /dev/null
+++ b/src/lib/passkeys.ts
@@ -0,0 +1,73 @@
+export type Account = { id: string; username: string; displayName: string };
+export type SavedPasskey = { id: string; name: string; provider: string; providerIcon?: string; registeredAt: number; lastUsedAt?: number; backedUp: boolean; deviceType: string };
+export type PasskeyList = { user: Account; rpId: string; userId: string; credentials: SavedPasskey[] };
+export class ApiError extends Error { constructor(message: string, public status: number) { super(message); } }
+export async function api<T = Record<string, unknown>>(action: string, body?: unknown, signal?: AbortSignal): Promise<T> {
+  const response = await fetch(`${import.meta.env.BASE_URL}api/auth/${action}`, {
+    method: body === undefined ? 'GET' : 'POST', credentials: 'same-origin', cache: 'no-store',
+    headers: body === undefined ? undefined : { 'Content-Type': 'application/json' },
+    body: body === undefined ? undefined : JSON.stringify(body), signal,
+  });
+  const data = await response.json();
+  if (!response.ok) throw new ApiError(data.error || 'The request failed. Please try again.', response.status);
+  return data;
+}
+export async function capabilities() {
+  if (!window.isSecureContext || !window.PublicKeyCredential) return { create: false, authenticate: false, conditional: false };
+  // Import only in the browser: the polyfill accesses browser globals.
+  await import('webauthn-polyfills');
+  const result = await PublicKeyCredential.getClientCapabilities();
+  return { create: Boolean(result.passkeyPlatformAuthenticator && result.conditionalGet), authenticate: true, conditional: Boolean(result.conditionalGet) };
+}
+const validId = (id: string) => typeof id === 'string' && id.length > 0 && id.length % 4 !== 1 && /^[A-Za-z0-9_-]+$/.test(id);
+async function passiveSync(callback: () => Promise<unknown>) {
+  try { await callback(); } catch (error) { console.warn('Passkey provider synchronization was unavailable.', error); }
+}
+export async function syncAccepted(list: PasskeyList) {
+  if (window.PublicKeyCredential && typeof PublicKeyCredential.signalAllAcceptedCredentials === 'function' && list.rpId && validId(list.userId) && list.credentials.every(key => validId(key.id))) {
+    await passiveSync(() => PublicKeyCredential.signalAllAcceptedCredentials({ rpId: list.rpId, userId: list.userId, allAcceptedCredentialIds: list.credentials.map(key => key.id) }));
+  }
+}
+export async function syncProfile(data: { rpId: string; userId: string; user: Account }) {
+  if (window.PublicKeyCredential && typeof PublicKeyCredential.signalCurrentUserDetails === 'function' && data.rpId && validId(data.userId)) {
+    await passiveSync(() => PublicKeyCredential.signalCurrentUserDetails({ rpId: data.rpId, userId: data.userId, name: data.user.username, displayName: data.user.displayName }));
+  }
+}
+async function signalUnknown(rpId: string | undefined, id: string) {
+  if (rpId && validId(id) && PublicKeyCredential.signalUnknownCredential) {
+    await passiveSync(() => PublicKeyCredential.signalUnknownCredential({ rpId, credentialId: id }));
+  }
+}
+export async function registerPasskey(promotion = false, signal?: AbortSignal) {
+  const { options, flowId } = await api<{ options: PublicKeyCredentialCreationOptionsJSON; flowId: string }>('registration/options', { promotion }, signal);
+  const publicKey = PublicKeyCredential.parseCreationOptionsFromJSON(options);
+  const credential = await navigator.credentials.create({ publicKey, signal }) as PublicKeyCredential | null;
+  if (!credential) throw new Error('No passkey was created. Please try again.');
+  const encoded = credential.toJSON();
+  try { await api('registration/verify', { flowId, credential: encoded }, signal); }
+  catch (error) { await signalUnknown(publicKey.rp.id, encoded.id); throw error; }
+}
+export async function authenticatePasskey(kind: 'authentication' | 'reauthentication', signal?: AbortSignal, conditional = false, onSelected?: () => void) {
+  const { options, flowId } = await api<{ options: PublicKeyCredentialRequestOptionsJSON; flowId: string }>(`${kind}/options`, {}, signal);
+  const publicKey = PublicKeyCredential.parseRequestOptionsFromJSON(options);
+  if (kind === 'reauthentication' && !publicKey.allowCredentials?.length) throw new Error('Use your password to verify your identity.');
+  const credential = await navigator.credentials.get({ publicKey, signal, ...(conditional ? { mediation: 'conditional' as const } : {}) }) as PublicKeyCredential | null;
+  if (!credential) throw new Error('No passkey was selected. Please try again.');
+  onSelected?.();
+  const encoded = credential.toJSON();
+  try { return await api<{ user: Account }>(`${kind}/verify`, { flowId, credential: encoded }, signal); }
+  catch (error) {
+    if (kind === 'authentication' && error instanceof ApiError && error.status === 404) await signalUnknown(publicKey.rpId, encoded.id);
+    throw error;
+  }
+}
+export function errorMessage(error: unknown) {
+  if (error instanceof Error) {
+    if (error.name === 'NotAllowedError') return 'The passkey request was cancelled or timed out. Try again, or use your password.';
+    if (error.name === 'InvalidStateError') return 'A passkey already exists in this password manager. Use another provider or device.';
+    if (error.name === 'SecurityError') return 'Passkeys are unavailable on this site address. Try signing in with your password.';
+    if (error.name === 'AbortError') return 'The request was cancelled. You can try again.';
+    return error.message;
+  }
+  return 'Something went wrong. Please try again.';
+}
diff --git a/src/lib/server/auth-store.ts b/src/lib/server/auth-store.ts
new file mode 100644
index 0000000..1a44833
--- /dev/null
+++ b/src/lib/server/auth-store.ts
@@ -0,0 +1,74 @@
+import { DatabaseSync } from 'node:sqlite';
+import { mkdirSync } from 'node:fs';
+import { dirname, resolve } from 'node:path';
+import { randomBytes, createHash } from 'node:crypto';
+
+export type User = { id: string; username: string; displayName: string };
+export type Passkey = {
+  id: string; userId: string; publicKey: string; counter: number; transports: string[];
+  name: string; aaguid: string; provider: string; providerIcon?: string;
+  registeredAt: number; lastUsedAt?: number; deviceType: string; backedUp: boolean;
+};
+export type Session = { id: string; userId?: string; verifiedAt?: number; expires: number };
+export type Challenge = {
+  id: string; sessionId: string; userId?: string; challenge: string;
+  kind: 'registration' | 'authentication' | 'reauthentication'; expires: number;
+};
+let database: DatabaseSync;
+function db() {
+  if (!database) {
+    const path = resolve(process.env.AUTH_DB_PATH || './data/auth.sqlite');
+    mkdirSync(dirname(path), { recursive: true, mode: 0o700 });
+    database = new DatabaseSync(path);
+    database.exec(`PRAGMA journal_mode=WAL;
+      CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, username TEXT UNIQUE NOT NULL, data TEXT NOT NULL);
+      CREATE TABLE IF NOT EXISTS passkeys (id TEXT PRIMARY KEY, userId TEXT NOT NULL, data TEXT NOT NULL);
+      CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, expires INTEGER NOT NULL, data TEXT NOT NULL);
+      CREATE TABLE IF NOT EXISTS challenges (id TEXT PRIMARY KEY, expires INTEGER NOT NULL, data TEXT NOT NULL);`);
+  }
+  return database;
+}
+function decode<T>(row: unknown): T | undefined {
+  return row ? JSON.parse((row as { data: string }).data) as T : undefined;
+}
+export const randomId = () => randomBytes(32).toString('base64url');
+export const sessionKey = (token: string) => createHash('sha256').update(token).digest('hex');
+export const getUser = (id: string) => decode<User>(db().prepare('SELECT data FROM users WHERE id=?').get(id));
+export function findOrCreateUser(username: string) {
+  const user = decode<User>(db().prepare('SELECT data FROM users WHERE username=?').get(username));
+  if (user) return user;
+  const created = { id: randomId(), username, displayName: username };
+  db().prepare('INSERT OR IGNORE INTO users VALUES (?, ?, ?)').run(created.id, username, JSON.stringify(created));
+  return decode<User>(db().prepare('SELECT data FROM users WHERE username=?').get(username))!;
+}
+export function saveUser(user: User) {
+  db().prepare('UPDATE users SET data=? WHERE id=?').run(JSON.stringify(user), user.id);
+}
+export const getPasskey = (id: string) => decode<Passkey>(db().prepare('SELECT data FROM passkeys WHERE id=?').get(id));
+export const listPasskeys = (userId: string) => db().prepare('SELECT data FROM passkeys WHERE userId=?').all(userId).map(row => decode<Passkey>(row)!);
+export function addPasskey(key: Passkey) {
+  db().prepare('INSERT INTO passkeys VALUES (?, ?, ?)').run(key.id, key.userId, JSON.stringify(key));
+}
+export function savePasskey(key: Passkey, previousCounter?: number) {
+  // Compare-and-swap prevents concurrent assertions from rolling the signature counter back.
+  const result = db().prepare(`UPDATE passkeys SET data=? WHERE id=? AND (? IS NULL OR json_extract(data, '$.counter')=?)`)
+    .run(JSON.stringify(key), key.id, previousCounter ?? null, previousCounter ?? null);
+  return result.changes === 1;
+}
+export const deletePasskey = (id: string, userId: string) => db().prepare('DELETE FROM passkeys WHERE id=? AND userId=?').run(id, userId);
+export function getSession(token: string) {
+  const result = decode<Session>(db().prepare('SELECT data FROM sessions WHERE id=? AND expires>?').get(sessionKey(token), Date.now()));
+  return result;
+}
+export function saveSession(session: Session) {
+  db().prepare('INSERT OR REPLACE INTO sessions VALUES (?, ?, ?)').run(session.id, session.expires, JSON.stringify(session));
+}
+export const deleteSession = (id: string) => db().prepare('DELETE FROM sessions WHERE id=?').run(id);
+export function saveChallenge(value: Challenge) {
+  db().prepare('DELETE FROM challenges WHERE expires<?').run(Date.now());
+  db().prepare('DELETE FROM sessions WHERE expires<?').run(Date.now());
+  db().prepare('INSERT INTO challenges VALUES (?, ?, ?)').run(value.id, value.expires, JSON.stringify(value));
+}
+export function consumeChallenge(id: string) {
+  return decode<Challenge>(db().prepare('DELETE FROM challenges WHERE id=? RETURNING data').get(id));
+}
