+import type { APIRoute } from 'astro';
+import { generateRegistrationOptions, generateAuthenticationOptions, verifyRegistrationResponse, verifyAuthenticationResponse } from '@simplewebauthn/server';
+import { randomId, sessionKey, getSession, saveSession, deleteSession, getUser, findOrCreateUser, saveUser, listPasskeys, getPasskey, addPasskey, savePasskey, deletePasskey, saveChallenge, consumeChallenge, type Session, type Challenge } from '../../../lib/server/auth-store';
+import registry from '../../../lib/server/passkey-providers.json';
+
+const PASSWORD_API = 'https://us-central1-web-devrel-apps.cloudfunctions.net/times_cdn/api';
+const COOKIE = 'times_auth';
+const FRESH_FOR = 5 * 60_000;
+class AuthError extends Error { constructor(message: string, public status = 400) { super(message); } }
+function text(value: unknown, label: string, max = 100) {
+  if (typeof value !== 'string' || !value.trim() || value.length > max) throw new AuthError(`Enter a valid ${label}.`);
+  return value.trim();
+}
+
+export const ALL: APIRoute = async ({ request, cookies, params, url, site }) => {
+  const json = (body: unknown, status = 200) => new Response(JSON.stringify(body), { status, headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' } });
+  try {
+    const origin = new URL(process.env.WEBAUTHN_ORIGIN || (['localhost', '127.0.0.1', '[::1]'].includes(url.hostname) ? url.origin : site!.origin)).origin;
+    const rpId = process.env.WEBAUTHN_RP_ID || new URL(origin).hostname;
+    if (url.origin !== origin) throw new AuthError('This origin is not configured for account access.', 403);
+    if (request.method !== 'GET' && request.headers.get('Origin') !== origin) throw new AuthError('Account requests must come from this site.', 403);
+    const action = params.action || '';
+    let session = cookies.get(COOKIE)?.value ? getSession(cookies.get(COOKIE)!.value) : undefined;
+    const user = session?.userId ? getUser(session.userId) : undefined;
+    function newSession(userId?: string) {
+      if (session) deleteSession(session.id);
+      const token = randomId();
+      session = { id: sessionKey(token), userId, verifiedAt: userId ? Date.now() : undefined, expires: Date.now() + 7 * 86400_000 };
+      saveSession(session);
+      cookies.set(COOKIE, token, { httpOnly: true, secure: origin.startsWith('https:'), sameSite: 'strict', path: import.meta.env.BASE_URL, maxAge: 7 * 86400 });
+      return session;
+    }
+    const requireUser = () => { if (!user) throw new AuthError('Please sign in to manage your account.', 401); return user; };
+    const requireFresh = () => { requireUser(); if (!session?.verifiedAt || Date.now() - session.verifiedAt > FRESH_FOR) throw new AuthError('Verify your identity to continue.', 403); };
+    const management = () => ({ user, rpId, userId: user!.id, credentials: listPasskeys(user!.id).map(({ publicKey, counter, userId, ...key }) => key) });
+    if (request.method === 'GET') {
+      if (action === 'session') return json({ user: user || null });
+      if (action === 'passkeys') { requireUser(); return json(management()); }
+      throw new AuthError('Not found.', 404);
+    }
+    if (request.method !== 'POST') throw new AuthError('Method not allowed.', 405);
+    if (!request.headers.get('Content-Type')?.includes('application/json')) throw new AuthError('JSON is required.', 415);
+    const raw = await request.text();
+    if (raw.length > 65536) throw new AuthError('Request too large.', 413);
+    const body = JSON.parse(raw);
+    if (['login', 'signup', 'password-reauth'].includes(action)) {
+      const username = action === 'password-reauth' ? requireUser().username : text(body.username, 'username');
+      if (typeof body.password !== 'string' || !body.password || body.password.length > 1024) throw new AuthError('Enter your password.');
+      const response = await fetch(`${PASSWORD_API}/${action === 'signup' ? 'register' : 'login'}`, {
+        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ username, password: body.password }), signal: AbortSignal.timeout(15000),
+      });
+      if (!response.ok) throw new AuthError(action === 'signup' ? 'Could not create your account. Check your username and password, or try signing in.' : 'Your username or password was not accepted. Try again.', response.status === 429 ? 429 : 400);
+      if (action === 'password-reauth') { session!.verifiedAt = Date.now(); saveSession(session!); return json({ verified: true }); }
+      const account = findOrCreateUser(username);
+      newSession(account.id);
+      return json({ user: account });
+    }
+    if (action === 'logout') {
+      if (session) deleteSession(session.id);
+      cookies.delete(COOKIE, { path: import.meta.env.BASE_URL });
+      return json({ success: true });
+    }
+    if (action.endsWith('/options')) {
+      const kind = action.split('/')[0] as Challenge['kind'];
+      if (!['registration', 'authentication', 'reauthentication'].includes(kind)) throw new AuthError('Not found.', 404);
+      if (kind !== 'authentication') requireUser();
+      if (kind === 'registration') requireFresh();
+      const keys = user ? listPasskeys(user.id) : [];
+      if (kind === 'registration' && keys.length >= 20) throw new AuthError('You can save up to 20 passkeys. Remove one before adding another.');
+      if (kind === 'reauthentication' && !keys.length) throw new AuthError('No passkey is registered. Verify with your password instead.');
+      if (!session) newSession();
+      const options = kind === 'registration'
+        ? await generateRegistrationOptions({ rpName: 'The DevTools Times', rpID: rpId, userID: Buffer.from(user!.id, 'base64url'), userName: user!.username, userDisplayName: user!.displayName, attestationType: 'none', excludeCredentials: keys.map(key => ({ id: key.id, transports: key.transports })), authenticatorSelection: { residentKey: 'required', requireResidentKey: true, userVerification: 'required', ...(body.promotion ? { authenticatorAttachment: 'platform' as const } : {}) } })
+        : await generateAuthenticationOptions({ rpID: rpId, userVerification: 'required', allowCredentials: kind === 'reauthentication' ? keys.map(key => ({ id: key.id, transports: key.transports })) : [] });
+      const flowId = randomId();
+      saveChallenge({ id: flowId, sessionId: session!.id, userId: kind === 'authentication' ? undefined : user!.id, challenge: options.challenge, kind, expires: Date.now() + 5 * 60_000 });
+      return json({ options, flowId });
+    }
+    if (action.endsWith('/verify')) {
+      if (!session || typeof body.flowId !== 'string') throw new AuthError('Your request expired. Please try again.');
+      const flow = consumeChallenge(body.flowId);
+      if (!flow || flow.sessionId !== session.id || flow.expires < Date.now() || `${flow.kind}/verify` !== action || (flow.userId && flow.userId !== user?.id)) throw new AuthError('Your request expired. Please try again.');
+      if (flow.kind === 'registration') {
+        requireFresh();
+        const result = await verifyRegistrationResponse({ response: body.credential, expectedChallenge: flow.challenge, expectedOrigin: origin, expectedRPID: rpId, requireUserVerification: true });
+        if (!result.verified) throw new AuthError('Passkey registration could not be verified.');
+        const info = result.registrationInfo;
+        const provider = (registry.providers as Record<string, { name: string; icon?: string }>)[info.aaguid];
+        addPasskey({ id: info.credential.id, userId: user!.id, publicKey: Buffer.from(info.credential.publicKey).toString('base64url'), counter: info.credential.counter, transports: info.credential.transports || [], name: provider?.name || 'My passkey', provider: provider?.name || 'Unknown passkey provider', providerIcon: provider?.icon ? (registry.icons as Record<string, string>)[provider.icon] : undefined, aaguid: info.aaguid, registeredAt: Date.now(), deviceType: info.credentialDeviceType, backedUp: info.credentialBackedUp });
+        return json({ success: true });
+      }
+      const key = typeof body.credential?.id === 'string' ? getPasskey(body.credential.id) : undefined;
+      if (!key) throw new AuthError('This passkey is no longer registered. Sign in with your password.', 404);
+      if (flow.kind === 'reauthentication' && key.userId !== requireUser().id) throw new AuthError('Use a passkey belonging to your signed-in account.', 403);
+      if (body.credential.response?.userHandle && body.credential.response.userHandle !== key.userId) throw new AuthError('Passkey account does not match.', 403);
+      const result = await verifyAuthenticationResponse({ response: body.credential, expectedChallenge: flow.challenge, expectedOrigin: origin, expectedRPID: rpId, requireUserVerification: true, credential: { id: key.id, publicKey: Buffer.from(key.publicKey, 'base64url'), counter: key.counter, transports: key.transports } });
+      if (!result.verified) throw new AuthError('Your identity could not be verified.', 403);
+      const previousCounter = key.counter;
+      key.counter = result.authenticationInfo.newCounter;
+      key.lastUsedAt = Date.now();
+      key.backedUp = result.authenticationInfo.credentialBackedUp;
+      if (!savePasskey(key, previousCounter)) throw new AuthError('Another sign-in completed. Please try again.');
+      if (flow.kind === 'authentication') newSession(key.userId);
+      else { session.verifiedAt = Date.now(); saveSession(session); }
+      return json({ verified: true, user: getUser(key.userId) });
+    }
+    requireFresh();
+    if (action === 'profile') {
+      user!.displayName = text(body.displayName, 'display name');
+      saveUser(user!);
+      return json({ user, rpId, userId: user!.id });
+    }
+    if (action === 'passkeys/rename' || action === 'passkeys/delete') {
+      const key = getPasskey(text(body.id, 'passkey ID', 2048));
+      if (!key || key.userId !== user!.id) throw new AuthError('Passkey not found.', 404);
+      if (action.endsWith('rename')) { key.name = text(body.name, 'passkey name'); savePasskey(key); }
+      else deletePasskey(key.id, user!.id);
+      return json(management());
+    }
+    throw new AuthError('Not found.', 404);
+  } catch (error) {
+    if (error instanceof AuthError) return json({ error: error.message }, error.status);
+    if (error instanceof SyntaxError) return json({ error: 'Invalid request.' }, 400);
+    console.warn('Account request failed:', error instanceof Error ? error.message : 'Unknown error');
+    return json({ error: 'The request could not be completed. Please try again.' }, 400);
+  }
+};
