+import test from 'node:test';
+import assert from 'node:assert/strict';
+import { mkdtempSync, rmSync } from 'node:fs';
+import { tmpdir } from 'node:os';
+import { join } from 'node:path';
+import * as store from '../src/lib/server/auth-store.ts';
+
+const directory = mkdtempSync(join(tmpdir(), 'times-auth-'));
+process.env.AUTH_DB_PATH = join(directory, 'auth.sqlite');
+process.on('exit', () => rmSync(directory, { recursive: true, force: true }));
+
+test('account identities are persistent and separate', () => {
+  const first = store.findOrCreateUser('reader');
+  const again = store.findOrCreateUser('reader');
+  const other = store.findOrCreateUser('another-reader');
+  assert.equal(first.id, again.id);
+  assert.notEqual(first.id, other.id);
+  assert.match(first.id, /^[A-Za-z0-9_-]+$/);
+  assert.equal(first.id.length % 4 === 1, false);
+});
+
+test('sessions expire, are keyed by a token hash, and can be revoked', () => {
+  const token = store.randomId();
+  const id = store.sessionKey(token);
+  assert.notEqual(id, token);
+  store.saveSession({ id, userId: store.findOrCreateUser('session-reader').id, expires: Date.now() + 60_000 });
+  assert.equal(store.getSession(token).id, id);
+  store.deleteSession(id);
+  assert.equal(store.getSession(token), undefined);
+  store.saveSession({ id, expires: Date.now() - 1 });
+  assert.equal(store.getSession(token), undefined);
+});
+
+test('challenges are consumed atomically and cannot be replayed', () => {
+  const challenge = { id: store.randomId(), sessionId: store.randomId(), challenge: store.randomId(), kind: 'reauthentication', userId: store.findOrCreateUser('challenge-reader').id, expires: Date.now() + 60_000 };
+  store.saveChallenge(challenge);
+  assert.deepEqual(store.consumeChallenge(challenge.id), challenge);
+  assert.equal(store.consumeChallenge(challenge.id), undefined);
+});
+
+test('credentials stay with their owner, duplicates fail, and stale counters cannot overwrite current counters', () => {
+  const user = store.findOrCreateUser('passkey-reader');
+  const other = store.findOrCreateUser('other-passkey-reader');
+  const key = { id: store.randomId(), userId: user.id, publicKey: 'cHVibGljLWtleQ', counter: 1, transports: ['internal'], name: 'My device', aaguid: '00000000-0000-0000-0000-000000000000', provider: 'Unknown passkey provider', registeredAt: Date.now(), deviceType: 'singleDevice', backedUp: false };
+  store.addPasskey(key);
+  assert.throws(() => store.addPasskey({ ...key, userId: other.id }));
+  assert.equal(store.listPasskeys(other.id).length, 0);
+  assert.equal(store.listPasskeys(user.id)[0].id, key.id);
+  assert.equal(store.savePasskey({ ...key, counter: 2 }, 1), true);
+  assert.equal(store.savePasskey({ ...key, counter: 3 }, 1), false);
+  assert.equal(store.getPasskey(key.id).counter, 2);
+  store.deletePasskey(key.id, other.id);
+  assert.ok(store.getPasskey(key.id));
+  store.deletePasskey(key.id, user.id);
+  assert.equal(store.getPasskey(key.id), undefined);
+});

