+          {!supported && <p role="status" className="auth-notice">Passkeys need a supported browser and a secure connection. You can use the password option instead.</p>}
+          <button className="primary-button" type="submit" disabled={busy || !supported}><Icon name="fingerprint" size={21}/>{busy ? 'Waiting for your device…' : signup ? 'Create account with a passkey' : 'Continue with a passkey'}{!busy && <Icon name="arrow" size={19}/>}</button>
+          <div className="device-hint"><Icon name="device" size={14}/> You can also use a passkey from another device.</div>
