diff --git a/src/lib/auth-client.ts b/src/lib/auth-client.ts
new file mode 100644
index 0000000..fffae69
--- /dev/null
+++ b/src/lib/auth-client.ts
@@ -0,0 +1,27 @@
+import { startRegistration, startAuthentication, browserSupportsWebAuthn } from '@simplewebauthn/browser';
+export const base = import.meta.env.BASE_URL;
+export const supportsPasskeys = () => window.isSecureContext && browserSupportsWebAuthn();
+export class RequestError extends Error { constructor(message: string, public status: number) { super(message); } }
+export async function api(action: string, body?: object) {
+  const res = await fetch(`${base}api/auth/${action}`, { method: body ? 'POST' : 'GET', credentials: 'same-origin', headers: { 'Content-Type': 'application/json' }, ...(body ? { body: JSON.stringify(body) } : {}) });
+  const data = await res.json();
+  if (!res.ok) throw new RequestError(data.error || 'Something went wrong. Please try again.', res.status);
+  return data;
+}
+export async function registerPasskey(data: { signup?: boolean; username?: string; name?: string }) {
+  const optionsJSON = await api('register/options', data);
+  const credential = await startRegistration({ optionsJSON });
+  await api('register/verify', { credential });
+}
+export async function authenticate(reauthenticate = false) {
+  const optionsJSON = await api('authenticate/options', { reauthenticate });
+  const credential = await startAuthentication({ optionsJSON });
+  await api('authenticate/verify', { credential });
+}
+export function errorMessage(error: unknown) {
+  if (error instanceof Error && (error.name === 'NotAllowedError' || error.name === 'AbortError')) return 'The passkey request was canceled or timed out. You can try again.';
+  if (error instanceof Error && error.name === 'InvalidStateError') return 'This device already has a passkey for your account. Try signing in instead.';
+  if (error instanceof Error && error.name === 'SecurityError') return 'Passkeys are unavailable on this address. Use a secure connection or sign in with your password.';
+  return error instanceof Error ? error.message : 'Something went wrong. Please try again.';
+}
+export interface Account { username: string; hasPassword: boolean; passkeys: { id: string; name: string; createdAt: number; lastUsed: number | null }[] }
diff --git a/src/lib/auth-store.ts b/src/lib/auth-store.ts
new file mode 100644
index 0000000..b5b8dea
--- /dev/null
+++ b/src/lib/auth-store.ts
@@ -0,0 +1,35 @@
+import { DatabaseSync } from 'node:sqlite';
+import { chmodSync, mkdirSync } from 'node:fs';
+import { dirname, resolve } from 'node:path';
+import { randomBytes, scryptSync, timingSafeEqual, createHash } from 'node:crypto';
+
+let database: DatabaseSync;
+export function db() {
+  if (!database) {
+    const path = resolve(process.env.AUTH_DB_PATH || '.data/auth.sqlite');
+    mkdirSync(dirname(path), { recursive: true, mode: 0o700 });
+    database = new DatabaseSync(path);
+    chmodSync(path, 0o600);
+    database.exec(`PRAGMA journal_mode=WAL; PRAGMA foreign_keys=ON;
+      CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, username TEXT UNIQUE NOT NULL, password TEXT);
+      CREATE TABLE IF NOT EXISTS passkeys (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), name TEXT NOT NULL, public_key TEXT NOT NULL, counter INTEGER NOT NULL, transports TEXT NOT NULL, created_at INTEGER NOT NULL, last_used INTEGER);
+      CREATE TABLE IF NOT EXISTS sessions (token TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires INTEGER NOT NULL, verified INTEGER NOT NULL);
+      CREATE TABLE IF NOT EXISTS challenges (token TEXT PRIMARY KEY, payload TEXT NOT NULL, expires INTEGER NOT NULL);
+      CREATE TABLE IF NOT EXISTS attempts (key TEXT PRIMARY KEY, count INTEGER NOT NULL, expires INTEGER NOT NULL);`);
+  }
+  return database;
+}
+export interface User { id: string; username: string; password: string | null }
+export interface Passkey { id: string; user_id: string; name: string; public_key: string; counter: number; transports: string; created_at: number; last_used: number | null }
+export const token = () => randomBytes(32).toString('base64url');
+export const digest = (value: string) => createHash('sha256').update(value).digest('hex');
+export function hashPassword(password: string) {
+  const salt = token();
+  return `${salt}:${scryptSync(password, salt, 64).toString('hex')}`;
+}
+export function checkPassword(password: string, stored: string) {
+  const [salt, hash] = stored.split(':');
+  return timingSafeEqual(scryptSync(password, salt, 64), Buffer.from(hash, 'hex'));
+}
+export function getUser(id: string) { return db().prepare('SELECT * FROM users WHERE id = ?').get(id) as unknown as User | undefined; }
+export function getPasskeys(id: string) { return db().prepare('SELECT * FROM passkeys WHERE user_id = ? ORDER BY created_at DESC').all(id) as unknown as Passkey[]; }
