+/** Verify existing Times password accounts before linking them to local passkeys. */
+export async function verifyLegacyAccount(username: string, password: string) {
+  const response = await fetch('https://us-central1-web-devrel-apps.cloudfunctions.net/times_cdn/api/login', {
+    method: 'POST',
+    headers: { 'Content-Type': 'application/json' },
+    body: JSON.stringify({ username, password }),
+    signal: AbortSignal.timeout(10_000),
+  });
+  if (!response.ok) return false;
+  const data = await response.json();
+  return !data.error;
+}
