diff --git a/src/pages/api/auth/[...action].ts b/src/pages/api/auth/[...action].ts
new file mode 100644
index 0000000..dcb80b6
--- /dev/null
+++ b/src/pages/api/auth/[...action].ts
@@ -0,0 +1,170 @@
+import type { APIRoute, APIContext } from 'astro';
+import { generateRegistrationOptions, verifyRegistrationResponse, generateAuthenticationOptions, verifyAuthenticationResponse } from '@simplewebauthn/server';
+import { verifyLegacyAccount } from '../../../lib/legacy-auth';
+import { db, token, digest, hashPassword, checkPassword, getUser, getPasskeys, type User, type Passkey } from '../../../lib/auth-store';
+
+const cookieName = 'times_session';
+const challengeCookie = 'times_ceremony';
+const response = (body: unknown, status = 200) => new Response(JSON.stringify(body), { status, headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' } });
+class AuthError extends Error { constructor(message: string, public status = 400) { super(message); } }
+function cookieOptions(ctx: APIContext) { return { httpOnly: true, sameSite: 'strict' as const, secure: new URL(process.env.AUTH_ORIGIN || ctx.url.origin).protocol === 'https:', path: import.meta.env.BASE_URL }; }
+function session(ctx: APIContext) {
+  const raw = ctx.cookies.get(cookieName)?.value;
+  if (!raw) return undefined;
+  return db().prepare('SELECT * FROM sessions WHERE token = ? AND expires > ?').get(digest(raw), Date.now()) as { token: string; user_id: string; verified: number } | undefined;
+}
+function requireSession(ctx: APIContext, recent = false) {
+  const current = session(ctx);
+  if (!current) throw new AuthError('Please sign in to manage your account.', 401);
+  if (recent && Date.now() - current.verified > 5 * 60_000) throw new AuthError('Verify your identity to continue.', 403);
+  return current;
+}
+function startSession(ctx: APIContext, userId: string) {
+  const raw = token();
+  const previous = ctx.cookies.get(cookieName)?.value;
+  if (previous) db().prepare('DELETE FROM sessions WHERE token = ?').run(digest(previous));
+  db().prepare('INSERT INTO sessions VALUES (?, ?, ?, ?)').run(digest(raw), userId, Date.now() + 7 * 86400_000, Date.now());
+  ctx.cookies.set(cookieName, raw, { ...cookieOptions(ctx), maxAge: 7 * 86400 });
+}
+function saveChallenge(ctx: APIContext, payload: object) {
+  const raw = token();
+  db().prepare('DELETE FROM challenges WHERE expires < ?').run(Date.now());
+  db().prepare('INSERT INTO challenges VALUES (?, ?, ?)').run(digest(raw), JSON.stringify(payload), Date.now() + 5 * 60_000);
+  ctx.cookies.set(challengeCookie, raw, { ...cookieOptions(ctx), maxAge: 300 });
+}
+function consumeChallenge(ctx: APIContext) {
+  const raw = ctx.cookies.get(challengeCookie)?.value || '';
+  const stored = db().prepare('DELETE FROM challenges WHERE token = ? AND expires > ? RETURNING payload').get(digest(raw), Date.now()) as { payload: string } | undefined;
+  ctx.cookies.delete(challengeCookie, { path: import.meta.env.BASE_URL });
+  if (!stored) throw new AuthError('This request expired. Please try again.');
+  return JSON.parse(stored.payload);
+}
+function name(value: unknown) {
+  if (typeof value !== 'string' || !/^[a-zA-Z0-9_.@+-]{3,100}$/.test(value.trim())) throw new AuthError('Use 3–100 letters, numbers, or email address characters for your username.');
+  return value.trim().toLowerCase();
+}
+function passkeyName(value: unknown) { return typeof value === 'string' && value.trim() ? value.trim().slice(0, 60) : 'My passkey'; }
+function validPassword(value: unknown): asserts value is string {
+  if (typeof value !== 'string' || value.length < 8 || value.length > 256 || !/\d/.test(value)) throw new AuthError('Your password needs at least 8 characters and a number.');
+}
+function publicAccount(user: User) {
+  return { username: user.username, hasPassword: !!user.password, passkeys: getPasskeys(user.id).map(k => ({ id: k.id, name: k.name, createdAt: k.created_at, lastUsed: k.last_used })) };
+}
+export const GET: APIRoute = async (ctx) => {
+  if (ctx.params.action !== 'session') return response({ error: 'Not found' }, 404);
+  const current = session(ctx);
+  const user = current && getUser(current.user_id);
+  return response(user ? { user: publicAccount(user) } : { user: null });
+};
+export const POST: APIRoute = async (ctx) => {
+  try {
+    const origin = process.env.AUTH_ORIGIN || ctx.url.origin;
+    if (ctx.request.headers.get('origin') !== origin) throw new AuthError('This request could not be verified. Refresh the page and try again.', 403);
+    const rpID = new URL(origin).hostname;
+    const action = ctx.params.action;
+    // Bound repeated requests without trusting client-provided forwarding headers.
+    const key = `${ctx.clientAddress}:${action}`;
+    db().prepare('DELETE FROM sessions WHERE expires < ?').run(Date.now());
+    db().prepare('DELETE FROM attempts WHERE expires < ?').run(Date.now());
+    db().prepare('INSERT INTO attempts VALUES (?, 1, ?) ON CONFLICT(key) DO UPDATE SET count = count + 1').run(key, Date.now() + 60_000);
+    if ((db().prepare('SELECT count FROM attempts WHERE key = ?').get(key) as { count: number }).count > 30) throw new AuthError('Too many attempts. Please wait a minute and try again.', 429);
+    const body = await ctx.request.json();
+    if (action === 'logout') {
+      const current = session(ctx);
+      if (current) db().prepare('DELETE FROM sessions WHERE token = ?').run(current.token);
+      ctx.cookies.delete(cookieName, { path: import.meta.env.BASE_URL });
+      return response({ ok: true });
+    }
+    if (action === 'register') {
+      const username = name(body.username);
+      validPassword(body.password);
+      if (db().prepare('SELECT id FROM users WHERE username = ?').get(username)) throw new AuthError('That username is already registered. Try signing in.');
+      const id = token();
+      db().prepare('INSERT INTO users VALUES (?, ?, ?)').run(id, username, hashPassword(body.password));
+      startSession(ctx, id);
+      return response({ ok: true });
+    }
+    if (action === 'login' || action === 'reauthenticate/password') {
+      const current = action === 'reauthenticate/password' ? requireSession(ctx) : undefined;
+      let user = current ? getUser(current.user_id) : db().prepare('SELECT * FROM users WHERE username = ?').get(name(body.username)) as unknown as User | undefined;
+      if (typeof body.password !== 'string' || body.password.length > 256) throw new AuthError('Enter your password.');
+      // Existing remote password accounts can enroll passkeys after a verified login.
+      let remoteValid = false;
+      if ((!current && !user) || user?.password === 'remote') {
+        try {
+          remoteValid = await verifyLegacyAccount(user?.username || name(body.username), body.password);
+          if (!user && remoteValid) {
+            user = { id: token(), username: name(body.username), password: 'remote' };
+            db().prepare('INSERT INTO users VALUES (?, ?, ?)').run(user.id, user.username, user.password);
+          }
+        } catch { throw new AuthError('Password sign-in is temporarily unavailable. Please try again.', 503); }
+      }
+      // Always run the password derivation, including for unknown accounts.
+      const derived = checkPassword(body.password, user?.password && user.password !== 'remote' ? user.password : `${'0'.repeat(43)}:${'0'.repeat(128)}`);
+      const valid = user?.password === 'remote' ? remoteValid : derived;
+      if (!user || !user.password || !valid) throw new AuthError('Your username or password is incorrect.', 401);
+      if (current) db().prepare('UPDATE sessions SET verified = ? WHERE token = ?').run(Date.now(), current.token);
+      else startSession(ctx, user.id);
+      return response({ ok: true });
+    }
+    if (action === 'register/options') {
+      const current = body.signup ? undefined : requireSession(ctx, true);
+      const user: User = current ? getUser(current.user_id)! : { id: token(), username: name(body.username), password: null };
+      if (!current && db().prepare('SELECT id FROM users WHERE username = ?').get(user.username)) throw new AuthError('That username is already registered. Try signing in.');
+      const options = await generateRegistrationOptions({ rpName: 'The DevTools Times', rpID, userID: new TextEncoder().encode(user.id), userName: user.username, attestationType: 'none', excludeCredentials: current ? getPasskeys(user.id).map(k => ({ id: k.id })) : [], authenticatorSelection: { residentKey: 'required', userVerification: 'required' } });
+      saveChallenge(ctx, { flow: 'register', challenge: options.challenge, user, signup: !current, sessionToken: current?.token, name: passkeyName(body.name) });
+      return response(options);
+    }
+    if (action === 'register/verify') {
+      const pending = consumeChallenge(ctx);
+      if (pending.flow !== 'register') throw new AuthError('Please restart passkey setup.');
+      if (!pending.signup && requireSession(ctx, true).token !== pending.sessionToken) throw new AuthError('Please restart passkey setup.');
+      const result = await verifyRegistrationResponse({ response: body.credential, expectedChallenge: pending.challenge, expectedOrigin: origin, expectedRPID: rpID, requireUserVerification: true });
+      if (!result.verified || !result.registrationInfo) throw new AuthError('Your passkey could not be verified. Please try again.');
+      const { credential } = result.registrationInfo;
+      db().exec('BEGIN IMMEDIATE');
+      try {
+        if (pending.signup) db().prepare('INSERT INTO users VALUES (?, ?, NULL)').run(pending.user.id, pending.user.username);
+        db().prepare('INSERT INTO passkeys VALUES (?, ?, ?, ?, ?, ?, ?, NULL)').run(credential.id, pending.user.id, pending.name, Buffer.from(credential.publicKey).toString('base64'), credential.counter, JSON.stringify(credential.transports || []), Date.now());
+        db().exec('COMMIT');
+      } catch (error) { db().exec('ROLLBACK'); throw error; }
+      if (pending.signup) startSession(ctx, pending.user.id);
+      return response({ ok: true });
+    }
+    if (action === 'authenticate/options') {
+      const current = body.reauthenticate ? requireSession(ctx) : undefined;
+      const options = await generateAuthenticationOptions({ rpID, userVerification: 'required', ...(current ? { allowCredentials: getPasskeys(current.user_id).map(k => ({ id: k.id })) } : {}) });
+      if (current && !getPasskeys(current.user_id).length) throw new AuthError('This account does not have a passkey yet. Use your password.');
+      saveChallenge(ctx, { flow: 'authenticate', challenge: options.challenge, userId: current?.user_id, sessionToken: current?.token });
+      return response(options);
+    }
+    if (action === 'authenticate/verify') {
+      const pending = consumeChallenge(ctx);
+      if (pending.flow !== 'authenticate') throw new AuthError('Please restart sign-in.');
+      const key = db().prepare('SELECT * FROM passkeys WHERE id = ?').get(body.credential?.id || '') as unknown as Passkey | undefined;
+      if (!key || (pending.userId && key.user_id !== pending.userId)) throw new AuthError('This passkey is not registered to this account.');
+      if (pending.sessionToken && requireSession(ctx).token !== pending.sessionToken) throw new AuthError('Please restart verification.');
+      const result = await verifyAuthenticationResponse({ response: body.credential, expectedChallenge: pending.challenge, expectedOrigin: origin, expectedRPID: rpID, requireUserVerification: true, credential: { id: key.id, publicKey: new Uint8Array(Buffer.from(key.public_key, 'base64')), counter: key.counter } });
+      if (!result.verified) throw new AuthError('Your passkey could not be verified.');
+      db().prepare('UPDATE passkeys SET counter = ?, last_used = ? WHERE id = ?').run(result.authenticationInfo.newCounter, Date.now(), key.id);
+      if (pending.sessionToken) db().prepare('UPDATE sessions SET verified = ? WHERE token = ?').run(Date.now(), pending.sessionToken);
+      else startSession(ctx, key.user_id);
+      return response({ ok: true });
+    }
+    if (action === 'passkeys/rename' || action === 'passkeys/remove') {
+      const current = requireSession(ctx, true);
+      const keys = getPasskeys(current.user_id);
+      if (!keys.some(k => k.id === body.id)) throw new AuthError('This passkey was not found.', 404);
+      if (action === 'passkeys/remove') {
+        if (keys.length === 1 && !getUser(current.user_id)?.password) throw new AuthError('Add another passkey before removing your only sign-in method.');
+        db().prepare('DELETE FROM passkeys WHERE id = ? AND user_id = ?').run(body.id, current.user_id);
+      } else db().prepare('UPDATE passkeys SET name = ? WHERE id = ? AND user_id = ?').run(passkeyName(body.name), body.id, current.user_id);
+      return response({ ok: true });
+    }
+    throw new AuthError('Not found', 404);
+  } catch (error) {
+    if (error instanceof AuthError) return response({ error: error.message }, error.status);
+    console.error('Authentication request failed:', error instanceof Error ? error.message : 'Unknown error');
+    return response({ error: 'We could not complete that request. Please try again.' }, 400);
+  }
+};
