diff --git a/tests/auth-store.test.ts b/tests/auth-store.test.ts
new file mode 100644
index 0000000..e7cbb80
--- /dev/null
+++ b/tests/auth-store.test.ts
@@ -0,0 +1,36 @@
+import { test, after } from 'node:test';
+import assert from 'node:assert/strict';
+import { mkdtempSync, rmSync, statSync } from 'node:fs';
+import { tmpdir } from 'node:os';
+import { join } from 'node:path';
+import { DatabaseSync } from 'node:sqlite';
+import { db, hashPassword, checkPassword, digest, token } from '../src/lib/auth-store.ts';
+
+const directory = mkdtempSync(join(tmpdir(), 'times-auth-test-'));
+process.env.AUTH_DB_PATH = join(directory, 'auth.sqlite');
+after(() => { db().close(); rmSync(directory, { recursive: true, force: true }); });
+
+test('password credentials verify only the correct password and use individual salts', () => {
+  const first = hashPassword('my-password-42');
+  const second = hashPassword('my-password-42');
+  assert.notEqual(first, second);
+  assert.equal(checkPassword('my-password-42', first), true);
+  assert.equal(checkPassword('wrong-password', first), false);
+});
+
+test('accounts, passkeys, and opaque sessions persist with ownership constraints', () => {
+  const userId = token();
+  const rawSession = token();
+  db().prepare('INSERT INTO users VALUES (?, ?, ?)').run(userId, 'reader', hashPassword('reader-42'));
+  db().prepare('INSERT INTO passkeys VALUES (?, ?, ?, ?, ?, ?, ?, NULL)').run('credential-1', userId, 'Laptop', 'public-key', 0, '[]', Date.now());
+  db().prepare('INSERT INTO sessions VALUES (?, ?, ?, ?)').run(digest(rawSession), userId, Date.now() + 60_000, Date.now());
+  const secondConnection = new DatabaseSync(process.env.AUTH_DB_PATH!);
+  assert.equal((secondConnection.prepare('SELECT username FROM users WHERE id = ?').get(userId) as { username: string }).username, 'reader');
+  assert.equal((secondConnection.prepare('SELECT user_id FROM passkeys WHERE id = ?').get('credential-1') as { user_id: string }).user_id, userId);
+  assert.equal(secondConnection.prepare('SELECT token FROM sessions WHERE token = ?').get(rawSession), undefined);
+  assert.ok(secondConnection.prepare('SELECT token FROM sessions WHERE token = ?').get(digest(rawSession)));
+  assert.throws(() => db().prepare('INSERT INTO users VALUES (?, ?, NULL)').run(token(), 'reader'), /UNIQUE/);
+  assert.throws(() => db().prepare('INSERT INTO passkeys VALUES (?, ?, ?, ?, ?, ?, ?, NULL)').run('orphan', 'missing-user', 'Laptop', 'public-key', 0, '[]', Date.now()), /FOREIGN KEY/);
+  assert.equal(statSync(process.env.AUTH_DB_PATH!).mode & 0o777, 0o600);
+  secondConnection.close();
+});

