--- /dev/null
+++ b/seasonal-drink.js
@@ -0,0 +1,38 @@
+// Module scripts run after parsing, so every declarative shadow root is ready.
+class SeasonalDrink extends HTMLElement {
+  #button;
+
+  connectedCallback() {
+    if (this.#button) return;
+
+    // Reuse the parser-created root. Older engines can consume the same template.
+    if (!this.shadowRoot) {
+      const template = this.querySelector('template[shadowrootmode="open"]');
+      if (!template) return;
+      this.attachShadow({ mode: 'open' }).append(template.content.cloneNode(true));
+      template.remove();
+    }
+
+    const button = this.shadowRoot.querySelector('button');
+    if (!button) return;
+    this.#button = button;
+    const icon = button.querySelector('.favorite-icon');
+
+    // The native button owns the state; neither upgrade nor reconnect rebuilds DOM.
+    button.addEventListener('click', () => {
+      const favorite = button.getAttribute('aria-pressed') !== 'true';
+      button.setAttribute('aria-pressed', String(favorite));
+      if (icon) icon.textContent = favorite ? '★' : '☆';
+      this.dispatchEvent(new CustomEvent('favorite-change', {
+        bubbles: true,
+        composed: true,
+        detail: { drinkId: this.dataset.drinkId, favorite },
+      }));
+    });
+    button.disabled = false;
+  }
+}
+
+if (!customElements.get('seasonal-drink')) {
+  customElements.define('seasonal-drink', SeasonalDrink);
+}
