@@ -0,0 +1,90 @@
+const { test } = require('node:test');
+const assert = require('node:assert/strict');
+const { readFileSync } = require('node:fs');
+const { runInNewContext } = require('node:vm');
+
+const source = readFileSync(new URL('../seasonal-drink.js', `file://${__filename}`), 'utf8');
+
+function fixture({ declarative = true } = {}) {
+  const icon = { textContent: '☆' };
+  const button = new EventTarget();
+  const attributes = new Map([['aria-pressed', 'false']]);
+  button.disabled = true;
+  button.getAttribute = (name) => attributes.get(name);
+  button.setAttribute = (name, value) => attributes.set(name, value);
+  button.querySelector = () => icon;
+  const root = { querySelector: () => button };
+  let definition;
+  let clones = 0;
+  let removed = false;
+  const template = {
+    content: { cloneNode: () => { clones++; return root; } },
+    remove: () => { removed = true; },
+  };
+  class Host extends EventTarget {
+    shadowRoot = declarative ? root : null;
+    dataset = { drinkId: 'maple-oat-latte' };
+    querySelector() { return template; }
+    attachShadow() {
+      assert.equal(this.shadowRoot, null, 'must never replace a declarative root');
+      return { append: (content) => { this.shadowRoot = content; } };
+    }
+  }
+  class CustomEvent extends Event {
+    constructor(type, options) { super(type, options); this.detail = options.detail; }
+  }
+  runInNewContext(source, {
+    HTMLElement: Host,
+    CustomEvent,
+    customElements: { get: () => undefined, define: (_, constructor) => { definition = constructor; } },
+  });
+  const host = new definition();
+  return { host, root, button, icon, get clones() { return clones; }, get removed() { return removed; } };
+}
+
+test('all three cards ship their content, styles, and initial button state in HTML', () => {
+  const html = readFileSync(new URL('../index.html', `file://${__filename}`), 'utf8');
+  const cards = [...html.matchAll(/<seasonal-drink\b[^>]*>([\s\S]*?)<\/seasonal-drink>/g)];
+  assert.equal(cards.length, 3);
+  for (const [, card] of cards) {
+    assert.match(card, /<template shadowrootmode="open">\s*<style>[\s\S]*?:host/);
+    assert.match(card, /<h3 id="drink-name">[^<]+<\/h3>/);
+    assert.match(card, /<p>[^<]+<\/p>/);
+    assert.match(card, /<a href="\/menu\/[^"]+">View Details<\/a>/);
+    assert.match(card, /<button type="button"[^>]*aria-pressed="false" disabled>/);
+  }
+  assert.match(html, /<script type="module" src="\/seasonal-drink.js"><\/script>/);
+});
+
+test('upgrade preserves the existing root and button, toggles state, and survives reconnect', () => {
+  const f = fixture();
+  const changes = [];
+  f.host.addEventListener('favorite-change', (event) => changes.push(event));
+  f.host.connectedCallback();
+  assert.equal(f.host.shadowRoot, f.root);
+  assert.equal(f.root.querySelector('button'), f.button);
+  assert.equal(f.button.disabled, false);
+  assert.equal(f.clones, 0);
+  f.button.dispatchEvent(new Event('click'));
+  assert.equal(f.button.getAttribute('aria-pressed'), 'true');
+  assert.equal(f.icon.textContent, '★');
+  assert.equal(changes[0].detail.drinkId, 'maple-oat-latte');
+  assert.equal(changes[0].detail.favorite, true);
+  assert.equal(changes[0].bubbles, true);
+  assert.equal(changes[0].composed, true);
+  f.host.connectedCallback();
+  f.button.dispatchEvent(new Event('click'));
+  assert.equal(changes.length, 2, 'reconnect must not duplicate listeners');
+  assert.equal(f.button.getAttribute('aria-pressed'), 'false');
+  assert.equal(f.icon.textContent, '☆');
+});
+
+test('engines without declarative shadow DOM consume the supplied template once', () => {
+  const f = fixture({ declarative: false });
+  f.host.connectedCallback();
+  f.host.connectedCallback();
+  assert.equal(f.host.shadowRoot, f.root);
+  assert.equal(f.clones, 1);
+  assert.equal(f.removed, true);
+  assert.equal(f.button.disabled, false);
+});

