+import assert from 'node:assert/strict';
+import { readFile, readdir, stat } from 'node:fs/promises';
+import { resolve, dirname } from 'node:path';
+import { fileURLToPath } from 'node:url';
+
+const root = fileURLToPath(new URL('../', import.meta.url));
+const read = (path) => readFile(resolve(root, path), 'utf8');
+const headers = await read('_headers');
+const header = (name) => headers.match(new RegExp(`^  ${name}: (.+)$`, 'mi'))?.[1];
+const csp = header('Content-Security-Policy');
+assert.ok(headers.startsWith('/*\n'), 'Headers must cover every public route');
+for (const directive of ["default-src 'none'", "script-src 'none'", "style-src 'self'", "img-src 'self'", "connect-src 'none'", "font-src 'none'", "frame-src 'none'", "worker-src 'none'", "object-src 'none'", "base-uri 'none'", "form-action 'none'", "frame-ancestors 'none'", "require-trusted-types-for 'script'", "trusted-types 'none'"]) {
+  assert.ok(csp?.split('; ').includes(directive), `Missing CSP directive: ${directive}`);
+}
+assert.doesNotMatch(csp, /unsafe-|https?:|\*/i);
+assert.equal(header('Referrer-Policy'), 'no-referrer');
+assert.equal(header('X-Content-Type-Options'), 'nosniff');
+assert.equal(header('X-Frame-Options'), 'DENY');
+assert.equal(header('Cross-Origin-Resource-Policy'), 'same-origin');
+assert.ok(header('Strict-Transport-Security')?.startsWith('max-age='));
+for (const feature of ['camera', 'microphone', 'geolocation', 'payment', 'usb']) {
+  assert.ok(header('Permissions-Policy')?.split(', ').includes(`${feature}=()`), `Permission must be disabled: ${feature}`);
+}
+
+async function checkLocalAsset(reference, source) {
+  assert.ok(!/^(?:[a-z][a-z\d+.-]*:|\/\/)/i.test(reference), `${source}: external or embedded resource`);
+  const path = reference.startsWith('/') ? resolve(root, `.${reference}`) : resolve(dirname(resolve(root, source)), reference);
+  assert.ok(path.startsWith(root), 'Asset must stay inside the site');
+  assert.ok((await stat(path)).isFile(), `${source}: missing asset ${reference}`);
+}
+
+async function audit(path) {
+  if ((await stat(resolve(root, path))).isDirectory()) {
+    for (const child of await readdir(resolve(root, path))) await audit(`${path}/${child}`);
+    return;
+  }
+  assert.ok(!/\.(?:m?js|cjs|wasm)$/i.test(path), `${path}: client code requires a new privacy review`);
+  if (!/\.(?:html|css|svg)$/i.test(path)) return;
+  const source = await read(path);
+  assert.doesNotMatch(source, /(?:https?:)?\/\/|@import\b|<\s*(?:script|iframe|object|embed|form)\b|\bon\w+\s*=|\bstyle\s*=|\b(?:ping|srcdoc|srcset)\s*=|\brel\s*=\s*["'](?:preconnect|dns-prefetch|prefetch|prerender)|\b(?:localStorage|sessionStorage|indexedDB|sendBeacon)\b/i, `${path}: unexpected network, executable, or storage surface`);
+  if (path.endsWith('.html')) {
+    assert.ok(source.includes('<meta name="referrer" content="no-referrer">'), `${path}: missing referrer fallback`);
+    const meta = source.match(/<meta http-equiv="Content-Security-Policy" content="([^"]+)">/)?.[1];
+    assert.equal(meta, csp.replace("; frame-ancestors 'none'", ''), `${path}: CSP fallback differs from header`);
+    for (const match of source.matchAll(/\b(?:src|href)="([^"]+)"/g)) {
+      assert.doesNotMatch(match[1], /^(?:[a-z][a-z\d+.-]*:|\/\/)/i, `${path}: external navigation needs review`);
+      if (match[1].startsWith('/assets/')) await checkLocalAsset(match[1], path);
+    }
+  }
+  for (const match of source.matchAll(/url\(\s*['"]?([^\s'"\)]+)['"]?\s*\)/g)) await checkLocalAsset(match[1], path);
+}
+
+for (const path of ['index.html', 'privacy-policy', 'assets']) await audit(path);
+assert.ok((await read('index.html')).includes('href="/privacy-policy/"'));
+console.log('Privacy audit passed: local assets, no client scripts or external connections, restrictive CSP and privacy headers.');
