@@ -0,0 +1,52 @@
+import assert from 'node:assert/strict';
+import { readFile, readdir, access } from 'node:fs/promises';
+
+// A deliberately script-free site: new executable assets require a privacy review.
+export function auditSource(source, filename) {
+  const forbidden = [
+    [/<script\b|\bon\w+\s*=|\bjavascript\s*:/i, 'executable markup'],
+    [/<style\b|\sstyle\s*=/i, 'inline styles'],
+    [/<(?:iframe|object|embed|form|input|textarea|base)\b/i, 'embedded content or data collection'],
+    [/\b(?:src|href|srcset|action|ping)\s*=\s*["']?\s*(?:https?:|\/\/|data:|blob:)/i, 'external or embedded resource'],
+    [/url\(\s*["']?\s*(?:https?:|\/\/|data:|blob:)|@import\b/i, 'external stylesheet resource'],
+    [/\b(?:document\.cookie|localStorage|sessionStorage|indexedDB|sendBeacon|fetch\s*\(|XMLHttpRequest|WebSocket|serviceWorker)\b/i, 'browser storage or network API'],
+    [/<meta\b[^>]*http-equiv\s*=\s*["']?refresh/i, 'automatic redirect'],
+  ];
+  for (const [pattern, reason] of forbidden) {
+    assert(!pattern.test(source), `${filename}: privacy audit rejected ${reason}`);
+  }
+}
+
+async function walk(dir) {
+  const entries = await readdir(dir, { withFileTypes: true });
+  return (await Promise.all(entries.map(entry => entry.isDirectory()
+    ? walk(`${dir}/${entry.name}`) : [`${dir}/${entry.name}`]))).flat();
+}
+
+const headers = await readFile('_headers', 'utf8');
+const vercel = JSON.parse(await readFile('vercel.json', 'utf8'));
+const vercelHeaders = Object.fromEntries(vercel.headers[0].headers.map(({ key, value }) => [key, value]));
+for (const line of headers.split('\n').filter(line => line.startsWith('  '))) {
+  const split = line.indexOf(':');
+  assert.equal(vercelHeaders[line.slice(2, split)], line.slice(split + 2), 'Hosting header configurations must match');
+}
+for (const directive of ["script-src 'none'", "connect-src 'none'", "form-action 'none'", "frame-ancestors 'none'"]) {
+  assert(headers.includes(directive), `Missing CSP directive: ${directive}`);
+}
+const pages = ['index.html', 'privacy-policy.html'];
+for (const file of [...pages, ...await walk('assets')]) {
+  assert(!/\.(?:m?js|cjs|wasm|svg)$/i.test(file), `${file}: executable asset requires review`);
+  if (!/\.(?:html|css)$/i.test(file)) continue;
+  const source = await readFile(file, 'utf8');
+  auditSource(source, file);
+  if (file.endsWith('.html')) {
+    assert(source.includes('<meta name="referrer" content="no-referrer">'), `${file}: missing referrer protection`);
+    const policy = source.match(/http-equiv="Content-Security-Policy" content="([^"]+)"/)?.[1];
+    assert.equal(`${policy}; frame-ancestors 'none'`, vercelHeaders['Content-Security-Policy'], `${file}: CSP mismatch`);
+  }
+  // Confirm local resource references are present in the published asset tree.
+  for (const match of source.matchAll(/(?:href=["']|url\(["']?)(\/assets\/[^"')\s]+)/g)) {
+    await access(`.${match[1]}`);
+  }
+}
+console.log('Privacy audit passed: no scripts, collection markup, external resources, or browser storage; CSP and hosting headers agree.');
