@@ -0,0 +1,21 @@
+const accountService = 'https://us-central1-web-devrel-apps.cloudfunctions.net/times_cdn/api';
+
+// Keep credential requests free of ambient cookies, referrers, and persistent storage.
+export async function submitCredentials(
+  action: 'login' | 'register',
+  username: string,
+  password: string,
+): Promise<boolean> {
+  const response = await fetch(`${accountService}/${action}`, {
+    method: 'POST',
+    credentials: 'omit',
+    referrerPolicy: 'no-referrer',
+    cache: 'no-store',
+    redirect: 'error',
+    headers: { 'Content-Type': 'application/json' },
+    body: JSON.stringify({ username, password }),
+  });
+
+  // Do not expose service errors or retain returned tokens in the client.
+  return response.ok;
+}
