@@ -0,0 +1,35 @@
+import assert from 'node:assert/strict';
+import { test } from 'node:test';
+import { submitCredentials } from '../src/lib/auth.ts';
+
+for (const action of ['login', 'register']) {
+  test(`${action} sends only the required fields without ambient credentials or referrers`, async (t) => {
+    const fetch = t.mock.method(globalThis, 'fetch', async (url, options) => {
+      assert.equal(url, `https://us-central1-web-devrel-apps.cloudfunctions.net/times_cdn/api/${action}`);
+      assert.equal(options.method, 'POST');
+      assert.deepEqual(JSON.parse(options.body), { username: 'reader', password: 'example-password9' });
+      assert.deepEqual(options.headers, { 'Content-Type': 'application/json' });
+      assert.equal(options.credentials, 'omit');
+      assert.equal(options.referrerPolicy, 'no-referrer');
+      assert.equal(options.cache, 'no-store');
+      assert.equal(options.redirect, 'error');
+      // Successful responses need not return JSON or expose tokens to the UI.
+      return new Response(null, { status: 204 });
+    });
+    assert.equal(await submitCredentials(action, 'reader', 'example-password9'), true);
+    assert.equal(fetch.mock.callCount(), 1);
+  });
+}
+
+test('rejects a failed response without reading or exposing the backend error', async (t) => {
+  t.mock.method(globalThis, 'fetch', async () => ({
+    ok: false,
+    json() { throw new Error('Sensitive response bodies must not be read'); },
+  }));
+  assert.equal(await submitCredentials('login', 'reader', 'example-password9'), false);
+});
+
+test('propagates network and blocked redirect failures for generic form handling', async (t) => {
+  t.mock.method(globalThis, 'fetch', async () => { throw new TypeError('Network failure'); });
+  await assert.rejects(submitCredentials('register', 'reader', 'example-password9'), TypeError);
+});

