+      try {
+        return await api('/api/login/verify', encoded);
+      } catch (error) {
+        if (error.status === 404) {
+          if (PublicKeyCredential.signalUnknownCredential) {
+            try {
+              await PublicKeyCredential.signalUnknownCredential({ rpId: publicKey.rpId, credentialId: encoded.id });
+            } catch { /* Password-manager synchronization is optional. */ }
+          }
+          throw new Error('This passkey is no longer recognized. Please use your password or another passkey.');
+        }
+        throw error;
+      }
+    }
+
+    async function startConditional() {
+      if (!dialog.open || signedIn || busy || !capabilities.conditionalGet || conditionalController) return;
+      const controller = new AbortController();
+      conditionalController = controller;
+      let verifying = false;
+      try {
+        const publicKey = await getOptions(controller.signal);
+        const credential = await navigator.credentials.get({ publicKey, mediation: 'conditional', signal: controller.signal });
+        if (controller.signal.aborted || !dialog.open || busy) return;
+        setBusy(true);
+        verifying = true;
+        completeSignIn(await verifyCredential(credential, publicKey));
+      } catch (error) {
+        if (!controller.signal.aborted && dialog.open && !['AbortError', 'NotAllowedError'].includes(error.name)) {
+          message.textContent = error.message;
+        }
+      } finally {
+        if (conditionalController === controller) conditionalController = null;
+        if (verifying) setBusy(false);
+      }
+    }
+
+    document.querySelectorAll('[data-sign-in], [data-auth-required]').forEach(control => {
+      control.addEventListener('click', async event => {
+        // Keep modified link clicks available for opening another tab.
+        if (event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
+        if (signedIn && control.matches('a')) return;
+        event.preventDefault();
+        if (busy) return;
+        trigger = control;
+        destination = control.matches('a') ? control.href : null;
+        stopConditional();
