+          if (dialog.open) void startConditional();
+        }
+      });
+    });
+
+    form.addEventListener('submit', async event => {
+      event.preventDefault();
+      if (busy) return;
+      stopConditional();
+      setBusy(true);
+      message.textContent = 'Signing in…';
+      try {
+        completeSignIn(await api('/api/login/password', {
+          username: form.elements.username.value,
+          password: form.elements.password.value,
+        }));
+      } catch (error) {
+        if (dialog.open) message.textContent = error.message;
+      } finally {
+        setBusy(false);
+        void startConditional();
+      }
+    });
+
+    passkeyButton.addEventListener('click', async () => {
+      if (busy) return;
+      stopConditional();
+      setBusy(true);
+      const controller = new AbortController();
+      explicitController = controller;
+      message.textContent = 'Choose a passkey in your browser.';
+      try {
+        const publicKey = await getOptions(controller.signal);
+        const credential = await navigator.credentials.get({ publicKey, signal: controller.signal });
+        if (!controller.signal.aborted) completeSignIn(await verifyCredential(credential, publicKey));
+      } catch (error) {
+        if (!controller.signal.aborted && dialog.open) {
+          message.textContent = error.name === 'NotAllowedError' ? 'No passkey selected. Try again or use your password.' : error.message;
+        }
+      } finally {
+        explicitController = null;
+        setBusy(false);
+        void startConditional();
+      }
+    });
+
+    document.querySelector('.password-toggle').addEventListener('click', event => {
+      const input = document.querySelector('#sign-in-password');
+      const visible = input.type === 'password';
+      input.type = visible ? 'text' : 'password';
+      event.currentTarget.textContent = visible ? 'Hide password' : 'Show password';
+      event.currentTarget.setAttribute('aria-pressed', String(visible));
+    });
+
+    dialog.addEventListener('close', () => {
+      stopConditional();
+      explicitController?.abort();
+      destination = null;
+      resetForm();
+      status.textContent = signedIn ? 'You’re signed in.' : 'Sign-in closed. Keep browsing and sign in whenever you’re ready.';
+    });
