+      const session = await api('/api/login/session');
+      if (session.authenticated === true && !busy && !dialog.open) {
+        signedIn = true;
+        renderSignedIn();
+      }
+    } catch { /* Anonymous browsing and inline sign-in remain available. */ }
+  </script>
+
