@@ -0,0 +1,110 @@
+import { createServer } from 'node:http';
+import { randomBytes } from 'node:crypto';
+import { readFile, mkdir, appendFile } from 'node:fs/promises';
+import { dirname, resolve } from 'node:path';
+
+const root = new URL('./', import.meta.url);
+const [template, styles, script] = await Promise.all([
+  readFile(new URL('index.html', root), 'utf8'),
+  readFile(new URL('styles.css', root)),
+  readFile(new URL('newsletter.js', root)),
+]);
+const subscriberFile = resolve(process.env.NEWSLETTER_FILE || new URL('data/subscribers.jsonl', root).pathname);
+
+async function readBody(req, limit) {
+  let size = 0;
+  const chunks = [];
+  for await (const chunk of req) {
+    size += chunk.length;
+    if (size > limit) throw Object.assign(new Error('Body too large'), { status: 413 });
+    chunks.push(chunk);
+  }
+  return Buffer.concat(chunks).toString('utf8');
+}
+
+const server = createServer(async (req, res) => {
+  const nonce = randomBytes(18).toString('base64');
+  // Apply to every response, including document and any future worker responses.
+  res.setHeader('Connection-Allowlist', '(response-origin "https://images.unsplash.com"); report-to=connections');
+  res.setHeader('Reporting-Endpoints', 'connections="/api/security-reports"');
+  res.setHeader('Content-Security-Policy', [
+    "default-src 'self'",
+    `script-src 'nonce-${nonce}' 'strict-dynamic'`,
+    "script-src-attr 'none'",
+    "style-src 'self'",
+    "connect-src 'self'",
+    "img-src 'self' https://images.unsplash.com",
+    "form-action 'self'",
+    "worker-src 'none'",
+    "frame-src 'none'",
+    "object-src 'none'",
+    "base-uri 'none'",
+    "frame-ancestors 'none'",
+    "require-trusted-types-for 'script'",
+    "trusted-types 'none'",
+    'report-to connections',
+  ].join('; '));
+  res.setHeader('X-Content-Type-Options', 'nosniff');
+  res.setHeader('X-DNS-Prefetch-Control', 'off');
+  res.setHeader('Referrer-Policy', 'no-referrer');
+  res.setHeader('Cache-Control', 'no-store');
+
+  const send = (status, body, type = 'text/plain; charset=utf-8') => {
+    res.writeHead(status, { 'Content-Type': type });
+    res.end(req.method === 'HEAD' ? undefined : body);
+  };
+  let path;
+  try {
+    path = new URL(req.url, 'http://localhost').pathname;
+    if (path === '/api/security-reports' && req.method === 'POST') {
+      // Reports can contain customer URLs. Bound and discard them without logging PII.
+      await readBody(req, 65536);
+      res.writeHead(204);
+      res.end();
+      return;
+    }
+    if (path === '/api/newsletter' && req.method === 'POST') {
+      if (req.headers['sec-fetch-site'] && req.headers['sec-fetch-site'] !== 'same-origin') {
+        send(403, 'Please sign up from the Daily Grind homepage.');
+        return;
+      }
+      if (req.headers['content-type']?.split(';')[0].trim() !== 'application/x-www-form-urlencoded') {
+        send(415, 'Unsupported signup format.');
+        return;
+      }
+      const data = new URLSearchParams(await readBody(req, 4096));
+      const email = data.get('email')?.trim();
+      if (data.getAll('email').length !== 1 || !email || email.length > 254 || !/^[a-zA-Z0-9.!#$%&'*+\/=?^_`{|}~-]+@[a-zA-Z0-9](?:[a-zA-Z0-9-]*[a-zA-Z0-9])?(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]*[a-zA-Z0-9])?)*$/.test(email)) {
+        send(400, 'Please enter a valid email address and try again.');
+        return;
+      }
+      await mkdir(dirname(subscriberFile), { recursive: true, mode: 0o700 });
+      await appendFile(subscriberFile, JSON.stringify({ email, subscribedAt: new Date().toISOString() }) + '\n', { mode: 0o600 });
+      if (req.headers.accept?.includes('application/json')) {
+        send(201, JSON.stringify({ ok: true }), 'application/json; charset=utf-8');
+      } else {
+        send(201, '<!doctype html><html lang="en"><meta charset="utf-8"><title>Subscribed | Daily Grind</title><h1>Thanks for subscribing!</h1><p>You’re signed up for the Daily Grind newsletter.</p><a href="/">Back to Daily Grind</a></html>', 'text/html; charset=utf-8');
+      }
+      return;
+    }
+    if (req.method !== 'GET' && req.method !== 'HEAD') {
+      res.setHeader('Allow', path.startsWith('/api/') ? 'POST' : 'GET, HEAD');
+      send(405, 'Method not allowed.');
+      return;
+    }
+    if (path === '/' || path === '/index.html') {
+      send(200, template.replace('__SCRIPT_NONCE__', nonce), 'text/html; charset=utf-8');
+    } else if (path === '/styles.css') {
+      send(200, styles, 'text/css; charset=utf-8');
+    } else if (path === '/newsletter.js') {
+      send(200, script, 'text/javascript; charset=utf-8');
+    } else {
+      send(404, 'Page not found.');
+    }
+  } catch (error) {
+    send(error.status || 500, 'We couldn’t process your request. Please try again.');
+  }
+});
+
+server.requestTimeout = 15000;
+server.listen(Number(process.env.PORT || 11222), process.env.HOST || '0.0.0.0');
