new file mode 100644
index 0000000..4fd6715
--- /dev/null
+++ b/server.mjs
@@ -0,0 +1,87 @@
+import { createServer } from 'node:http';
+import { readFile, mkdir, appendFile } from 'node:fs/promises';
+import { fileURLToPath } from 'node:url';
+import { resolve, dirname } from 'node:path';
+
+const root = dirname(fileURLToPath(import.meta.url));
+const signupFile = resolve(process.env.NEWSLETTER_FILE || resolve(root, 'data/newsletter.jsonl'));
+const assets = new Map([
+  ['/', ['index.html', 'text/html; charset=utf-8']],
+  ['/index.html', ['index.html', 'text/html; charset=utf-8']],
+  ['/styles.css', ['public/styles.css', 'text/css; charset=utf-8']],
+  ['/newsletter.js', ['public/newsletter.js', 'text/javascript; charset=utf-8']],
+]);
+const policy = [
+  "default-src 'none'",
+  "script-src 'self'",
+  "style-src 'self'",
+  "img-src 'self' https://images.unsplash.com",
+  "connect-src 'self'",
+  "form-action 'self'",
+  "base-uri 'none'",
+  "object-src 'none'",
+  "frame-ancestors 'none'",
+].join('; ');
+
+function send(res, status, body, type = 'application/json; charset=utf-8') {
+  res.writeHead(status, { 'Content-Type': type });
+  res.end(type.startsWith('application/json') ? JSON.stringify(body) : body);
+}
+
+const server = createServer(async (req, res) => {
+  res.setHeader('Content-Security-Policy', policy);
+  res.setHeader('X-Content-Type-Options', 'nosniff');
+  res.setHeader('Referrer-Policy', 'no-referrer');
+  res.setHeader('X-Frame-Options', 'DENY');
+  res.setHeader('Cache-Control', 'no-store');
+  try {
+    const path = new URL(req.url, 'http://localhost').pathname;
+    if (path === '/api/newsletter') {
+      if (req.method !== 'POST') {
+        res.setHeader('Allow', 'POST');
+        return send(res, 405, { error: 'Use POST to sign up.' });
+      }
+      if (req.headers['sec-fetch-site'] === 'cross-site') {
+        return send(res, 403, { error: 'Please sign up from our homepage.' });
+      }
+      if (req.headers['content-type']?.split(';')[0].trim().toLowerCase() !== 'application/json') {
+        return send(res, 415, { error: 'Expected JSON.' });
+      }
+      let size = 0;
+      const chunks = [];
+      for await (const chunk of req) {
+        size += chunk.length;
+        if (size > 2048) return send(res, 413, { error: 'Request too large.' });
+        chunks.push(chunk);
+      }
+      let payload;
+      try {
+        payload = JSON.parse(Buffer.concat(chunks).toString('utf8'));
+      } catch {
+        return send(res, 400, { error: 'Invalid JSON.' });
+      }
+      const email = typeof payload?.email === 'string' ? payload.email.trim() : '';
+      if (email.length > 254 || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
+        return send(res, 400, { error: 'Enter a valid email address.' });
+      }
+      await mkdir(dirname(signupFile), { recursive: true, mode: 0o700 });
+      await appendFile(signupFile, `${JSON.stringify({ email, subscribedAt: new Date().toISOString() })}\n`, { mode: 0o600 });
+      return send(res, 201, { ok: true });
+    }
+    const asset = assets.get(path);
+    if (!asset) return send(res, 404, { error: 'Not found.' });
+    if (req.method !== 'GET' && req.method !== 'HEAD') {
+      res.setHeader('Allow', 'GET, HEAD');
+      return send(res, 405, { error: 'Method not allowed.' });
+    }
+    const content = await readFile(resolve(root, asset[0]));
+    res.writeHead(200, { 'Content-Type': asset[1] });
+    res.end(req.method === 'HEAD' ? undefined : content);
+  } catch {
+    send(res, 500, { error: 'Unable to process your request. Please try again.' });
+  }
+});
+
+server.requestTimeout = 15000;
+server.headersTimeout = 10000;
+server.listen(Number(process.env.PORT || 11222), '0.0.0.0');

