+const REPORT_LIMIT = 16 * 1024;
+const POLICY = [
+  "default-src 'none'",
+  // There is no JavaScript on this site. Do not authorize future scripts implicitly.
+  "script-src 'none' 'report-sample'",
+  "script-src-attr 'none'",
+  "style-src 'self'",
+  "style-src-attr 'none'",
+  "img-src 'self' https://images.unsplash.com",
+  "connect-src 'none'",
+  "object-src 'none'",
+  "base-uri 'none'",
+  "frame-ancestors 'none'",
+  "form-action 'self'",
+  "require-trusted-types-for 'script'",
+  "trusted-types 'none'",
+  'report-to default',
+  'report-uri /security-reports',
+].join('; ');
+
+const PAGE_ROUTES = new Set([
+  '/', '/index.html', '/menu', '/locations', '/rewards', '/account',
+  '/order-online', '/menu/seasonal', '/menu/espresso', '/menu/cold-brew',
+  '/about', '/careers', '/contact', '/privacy-policy',
+]);
+
+function logoutPage(complete) {
+  return `<!doctype html>
+<html lang="en"><head><meta charset="utf-8">
+<meta name="viewport" content="width=device-width, initial-scale=1">
+<title>${complete ? 'Signed out' : 'Sign out'} | The Daily Grind</title>
+<link rel="stylesheet" href="/styles.css"></head>
+<body><main class="container"><h1>${complete ? 'You are signed out' : 'Sign out of The Daily Grind'}</h1>
+${complete ? '<p>Your sign-out request is complete.</p>' : '<form action="/logout" method="post"><button class="btn" type="submit">Sign out</button></form>'}
+<p><a href="/">Return to The Daily Grind</a></p></main></body></html>`;
+}
+
+function createHandler({ origin = 'http://localhost:11222', policyMode = 'enforce', onReport = console.info } = {}) {
+  const publicURL = new URL(origin);
+  if (!['http:', 'https:'].includes(publicURL.protocol) || publicURL.username || publicURL.password ||
+      publicURL.pathname !== '/' || publicURL.search || publicURL.hash) {
+    throw new Error('PUBLIC_ORIGIN must be an HTTP(S) origin without credentials, path, query or fragment');
+  }
+  if (!['enforce', 'report-only'].includes(policyMode)) throw new Error('Invalid CSP_MODE');
+
+  return async function handle(req, res) {
+    res.setHeader('Cache-Control', 'no-store');
+    res.setHeader('X-Content-Type-Options', 'nosniff');
+    res.setHeader('X-Frame-Options', 'DENY');
+    res.setHeader('Referrer-Policy', 'no-referrer');
+    res.setHeader('Permissions-Policy', 'camera=(), microphone=(), geolocation=(), payment=(), usb=(), focus-without-user-activation=()');
+    res.setHeader('Cross-Origin-Opener-Policy', 'same-origin-allow-popups');
+    res.setHeader('Cross-Origin-Resource-Policy', 'same-origin');
+    res.setHeader('Vary', 'Sec-Fetch-Dest, Sec-Fetch-Mode, Sec-Fetch-Site');
