+        // Logs intentionally contain no URLs, referrers, samples, cookies or other input strings.
+        const directives = new Set(['script-src', 'script-src-elem', 'script-src-attr', 'style-src', 'style-src-elem', 'style-src-attr', 'img-src', 'connect-src', 'object-src', 'base-uri', 'frame-ancestors', 'form-action', 'require-trusted-types-for', 'trusted-types']);
