+        }
+        return send(200, logoutPage(false), 'text/html; charset=utf-8');
+      }
+
+      if (!['GET', 'HEAD'].includes(req.method)) return methodNotAllowed('GET, HEAD');
+      // Explicit routes prevent accidentally exposing source, dotfiles or dependencies.
+      if (pathname === '/styles.css') {
+        return send(200, await readFile(path.join(__dirname, 'styles.css')), 'text/css; charset=utf-8');
+      }
+      if (PAGE_ROUTES.has(pathname)) {
+        return send(200, await readFile(path.join(__dirname, 'index.html')), 'text/html; charset=utf-8');
+      }
+      return send(404, 'Not found');
+    } catch {
+      return send(500, 'Server error');
+    }
+  };
+}
+
+module.exports = { createHandler };
