@@ -0,0 +1,126 @@
+'use strict';
+
+const test = require('node:test');
+const assert = require('node:assert/strict');
+const { Readable } = require('node:stream');
+const { readFile } = require('node:fs/promises');
+const { createHandler } = require('../app');
+
+const origin = 'https://coffee.example';
+async function request(url, { method = 'GET', headers = {}, body = '', handler = createHandler({ origin }) } = {}) {
+  const req = Readable.from(body ? [Buffer.from(body)] : []);
+  Object.assign(req, { url, method, headers });
+  const res = {
+    headers: {}, statusCode: 200,
+    setHeader(name, value) { this.headers[name.toLowerCase()] = value; },
+    end(value) { this.body = value?.toString() || ''; },
+  };
+  await handler(req, res);
+  return res;
+}
+
+test('documents enforce the audited policy and preserve the existing site', async () => {
+  const res = await request('/');
+  assert.equal(res.statusCode, 200);
+  assert.match(res.body, /Wake Up Your Senses/);
+  for (const directive of ["default-src 'none'", "script-src 'none' 'report-sample'", "style-src 'self'", "img-src 'self' https:\/\/images.unsplash.com", "require-trusted-types-for 'script'", "trusted-types 'none'", "frame-ancestors 'none'", 'report-to default']) {
