+const { readFileSync } = require('node:fs');
+const path = require('node:path');
+
+// Explicit routes preserve existing navigation without exposing project files.
+const pages = new Set([
+  '/', '/index.html', '/menu', '/locations', '/rewards', '/account',
+  '/order-online', '/menu/seasonal', '/menu/espresso', '/menu/cold-brew',
+  '/about', '/careers', '/contact', '/privacy-policy',
+]);
+
+function logoutPage(complete) {
+  return `<!doctype html>
+<html lang="en"><head><meta charset="utf-8">
+<meta name="viewport" content="width=device-width, initial-scale=1">
+<title>${complete ? 'Signed out' : 'Sign out'} | The Daily Grind</title>
+<link rel="stylesheet" href="/styles.css"></head>
+<body><main class="container logout-page">
+<h1>${complete ? 'You’re signed out' : 'Sign out of The Daily Grind'}</h1>
+${complete ? '<p>Your browser session data has been cleared.</p>' :
+    '<p>Confirm to clear your session on this device.</p><form action="/logout" method="post"><button class="btn" type="submit">Sign out</button></form>'}
+<p><a href="/">Return to The Daily Grind</a></p>
+</main></body></html>`;
+}
+
+function createHandler({
+  publicOrigin = process.env.PUBLIC_ORIGIN,
+  policyMode = process.env.SECURITY_POLICY_MODE || 'enforce',
+} = {}) {
+  if (!['enforce', 'report-only'].includes(policyMode)) {
+    throw new Error('SECURITY_POLICY_MODE must be enforce or report-only');
+  }
+  let origin;
+  if (publicOrigin) {
+    const parsed = new URL(publicOrigin);
+    if (!['http:', 'https:'].includes(parsed.protocol) || parsed.origin !== publicOrigin) {
+      throw new Error('PUBLIC_ORIGIN must be an HTTP(S) origin without a trailing slash');
+    }
+    origin = parsed.origin;
+  }
+  const https = origin?.startsWith('https://');
+  const index = readFileSync(path.join(__dirname, 'index.html'));
+  const css = readFileSync(path.join(__dirname, 'styles.css'));
+  const baseline = "script-src 'none'; object-src 'none'; base-uri 'none'; frame-ancestors 'none'; form-action 'self'";
+  const policy = [
+    "default-src 'none'", baseline, "style-src 'self'", "style-src-attr 'none'",
+    "img-src 'self' https://images.unsplash.com", "connect-src 'none'",
+    "font-src 'none'", "frame-src 'none'", "worker-src 'none'",
+    "manifest-src 'none'", "require-trusted-types-for 'script'", "trusted-types 'none'",
+    ...(https ? ['upgrade-insecure-requests'] : []),
+  ].join('; ');
+
+  return function handleRequest(req, res) {
+    res.setHeader('Content-Security-Policy', policyMode === 'enforce' ? policy : baseline);
+    if (policyMode === 'report-only') {
+      res.setHeader('Content-Security-Policy-Report-Only', policy);
+    }
+    res.setHeader('X-Content-Type-Options', 'nosniff');
+    res.setHeader('X-Frame-Options', 'DENY');
+    // Preserve same-origin form Origin headers for the logout CSRF check.
+    res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
+    res.setHeader('Permissions-Policy', 'camera=(), microphone=(), geolocation=(), payment=(), usb=()');
+    res.setHeader('Cross-Origin-Opener-Policy', 'same-origin');
+    res.setHeader('Cross-Origin-Resource-Policy', 'same-origin');
+    res.setHeader('Cache-Control', 'no-store');
+    if (https) res.setHeader('Strict-Transport-Security', 'max-age=31536000');
+
+    function send(status, body, type = 'text/plain; charset=utf-8') {
+      res.writeHead(status, { 'Content-Type': type });
+      res.end(req.method === 'HEAD' ? undefined : body);
+    }
+
+    let url;
+    try {
+      // Do not use the untrusted Host header to parse the request target.
+      if (!req.url.startsWith('/') || req.url.startsWith('//')) throw new Error('Invalid target');
+      url = new URL(req.url, 'http://localhost');
+    } catch {
+      return send(400, 'Bad request');
+    }
+
+    const isLogout = url.pathname === '/logout' || url.pathname === '/logout/';
+    if (isLogout && req.method === 'POST') {
+      // Browser form POSTs carry Origin. Fail closed if it is absent or foreign.
+      // Set PUBLIC_ORIGIN behind a TLS proxy; forwarded headers are not trusted.
+      const expectedOrigin = origin || `${req.socket.encrypted ? 'https' : 'http'}://${req.headers.host}`;
+      if (req.headers.origin !== expectedOrigin || req.headers['sec-fetch-site'] === 'cross-site') {
+        return send(403, 'Forbidden');
+      }
+      res.setHeader('Clear-Site-Data', '"cache", "cookies", "storage"');
+      // Explicit expiry also works where Clear-Site-Data is unsupported.
+      const names = new Set(['session', '__Host-session']);
+      for (const cookie of (req.headers.cookie || '').split(';')) {
+        const name = cookie.trim().split('=')[0];
+        if (/^[!#$%&'*+.^_`|~0-9A-Za-z-]+$/.test(name)) names.add(name);
+      }
+      res.setHeader('Set-Cookie', [...names].map(name =>
+        `${name}=; Path=/; Max-Age=0; Expires=Thu, 01 Jan 1970 00:00:00 GMT; HttpOnly; SameSite=Strict${https || req.socket.encrypted || name.startsWith('__Host-') || name.startsWith('__Secure-') ? '; Secure' : ''}`));
+      return send(200, logoutPage(true), 'text/html; charset=utf-8');
+    }
+
+    if (!['GET', 'HEAD'].includes(req.method)) {
+      res.setHeader('Allow', isLogout ? 'GET, HEAD, POST' : 'GET, HEAD');
+      return send(405, 'Method not allowed');
+    }
+    if (isLogout) return send(200, logoutPage(false), 'text/html; charset=utf-8');
+    if (url.pathname === '/styles.css') return send(200, css, 'text/css; charset=utf-8');
+    if (pages.has(url.pathname)) return send(200, index, 'text/html; charset=utf-8');
+    return send(404, 'Not found');
+  };
+}
+
+module.exports = { createHandler };
