diff --git a/test/security.test.js b/test/security.test.js
new file mode 100644
index 0000000..6dbf048
--- /dev/null
+++ b/test/security.test.js
@@ -0,0 +1,114 @@
+const test = require('node:test');
+const assert = require('node:assert/strict');
+const { readFileSync } = require('node:fs');
+const path = require('node:path');
+// This module exports only a handler: no server entrypoint is imported or started.
+const { createHandler } = require('../app');
+
+const origin = 'https://daily-grind.example';
+const handler = createHandler({ publicOrigin: origin, policyMode: 'enforce' });
+function request(url, { method = 'GET', headers = {}, handle = handler } = {}) {
+  const response = { headers: {}, status: undefined, body: undefined,
+    setHeader(name, value) { this.headers[name.toLowerCase()] = value; },
+    writeHead(status, values) {
+      this.status = status;
+      for (const [name, value] of Object.entries(values)) this.setHeader(name, value);
+    },
+    end(body) { this.body = body?.toString() || ''; },
+  };
+  handle({ url, method, headers: { host: 'daily-grind.example', ...headers }, socket: {} }, response);
+  return response;
+}
+
+test('logout GET and HEAD are safe, including prefetch requests', () => {
+  for (const url of ['/logout', '/logout/']) {
+    for (const method of ['GET', 'HEAD']) {
+      const res = request(url, { method, headers: { purpose: 'prefetch' } });
+      assert.equal(res.status, 200);
+      assert.equal(res.headers['clear-site-data'], undefined);
+      assert.equal(res.headers['set-cookie'], undefined);
+      if (method === 'GET') assert.match(res.body, /form action="\/logout" method="post"/);
+      else assert.equal(res.body, '');
+    }
+  }
+});
+
+test('same-origin POST clears site data and expires cookies without reflecting input', () => {
+  const res = request('/logout?next=https://evil.example', {
+    method: 'POST', headers: { origin, cookie: 'session=secret; preferences=dark; bad name=value' },
+  });
+  assert.equal(res.status, 200);
+  assert.equal(res.headers['clear-site-data'], '"cache", "cookies", "storage"');
+  assert.equal(res.headers['cache-control'], 'no-store');
+  assert.ok(res.headers['set-cookie'].some(cookie => cookie.startsWith('preferences=;')));
+  for (const cookie of res.headers['set-cookie']) {
+    assert.match(cookie, /Max-Age=0/);
+    assert.match(cookie, /; Secure$/);
+    assert.doesNotMatch(cookie, /secret|bad name/);
+  }
+  assert.doesNotMatch(res.body, /evil.example|secret/);
+  assert.equal(res.headers.location, undefined);
+});
+
+test('logout rejects foreign, missing, null, spoofed-host, and cross-site requests', () => {
+  for (const headers of [
+    {}, { origin: 'null' }, { origin: 'https://evil.example' },
+    { origin: 'https://evil.example', host: 'evil.example' },
+    { origin, 'sec-fetch-site': 'cross-site' },
+    { 'x-forwarded-host': 'evil.example', 'x-forwarded-proto': 'https', origin: 'https://evil.example' },
+  ]) {
+    const res = request('/logout', { method: 'POST', headers });
+    assert.equal(res.status, 403);
+    assert.equal(res.headers['clear-site-data'], undefined);
+    assert.equal(res.headers['set-cookie'], undefined);
+  }
+});
+
+test('private files, malformed targets, unknown paths and methods are handled safely', () => {
+  for (const url of ['/package.json', '/server.js', '/app.js', '/.git/config', '/%2e%2e/package.json', '/unknown']) {
+    assert.equal(request(url).status, 404);
+  }
+  assert.equal(request('http://evil.example/logout').status, 400);
+  assert.equal(request('//evil.example/logout').status, 400);
+  const res = request('/logout', { method: 'DELETE' });
+  assert.equal(res.status, 405);
+  assert.equal(res.headers.allow, 'GET, HEAD, POST');
+});
+
+test('security headers cover documents, CSS and error responses', () => {
+  for (const url of ['/', '/styles.css', '/logout', '/missing']) {
+    const res = request(url);
+    assert.equal(res.headers['x-content-type-options'], 'nosniff');
+    assert.equal(res.headers['x-frame-options'], 'DENY');
+    assert.equal(res.headers['referrer-policy'], 'strict-origin-when-cross-origin');
+    assert.equal(res.headers['strict-transport-security'], 'max-age=31536000');
+    assert.match(res.headers['content-security-policy'], /script-src 'none'/);
+    assert.match(res.headers['content-security-policy'], /style-src 'self'/);
+    assert.match(res.headers['content-security-policy'], /require-trusted-types-for 'script'/);
+    assert.doesNotMatch(res.headers['content-security-policy'], /unsafe-inline|unsafe-eval/);
+  }
+  assert.equal(request('/styles.css').headers['content-type'], 'text/css; charset=utf-8');
+  assert.equal(request('/', { method: 'HEAD' }).body, '');
+});
+
+test('report-only rollout retains the enforced baseline and local HTTP avoids HSTS/upgrades', () => {
+  const handle = createHandler({ publicOrigin: 'http://localhost:11222', policyMode: 'report-only' });
+  const res = request('/', { handle });
+  assert.match(res.headers['content-security-policy'], /script-src 'none'/);
+  assert.match(res.headers['content-security-policy-report-only'], /default-src 'none'/);
+  assert.doesNotMatch(res.headers['content-security-policy-report-only'], /upgrade-insecure-requests/);
+  assert.equal(res.headers['strict-transport-security'], undefined);
+  assert.throws(() => createHandler({ policyMode: 'typo' }));
+  assert.throws(() => createHandler({ publicOrigin: `${origin}/` }));
+});
+
+test('markup and CSS remain compatible with the enforced policy', () => {
+  const html = readFileSync(path.join(__dirname, '../index.html'), 'utf8');
+  assert.doesNotMatch(html, /<script\b|<style\b|\sstyle\s*=|\son\w+\s*=|javascript:/i);
+  assert.match(html, /<link rel="stylesheet" href="\/styles.css">/);
+  assert.match(html, /<form action="\/logout" method="post"/);
+  const css = readFileSync(path.join(__dirname, '../styles.css'), 'utf8');
+  for (const match of css.matchAll(/url\(['"]?([^)'"\s]+)/g)) {
+    assert.equal(new URL(match[1], origin).origin, 'https://images.unsplash.com');
+  }
+});

