+/* The server must issue and verify codes; the browser never decides authenticity. */
+const phoneForm = document.querySelector('#phone-form');
+const codeForm = document.querySelector('#code-form');
+const phoneInput = document.querySelector('#phone');
+const codeInput = document.querySelector('#code');
+const status = document.querySelector('#auth-status');
+const resend = document.querySelector('#resend');
+const title = document.querySelector('#signin-title');
+let challengeId = null;
+let otpController = null;
+let otpTimeout = null;
+let resendTimer = null;
+let pending = false;
+let generation = 0;
+let receivedCode = null;
+
+function stopListening() {
+  otpController?.abort();
+  otpController = null;
+  clearTimeout(otpTimeout);
+}
+
+async function listenForCode() {
+  stopListening();
+  if (!window.isSecureContext || !('OTPCredential' in window) || !navigator.credentials) return;
+  const controller = new AbortController();
+  otpController = controller;
+  otpTimeout = setTimeout(() => controller.abort(), 60000);
+  try {
+    const credential = await navigator.credentials.get({ otp: { transport: ['sms'] }, signal: controller.signal });
+    if (!controller.signal.aborted && credential) {
+      receivedCode = credential.code;
+      submitReceivedCode();
+    }
+  } catch {
+    // Permission denial, timeout and unsupported environments retain manual entry.
+  } finally {
+    if (otpController === controller) {
+      clearTimeout(otpTimeout);
+      otpController = null;
+    }
+  }
+}
+
+function submitReceivedCode() {
+  if (!receivedCode || pending || codeForm.hidden || !challengeId) return;
+  codeInput.value = receivedCode;
+  receivedCode = null;
+  clearError(codeInput);
+  codeForm.requestSubmit();
+}
+
+function clearError(input) {
+  input.setCustomValidity('');
+  input.removeAttribute('aria-invalid');
+  document.querySelector(`#${input.id}-error`).textContent = '';
+}
+for (const input of [phoneInput, codeInput]) {
+  input.addEventListener('input', () => clearError(input));
+  input.addEventListener('invalid', () => {
+    input.setAttribute('aria-invalid', 'true');
+    const message = input === codeInput ? 'Enter the 6-digit code from your text message.' : 'Enter your mobile number, including your country code.';
+    document.querySelector(`#${input.id}-error`).textContent = message;
+  });
+}
+
+async function post(url, body) {
+  const controller = new AbortController();
+  const timeout = setTimeout(() => controller.abort(), 15000);
+  try {
+    const response = await fetch(url, {
+      method: 'POST', credentials: 'same-origin',
+      headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
+      body: JSON.stringify(body), signal: controller.signal,
+    });
+    const data = await response.json().catch(() => ({}));
+    if (!response.ok) {
+      if (response.status === 429) throw new Error('Too many attempts. Please wait a moment and try again.');
+      if (response.status === 400 || response.status === 401 || response.status === 410) {
+        throw new Error(url.endsWith('/verify') ? 'That code is incorrect or expired. Try again or request a new code.' : 'Check your mobile number and try again.');
+      }
+      throw new Error('Text verification is unavailable right now. Please try again later.');
+    }
+    return data;
+  } catch (error) {
+    if (error.name === 'AbortError' || error instanceof TypeError) throw new Error('We couldn’t connect. Please try again.');
+    throw error;
+  } finally { clearTimeout(timeout); }
+}
+
+function purpose() { return document.querySelector('input[name="purpose"]:checked').value; }
+function lock(locked) {
+  pending = locked;
+  document.querySelectorAll('.primary-button').forEach(button => { button.disabled = locked; });
+  resend.disabled = locked || Boolean(resendTimer);
+  document.querySelector('#change-number').disabled = locked;
+  phoneForm.setAttribute('aria-busy', String(locked));
+  codeForm.setAttribute('aria-busy', String(locked));
+}
+function cooldown() {
+  clearInterval(resendTimer);
+  let remaining = 30;
+  resend.disabled = true;
+  resend.textContent = `Resend in ${remaining}s`;
+  resendTimer = setInterval(() => {
+    remaining -= 1;
+    resend.textContent = remaining ? `Resend in ${remaining}s` : 'Resend code';
+    if (!remaining) { clearInterval(resendTimer); resendTimer = null; resend.disabled = pending; }
+  }, 1000);
+}
+
+async function requestCode() {
+  if (pending) return;
+  stopListening();
+  const currentGeneration = generation;
+  const isResend = !codeForm.hidden;
+  lock(true);
+  status.textContent = 'Requesting your verification text…';
+  // Listen before sending the SMS; retain a fast-arriving code until the challenge is ready.
+  receivedCode = null;
+  void listenForCode();
+  try {
+    const data = await post(phoneForm.action, { phone: phoneInput.value.trim(), purpose: purpose() });
+    if (currentGeneration !== generation) return;
+    if (typeof data.challengeId !== 'string' || !data.challengeId) throw new Error('Text verification is unavailable right now. Please try again later.');
+    challengeId = data.challengeId;
+    phoneForm.hidden = true;
+    codeForm.hidden = false;
+    title.textContent = 'Check your phone.';
+    document.querySelector('#delivery-note').textContent = `We sent a code to ${data.maskedPhone || `the number ending in ${phoneInput.value.replace(/\D/g, '').slice(-4)}`}.`;
+    codeInput.value = '';
+    clearError(codeInput);
+    status.textContent = isResend ? 'A new code is on its way.' : 'Your code is on its way.';
+    cooldown();
+    codeInput.focus();
+  } catch (error) {
+    stopListening();
+    receivedCode = null;
+    if (currentGeneration === generation) status.textContent = error.message;
+  } finally { lock(false); submitReceivedCode(); }
+}
+phoneForm.addEventListener('submit', event => { event.preventDefault(); void requestCode(); });
+resend.addEventListener('click', () => { void requestCode(); });
+codeForm.addEventListener('submit', async event => {
+  event.preventDefault();
+  stopListening();
+  if (pending || !challengeId) return;
+  const currentGeneration = generation;
+  lock(true);
+  status.textContent = 'Verifying your code…';
+  try {
+    const data = await post(codeForm.action, { challengeId, code: codeInput.value, purpose: purpose() });
+    if (currentGeneration !== generation) return;
+    if (data.verified !== true) throw new Error('That code could not be verified. Please try again.');
+    status.textContent = 'You’re verified. Taking you to your next good thing…';
+    window.location.assign(purpose() === 'order' ? '/order-online' : '/rewards');
+  } catch (error) {
+    if (currentGeneration !== generation) return;
+    status.textContent = '';
+    document.querySelector('#code-error').textContent = error.message;
+    codeInput.setAttribute('aria-invalid', 'true');
+    codeInput.focus();
+    void listenForCode();
+  } finally { lock(false); }
+});
+document.querySelector('#change-number').addEventListener('click', () => {
+  generation += 1;
+  stopListening();
+  clearInterval(resendTimer);
+  resendTimer = null;
+  resend.textContent = 'Resend code';
+  challengeId = null;
+  receivedCode = null;
+  codeInput.value = '';
+  clearError(codeInput);
+  phoneForm.hidden = false;
+  codeForm.hidden = true;
+  title.innerHTML = 'Good to have<br>you here.';
+  status.textContent = '';
+  phoneInput.focus();
+});
+document.querySelectorAll('[data-purpose]').forEach(link => {
+  link.addEventListener('click', () => {
+    document.querySelector(`input[name="purpose"][value="${link.dataset.purpose}"]`).checked = true;
+    (codeForm.hidden ? phoneInput : codeInput).focus({ preventScroll: true });
+  });
+});
+window.addEventListener('pagehide', () => { generation += 1; stopListening(); clearInterval(resendTimer); });
