+(() => {
+  const form = document.querySelector('#verification-form');
+  const phone = document.querySelector('#phone');
+  const code = document.querySelector('#code');
+  const send = document.querySelector('#send-code');
+  const resend = document.querySelector('#resend-code');
+  const verify = document.querySelector('#verify-button');
+  const status = document.querySelector('#form-status');
+  const phoneError = document.querySelector('#phone-error');
+  const codeError = document.querySelector('#code-error');
+  const countdown = document.querySelector('#countdown');
+  const DEMO_CODE = '123456';
+  let purpose = 'rewards';
+  let sentTo = '';
+  let timer;
+  let smsController;
+  let product = '';
+
+  function normalizedPhone() {
+    const digits = phone.value.replace(/\D/g, '');
+    return digits.length === 11 && digits.startsWith('1') ? digits.slice(1) : digits;
+  }
+
+  function selectPurpose(next) {
+    purpose = next;
+    document.querySelectorAll('[data-tab]').forEach(button => {
+      const active = button.dataset.tab === purpose;
+      button.classList.toggle('selected', active);
+      button.setAttribute('aria-pressed', String(active));
+    });
+    verify.innerHTML = `${purpose === 'order' ? 'Verify & continue to order' : 'Verify & sign in'} <span aria-hidden="true">→</span>`;
+  }
+
+  function resetCode() {
+    clearInterval(timer);
+    smsController?.abort();
+    sentTo = '';
+    code.value = '';
+    code.disabled = true;
+    verify.disabled = true;
+    resend.disabled = true;
+    send.disabled = false;
+    send.innerHTML = 'Send code <span aria-hidden="true">→</span>';
+    countdown.textContent = '';
+    codeError.textContent = '';
+    code.removeAttribute('aria-invalid');
+    document.querySelector('#delivery-label').textContent = 'Sent by SMS';
+    status.classList.remove('success');
+  }
+
+  function beginAutofill() {
+    smsController?.abort();
+    // WebOTP needs HTTPS and a domain-bound SMS from a real SMS provider.
+    // Native autocomplete="one-time-code" remains available on supporting devices.
+    if (!('OTPCredential' in window) || !window.isSecureContext) return;
+    smsController = new AbortController();
+    navigator.credentials.get({ otp: { transport: ['sms'] }, signal: smsController.signal })
+      .then(credential => {
+        if (credential && /^\d{6}$/.test(credential.code) && sentTo) {
+          code.value = credential.code;
+          code.dispatchEvent(new Event('input'));
+          code.focus();
+        }
+      }).catch(() => { /* Manual entry remains available when declined or unsupported. */ });
+  }
+
+  function sendCode() {
+    const number = normalizedPhone();
+    if (!/^[2-9]\d{9}$/.test(number)) {
+      phoneError.textContent = 'Enter a valid 10-digit US mobile number.';
+      phone.setAttribute('aria-invalid', 'true');
+      phone.focus();
+      return;
+    }
+    resetCode();
+    phoneError.textContent = '';
+    phone.removeAttribute('aria-invalid');
+    sentTo = number;
+    code.disabled = false;
+    send.disabled = true;
+    send.textContent = 'Code ready ✓';
+    document.querySelector('#delivery-label').textContent = `For ••• ••• ${number.slice(-4)}`;
+    status.textContent = 'Demo code: 123456. No SMS was sent. Enter the code to try verification.';
+    let remaining = 30;
+    countdown.textContent = ` (${remaining}s)`;
+    timer = setInterval(() => {
+      remaining -= 1;
+      countdown.textContent = ` (${remaining}s)`;
+      if (remaining <= 0) {
+        clearInterval(timer);
+        countdown.textContent = '';
+        resend.disabled = false;
+      }
+    }, 1000);
+    code.focus();
+    beginAutofill();
+  }
+
+  send.addEventListener('click', sendCode);
+  resend.addEventListener('click', sendCode);
+  phone.addEventListener('input', () => {
+    phoneError.textContent = '';
+    phone.removeAttribute('aria-invalid');
+    if (sentTo && normalizedPhone() !== sentTo) {
+      resetCode();
+      status.textContent = 'Mobile number changed. Request a new code to continue.';
+    }
+  });
+  code.addEventListener('input', () => {
+    code.value = code.value.replace(/\D/g, '').slice(0, 6);
+    codeError.textContent = '';
+    code.removeAttribute('aria-invalid');
+    verify.disabled = !/^\d{6}$/.test(code.value) || !sentTo;
+  });
+  code.addEventListener('paste', event => {
+    const pasted = event.clipboardData.getData('text');
+    const match = pasted.match(/(?:^|\D)(\d{6})(?!\d)/);
+    if (match) {
+      event.preventDefault();
+      code.value = match[1];
+      code.dispatchEvent(new Event('input'));
+    }
+  });
+  form.addEventListener('submit', event => {
+    event.preventDefault();
+    if (!sentTo) { sendCode(); return; }
+    if (!/^\d{6}$/.test(code.value)) {
+      codeError.textContent = 'Enter all 6 digits of your verification code.';
+      code.setAttribute('aria-invalid', 'true');
+      code.focus();
+      return;
+    }
+    if (code.value !== DEMO_CODE) {
+      codeError.textContent = 'That code doesn’t match. Use 123456 for this demo.';
+      code.setAttribute('aria-invalid', 'true');
+      code.focus();
+      return;
+    }
+    clearInterval(timer);
+    smsController?.abort();
+    status.classList.add('success');
+    status.textContent = purpose === 'order'
+      ? `Demo verification complete! ${product ? `${product} is your selection. ` : ''}Online checkout will be available when the ordering service is connected.`
+      : 'Demo verification complete! You’re ready for Rewards. Account access will be available when the sign-in service is connected.';
+    verify.textContent = 'Demo verified ✓';
+    verify.disabled = true;
+    code.disabled = true;
+    resend.disabled = true;
+    countdown.textContent = '';
+  });
+  document.querySelectorAll('[data-tab]').forEach(button => button.addEventListener('click', () => selectPurpose(button.dataset.tab)));
+  document.querySelectorAll('[data-purpose]').forEach(link => link.addEventListener('click', () => selectPurpose(link.dataset.purpose)));
+  document.querySelectorAll('[data-product]').forEach(button => button.addEventListener('click', () => {
