@@ -0,0 +1,59 @@
+import { createHmac, randomInt, randomUUID, timingSafeEqual } from 'node:crypto';
+
+export type SignupChallenge = {
+  phone: string;
+  nonce: string;
+  digest: string;
+  expiresAt: number;
+  attempts: number;
+};
+
+export const CODE_LIFETIME = 5 * 60 * 1000;
+export const RESEND_DELAY = 60 * 1000;
+export const MAX_ATTEMPTS = 5;
+
+export function json(data: unknown, status = 200) {
+  return new Response(JSON.stringify(data), {
+    status, headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' },
+  });
+}
+
+export function sameOrigin(request: Request) {
+  return request.headers.get('Origin') === new URL(request.url).origin
+    && request.headers.get('Content-Type')?.split(';')[0].trim() === 'application/json';
+}
+
+export function normalizePhone(value: unknown): string | null {
+  if (typeof value !== 'string' || value.length > 30 || !/^\+[0-9\s()-]+$/.test(value)) return null;
+  const phone = value.replace(/[\s()-]/g, '');
+  return /^\+[1-9][0-9]{6,14}$/.test(phone) ? phone : null;
+}
+
+export function smsConfig() {
+  const { TWILIO_ACCOUNT_SID: account, TWILIO_AUTH_TOKEN: token, TWILIO_FROM_NUMBER: from } = process.env;
+  return account && /^AC[a-fA-F0-9]{32}$/.test(account) && token && from ? { account, token, from } : null;
+}
+
+function digest(code: string, phone: string, nonce: string, secret: string) {
+  return createHmac('sha256', secret).update(`${nonce}:${phone}:${code}`).digest('hex');
+}
+
+export function createChallenge(phone: string, secret: string, now = Date.now()) {
+  const code = randomInt(0, 1_000_000).toString().padStart(6, '0');
+  const nonce = randomUUID();
+  const challenge: SignupChallenge = {
+    phone, nonce, digest: digest(code, phone, nonce, secret),
+    expiresAt: now + CODE_LIFETIME, attempts: 0,
+  };
+  return { code, challenge };
+}
+
+export function matchesCode(challenge: SignupChallenge, code: string, secret: string) {
+  const expected = Buffer.from(challenge.digest, 'hex');
+  const actual = Buffer.from(digest(code, challenge.phone, challenge.nonce, secret), 'hex');
+  return expected.length === actual.length && timingSafeEqual(expected, actual);
+}
+
+export function smsBody(domain: string, code: string) {
+  return `Your DevTools Times verification code is ${code}. It expires in 5 minutes.\n\n@${domain} #${code}`;
+}
