+import type { APIRoute } from 'astro';
+import { json, matchesCode, MAX_ATTEMPTS, normalizePhone, sameOrigin, smsConfig } from '../../../lib/signup.ts';
+
+export const POST: APIRoute = async ({ request, session }) => {
+  if (!sameOrigin(request)) return json({ error: 'Please send this request from the sign-up page.' }, 403);
+  if (!session) return json({ error: 'Phone verification is temporarily unavailable.' }, 503);
+  const config = smsConfig();
+  if (!config) return json({ error: 'SMS verification is not configured. Please try again later.' }, 503);
+
+  let data;
+  try { data = await request.json(); }
+  catch { return json({ error: 'Please provide your account details and verification code.' }, 400); }
+  const { username, password, code } = data ?? {};
+  const phone = normalizePhone(data?.phone);
+  if (typeof username !== 'string' || !username.trim() || username.length > 100
+    || typeof password !== 'string' || password.length < 8 || password.length > 128 || !/[0-9]/.test(password)) {
+    return json({ error: 'Enter a username and a password of 8–128 characters including a number. Choose Change details to update them.' }, 400);
+  }
+  if (typeof code !== 'string' || !/^[0-9]{6}$/.test(code)) return json({ error: 'Enter the 6-digit code from your SMS.' }, 400);
+
+  const challenge = await session.get('signupChallenge');
+  if (!challenge || challenge.expiresAt <= Date.now() || challenge.attempts >= MAX_ATTEMPTS) {
+    await session.delete('signupChallenge');
+    return json({ error: 'Your code has expired or is no longer available. Please request a new code.' }, 400);
+  }
+  if (phone !== challenge.phone) return json({ error: 'Your phone number changed. Please request a new code.' }, 400);
+  challenge.attempts += 1;
+  await session.set('signupChallenge', challenge);
+  if (!matchesCode(challenge, code, config.token)) {
+    if (challenge.attempts >= MAX_ATTEMPTS) await session.delete('signupChallenge');
+    return json({ error: challenge.attempts >= MAX_ATTEMPTS ? 'Too many incorrect attempts. Please request a new code.' : 'That code is incorrect. Check your SMS and try again.' }, 400);
+  }
+
+  // Consume before registration; neither a successful code nor a failed registration can replay it.
+  await session.delete('signupChallenge');
+  try {
+    const response = await fetch('https://us-central1-web-devrel-apps.cloudfunctions.net/times_cdn/api/register', {
+      method: 'POST', headers: { 'Content-Type': 'application/json' },
+      body: JSON.stringify({ username, password, phoneNumber: challenge.phone }),
+      signal: AbortSignal.timeout(15_000),
+    });
+    if (!response.ok) {
+      return json({ error: 'Registration was not completed. Check your account details and request a new code to try again.' }, 400);
+    }
+    return json({ success: true });
+  } catch {
+    return json({ error: 'The registration service is unavailable. Request a new code to try again.' }, 502);
+  }
+};
