+import type { APIRoute } from 'astro';
+import { createChallenge, json, normalizePhone, RESEND_DELAY, sameOrigin, smsBody, smsConfig } from '../../../lib/signup.ts';
+
+export const POST: APIRoute = async ({ request, session }) => {
+  if (!sameOrigin(request)) return json({ error: 'Please send this request from the sign-up page.' }, 403);
+  if (!session) return json({ error: 'Phone verification is temporarily unavailable.' }, 503);
+  const config = smsConfig();
+  if (!config) return json({ error: 'SMS verification is not configured. Please try again later.' }, 503);
+
+  let phone: string | null;
+  try { phone = normalizePhone((await request.json()).phone); }
+  catch { return json({ error: 'Please provide a valid phone number.' }, 400); }
+  if (!phone) return json({ error: 'Include a country code and a valid phone number, for example +1 202 555 0123.' }, 400);
+
+  const now = Date.now();
+  const retryAt = (await session.get('signupLastSent') || 0) + RESEND_DELAY;
+  if (now < retryAt) return json({ error: 'Please wait before requesting another code.', retryAt }, 429);
+
+  const { code, challenge } = createChallenge(phone, config.token, now);
+  // Reserve the cooldown even if the provider fails, and invalidate the old code on resend.
+  await session.set('signupLastSent', now);
+  await session.delete('signupChallenge');
+  try {
+    const response = await fetch(`https://api.twilio.com/2010-04-01/Accounts/${config.account}/Messages.json`, {
+      method: 'POST',
+      headers: {
+        Authorization: `Basic ${Buffer.from(`${config.account}:${config.token}`).toString('base64')}`,
+        'Content-Type': 'application/x-www-form-urlencoded',
+      },
+      body: new URLSearchParams({
+        To: phone, From: config.from,
+        Body: smsBody(new URL(request.url).hostname, code),
+      }),
+      signal: AbortSignal.timeout(15_000),
+    });
+    if (!response.ok) throw new Error('SMS provider rejected delivery');
+    await session.set('signupChallenge', challenge);
+    return json({ phone, retryAt: now + RESEND_DELAY });
+  } catch {
+    return json({ error: 'We could not send your SMS. Please wait a minute and try again.', retryAt: now + RESEND_DELAY }, 502);
+  }
+};
