+import assert from 'node:assert/strict';
+import { test } from 'node:test';
+import { CODE_LIFETIME, createChallenge, matchesCode, normalizePhone, sameOrigin, smsBody } from '../src/lib/signup.ts';
+
+test('normalizes international numbers without guessing a country', () => {
+  assert.equal(normalizePhone('+1 (202) 555-0123'), '+12025550123');
+  for (const invalid of ['2025550123', '+012345678', '+1', '+1234567890123456', '+1abc2025550123', null, {}]) {
+    assert.equal(normalizePhone(invalid), null);
+  }
+});
+
+test('creates expiring six-digit challenges without storing plaintext codes', () => {
+  const { code, challenge } = createChallenge('+12025550123', 'test-secret', 1000);
+  assert.match(code, /^[0-9]{6}$/);
+  assert.equal(challenge.expiresAt, 1000 + CODE_LIFETIME);
+  assert.equal(challenge.attempts, 0);
+  assert.ok(!Object.values(challenge).includes(code));
+  assert.equal(matchesCode(challenge, code, 'test-secret'), true);
+  assert.equal(matchesCode(challenge, code, 'different-secret'), false);
+  assert.equal(matchesCode({ ...challenge, phone: '+442079460123' }, code, 'test-secret'), false);
+  const otherCode = code === '000000' ? '000001' : '000000';
+  assert.equal(matchesCode(challenge, otherCode, 'test-secret'), false);
+  const fresh = createChallenge(challenge.phone, 'test-secret', 1000);
+  assert.notEqual(fresh.challenge.nonce, challenge.nonce);
+  assert.notEqual(fresh.challenge.digest, challenge.digest);
+});
+
+test('SMS keeps leading zeroes and ends with the exact origin-bound line', () => {
+  const body = smsBody('news.example.com', '012345');
+  assert.ok(body.startsWith('Your DevTools Times verification code is 012345.'));
+  assert.equal(body.split('\n').at(-1), '@news.example.com #012345');
+});
+
+test('requires same-origin JSON mutations', () => {
+  const request = (origin: string, contentType = 'application/json') => new Request('https://news.example.com/api/signup/send-code', {
+    method: 'POST', headers: { Origin: origin, 'Content-Type': contentType },
+  });
+  assert.equal(sameOrigin(request('https://news.example.com')), true);
+  assert.equal(sameOrigin(request('https://news.example.com', 'application/json; charset=utf-8')), true);
+  assert.equal(sameOrigin(request('https://attacker.example')), false);
+  assert.equal(sameOrigin(request('https://news.example.com', 'text/plain')), false);
+});

