index 0000000..b3c201d
--- /dev/null
+++ b/src/lib/phone-verification.ts
@@ -0,0 +1,52 @@
+export const PHONE_PATTERN = /^\+[1-9]\d{7,14}$/;
+export const CODE_PATTERN = /^\d{6}$/;
+
+export function normalizePhone(value: string): string {
+  return value.replace(/[\s().-]/g, '');
+}
+
+export class VerificationError extends Error {
+  status: number;
+  constructor(message: string, status = 400) {
+    super(message);
+    this.status = status;
+  }
+}
+
+type VerifyConfig = { accountSid?: string; authToken?: string; serviceSid?: string };
+
+export async function verifyPhone(
+  config: VerifyConfig,
+  phone: string,
+  code?: string,
+  request: typeof fetch = fetch,
+): Promise<void> {
+  if (!config.accountSid || !config.authToken || !config.serviceSid) {
+    throw new VerificationError('SMS verification is currently unavailable. Please try again later.', 503);
+  }
+  const response = await request(
+    `https://verify.twilio.com/v2/Services/${encodeURIComponent(config.serviceSid)}/${code ? 'VerificationCheck' : 'Verifications'}`,
+    {
+      method: 'POST',
+      headers: {
+        Authorization: `Basic ${Buffer.from(`${config.accountSid}:${config.authToken}`).toString('base64')}`,
+        'Content-Type': 'application/x-www-form-urlencoded',
+      },
+      body: new URLSearchParams({ To: phone, ...(code ? { Code: code } : { Channel: 'sms' }) }),
+      signal: AbortSignal.timeout(15000),
+    },
+  );
+  if (response.status === 429) {
+    throw new VerificationError('Too many attempts. Please wait before trying again.', 429);
+  }
+  if (response.status === 404 && code) {
+    throw new VerificationError('This code has expired or was already used. Request a new code.');
+  }
+  if (!response.ok) {
+    throw new VerificationError(code ? 'Unable to verify this code. Request a new code and try again.' : 'Unable to send a text message. Check your phone number and try again.', 400);
+  }
+  const result = await response.json();
+  if (code ? result.status !== 'approved' : result.status !== 'pending') {
+    throw new VerificationError(code ? 'The code is incorrect. Please try again.' : 'Unable to send a text message. Please try again.');
+  }
+}
