+++ b/src/pages/api/signup.ts
@@ -0,0 +1,70 @@
+import type { APIRoute } from 'astro';
+import { CODE_PATTERN, PHONE_PATTERN, normalizePhone, VerificationError, verifyPhone } from '../../lib/phone-verification.ts';
+
+const json = (data: object, status = 200) => new Response(JSON.stringify(data), {
+  status,
+  headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' },
+});
+
+const nextSend = new Map<string, number>();
+
+export const POST: APIRoute = async ({ request, url }) => {
+  // Origin checks are disabled globally in this app; enforce them for SMS requests.
+  if (request.headers.get('origin') !== url.origin) {
+    return json({ error: 'This request must come from the sign-up form.' }, 403);
+  }
+  if (!request.headers.get('content-type')?.startsWith('application/json')) {
+    return json({ error: 'Expected a JSON request.' }, 415);
+  }
+  let body;
+  try {
+    body = await request.json();
+  } catch {
+    return json({ error: 'Invalid request.' }, 400);
+  }
+  if (!body || typeof body.phone !== 'string' || !['send', 'register'].includes(body.action)) {
+    return json({ error: 'Enter your phone number and try again.' }, 400);
+  }
+  const phone = normalizePhone(body.phone);
+  if (!PHONE_PATTERN.test(phone)) {
+    return json({ error: 'Enter an international phone number starting with + and your country code.' }, 400);
+  }
+  if (body.action === 'register' && (
+    typeof body.username !== 'string' || !body.username.trim() || body.username.length > 100 ||
+    typeof body.password !== 'string' || body.password.length < 8 || !/\d/.test(body.password) ||
+    typeof body.code !== 'string' || !CODE_PATTERN.test(body.code)
+  )) {
+    return json({ error: 'Enter a username, a password of at least 8 characters containing a number, and a 6-digit code.' }, 400);
+  }
+  try {
+    if (body.action === 'send') {
+      const now = Date.now();
+      for (const [key, expiry] of nextSend) if (expiry <= now) nextSend.delete(key);
+      if ((nextSend.get(phone) ?? 0) > now || nextSend.size >= 10000) {
+        return json({ error: 'Please wait 30 seconds before requesting another code.' }, 429);
+      }
+      nextSend.set(phone, now + 30000);
+    }
+    await verifyPhone({
+      accountSid: process.env.TWILIO_ACCOUNT_SID,
+      authToken: process.env.TWILIO_AUTH_TOKEN,
+      serviceSid: process.env.TWILIO_VERIFY_SERVICE_SID,
+    }, phone, body.action === 'register' ? body.code : undefined);
+    if (body.action === 'send') return json({ message: 'Verification code sent.' });
+
+    // Register only after the SMS provider has approved the code for this phone.
+    const response = await fetch('https://us-central1-web-devrel-apps.cloudfunctions.net/times_cdn/api/register', {
+      method: 'POST',
+      headers: { 'Content-Type': 'application/json' },
+      body: JSON.stringify({ username: body.username.trim(), password: body.password, phone }),
+      signal: AbortSignal.timeout(15000),
+    });
+    if (!response.ok) {
+      return json({ error: 'Registration failed. Your code has been used; request a new code before trying again.' }, 400);
+    }
+    return json({ message: 'Your phone is verified and your account is ready. You can now sign in.' });
+  } catch (error) {
+    if (error instanceof VerificationError) return json({ error: error.message }, error.status);
+    return json({ error: 'The service could not complete your request. Please request a new code and try again.' }, 502);
+  }
+};
