+import { test } from 'node:test';
+import assert from 'node:assert/strict';
+import { CODE_PATTERN, PHONE_PATTERN, normalizePhone, VerificationError, verifyPhone } from '../src/lib/phone-verification.ts';
+
+const config = { accountSid: 'ACtest', authToken: 'secret', serviceSid: 'VAtest' };
+const reply = (status: number, body: object): typeof fetch => async () => new Response(JSON.stringify(body), { status });
+
+test('accepts international numbers, normalizes formatting, and rejects ambiguous numbers', () => {
+  assert.equal(normalizePhone('+1 (202) 555-0123'), '+12025550123');
+  for (const phone of ['+12025550123', '+442079460123']) assert.ok(PHONE_PATTERN.test(phone));
+  for (const phone of ['2025550123', '+0123456789', '+1', '+12025550123ext4']) assert.ok(!PHONE_PATTERN.test(phone));
+  for (const code of ['12345', '1234567', '12a456']) assert.ok(!CODE_PATTERN.test(code));
+  assert.ok(CODE_PATTERN.test('012345'));
+});
+
+test('missing server configuration fails closed without contacting the provider', async () => {
+  await assert.rejects(verifyPhone({}, '+12025550123', undefined, async () => {
+    assert.fail('provider should not be called');
+  }), (err: VerificationError) => err.status === 503);
+});
+
+test('SMS request uses server credentials and never sends a caller-supplied code', async () => {
+  await verifyPhone(config, '+12025550123', undefined, async (url, init) => {
+    assert.equal(url, 'https://verify.twilio.com/v2/Services/VAtest/Verifications');
+    assert.equal(init?.method, 'POST');
+    const body = init?.body as URLSearchParams;
+    assert.equal(body.get('To'), '+12025550123');
+    assert.equal(body.get('Channel'), 'sms');
+    assert.equal(body.has('Code'), false);
+    assert.equal(new Headers(init?.headers).get('Authorization'), `Basic ${Buffer.from('ACtest:secret').toString('base64')}`);
+    return new Response(JSON.stringify({ status: 'pending' }));
+  });
+});
+
+test('code check is bound to the phone and requires an approved provider status', async () => {
+  await verifyPhone(config, '+12025550123', '012345', async (url, init) => {
+    assert.ok(String(url).endsWith('/VerificationCheck'));
+    const body = init?.body as URLSearchParams;
+    assert.equal(body.get('To'), '+12025550123');
+    assert.equal(body.get('Code'), '012345');
+    return new Response(JSON.stringify({ status: 'approved' }));
+  });
+  for (const status of ['pending', 'canceled', undefined]) {
+    await assert.rejects(verifyPhone(config, '+12025550123', '123456', reply(200, { status })), /incorrect/);
+  }
+});
+
+test('expired codes, provider errors, and throttling cannot pass verification', async () => {
+  await assert.rejects(verifyPhone(config, '+12025550123', '123456', reply(404, {})), /expired/);
+  await assert.rejects(verifyPhone(config, '+12025550123', '123456', reply(429, {})), (err: VerificationError) => err.status === 429);
+  await assert.rejects(verifyPhone(config, '+12025550123', '123456', reply(500, {})), /Unable to verify/);
+  await assert.rejects(verifyPhone(config, '+12025550123', undefined, reply(400, {})), /Unable to send/);
+  await assert.rejects(verifyPhone(config, '+12025550123', undefined, reply(200, { status: 'approved' })), /Unable to send/);
+});
