+import { test } from 'node:test';
+import assert from 'node:assert/strict';
+import { POST } from '../src/pages/api/signup.ts';
+
+const url = new URL('https://example.com/devtools-times/api/signup');
+const details = { action: 'register', username: 'reader', password: 'password1', phone: '+12025550123', code: '123456' };
+function call(body: object, origin = url.origin) {
+  return POST({ request: new Request(url, {
+    method: 'POST', headers: { Origin: origin, 'Content-Type': 'application/json' }, body: JSON.stringify(body),
+  }), url } as Parameters<typeof POST>[0]);
+}
+
+test('rejects cross-origin requests and invalid input before calling any service', async (t) => {
+  t.mock.method(globalThis, 'fetch', async () => { assert.fail('must not call external services'); });
+  assert.equal((await call(details, 'https://other.example')).status, 403);
+  assert.equal((await call({ ...details, phone: '2025550123' })).status, 400);
+  assert.equal((await call({ ...details, password: 'short' })).status, 400);
+  assert.equal((await call({ ...details, code: 'abcdef' })).status, 400);
+});
+
+test('never registers an account for an unapproved code', async (t) => {
+  process.env.TWILIO_ACCOUNT_SID = 'ACtest';
+  process.env.TWILIO_AUTH_TOKEN = 'test';
+  process.env.TWILIO_VERIFY_SERVICE_SID = 'VAtest';
+  const mock = t.mock.method(globalThis, 'fetch', async (input: unknown) => {
+    assert.ok(String(input).endsWith('/VerificationCheck'));
+    return new Response(JSON.stringify({ status: 'pending' }));
+  });
+  const response = await call(details);
+  assert.equal(response.status, 400);
+  assert.equal(mock.mock.callCount(), 1);
+});
+
+test('registers only after approval and forwards the verified normalized phone', async (t) => {
+  const calls: string[] = [];
+  t.mock.method(globalThis, 'fetch', async (input: unknown, init?: RequestInit) => {
+    calls.push(String(input));
+    if (calls.length === 1) {
+      assert.ok(String(input).endsWith('/VerificationCheck'));
+      return new Response(JSON.stringify({ status: 'approved' }));
+    }
+    assert.ok(String(input).endsWith('/api/register'));
+    assert.deepEqual(JSON.parse(String(init?.body)), { username: 'reader', password: 'password1', phone: '+12025550123' });
+    return new Response('{}');
+  });
+  assert.equal((await call({ ...details, phone: '+1 (202) 555-0123' })).status, 200);
+  assert.equal(calls.length, 2);
+});
+
+test('throttles SMS resends on the server', async (t) => {
+  const mock = t.mock.method(globalThis, 'fetch', async () => new Response(JSON.stringify({ status: 'pending' })));
+  const body = { action: 'send', phone: '+12025550124' };
+  assert.equal((await call(body)).status, 200);
+  assert.equal((await call(body)).status, 429);
+  assert.equal(mock.mock.callCount(), 1);
+});

