+  const crossFar = horizontal ? 'bottom' : 'right';
+  const origin = current.getBoundingClientRect();
+  const originCenter = (origin[crossNear] + origin[crossFar]) / 2;
+  let best;
+
+  for (const element of candidates) {
+    if (element === current) continue;
+    const rect = element.getBoundingClientRect();
+    const gap = direction.sign > 0
+      ? rect[near] - origin[far]
+      : origin[near] - rect[far];
+    if (gap < -1) continue; // Allow subpixel rounding at adjacent edges.
+
+    const offset = Math.abs((rect[crossNear] + rect[crossFar]) / 2 - originCenter);
+    const aligned = Math.min(origin[crossFar], rect[crossFar])
+      > Math.max(origin[crossNear], rect[crossNear]);
+    const distance = Math.max(0, gap);
+    const score = distance + 2 * offset;
+    if (!best || (aligned && !best.aligned)
+      || (aligned === best.aligned && (aligned
+        ? distance < best.distance || (distance === best.distance && offset < best.offset)
+        : score < best.score))) {
+      best = { element, aligned, distance, offset, score };
