+function isAvailable(element) {
+  if (element.matches(':disabled, [aria-disabled="true"]')
+    || element.closest('[hidden], [inert], [aria-hidden="true"]')) return false;
+  if (typeof element.checkVisibility === 'function'
+    && !element.checkVisibility({ checkVisibilityCSS: true, checkOpacity: true })) return false;
+  const style = element.ownerDocument.defaultView.getComputedStyle(element);
+  const rect = element.getBoundingClientRect();
+  return style.visibility !== 'hidden' && style.visibility !== 'collapse'
+    && style.display !== 'none' && rect.width > 0 && rect.height > 0;
+}
+
+export function initializeSpatialGrid(widget) {
+  const row = widget.querySelector('.grid');
+  const items = () => [...row.querySelectorAll('.card > a.btn[href]')];
+  const setActive = (active) => {
+    for (const item of items()) item.tabIndex = item === active ? 0 : -1;
+  };
+  const first = items().find(isAvailable);
+  if (!first) return;
+
+  widget.setAttribute('role', 'grid');
+  // This layout grid is one logical row of cards, which may wrap visually.
+  row.setAttribute('role', 'row');
+  for (const card of row.querySelectorAll('.card')) card.setAttribute('role', 'gridcell');
+  setActive(first);
+  const help = widget.ownerDocument.getElementById(widget.getAttribute('aria-describedby'));
+  if (help) help.hidden = false;
+
+  // Pointer or programmatic focus also establishes the next Tab entry point.
+  widget.addEventListener('focusin', (event) => {
+    const target = event.composedPath()[0];
+    if (items().includes(target) && isAvailable(target)) setActive(target);
+  });
+
+  widget.addEventListener('keydown', (event) => {
+    if (!directions[event.key] || event.defaultPrevented || event.isComposing
+      || event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) return;
+    const target = event.composedPath()[0];
+    // Do not take arrow keys from editors, sliders, selects, or nested controls.
+    if (!target?.matches || target.matches(':read-write, select, input, textarea, [role="slider"]')) return;
+    const candidates = items().filter(isAvailable);
+    if (!candidates.includes(target)) return;
+    const next = findSpatialTarget(target, candidates, event.key);
+    if (!next) return; // At boundaries, preserve native viewport scrolling.
+    event.preventDefault();
+    setActive(next);
+    next.focus({ preventScroll: true });
+    next.scrollIntoView({ block: 'nearest', inline: 'nearest' });
+  });
+}
+
+if (typeof document !== 'undefined') {
+  document.querySelectorAll('[data-spatial-grid]').forEach(initializeSpatialGrid);
+}
