@@ -0,0 +1,164 @@
+import test from 'node:test';
+import assert from 'node:assert/strict';
+import { findSpatialTarget, initializeSpatialGrid } from './spatial-navigation.mjs';
+
+function item(x, y, width = 80, height = 40) {
+  return {
+    rect: { left: x, top: y, right: x + width, bottom: y + height, width, height },
+    getBoundingClientRect() { return this.rect; },
+  };
+}
+
+test('moves in all four physical directions independently of DOM order', () => {
+  const center = item(100, 100);
+  const left = item(0, 100);
+  const right = item(200, 100);
+  const up = item(100, 0);
+  const down = item(100, 200);
+  const items = [down, right, center, up, left];
+  for (const [key, expected] of Object.entries({
+    ArrowLeft: left, ArrowRight: right, ArrowUp: up, ArrowDown: down,
+  })) assert.equal(findSpatialTarget(center, items, key), expected);
+});
+
+test('uses live geometry after responsive reflow or layout changes', () => {
+  const first = item(0, 0);
+  const second = item(100, 0);
+  assert.equal(findSpatialTarget(first, [first, second], 'ArrowRight'), second);
+  second.rect = item(0, 100).rect;
+  assert.equal(findSpatialTarget(first, [first, second], 'ArrowRight'), undefined);
+  assert.equal(findSpatialTarget(first, [first, second], 'ArrowDown'), second);
+});
+
+test('does not wrap at row or column boundaries', () => {
+  const first = item(0, 0);
+  const lastInRow = item(100, 0);
+  const wrapped = item(0, 100);
+  assert.equal(findSpatialTarget(lastInRow, [first, lastInRow, wrapped], 'ArrowRight'), undefined);
+  assert.equal(findSpatialTarget(first, [first, lastInRow, wrapped], 'ArrowUp'), undefined);
+});
+
+test('prefers aligned candidates over nearer diagonals, including wide items', () => {
+  const current = item(0, 0);
+  const aligned = item(200, 0, 400);
+  const diagonal = item(90, 50);
+  assert.equal(findSpatialTarget(current, [current, diagonal, aligned], 'ArrowRight'), aligned);
+});
+
+test('uses edge direction rather than center direction for overlapping items', () => {
+  const current = item(0, 0, 200);
+  const overlapping = item(100, 0, 200);
+  const adjacent = item(220, 0);
+  assert.equal(findSpatialTarget(current, [overlapping, adjacent], 'ArrowRight'), adjacent);
+});
+
+test('breaks aligned distance ties by perpendicular offset', () => {
+  const current = item(0, 0, 80, 100);
+  const offCenter = item(100, 0);
+  const centered = item(100, 30);
+  assert.equal(findSpatialTarget(current, [offCenter, centered], 'ArrowRight'), centered);
+});
+
+test('uses weighted diagonal fallback for staggered and incomplete rows', () => {
+  const current = item(100, 0);
+  const farSide = item(400, 50);
+  const nearerColumn = item(0, 120);
+  assert.equal(findSpatialTarget(current, [farSide, nearerColumn], 'ArrowDown'), nearerColumn);
+});
+
+// A small DOM adapter tests event cooperation without a browser or server.
+function fixture() {
+  const links = [item(0, 0), item(100, 0), item(200, 0)];
+  const listeners = {};
+  const help = { hidden: true };
+  const doc = {
+    getElementById: () => help,
+    defaultView: { getComputedStyle: () => ({ visibility: 'visible', display: 'block' }) },
+  };
+  for (const link of links) {
+    Object.assign(link, {
+      ownerDocument: doc,
+      matches(selector) {
+        return selector.startsWith(':disabled') ? Boolean(this.disabled) : Boolean(this.editable);
+      },
+      closest() { return this.hidden ? {} : null; },
+      checkVisibility() { return !this.invisible; },
+      focus(options) { doc.activeElement = this; this.focusOptions = options; },
+      scrollIntoView(options) { this.scrollOptions = options; },
+    });
+  }
+  const cards = links.map(() => ({ setAttribute(name, value) { this[name] = value; } }));
+  const row = {
+    setAttribute(name, value) { this[name] = value; },
+    querySelectorAll: (selector) => selector === '.card' ? cards : links,
+  };
+  const widget = {
+    ownerDocument: doc,
+    querySelector: () => row,
+    getAttribute: () => 'help',
+    setAttribute(name, value) { this[name] = value; },
+    addEventListener(name, callback) { listeners[name] = callback; },
+  };
+  initializeSpatialGrid(widget);
+  const press = (target, key, overrides = {}) => {
+    const event = {
+      key, composedPath: () => [target],
+      preventDefault() { this.defaultPrevented = true; },
+      ...overrides,
+    };
+    listeners.keydown(event);
+    return event;
+  };
+  return { links, widget, row, cards, help, doc, listeners, press };
+}
+
+test('enhances grid semantics and maintains one remembered Tab stop', () => {
+  const { links, widget, row, cards, help, doc, listeners, press } = fixture();
+  assert.equal(widget.role, 'grid');
+  assert.equal(row.role, 'row');
+  assert.ok(cards.every((card) => card.role === 'gridcell'));
+  assert.equal(help.hidden, false);
+  assert.deepEqual(links.map((link) => link.tabIndex), [0, -1, -1]);
+  assert.equal(press(links[0], 'ArrowRight').defaultPrevented, true);
+  assert.equal(doc.activeElement, links[1]);
+  assert.deepEqual(links.map((link) => link.tabIndex), [-1, 0, -1]);
+  assert.deepEqual(links[1].focusOptions, { preventScroll: true });
+  assert.deepEqual(links[1].scrollOptions, { block: 'nearest', inline: 'nearest' });
+  listeners.focusin({ composedPath: () => [links[2]] });
+  assert.deepEqual(links.map((link) => link.tabIndex), [-1, -1, 0]);
+});
+
+test('preserves boundary scrolling, Tab, activation, modifiers, and handled events', () => {
+  const { links, press, doc } = fixture();
+  for (const key of ['ArrowLeft', 'ArrowUp', 'Tab', 'Enter', ' ']) {
+    assert.equal(press(links[0], key).defaultPrevented, undefined);
+  }
+  for (const modifier of ['altKey', 'ctrlKey', 'metaKey', 'shiftKey', 'isComposing']) {
+    assert.equal(press(links[0], 'ArrowRight', { [modifier]: true }).defaultPrevented, undefined);
+  }
+  press(links[0], 'ArrowRight', { defaultPrevented: true });
+  assert.equal(doc.activeElement, undefined);
+});
+
+test('ignores unavailable candidates, with and without checkVisibility support', () => {
+  for (const property of ['disabled', 'hidden', 'invisible']) {
+    const { links, press, doc } = fixture();
+    links[1][property] = true;
+    press(links[0], 'ArrowRight');
+    assert.equal(doc.activeElement, links[2]);
+  }
+  const { links, press, doc } = fixture();
+  for (const link of links) delete link.checkVisibility;
+  links[1].rect.width = 0;
+  press(links[0], 'ArrowRight');
+  assert.equal(doc.activeElement, links[2]);
+});
+
+test('leaves editable and nested controls alone, including retargeted events', () => {
+  const { links, press, doc } = fixture();
+  links[0].editable = true;
+  assert.equal(press(links[0], 'ArrowRight').defaultPrevented, undefined);
+  const child = { matches: () => false };
+  assert.equal(press(child, 'ArrowRight', { target: links[0] }).defaultPrevented, undefined);
+  assert.equal(doc.activeElement, undefined);
+});

