+    const directions = {
+      ArrowLeft: [-1, 0],
+      ArrowRight: [1, 0],
+      ArrowUp: [0, -1],
+      ArrowDown: [0, 1],
+    };
+    const direction = directions[event.key];
+    if (!direction || event.defaultPrevented || event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) return;
+
+    const links = [...grid.querySelectorAll('.card a.btn')];
+    const current = links.find((link) => link === event.target);
+    if (!current || current.isContentEditable) return;
+
+    // Read fresh rectangles on every keypress to support resizing and layout changes.
+    const items = links.filter((link) => !link.closest('[hidden], [inert]') && link.getClientRects().length)
+      .map((link) => ({ link, rect: link.closest('.card').getBoundingClientRect() }))
+      .filter(({ rect }) => rect.width > 0 && rect.height > 0);
+    const origin = items.find(({ link }) => link === current);
+    if (!origin) return;
+
+    const horizontal = direction[0] !== 0;
+    const primary = horizontal ? 'left' : 'top';
+    const secondary = horizontal ? 'top' : 'left';
+    const size = horizontal ? 'width' : 'height';
+    const crossSize = horizontal ? 'height' : 'width';
+    const sign = direction[0] || direction[1];
+    const center = (rect, axis, length) => rect[axis] + rect[length] / 2;
+
+    const candidates = items.filter((item) => item !== origin).map((item) => {
+      const forward = sign * (center(item.rect, primary, size) - center(origin.rect, primary, size));
+      const sideways = Math.abs(center(item.rect, secondary, crossSize) - center(origin.rect, secondary, crossSize));
+      const aligned = item.rect[secondary] < origin.rect[secondary] + origin.rect[crossSize] &&
+        item.rect[secondary] + item.rect[crossSize] > origin.rect[secondary];
+      return { ...item, forward, sideways, aligned };
+    }).filter(({ forward }) => forward > 1);
+
+    candidates.sort((a, b) => Number(b.aligned) - Number(a.aligned) ||
+      a.forward - b.forward || a.sideways - b.sideways);
+
+    // Consume unmodified arrows at boundaries too, without wrapping or scrolling.
+    event.preventDefault();
+    candidates[0]?.link.focus();
+  });
+});
