+const { test } = require('node:test');
+const assert = require('node:assert/strict');
+const { readFileSync } = require('node:fs');
+const { runInNewContext } = require('node:vm');
+
+const source = readFileSync(require('node:path').join(__dirname, '../card-navigation.js'), 'utf8');
+
+function setup(positions) {
+  let handler;
+  let focused;
+  const links = positions.map(([left, top]) => {
+    const link = {
+      rect: { left, top, width: 250, height: 180 },
+      hidden: false,
+      getClientRects: () => link.hidden ? [] : [link.rect],
+      closest: (selector) => selector === '.card' ? { getBoundingClientRect: () => link.rect } : null,
+      focus: () => { focused = link; },
+    };
+    return link;
+  });
+  const grid = {
+    querySelectorAll: () => links,
+    addEventListener: (_, callback) => { handler = callback; },
+  };
+  runInNewContext(source, { document: { querySelectorAll: () => [grid] } });
+  return {
+    links,
+    press(index, key, overrides = {}) {
+      focused = links[index];
+      const event = { target: links[index], key, preventDefault() { this.prevented = true; }, ...overrides };
+      handler(event);
+      return { index: links.indexOf(focused), prevented: !!event.prevented };
+    },
+  };
+}
+
+test('three-column layout follows physical horizontal directions and stops at edges', () => {
+  const grid = setup([[0, 0], [270, 0], [540, 0]]);
+  assert.equal(grid.press(0, 'ArrowRight').index, 1);
+  assert.equal(grid.press(2, 'ArrowLeft').index, 1);
+  assert.deepEqual(grid.press(2, 'ArrowRight'), { index: 2, prevented: true });
+  assert.equal(grid.press(1, 'ArrowDown').index, 1);
+});
+
+test('two-column layout navigates an incomplete final row without horizontal wrapping', () => {
+  const grid = setup([[0, 0], [270, 0], [0, 200]]);
+  assert.equal(grid.press(0, 'ArrowDown').index, 2);
+  assert.equal(grid.press(1, 'ArrowDown').index, 2);
+  assert.equal(grid.press(2, 'ArrowUp').index, 0);
+  assert.equal(grid.press(1, 'ArrowRight').index, 1);
+});
+
+test('one-column layout uses vertical arrows', () => {
+  const grid = setup([[0, 0], [0, 200], [0, 400]]);
+  assert.equal(grid.press(0, 'ArrowDown').index, 1);
+  assert.equal(grid.press(2, 'ArrowUp').index, 1);
+  assert.equal(grid.press(1, 'ArrowRight').index, 1);
+  assert.equal(grid.press(2, 'ArrowDown').index, 2);
+});
+
+test('layout changes are read on the next keypress', () => {
+  const grid = setup([[0, 0], [270, 0], [540, 0]]);
+  assert.equal(grid.press(0, 'ArrowRight').index, 1);
+  grid.links.forEach((link, index) => { link.rect.left = 0; link.rect.top = index * 200; });
+  assert.equal(grid.press(0, 'ArrowDown').index, 1);
+  assert.equal(grid.press(0, 'ArrowRight').index, 0);
+});
+
+test('physical navigation supports reversed visual order', () => {
+  const grid = setup([[540, 0], [270, 0], [0, 0]]);
+  assert.equal(grid.press(0, 'ArrowLeft').index, 1);
+  assert.equal(grid.press(1, 'ArrowRight').index, 0);
+});
+
+test('hidden cards are skipped', () => {
+  const grid = setup([[0, 0], [270, 0], [540, 0]]);
+  grid.links[1].hidden = true;
+  assert.equal(grid.press(0, 'ArrowRight').index, 2);
+});
+
+test('native keys, modified arrows, editable targets and handled events remain untouched', () => {
+  const grid = setup([[0, 0], [270, 0]]);
+  for (const key of ['Tab', 'Enter', ' ', 'Escape']) {
+    assert.deepEqual(grid.press(0, key), { index: 0, prevented: false });
+  }
+  for (const flag of ['altKey', 'ctrlKey', 'metaKey', 'shiftKey', 'defaultPrevented']) {
+    assert.deepEqual(grid.press(0, 'ArrowRight', { [flag]: true }), { index: 0, prevented: false });
+  }
+  assert.equal(grid.press(0, 'ArrowRight', { target: {} }).prevented, false);
+  grid.links[0].isContentEditable = true;
+  assert.equal(grid.press(0, 'ArrowRight').prevented, false);
+});

