+          tabList.scrollBy({ left: tabBounds.left - listBounds.left - padding, behavior: scrollBehavior() });
+        } else if (tabBounds.right > listBounds.right - padding) {
+          tabList.scrollBy({ left: tabBounds.right - listBounds.right + padding, behavior: scrollBehavior() });
