+        let delta = 0;
+        if (tabRect.left < listRect.left + inset) {
+          delta = tabRect.left - listRect.left - inset;
+        } else if (tabRect.right > listRect.right - inset) {
+          delta = tabRect.right - listRect.right + inset;
+        }
+        if (delta) tablist.scrollBy({ left: delta, behavior: animate ? behavior() : 'instant' });
+      }
