--- /dev/null
+++ b/translation.js
@@ -0,0 +1,113 @@
+// Always translate from the original copy, never from a previous translation.
+const passages = Array.from(document.querySelectorAll('[data-translatable]'));
+const originals = passages.map((element) => element.textContent);
+const language = document.getElementById('language');
+const button = document.getElementById('translate-button');
+const status = document.getElementById('translation-status');
+const supported = typeof window.Translator?.availability === 'function'
+  && typeof window.Translator?.create === 'function';
+let checkVersion = 0;
+let readyOptions = null;
+let displayedLanguage = 'en';
+
+function showPassages(texts, targetLanguage) {
+  passages.forEach((element, index) => {
+    element.textContent = texts[index];
+    element.lang = targetLanguage;
+    element.dir = targetLanguage === 'ar' ? 'rtl' : 'ltr';
+  });
+  displayedLanguage = targetLanguage;
+}
+
+async function checkLanguage() {
+  const version = ++checkVersion;
+  readyOptions = null;
+  button.disabled = true;
+  button.textContent = language.value === 'en' ? 'Show original' : 'Translate';
+
+  if (language.value === 'en') {
+    button.disabled = displayedLanguage === 'en';
+    status.textContent = displayedLanguage === 'en'
+      ? 'Showing the original English text. Choose a language to translate.'
+      : 'Select “Show original” to return to English.';
+    return;
+  }
+
+  status.textContent = 'Checking this language on your device…';
+  const options = {
+    sourceLanguage: 'en',
+    targetLanguage: language.value,
+    monitor(monitor) {
+      monitor.addEventListener('downloadprogress', (event) => {
+        const percent = Math.round(event.loaded * 100);
+        status.textContent = `Downloading language pack: ${percent}%. Keep this page open.`;
+      });
+    },
+  };
+
+  try {
+    const availability = await window.Translator.availability(options);
+    if (version !== checkVersion) return;
+    if (!['available', 'downloadable', 'downloading'].includes(availability)) {
+      status.textContent = 'This language is unavailable on your device. Choose another language. The displayed text has been kept.';
+      return;
+    }
+    readyOptions = options;
+    button.disabled = false;
+    button.textContent = availability === 'available' ? 'Translate' : 'Download & translate';
+    status.textContent = availability === 'available'
+      ? 'Ready to translate on your device.'
+      : 'A language pack is needed. Select “Download & translate” to continue.';
+  } catch {
+    if (version !== checkVersion) return;
+    status.textContent = 'Could not check this language. Choose a language again to retry. The displayed text has been kept.';
+  }
+}
+
+language.addEventListener('change', checkLanguage);
+button.addEventListener('click', async () => {
+  if (language.value === 'en') {
+    showPassages(originals, 'en');
+    checkLanguage();
+    return;
+  }
+  if (!readyOptions) return;
+
+  const options = readyOptions;
+  let translator;
+  language.disabled = true;
+  button.disabled = true;
+  button.textContent = 'Translating…';
+  status.textContent = 'Preparing on-device translation…';
+  document.querySelector('main').setAttribute('aria-busy', 'true');
+
+  try {
+    // Call create directly from the click, preserving user activation for downloads.
+    translator = await window.Translator.create(options);
+    status.textContent = 'Translating menu descriptions and our story…';
+    const translated = [];
+    for (const original of originals) {
+      const text = await translator.translate(original);
+      if (typeof text !== 'string' || !text.trim()) throw new Error('Empty translation');
+      translated.push(text);
+    }
+    // Commit together so failures cannot leave a partially translated page.
+    showPassages(translated, options.targetLanguage);
+    status.textContent = `Menu descriptions and story translated to ${language.selectedOptions[0].textContent}. Select English to restore the original.`;
+  } catch {
+    status.textContent = 'Translation could not finish. Your displayed text has been kept. Try again, choose another language, or select English to restore the original.';
+  } finally {
+    translator?.destroy();
+    language.disabled = false;
+    button.disabled = false;
+    button.textContent = 'Translate';
+    document.querySelector('main').removeAttribute('aria-busy');
+  }
+});
+
+if (supported) {
+  language.disabled = false;
+  checkLanguage();
+} else {
+  status.textContent = 'On-device translation is unavailable in this browser. Try a supported desktop browser such as Chrome. The original English text is shown below.';
+}

