+(() => {
+  'use strict';
+
+  const select = document.querySelector('#language-select');
+  const reset = document.querySelector('#reset-language');
+  const status = document.querySelector('#translation-status');
+  const nodes = [...document.querySelectorAll('[data-copy]')];
+  const original = Object.fromEntries(nodes.map(node => [node.dataset.copy, node.textContent]));
+  // Local copies keep all offered languages usable without a model or a network request.
+  const bundled = {
+    en: original,
+    es: {
+      hero: 'De origen ético, tostado localmente y siempre preparado con cariño. Un pequeño ritual. Mucho que esperar con ilusión.',
+      maple: 'Cremosa leche de avena con un toque de sirope de arce de Vermont.',
+      espresso: 'Intenso, ahumado y perfecto para empezar la mañana con energía.',
+      cold: 'Infusionado durante 18 horas para lograr la máxima suavidad.',
+      story: 'Creemos que las mejores cosas de la vida unen a las personas. Por eso seleccionamos nuestros granos con esmero, los tostamos localmente y damos la bienvenida a todos los que cruzan nuestra puerta.',
+      story2: 'Desde el primer sorbo de la mañana hasta una charla por la tarde, estamos aquí para hacer que cada día sea un poco más especial. Acércate y toma asiento. Estás en buena compañía.'
+    },
+    fr: {
+      hero: 'Un café issu de sources éthiques, torréfié localement et toujours préparé avec soin. Un petit rituel. Un grand plaisir à venir.',
+      maple: 'Un lait d’avoine onctueux avec une touche de sirop d’érable du Vermont.',
+      espresso: 'Intense, fumé et parfait pour bien commencer la matinée.',
+      cold: 'Infusé pendant 18 heures pour une douceur incomparable.',
+      story: 'Nous croyons que les meilleures choses de la vie rapprochent les gens. C’est pourquoi nous choisissons nos grains avec soin, les torréfions localement et accueillons chaque personne qui franchit notre porte.',
+      story2: 'De la première gorgée du matin aux retrouvailles de l’après-midi, nous sommes là pour rendre le quotidien un peu plus spécial. Prenez une chaise. Vous êtes en bonne compagnie.'
+    },
+    de: {
+      hero: 'Ethisch bezogen, lokal geröstet und immer mit Sorgfalt zubereitet. Ein kleines Ritual. Viel Vorfreude.',
+      maple: 'Cremige Hafermilch mit einem Hauch Ahornsirup aus Vermont.',
+      espresso: 'Kräftig, rauchig und perfekt für einen schwungvollen Start in den Morgen.',
+      cold: '18 Stunden lang gezogen für einen besonders milden Geschmack.',
+      story: 'Wir glauben, dass die schönsten Dinge im Leben Menschen zusammenbringen. Deshalb wählen wir unsere Bohnen sorgfältig aus, rösten sie vor Ort und heißen alle willkommen, die durch unsere Tür kommen.',
+      story2: 'Vom ersten Schluck am Morgen bis zum gemütlichen Gespräch am Nachmittag machen wir den Alltag ein wenig besonderer. Nehmen Sie Platz. Sie sind in guter Gesellschaft.'
+    },
+    ja: {
+      hero: '倫理的に調達し、地元で焙煎。いつも心を込めて淹れる一杯。小さな習慣が、毎日の楽しみに。',
+      maple: 'クリーミーなオーツミルクに、バーモント産メープルシロップをほんのり加えました。',
+      espresso: '力強くスモーキーな味わいで、朝の活力にぴったりの一杯。',
+      cold: '18時間かけてじっくり抽出した、とびきりなめらかな味わい。',
+      story: '人生の素晴らしいものは、人と人をつなぐと私たちは信じています。だからこそ、豆を丁寧に選び、地元で焙煎し、ドアを開けるすべての人を温かく迎えます。',
+      story2: '朝の最初のひと口から、午後のおしゃべりまで。何気ない毎日を少し特別にするお手伝いをします。どうぞお掛けください。ここには、心地よい仲間がいます。'
+    }
+  };
+  const cache = new Map();
+  let revision = 0;
+  let currentTranslator = null;
+  let cancelPending = null;
+  const released = new WeakSet();
+
+  function release(translator) {
+    if (translator && !released.has(translator)) {
+      released.add(translator);
+      translator.destroy();
+    }
+  }
+
+  function paint(language, copy) {
+    for (const node of nodes) {
+      node.textContent = copy[node.dataset.copy];
+      // Only the translated passages change language; navigation stays English.
+      node.lang = language;
+    }
+    select.value = language;
+    reset.hidden = language === 'en';
+    try { localStorage.setItem('daily-grind-language', language); } catch { /* Storage can be disabled. */ }
+  }
+
+  function cancelTranslation() {
+    cancelPending?.();
+    cancelPending = null;
+    release(currentTranslator);
+    currentTranslator = null;
+  }
+
+  async function changeLanguage(language, useNative = true) {
+    const request = ++revision;
+    cancelTranslation();
+    paint(language, cache.get(language) || bundled[language]);
+    if (language === 'en') {
+      status.textContent = 'Original English · Translated on your device. Always private.';
+      return;
+    }
+    const name = select.selectedOptions[0].textContent;
+    status.textContent = cache.has(language)
+      ? `${name} · Translated on your device. Always private.`
+      : `${name} · Saved translations, available on your device.`;
+    if (!useNative || cache.has(language) || !('Translator' in globalThis)) return;
+
+    let translator;
+    let timeout;
+    const controller = new AbortController();
+    cancelPending = () => controller.abort();
+    controller.signal.addEventListener('abort', () => {
+      if (request === revision) {
+        status.textContent = `${name} · Using saved translations. No translation service needed.`;
+      }
+    }, { once: true });
+    try {
+      const options = { sourceLanguage: 'en', targetLanguage: language };
+      // Start creation inside the user's interaction so model downloads are allowed.
+      status.textContent = 'Preparing on-device translation. Your selected language is ready below.';
+      timeout = setTimeout(() => controller.abort(), 30000);
+      translator = await globalThis.Translator.create({
+        ...options,
+        signal: controller.signal,
+        monitor(monitor) {
+          monitor.addEventListener('downloadprogress', event => {
+            if (request !== revision) return;
+            const percent = Math.round(event.loaded * 100);
+            status.textContent = `Downloading language pack: ${percent}%. Local translations are ready below.`;
+          });
+        }
+      });
+      if (request !== revision || controller.signal.aborted) return;
+      currentTranslator = translator;
+      status.textContent = 'Translating on your device…';
+      const translated = {};
+      for (const [key, text] of Object.entries(original)) {
+        const result = await translator.translate(text, { signal: controller.signal });
+        if (request !== revision || controller.signal.aborted) return;
+        if (typeof result !== 'string' || !result.trim()) throw new Error('Empty translation');
+        translated[key] = result;
+      }
+      cache.set(language, translated);
+      paint(language, translated);
+      status.textContent = `${name} · Translated on your device. Always private.`;
+    } catch {
+      if (request === revision) {
+        status.textContent = `${name} · Using saved translations. No translation service needed.`;
+      }
+    } finally {
+      clearTimeout(timeout);
+      release(translator);
+      if (request === revision) {
+        currentTranslator = null;
+        cancelPending = null;
+      }
+    }
+  }
+
