@@ -0,0 +1,144 @@
+import { translateTexts, type TranslatorAPI, type LocalTranslator } from '../utils/translation';
+
+class ArticleTranslation extends HTMLElement {
+  connectedCallback() {
+    const select = this.querySelector('select')!;
+    const form = this.querySelector('form')!;
+    const submit = this.querySelector<HTMLButtonElement>('[type="submit"]')!;
+    const restore = this.querySelector<HTMLButtonElement>('[data-restore]')!;
+    const status = this.querySelector<HTMLElement>('[data-status]')!;
+    const api = (window as Window & { Translator?: TranslatorAPI }).Translator;
+    if (!api || !window.isSecureContext) {
+      status.textContent = 'On-device translation is unavailable in this browser. Try a supported desktop Chrome or Edge browser; the original articles remain available.';
+      return;
+    }
+
+    const lifetime = new AbortController();
+    const targets = Array.from(document.querySelectorAll<HTMLElement>('[data-translate]'));
+    const nodes: Text[] = [];
+    for (const target of targets) {
+      const walker = document.createTreeWalker(target, NodeFilter.SHOW_TEXT, {
+        acceptNode(node) {
+          return node.textContent?.trim() && !node.parentElement?.closest('script, style, code, pre, button, [translate="no"]')
+            ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_REJECT;
+        },
+      });
+      while (walker.nextNode()) nodes.push(walker.currentNode as Text);
+    }
+    const originals = nodes.map(node => node.data);
+    const attributes = targets.map(target => ({ lang: target.getAttribute('lang'), dir: target.getAttribute('dir') }));
+    let translator: LocalTranslator | undefined;
+    let operation: AbortController | undefined;
+    let checkVersion = 0;
+    let currentLanguage = 'en';
+
+    const say = (message: string) => { status.textContent = message; };
+    const reset = () => {
+      operation?.abort();
+      translator?.destroy();
+      translator = undefined;
+      nodes.forEach((node, index) => { node.data = originals[index]; });
+      targets.forEach((target, index) => {
+        for (const key of ['lang', 'dir'] as const) {
+          const value = attributes[index][key];
+          if (value === null) target.removeAttribute(key);
+          else target.setAttribute(key, value);
+        }
+      });
+      currentLanguage = 'en';
+      restore.hidden = true;
+      form.removeAttribute('aria-busy');
+      say('Showing the original English articles.');
+    };
+
+    const check = async () => {
+      const version = ++checkVersion;
+      submit.disabled = true;
+      submit.textContent = select.value === 'en' ? 'Show original' : 'Translate';
+      if (select.value === 'en') {
+        submit.disabled = false;
+        return;
+      }
+      say('Checking language availability…');
+      try {
+        const availability = await api.availability({ sourceLanguage: 'en', targetLanguage: select.value });
+        if (version !== checkVersion || lifetime.signal.aborted) return;
+        submit.disabled = availability === 'unavailable' || nodes.length === 0;
+        say(nodes.length === 0 ? 'There are no articles to translate on this page.' : availability === 'unavailable'
+          ? 'This language is unavailable on your device. Choose another language.'
+          : availability === 'available' ? 'Ready to translate on your device.'
+          : 'A language pack is needed. Select Translate to download it and translate on your device.');
+      } catch {
+        if (version === checkVersion && !lifetime.signal.aborted) say('Could not check translation availability. Choose a language to try again.');
+      }
+    };
+
+    select.disabled = false;
+    select.addEventListener('change', check, { signal: lifetime.signal });
+    restore.addEventListener('click', () => {
+      reset();
+      select.disabled = false;
+      select.value = 'en';
+      void check();
+    }, { signal: lifetime.signal });
+    form.addEventListener('submit', async event => {
+      event.preventDefault();
+      if (submit.disabled) return;
+      if (select.value === 'en') { reset(); return; }
+      const targetLanguage = select.value;
+      const label = select.selectedOptions[0].textContent;
+      operation = new AbortController();
+      const signal = operation.signal;
+      submit.disabled = true;
+      select.disabled = true;
+      restore.hidden = false;
+      form.setAttribute('aria-busy', 'true');
+      say('Preparing on-device translation…');
+      let session: LocalTranslator | undefined;
+      try {
+        // Call create directly in the submit gesture; availability was checked earlier.
+        session = await api.create({
+          sourceLanguage: 'en', targetLanguage, signal,
+          monitor(monitor) {
+            monitor.addEventListener('downloadprogress', event => {
+              if (!signal.aborted) say(`Downloading language pack: ${Math.round(event.loaded * 100)}%`);
+            });
+          },
+        });
+        signal.throwIfAborted();
+        translator = session;
+        const translated = await translateTexts(session, originals, signal, (done, total) => {
+          say(`Translating article text: ${Math.round(done / total * 100)}%`);
+        });
+        signal.throwIfAborted();
+        nodes.forEach((node, index) => { node.data = translated[index]; });
+        targets.forEach(target => { target.lang = targetLanguage; target.dir = 'auto'; });
+        currentLanguage = targetLanguage;
+        say(`Articles translated to ${label} on your device. AI translations may contain errors.`);
+      } catch (error) {
+        if (!signal.aborted) say(error instanceof DOMException && error.name === 'NotAllowedError'
+          ? 'The language download needs permission. Select Translate to try again.'
+          : 'Translation could not finish. Your current article text is preserved. Select Translate to retry or choose another language.');
+      } finally {
+        session?.destroy();
+        if (translator === session) translator = undefined;
+        if (!signal.aborted) {
+          select.disabled = false;
+          submit.disabled = false;
+          restore.hidden = currentLanguage === 'en';
+          form.removeAttribute('aria-busy');
+        }
+      }
+    }, { signal: lifetime.signal });
+    document.addEventListener('astro:before-swap', () => {
+      lifetime.abort();
+      operation?.abort();
+      translator?.destroy();
+    }, { once: true, signal: lifetime.signal });
+    void check();
+  }
+}
+
+if (!customElements.get('article-translation')) {
+  customElements.define('article-translation', ArticleTranslation);
+}
