+++ b/src/utils/translation.ts
@@ -0,0 +1,39 @@
+export type Availability = 'available' | 'downloadable' | 'downloading' | 'unavailable';
+
+export interface LocalTranslator {
+  translate(text: string, options?: { signal: AbortSignal }): Promise<string>;
+  destroy(): void;
+}
+
+export interface TranslatorAPI {
+  availability(options: { sourceLanguage: string; targetLanguage: string }): Promise<Availability>;
+  create(options: {
+    sourceLanguage: string;
+    targetLanguage: string;
+    signal: AbortSignal;
+    monitor: (monitor: { addEventListener(type: 'downloadprogress', listener: (event: { loaded: number }) => void): void }) => void;
+  }): Promise<LocalTranslator>;
+}
+
+// Return a complete result before touching the page so failures leave it readable.
+export async function translateTexts(
+  translator: LocalTranslator,
+  originals: string[],
+  signal: AbortSignal,
+  progress: (done: number, total: number) => void,
+): Promise<string[]> {
+  const cache = new Map<string, string>();
+  const results: string[] = [];
+  for (const original of originals) {
+    signal.throwIfAborted();
+    const text = original.trim();
+    if (!cache.has(text)) {
+      cache.set(text, await translator.translate(text, { signal }));
+    }
+    signal.throwIfAborted();
+    // Preserve whitespace around inline elements and links.
+    results.push(original.replace(text, () => cache.get(text)!));
+    progress(results.length, originals.length);
+  }
+  return results;
+}
