@@ -0,0 +1,36 @@
+import test from 'node:test';
+import assert from 'node:assert/strict';
+import { translateTexts } from '../src/utils/translation.ts';
+
+test('preserves inline spacing, translates each unique original once, and reports progress', async () => {
+  const calls: string[] = [];
+  const progress: number[] = [];
+  const originals = [' Hello ', 'Hello', '\nWorld\n'];
+  const translated = await translateTexts({
+    async translate(text) { calls.push(text); return text === 'Hello' ? 'Bonjour' : 'Monde'; },
+    destroy() {},
+  }, originals, new AbortController().signal, done => progress.push(done));
+  assert.deepEqual(translated, [' Bonjour ', 'Bonjour', '\nMonde\n']);
+  assert.deepEqual(calls, ['Hello', 'World']);
+  assert.deepEqual(progress, [1, 2, 3]);
+  assert.deepEqual(originals, [' Hello ', 'Hello', '\nWorld\n']);
+});
+
+test('rejects the whole result on failure without modifying originals', async () => {
+  const originals = ['First', 'Second'];
+  await assert.rejects(translateTexts({
+    async translate(text) { if (text === 'Second') throw new Error('Model failed'); return 'Premier'; },
+    destroy() {},
+  }, originals, new AbortController().signal, () => {}), /Model failed/);
+  assert.deepEqual(originals, ['First', 'Second']);
+});
+
+test('cancellation during translation prevents further work or a completed result', async () => {
+  const controller = new AbortController();
+  let calls = 0;
+  await assert.rejects(translateTexts({
+    async translate() { calls++; controller.abort(); return 'Bonjour'; },
+    destroy() {},
+  }, ['Hello', 'World'], controller.signal, () => {}), { name: 'AbortError' });
+  assert.equal(calls, 1);
+});

