diff --git a/src/scripts/article-translation.ts b/src/scripts/article-translation.ts
new file mode 100644
index 0000000..0348c41
--- /dev/null
+++ b/src/scripts/article-translation.ts
@@ -0,0 +1,130 @@
+type TranslatorSession = {
+  translate(text: string): Promise<string>;
+  destroy(): void;
+};
+type TranslatorOptions = { sourceLanguage: string; targetLanguage: string };
+type TranslatorAPI = {
+  availability(options: TranslatorOptions): Promise<'unavailable' | 'downloadable' | 'downloading' | 'available'>;
+  create(options: TranslatorOptions & {
+    monitor?: (monitor: EventTarget) => void;
+  }): Promise<TranslatorSession>;
+};
+type OriginalText = { node: Text; text: string };
+
+class ArticleTranslation extends HTMLElement {
+  private originals: OriginalText[] = [];
+  private regions: HTMLElement[] = [];
+  private session?: TranslatorSession;
+  private revision = 0;
+  private events?: AbortController;
+
+  connectedCallback() {
+    this.events?.abort();
+    this.events = new AbortController();
+    const options = { signal: this.events.signal };
+    this.querySelector('[data-translate-button]')?.addEventListener('click', () => this.translateArticle(), options);
+    this.querySelector('[data-original-button]')?.addEventListener('click', () => this.restore(), options);
+    if (!this.api) {
+      this.status('On-device translation isn’t available in this browser. Try a recent desktop version of Chrome with Translator support.');
+      this.button.disabled = true;
+    }
+  }
+
+  disconnectedCallback() {
+    this.revision++;
+    this.events?.abort();
+    this.session?.destroy();
+    this.session = undefined;
+  }
+
+  private get api() {
+    return (globalThis as typeof globalThis & { Translator?: TranslatorAPI }).Translator;
+  }
+  private get button() { return this.querySelector<HTMLButtonElement>('[data-translate-button]')!; }
+  private get originalButton() { return this.querySelector<HTMLButtonElement>('[data-original-button]')!; }
+  private get language() { return this.querySelector<HTMLSelectElement>('[data-language]')!; }
+  private status(message: string) { this.querySelector('[data-status]')!.textContent = message; }
+  private busy(value: boolean) {
+    this.button.disabled = value;
+    this.language.disabled = value;
+    this.originalButton.disabled = value;
+    this.button.textContent = value ? 'Translating…' : 'Translate';
+    this.setAttribute('aria-busy', String(value));
+  }
+
+  private captureOriginals() {
+    if (this.originals.length) return;
+    const scope = this.closest('[data-translation-scope]');
+    this.regions = Array.from(scope?.querySelectorAll<HTMLElement>('[data-translatable]') ?? []);
+    for (const region of this.regions) {
+      const walker = document.createTreeWalker(region, NodeFilter.SHOW_TEXT, {
+        acceptNode: (node) => node.textContent?.trim() &&
+          !node.parentElement?.closest('script, style, code, pre, [translate="no"], article-translation')
+          ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_REJECT,
+      });
+      while (walker.nextNode()) {
+        const node = walker.currentNode as Text;
+        this.originals.push({ node, text: node.data });
+      }
+    }
+  }
+
+  private restore() {
+    for (const { node, text } of this.originals) node.data = text;
+    for (const region of this.regions) { region.lang = 'en'; region.dir = 'auto'; }
+    this.originalButton.hidden = true;
+    this.status('Showing the original English text.');
+  }
+
+  private async translateArticle() {
+    const api = this.api;
+    if (!api || this.button.disabled) return;
+    const revision = ++this.revision;
+    const targetLanguage = this.language.value;
+    const options = { sourceLanguage: 'en', targetLanguage };
+    this.busy(true);
+    this.status('Checking language availability…');
+    try {
+      const availability = await api.availability(options);
+      if (revision !== this.revision) return;
+      if (availability === 'unavailable') {
+        this.status('This language pair isn’t available on your device. Choose another language.');
+        return;
+      }
+      this.status(availability === 'available' ? 'Translating on your device…' : 'Downloading a language pack. This may take a moment…');
+      const session = await api.create({
+        ...options,
+        monitor: (monitor) => monitor.addEventListener('downloadprogress', (event) => {
+          if (revision !== this.revision) return;
+          const loaded = (event as Event & { loaded: number }).loaded;
+          this.status(`Downloading language pack… ${Math.round(loaded * 100)}%`);
+        }),
+      });
+      if (revision !== this.revision) { session.destroy(); return; }
+      this.session = session;
+      this.captureOriginals();
+      this.status('Translating on your device…');
+      // Stage all results before changing the page, so failures leave the current text intact.
+      const translations: string[] = [];
+      for (const { text } of this.originals) {
+        const translated = await session.translate(text.trim());
+        if (revision !== this.revision) return;
+        translations.push(text.replace(text.trim(), () => translated));
+      }
+      this.originals.forEach(({ node }, index) => { node.data = translations[index]; });
+      this.regions.forEach(region => { region.lang = targetLanguage; region.dir = 'auto'; });
+      this.originalButton.hidden = false;
+      this.status(`Translated to ${this.language.selectedOptions[0].textContent}. AI translations may contain errors.`);
+    } catch {
+      if (revision === this.revision) this.status('Translation couldn’t finish. Check your connection for language pack downloads and try again.');
+    } finally {
+      if (revision === this.revision) {
+        this.session?.destroy();
+        this.session = undefined;
+        this.busy(false);
+      }
+    }
+  }
+}
+
+if (!customElements.get('article-translation')) customElements.define('article-translation', ArticleTranslation);

