@@ -0,0 +1,59 @@
+import {
+  classifyLink, createWidgetValidator, getSafeRedirect, isTrustedOrderingMessage,
+} from './validation.js';
+
+const base = window.location.href;
+const orderStatus = document.getElementById('order-status');
+const widgetStatus = document.getElementById('widget-status');
+const widget = document.getElementById('rewards-widget');
+const acceptsWidgetMessage = createWidgetValidator(widget.contentWindow);
+
+window.addEventListener('message', (event) => {
+  const data = event.data;
+  if (!data || typeof data !== 'object' || Array.isArray(data)) return;
+
+  if (isTrustedOrderingMessage(event)) {
+    if (data.type === 'order-complete' && typeof data.message === 'string' && data.message.length <= 500) {
+      orderStatus.textContent = data.message;
+    } else if (data.type === 'redirect' && typeof data.url === 'string') {
+      const destination = getSafeRedirect(data.url, base);
+      if (destination) window.location.assign(destination);
+    }
+    return;
+  }
+
+  if (!acceptsWidgetMessage(event)) return;
+  if (data.type === 'init') {
+    widgetStatus.textContent = 'Rewards connected.';
+  } else if (data.type === 'widget-status' && typeof data.message === 'string' && data.message.length <= 500) {
+    widgetStatus.textContent = data.message;
+  }
+});
+
+// Register the receiver before starting the iframe, so initialization cannot race it.
+widget.src = widget.dataset.src;
+
+const returnTo = new URL(base).searchParams.get('returnTo');
+const returnLink = document.getElementById('return-link');
+if (returnTo !== null) {
+  const destination = getSafeRedirect(returnTo, base);
+  if (destination) {
+    returnLink.href = destination;
+    returnLink.hidden = false;
+  }
+}
+
+function validateLink(link) {
+  const classification = classifyLink(link, base);
+  link.dataset.site = classification;
+  if (classification === 'external') link.relList.add('noopener', 'noreferrer');
+  return classification !== 'blocked';
+}
+
+document.querySelectorAll('a[href]').forEach(validateLink);
+for (const eventType of ['click', 'auxclick']) {
+  document.addEventListener(eventType, (event) => {
+    const link = event.target.closest?.('a[href]');
+    if (link && !validateLink(link)) event.preventDefault();
+  });
+}
