+import assert from 'node:assert/strict';
+import { readFileSync } from 'node:fs';
+import { test } from 'node:test';
+import { runInNewContext } from 'node:vm';
+import * as validation from './validation.js';
+
+// Exercise the actual page script with a minimal DOM, without loading a server/browser.
+const pageScript = readFileSync(new URL('./page.js', import.meta.url), 'utf8')
+  .replace(/^import\s*\{[^}]+\}\s*from '\.\/validation\.js';/, '');
+
+function loadPage(returnTo) {
+  const messageHandlers = {};
+  const clickHandlers = {};
+  const redirects = [];
+  const widgetWindow = {};
+  const link = (href) => ({
+    href, dataset: {}, hidden: true,
+    relList: { values: new Set(), add(...values) { values.forEach(value => this.values.add(value)); } },
+  });
+  const links = [link('https://partner.test'), link('javascript:alert(1)'), link('https://www.dailygrind.coffee/menu')];
+  const elements = {
+    'order-status': { textContent: '' },
+    'widget-status': { textContent: 'Connecting' },
+    'return-link': link(''),
+    'rewards-widget': {
+      contentWindow: widgetWindow, dataset: { src: './widget.html' },
+      set src(value) {
+        assert.equal(value, './widget.html');
+        // An immediate init tests that the receiver was installed before navigation.
+        messageHandlers.message({ source: widgetWindow, origin: 'null', data: { type: 'init' } });
+      },
+    },
+  };
+  const window = {
+    location: {
+      href: `https://www.dailygrind.coffee/?returnTo=${encodeURIComponent(returnTo)}`,
+      assign: url => redirects.push(url),
+    },
+    addEventListener: (type, handler) => { messageHandlers[type] = handler; },
+  };
+  const document = {
+    getElementById: id => elements[id], querySelectorAll: () => links,
+    addEventListener: (type, handler) => { clickHandlers[type] = handler; },
+  };
+  runInNewContext(pageScript, { ...validation, window, document, URL });
+  const send = (origin, data, source = {}) => messageHandlers.message({ origin, data, source });
+  return { elements, links, clickHandlers, redirects, widgetWindow, send };
+}
+
+test('page gates ordering effects, renders plain text, and validates redirects', () => {
+  const page = loadPage('https://billing.dailygrind.coffee/orders');
+  const status = page.elements['order-status'];
+  page.send('https://attacker.test', { type: 'order-complete', message: 'Spoofed' });
+  assert.equal(status.textContent, '');
+  page.send(validation.ORDERING_ORIGIN, null);
+  page.send(validation.ORDERING_ORIGIN, { type: 'order-complete', message: {} });
+  page.send(validation.ORDERING_ORIGIN, { type: 'order-complete', message: 'x'.repeat(501) });
+  assert.equal(status.textContent, '');
+  page.send(validation.ORDERING_ORIGIN, { type: 'order-complete', message: '<img src=x onerror=alert(1)>' });
+  assert.equal(status.textContent, '<img src=x onerror=alert(1)>');
+  page.send(validation.ORDERING_ORIGIN, { type: 'redirect', url: '//attacker.test' });
+  page.send('https://attacker.test', { type: 'redirect', url: '/orders' });
+  assert.deepEqual(page.redirects, []);
+  page.send(validation.ORDERING_ORIGIN, { type: 'redirect', url: '/orders' });
+  assert.deepEqual(page.redirects, ['https://www.dailygrind.coffee/orders']);
+  assert.equal(page.elements['return-link'].hidden, false);
+  assert.equal(page.elements['return-link'].href, 'https://billing.dailygrind.coffee/orders');
+  assert.equal(loadPage('//attacker.test').elements['return-link'].hidden, true);
+});
+
+test('page accepts initialized widget updates and rejects other sandbox sources', () => {
+  const page = loadPage('/rewards');
+  const status = page.elements['widget-status'];
+  assert.equal(status.textContent, 'Rewards connected.');
+  page.send('null', { type: 'init' });
+  page.send('null', { type: 'widget-status', message: 'Spoofed' });
+  assert.equal(status.textContent, 'Rewards connected.');
+  page.send('null', { type: 'widget-status', message: 'Reward ready' }, page.widgetWindow);
+  assert.equal(status.textContent, 'Reward ready');
+});
+
+test('page classifies links and revalidates changed links on click and auxclick', () => {
+  const page = loadPage('/rewards');
+  assert.equal(page.links[0].dataset.site, 'external');
+  assert.deepEqual([...page.links[0].relList.values], ['noopener', 'noreferrer']);
+  assert.equal(page.links[2].dataset.site, 'internal');
+  page.links[2].href = 'data:text/html,unsafe';
+  for (const type of ['click', 'auxclick']) {
+    let prevented = false;
+    page.clickHandlers[type]({
+      target: { closest: () => page.links[2] },
+      preventDefault() { prevented = true; },
+    });
+    assert.equal(prevented, true);
+  }
+});
