+// Deployment configuration: use only an ordering origin and a private domain you control.
+export const ORDERING_ORIGIN = 'https://orders.dailygrind.coffee';
+const SITE_DOMAIN = 'dailygrind.coffee';
+
+export function parseWebUrl(candidate, base) {
+  try {
+    const value = typeof candidate === 'string' ? candidate : candidate?.href;
+    if (typeof value !== 'string' || !value.trim()) return null;
+    const url = new URL(value, base);
+    if (!['https:', 'http:'].includes(url.protocol) || url.username || url.password) return null;
+    return url;
+  } catch {
+    return null;
+  }
+}
+
+export function isTrustedOrderingMessage(event) {
+  try {
+    if ('Origin' in globalThis) {
+      let sender;
+      try {
+        sender = Origin.from(event);
+      } catch {
+        // Synthetic MessageEvents lack the browser's internal sender origin.
+        if (!(event instanceof MessageEvent)) return false;
+        sender = Origin.from(event.origin);
+      }
+      return !sender.opaque && sender.isSameOrigin(Origin.from(ORDERING_ORIGIN));
+    }
+    const sender = parseWebUrl(event.origin);
+    return sender !== null && sender.origin === new URL(ORDERING_ORIGIN).origin;
+  } catch {
+    return false;
+  }
+}
+
+function isConfiguredSite(hostname) {
+  // This boundary check is only for the explicitly configured PRIVATE domain,
+  // never a guessed registrable domain or a public suffix such as co.uk/github.io.
+  return hostname === SITE_DOMAIN || hostname.endsWith(`.${SITE_DOMAIN}`);
+}
+
+export function isSameSiteUrl(candidate, base) {
+  const url = parseWebUrl(candidate, base);
+  const app = parseWebUrl(base);
+  if (!url || !app) return false;
+  try {
+    if ('Origin' in globalThis) {
+      return Origin.from(url).isSameSite(Origin.from(app));
+    }
+    if (url.protocol !== app.protocol) return false;
+    if (isConfiguredSite(app.hostname)) return isConfiguredSite(url.hostname);
+    // Unknown deployments fail closed to the same hostname without guessing a PSL.
+    return url.hostname === app.hostname;
+  } catch {
+    return false;
+  }
+}
+
+export function getSafeRedirect(candidate, base) {
+  const url = parseWebUrl(candidate, base);
+  return url && isSameSiteUrl(url, base) ? url.href : null;
+}
+
+export function classifyLink(candidate, base) {
+  if (!parseWebUrl(candidate, base)) return 'blocked';
+  return isSameSiteUrl(candidate, base) ? 'internal' : 'external';
+}
+
+export function createWidgetValidator(expectedWidgetWindow) {
+  const hasOrigin = 'Origin' in globalThis;
+  let pinnedOrigin = hasOrigin ? new Origin() : null;
+  let pinned = false;
+
+  return (event) => {
+    // Check the source on EVERY message, including initialization. Never pin null.
+    if (!expectedWidgetWindow || event.source !== expectedWidgetWindow) return false;
+    try {
+      const sender = hasOrigin ? Origin.from(event) : null;
+      if (hasOrigin ? !sender.opaque : event.origin !== 'null') return false;
+      if (!pinned) {
+        if (event.data?.type !== 'init') return false;
+        pinnedOrigin = sender;
+        pinned = true;
+      }
+      // Do not fall back to parsing "null": it loses opaque origin identity.
+      // Without Origin, the pinned WindowProxy is the available sender identity.
+      return hasOrigin ? sender.isSameOrigin(pinnedOrigin) : true;
+    } catch {
+      return false;
+    }
+  };
+}
