+import assert from 'node:assert/strict';
+import { test } from 'node:test';
+import {
+  ORDERING_ORIGIN, classifyLink, createWidgetValidator, getSafeRedirect,
+  isSameSiteUrl, isTrustedOrderingMessage, parseWebUrl,
+} from './validation.js';
+
+const base = 'https://www.dailygrind.coffee/menu';
+
+test('ordering origin is exact, with default-port normalization', () => {
+  for (const origin of [ORDERING_ORIGIN, `${ORDERING_ORIGIN}:443`]) {
+    assert.equal(isTrustedOrderingMessage(new MessageEvent('message', { origin })), true);
+  }
+  for (const origin of [
+    'null', '', 'garbage', 'https://dailygrind.coffee',
+    'http://orders.dailygrind.coffee', 'https://orders.dailygrind.coffee:8443',
+    'https://orders.dailygrind.coffee.attacker.test',
+    'https://orders.dailygrind.coffee@attacker.test',
+    'https://orders.dailygrind.coffee.attacker.test/path',
+  ]) {
+    assert.equal(isTrustedOrderingMessage(new MessageEvent('message', { origin })), false, origin);
+  }
+});
+
+test('same-site redirects accept relative URLs, subdomains and alternate ports', () => {
+  for (const candidate of ['/orders?receipt=1#details', '//billing.dailygrind.coffee:8443/orders',
+    'https://dailygrind.coffee:443/orders', { href: 'https://billing.dailygrind.coffee/orders' }]) {
+    assert.equal(isSameSiteUrl(candidate, base), true);
+    assert.ok(getSafeRedirect(candidate, base));
+  }
+  assert.equal(getSafeRedirect('../rewards', base), 'https://www.dailygrind.coffee/rewards');
+});
+
+test('redirects reject spoofing, unsafe schemes, credentials, and invalid URLs', () => {
+  for (const candidate of [
+    '', ' ', null, {}, 42, 'https://[invalid',
+    'https://dailygrind.coffee.attacker.test', 'https://evildailygrind.coffee',
+    'https://dailygrind.coffee@attacker.test', 'https://user:password@dailygrind.coffee',
+    'http://www.dailygrind.coffee/orders', '//attacker.test',
+    String.raw`https:\\attacker.test`, 'javascript:alert(1)', 'data:text/html,hello',
+    'blob:https://www.dailygrind.coffee/id', 'file:///orders',
+  ]) {
+    assert.equal(getSafeRedirect(candidate, base), null, String(candidate));
+  }
+  assert.equal(getSafeRedirect('null', base), 'https://www.dailygrind.coffee/null');
+  // One backslash resolves to a same-site path; return the normalized URL we checked.
+  assert.equal(getSafeRedirect(String.raw`https:\attacker.test`, base),
+    'https://www.dailygrind.coffee/attacker.test');
+});
+
+test('fallback never guesses registrable domains or trusts shared hosting siblings', () => {
+  for (const [app, other] of [
+    ['https://a.co.uk', 'https://b.co.uk'],
+    ['https://tenant-a.github.io', 'https://tenant-b.github.io'],
+    ['https://app.example.co.uk', 'https://billing.example.co.uk'],
+    ['https://localhost:11222', 'https://other.localhost:11222'],
+  ]) {
+    assert.equal(isSameSiteUrl(other, app), false);
+    assert.equal(isSameSiteUrl('/orders', app), true);
+  }
+});
+
+test('links are classified using parsed destinations and schemes', () => {
+  assert.equal(classifyLink({ href: `${base}#menu` }, base), 'internal');
+  assert.equal(classifyLink('https://partner.test/coffee', base), 'external');
+  assert.equal(classifyLink('http://dailygrind.coffee', base), 'external');
+  assert.equal(classifyLink('javascript:alert(1)', base), 'blocked');
+  assert.equal(parseWebUrl('https://dailygrind.coffee:443/path').origin, 'https://dailygrind.coffee');
+});
+
+test('fallback pins only the expected sandbox WindowProxy on init', () => {
+  const widget = {};
+  const other = {};
+  const accepts = createWidgetValidator(widget);
+  const message = (source, type, origin = 'null') => ({ source, origin, data: { type } });
+  assert.equal(accepts(message(widget, 'widget-status')), false);
+  assert.equal(accepts(message(other, 'init')), false);
+  assert.equal(accepts(message(widget, 'init', ORDERING_ORIGIN)), false);
+  assert.equal(accepts(message(widget, 'init')), true);
+  assert.equal(accepts(message(widget, 'widget-status')), true);
+  assert.equal(accepts(message(other, 'init')), false);
+  assert.equal(accepts(message(other, 'widget-status')), false);
+  assert.equal(accepts(message(widget, 'widget-status', ORDERING_ORIGIN)), false);
+  assert.equal(createWidgetValidator(null)(message(null, 'init')), false);
+});
+
+test('native Origin path preserves opaque identity and delegates site comparison', () => {
+  // Contract fixture: Node has no browser-dispatched opaque MessageEvents or Origin API.
+  const internalOrigins = new WeakMap();
+  let siteComparison;
+  class BrowserOrigin {
+    constructor(identity = Symbol(), opaque = true) { this.identity = identity; this.opaque = opaque; }
+    static from(value) {
+      if (internalOrigins.has(value)) return internalOrigins.get(value);
+      if (typeof value !== 'string' && !(value instanceof URL)) throw new TypeError();
+      const url = new URL(value);
+      if (url.origin === 'null') throw new TypeError();
+      return new BrowserOrigin(url.origin, false);
+    }
+    isSameOrigin(other) { return this.identity === other.identity; }
+    isSameSite(other) {
+      siteComparison = [this.identity, other.identity];
+      return this.identity === 'https://billing.example.co.uk';
+    }
+  }
+  globalThis.Origin = BrowserOrigin;
+  try {
+    assert.equal(isTrustedOrderingMessage(new MessageEvent('message', { origin: ORDERING_ORIGIN })), true);
+    assert.equal(isTrustedOrderingMessage(new MessageEvent('message', { origin: 'null' })), false);
+    assert.equal(isSameSiteUrl('https://billing.example.co.uk/orders', 'https://app.example.co.uk'), true);
+    assert.deepEqual(siteComparison, ['https://billing.example.co.uk', 'https://app.example.co.uk']);
+    const widget = {};
+    const accepts = createWidgetValidator(widget);
+    const pinned = new BrowserOrigin();
+    const message = (source, type, origin) => {
+      const event = { source, origin: 'null', data: { type } };
+      internalOrigins.set(event, origin);
+      return event;
+    };
+    assert.equal(accepts(message({}, 'init', new BrowserOrigin())), false);
+    assert.equal(accepts(message(widget, 'widget-status', pinned)), false);
+    assert.equal(accepts(message(widget, 'init', new BrowserOrigin(ORDERING_ORIGIN, false))), false);
+    assert.equal(accepts(message(widget, 'init', pinned)), true);
+    assert.equal(accepts(message(widget, 'widget-status', pinned)), true);
+    // A navigation can keep the WindowProxy but create a different opaque origin.
+    assert.equal(accepts(message(widget, 'init', new BrowserOrigin())), false);
+    assert.equal(accepts(message(widget, 'widget-status', new BrowserOrigin())), false);
+    assert.equal(accepts(new MessageEvent('message', { origin: 'null' })), false);
+  } finally {
+    delete globalThis.Origin;
+  }
+});
