@@ -0,0 +1,75 @@
+// Deployment configuration: this must be an exact, trusted HTTPS origin.
+export const ORDERING_ORIGIN = 'https://orders.dailygrind.coffee';
+
+export function parseWebUrl(value, base) {
+  if (typeof value !== 'string' || !value.trim()) return null;
+  try {
+    const url = new URL(value, base);
+    if (!['http:', 'https:'].includes(url.protocol) || url.username || url.password) return null;
+    return url;
+  } catch {
+    return null;
+  }
+}
+
+export function sameSiteRedirect(value, pageUrl) {
+  const page = parseWebUrl(pageUrl);
+  if (!page) return null;
+  const target = parseWebUrl(value, page.href);
+  // Deliberately restrict redirects to the exact origin. This also excludes
+  // sibling subdomains, alternate ports, and protocol downgrades.
+  return target?.origin === page.origin ? target.href : null;
+}
+
+export function validateLinks(root, pageUrl) {
+  const page = parseWebUrl(pageUrl);
+  if (!page) return;
+  for (const link of root.querySelectorAll('a[href]')) {
+    const url = parseWebUrl(link.getAttribute('href'), page.href);
+    if (!url) {
+      link.removeAttribute('href');
+      link.removeAttribute('target');
+      link.setAttribute('aria-disabled', 'true');
+      continue;
+    }
+    link.href = url.href;
+    if (url.origin !== page.origin) {
+      const rel = new Set((link.getAttribute('rel') || '').match(/\S+/g) || []);
+      rel.add('noopener');
+      rel.add('noreferrer');
+      link.setAttribute('rel', [...rel].join(' '));
+    }
+  }
+}
+
+export function installMessageHandlers(host, widget) {
+  let widgetSender = null;
+  function handleMessage(event) {
+    const data = event.data;
+    if (!data || typeof data !== 'object' || Array.isArray(data)) return;
+
+    if (data.type === 'ordering:redirect') {
+      if (event.origin !== ORDERING_ORIGIN) return;
+      const target = sameSiteRedirect(data.url, host.location.href);
+      if (target) host.location.assign(target);
+      return;
+    }
+
+    // Sandboxed frames share the opaque origin "null"; origin alone cannot
+    // identify this widget. Only its known WindowProxy may initialize it.
+    if (!widget || event.origin !== 'null' || !event.source) return;
+    if (data.type === 'widget:init') {
+      if (!widgetSender && event.source === widget.contentWindow) {
+        widgetSender = event.source;
+      }
+      return;
+    }
+    if (event.source !== widgetSender) return;
+    if (data.type === 'widget:resize' && Number.isInteger(data.height)
+        && data.height >= 80 && data.height <= 600) {
+      widget.style.height = `${data.height}px`;
+    }
+  }
+  host.addEventListener('message', handleMessage);
+  return () => host.removeEventListener('message', handleMessage);
+}
