+import test from 'node:test';
+import assert from 'node:assert/strict';
+import { ORDERING_ORIGIN, parseWebUrl, sameSiteRedirect, validateLinks, installMessageHandlers } from './security.mjs';
+
+const page = 'https://dailygrind.coffee/menu';
+
+test('redirects use parsed exact origins and reject URL authority tricks', () => {
+  assert.equal(sameSiteRedirect('/account?next=/menu#orders', page), 'https://dailygrind.coffee/account?next=/menu#orders');
+  assert.equal(sameSiteRedirect('https://DAILYGRIND.coffee:443/order', page), 'https://dailygrind.coffee/order');
+  assert.equal(sameSiteRedirect('https://dailygrind.coffee\\@evil.example', page), 'https://dailygrind.coffee/@evil.example');
+  for (const value of [
+    '//evil.example/path', 'https://dailygrind.coffee.evil.example',
+    'https://dailygrind.coffee@evil.example', 'https://evil.example/dailygrind.coffee',
+    'https://dailygrind.coffee:444/order', 'http://dailygrind.coffee/order',
+    'https://shop.dailygrind.coffee/order', 'https://evil.example\\@dailygrind.coffee',
+    'javascript:alert(1)', 'data:text/html,hello', 'https://[', '', null, {},
+  ]) assert.equal(sameSiteRedirect(value, page), null, String(value));
+});
+
+test('web URL parsing rejects credentials and active schemes', () => {
+  assert.equal(parseWebUrl('https://user:pass@dailygrind.coffee', page), null);
+  assert.equal(parseWebUrl('javascript:alert(1)', page), null);
+  assert.equal(parseWebUrl('mailto:hello@dailygrind.coffee', page), null);
+  assert.equal(parseWebUrl('//example.com/coffee', page).origin, 'https://example.com');
+});
+
+test('links are parsed and external links receive opener and referrer protection', () => {
+  function link(href, rel = '') {
+    const attributes = new Map([['href', href], ['rel', rel], ['target', '_blank']]);
+    return {
+      attributes,
+      getAttribute: key => attributes.get(key) ?? null,
+      setAttribute: (key, value) => attributes.set(key, value),
+      removeAttribute: key => attributes.delete(key),
+    };
+  }
+  const internal = link('/menu');
+  const external = link('https://dailygrind.coffee.evil.example/', 'nofollow');
+  const unsafe = link('javascript:alert(1)');
+  validateLinks({ querySelectorAll: () => [internal, external, unsafe] }, page);
+  assert.equal(internal.href, 'https://dailygrind.coffee/menu');
+  assert.equal(external.getAttribute('rel'), 'nofollow noopener noreferrer');
+  assert.equal(unsafe.getAttribute('href'), null);
+  assert.equal(unsafe.getAttribute('target'), null);
+  assert.equal(unsafe.getAttribute('aria-disabled'), 'true');
+});
+
+function setup() {
+  const navigations = [];
+  let listener;
+  const host = {
+    location: { href: page, assign: url => navigations.push(url) },
+    addEventListener: (_, callback) => { listener = callback; },
+    removeEventListener: (_, callback) => { if (listener === callback) listener = null; },
+  };
+  const widget = { contentWindow: {}, style: {} };
+  const dispose = installMessageHandlers(host, widget);
+  return { widget, navigations, dispose, send: event => listener?.(event) };
+}
+
+test('ordering messages require the exact trusted origin and a same-origin redirect', () => {
+  const { send, navigations } = setup();
+  const data = { type: 'ordering:redirect', url: '/account' };
+  for (const origin of ['null', `${ORDERING_ORIGIN}.evil.example`, 'http://orders.dailygrind.coffee', `${ORDERING_ORIGIN}:444`]) {
+    send({ origin, data });
+  }
+  send({ origin: ORDERING_ORIGIN, data: { ...data, url: '//evil.example' } });
+  for (const data of [null, 'hello', [], {}, { type: 'ordering:redirect', url: {} }]) {
+    send({ origin: ORDERING_ORIGIN, data });
+  }
+  assert.deepEqual(navigations, []);
+  send({ origin: ORDERING_ORIGIN, data });
+  assert.deepEqual(navigations, ['https://dailygrind.coffee/account']);
+});
+
+test('only the designated sandboxed widget can initialize and use the pinned identity', () => {
+  const { send, widget, dispose } = setup();
+  const stranger = {};
+  const emit = (source, type, height = 200, origin = 'null') => send({ origin, source, data: { type, height } });
+  emit(widget.contentWindow, 'widget:resize');
+  emit(stranger, 'widget:init');
+  emit(stranger, 'widget:resize');
+  emit(null, 'widget:init');
+  emit(widget.contentWindow, 'widget:init', 200, ORDERING_ORIGIN);
+  emit(widget.contentWindow, 'widget:resize');
+  assert.equal(widget.style.height, undefined);
+  const pinned = widget.contentWindow;
+  emit(pinned, 'widget:init');
+  emit(pinned, 'widget:resize');
+  assert.equal(widget.style.height, '200px');
+  emit(stranger, 'widget:init');
+  emit(stranger, 'widget:resize', 300);
+  widget.contentWindow = stranger;
+  emit(stranger, 'widget:init');
+  emit(stranger, 'widget:resize', 300);
+  for (const height of [0, -1, 601, '300', NaN, Infinity, 200.5]) emit(pinned, 'widget:resize', height);
+  assert.equal(widget.style.height, '200px');
+  emit(pinned, 'widget:resize', 250);
+  assert.equal(widget.style.height, '250px');
+  dispose();
+  emit(pinned, 'widget:resize', 300);
+  assert.equal(widget.style.height, '250px');
+});

