+import { createServer } from 'node:http';
+import { DatabaseSync } from 'node:sqlite';
+import { mkdirSync } from 'node:fs';
+import { dirname } from 'node:path';
+import { createApplication } from './server/application.mjs';
+import { verifyEmail } from './server/verify-email.mjs';
+const port = Number(process.env.PORT || 11222);
+const origin = process.env.APP_ORIGIN || `http://localhost:${port}`;
+const databasePath = process.env.DATABASE_PATH || './data/rewards.sqlite';
+mkdirSync(dirname(databasePath), { recursive: true });
+const db = new DatabaseSync(databasePath);
+db.exec('PRAGMA journal_mode=WAL; PRAGMA busy_timeout=5000;');
+const handle = createApplication({ db, verify: verifyEmail, origin, trialToken: process.env.EMAIL_VERIFICATION_ORIGIN_TRIAL_TOKEN });
+createServer(async (req, res) => {
+  try {
+    const chunks = [];
+    let size = 0;
+    for await (const chunk of req) {
+      size += chunk.length;
+      if (size > 32768) { res.writeHead(413); res.end('Submission too large'); return; }
+      chunks.push(chunk);
+    }
+    const request = new Request(new URL(req.url, origin), {
+      method: req.method, headers: req.headers,
+      ...(req.method !== 'GET' && req.method !== 'HEAD' ? { body: Buffer.concat(chunks) } : {}),
+    });
+    const response = await handle(request);
+    res.writeHead(response.status, Object.fromEntries(response.headers));
+    res.end(Buffer.from(await response.arrayBuffer()));
+  } catch {
+    res.writeHead(500, { 'Content-Type': 'text/plain', 'Cache-Control': 'no-store' });
+    res.end('Something went wrong. Please reload and try again.');
+  }
+}).listen(port, '0.0.0.0');
