--- /dev/null
+++ b/server/application.mjs
@@ -0,0 +1,77 @@
+import { randomBytes, randomUUID, scrypt } from 'node:crypto';
+import { promisify } from 'node:util';
+import { readFile } from 'node:fs/promises';
+const derive = promisify(scrypt);
+const template = await readFile(new URL('../index.html', import.meta.url), 'utf8');
+const signupScript = await readFile(new URL('../signup.js', import.meta.url), 'utf8');
+const escape = value => String(value).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
+
+export function createApplication({ db, verify, origin, trialToken = '' }) {
+  if (new URL(origin).origin !== origin) throw new Error('APP_ORIGIN must be an exact origin');
+  db.exec(`CREATE TABLE IF NOT EXISTS signup_sessions (id TEXT PRIMARY KEY, nonce TEXT NOT NULL, expires INTEGER NOT NULL);
+    CREATE TABLE IF NOT EXISTS rewards_accounts (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL COLLATE NOCASE UNIQUE,
+      password_hash TEXT NOT NULL, email_verified_at TEXT NOT NULL, created_at TEXT NOT NULL);`);
+  const consume = db.prepare('DELETE FROM signup_sessions WHERE id = ? RETURNING nonce, expires');
+  const insert = db.prepare('INSERT INTO signup_sessions VALUES (?, ?, ?)');
+  const cleanup = db.prepare('DELETE FROM signup_sessions WHERE expires < ?');
+
+  function page({ message = '', success = false, status = 200, name = '', email = '' } = {}) {
+    cleanup.run(Date.now());
+    const id = randomBytes(32).toString('base64url');
+    const nonce = randomBytes(32).toString('base64url');
+    insert.run(id, nonce, Date.now() + 10 * 60 * 1000);
+    const html = template.replace('<!--SERVER_NOTICE-->', message ? `<div class="notice ${success ? 'success' : 'error'}" role="status">${escape(message)}</div>` : '')
+      .replace('nonce="SERVER_NONCE"', `nonce="${nonce}"`)
+      .replace('value="SERVER_CSRF"', `value="${nonce}"`)
+      .replace('value="SERVER_NAME"', `value="${escape(name)}"`)
+      .replace('value="SERVER_EMAIL"', `value="${escape(email)}"`);
+    const headers = new Headers({ 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store',
+      'Set-Cookie': `dg_signup=${id}; HttpOnly; SameSite=Lax; Path=/; Max-Age=600${origin.startsWith('https:') ? '; Secure' : ''}`,
+      'X-Content-Type-Options': 'nosniff', 'Referrer-Policy': 'same-origin',
+      'Content-Security-Policy': "default-src 'self'; img-src 'self' https://images.unsplash.com; style-src 'self' 'unsafe-inline'; script-src 'self'; base-uri 'none'; form-action 'self'; frame-ancestors 'none'",
+    });
+    if (trialToken) headers.set('Origin-Trial', trialToken);
+    return new Response(html, { status, headers });
+  }
+
+  return async function handle(request) {
+    const path = new URL(request.url).pathname;
+    if (request.method === 'GET' && path === '/') return page();
+    if (request.method === 'GET' && path === '/signup.js') return new Response(signupScript, { headers: { 'Content-Type': 'text/javascript; charset=utf-8', 'X-Content-Type-Options': 'nosniff' } });
+    if (request.method === 'GET' && path === '/api/verify-email') return Response.redirect(`${origin}/#rewards`, 303);
+    if (request.method !== 'POST' || path !== '/api/verify-email') return new Response('Not found', { status: 404 });
+    if (request.headers.get('origin') !== origin) return new Response('Forbidden', { status: 403 });
+    const sessionId = request.headers.get('cookie')?.match(/(?:^|;\s*)dg_signup=([A-Za-z0-9_-]{43})(?:;|$)/)?.[1];
+    // DELETE RETURNING consumes the challenge atomically, before asynchronous verification.
+    const session = sessionId ? consume.get(sessionId) : undefined;
+    if (!session || session.expires < Date.now()) return page({ status: 400, message: 'Your sign-up session expired. Please try again below.' });
+    if (!request.headers.get('content-type')?.startsWith('application/x-www-form-urlencoded')) return page({ status: 415, message: 'Please use the sign-up form below.' });
+    const body = await request.text();
+    if (Buffer.byteLength(body) > 32768) return page({ status: 413, message: 'That submission was too large. Please try again.' });
+    const form = new URLSearchParams(body);
+    const name = (form.get('name') || '').trim();
+    const email = (form.get('email') || '').trim();
+    const password = form.get('password') || '';
+    const failure = (message, status = 400) => page({ message, status, name: name.slice(0, 100), email: email.slice(0, 254) });
+    if (form.get('csrf') !== session.nonce) return failure('Your form could not be confirmed. Please try again.');
+    if (!name || name.length > 100 || email.length > 254 || !/^[^\s@]+@[a-z0-9.-]+\.[a-z]{2,}$/i.test(email) ||
+        password.length < 12 || password.length > 128) return failure('Enter your name, a valid email, and a password of 12–128 characters.');
+    const rawToken = (form.get('token') || '').trim();
+    if (!rawToken) return failure('Your browser could not verify this email. Use a supported Chrome browser and sign in to your email provider in the same browser, then try again. No email has been sent; no account was created.', 422);
+    try {
+      await verify({ rawToken, submittedEmail: email, expectedNonce: session.nonce, expectedAudience: origin });
+    } catch {
+      return failure('We could not confirm your email securely. Check that you are signed in to your email provider, then try again. No email has been sent; no account was created.', 422);
+    }
+    const salt = randomBytes(16).toString('hex');
+    const hash = `${salt}:${(await derive(password, salt, 64)).toString('hex')}`;
+    const now = new Date().toISOString();
+    try {
+      db.prepare('INSERT INTO rewards_accounts VALUES (?, ?, ?, ?, ?, ?)').run(randomUUID(), name, email, hash, now, now);
+    } catch (error) {
+      if (!String(error.message).includes('UNIQUE')) throw error;
+      return failure('An account already exists for this verified email address.', 409);
+    }
+    return page({ success: true, message: `Welcome to the Daily Grind, ${name}! Your email is verified and your rewards account is ready.` });
+  };
+}
