@@ -0,0 +1,85 @@
+import { createHash } from 'node:crypto';
+import { resolveTxt } from 'node:dns/promises';
+import { SDJwtInstance, decodeSdJwtSync } from '@sd-jwt/core';
+import { createRemoteJWKSet, importJWK, jwtVerify } from 'jose';
+
+const algorithms = ['Ed25519', 'EdDSA', 'ES256'];
+const normalize = alg => alg === 'Ed25519' ? 'EdDSA' : alg;
+const hasher = (data, alg) => {
+  if (alg !== 'sha-256') throw new Error('Unsupported digest');
+  return createHash('sha256').update(data).digest();
+};
+const configured = (name, fallback) => (process.env[name] || fallback).split(',').map(x => x.trim());
+
+// Explicit operator-managed network trust prevents token-controlled SSRF.
+function trustedURL(value, hosts) {
+  const url = new URL(value);
+  if (url.protocol !== 'https:' || url.port || url.username || url.password || url.hash || !hosts.includes(url.hostname)) {
+    throw new Error('Untrusted verification URL');
+  }
+  return url;
+}
+
+export function createEmailVerifier({ lookup = resolveTxt, fetchMetadata = fetch, loadKeys = createRemoteJWKSet } = {}) {
+return async function verifyEmail({ rawToken, submittedEmail, expectedNonce, expectedAudience }) {
+  if (!expectedNonce || rawToken.length > 24000) throw new Error('Invalid presentation');
+  const decoded = decodeSdJwtSync(rawToken, hasher);
+  const payload = decoded.jwt.payload;
+  const issuer = payload.iss;
+  if (!decoded.kbJwt || payload.email_verified !== true || typeof payload.email !== 'string' ||
+      payload.email.toLowerCase() !== submittedEmail.toLowerCase()) throw new Error('Email mismatch');
+  const issuerURL = trustedURL(issuer, configured('EVP_ISSUER_HOSTS', 'accounts.google.com'));
+  if (issuerURL.origin !== issuer) throw new Error('Issuer must be an exact origin');
+  const domain = submittedEmail.slice(submittedEmail.lastIndexOf('@') + 1).toLowerCase();
+  const records = await lookup(`_email-verification.${domain}`);
+  if (!records.some(parts => {
+    const record = parts.join('');
+    return record.startsWith('iss=') && `https://${record.slice(4).trim()}` === issuer;
+  })) throw new Error('Issuer not delegated by email domain');
+  const response = await fetchMetadata(new URL('/.well-known/email-verification', issuer), {
+    redirect: 'error', signal: AbortSignal.timeout(5000),
+  });
+  if (!response.ok) throw new Error('Discovery failed');
+  const metadataText = await response.text();
+  if (metadataText.length > 32000) throw new Error('Discovery too large');
+  const metadata = JSON.parse(metadataText);
+  if (metadata.issuer !== issuer) throw new Error('Discovery issuer mismatch');
+  const jwksURL = trustedURL(metadata.jwks_uri, configured('EVP_JWKS_HOSTS', 'accounts.google.com,www.googleapis.com'));
+  const keys = loadKeys(jwksURL, { timeoutDuration: 5000 });
+  const options = { issuer, typ: 'ev+sd-jwt', algorithms, requiredClaims: ['iss', 'iat', 'exp'], maxTokenAge: '5m', clockTolerance: 60 };
+  const sdJwt = new SDJwtInstance({
+    hasher,
+    verifier: async (data, signature) => {
+      const token = `${data}.${signature}`;
+      try { await jwtVerify(token, keys, options); }
+      catch (error) {
+        if (error.code !== 'ERR_JWKS_MULTIPLE_MATCHING_KEYS') throw error;
+        let matched = false;
+        for await (const key of error) {
+          try { await jwtVerify(token, key, options); matched = true; break; } catch {}
+        }
+        if (!matched) throw error;
+      }
+      return true;
+    },
+    kbVerifier: async (data, signature) => {
+      const jwk = payload.cnf?.jwk;
+      const alg = decoded.kbJwt.header.alg;
+      if (!jwk || jwk.d || !algorithms.includes(jwk.alg) || !algorithms.includes(alg) || normalize(jwk.alg) !== normalize(alg)) {
+        throw new Error('Invalid holder key');
+      }
+      await jwtVerify(`${data}.${signature}`, await importJWK(jwk, alg), {
+        typ: 'kb+jwt', audience: expectedAudience, algorithms: [alg], maxTokenAge: '5m', clockTolerance: 60,
+      });
+      return true;
+    },
+  });
+  await sdJwt.verify(rawToken, {
+    requiredClaimKeys: ['email', 'email_verified'], allowedIssuerAlgorithms: algorithms, allowedKeyBindingAlgorithms: algorithms, keyBindingNonce: expectedNonce,
+    expectedKeyBindingAudience: expectedAudience, keyBindingMaxAgeSeconds: 300, skewSeconds: 60,
+  });
+}
+
+}
+
+export const verifyEmail = createEmailVerifier();
