@@ -0,0 +1,130 @@
+import test from 'node:test';
+import assert from 'node:assert/strict';
+import { DatabaseSync } from 'node:sqlite';
+import { createHash } from 'node:crypto';
+import { SignJWT, generateKeyPair, exportJWK, createLocalJWKSet } from 'jose';
+import { createApplication } from '../server/application.mjs';
+import { createEmailVerifier } from '../server/verify-email.mjs';
+const origin = 'https://coffee.example';
+
+function setup(verify = async () => {}) {
+  const db = new DatabaseSync(':memory:');
+  const handle = createApplication({ db, verify, origin, trialToken: 'configured-trial' });
+  const count = () => db.prepare('SELECT COUNT(*) AS n FROM rewards_accounts').get().n;
+  async function form() {
+    const response = await handle(new Request(origin));
+    const html = await response.text();
+    assert.equal(response.headers.get('cache-control'), 'no-store');
+    assert.match(response.headers.get('set-cookie'), /HttpOnly; SameSite=Lax.*Secure/);
+    assert.equal(response.headers.get('origin-trial'), 'configured-trial');
+    assert(!html.includes('SERVER_NONCE'));
+    return { cookie: response.headers.get('set-cookie').split(';')[0], csrf: html.match(/name="csrf" value="([^"]+)"/)[1] };
+  }
+  function post(session, values = {}, suppliedOrigin = origin) {
+    return handle(new Request(`${origin}/api/verify-email`, { method: 'POST',
+      headers: { cookie: session.cookie, origin: suppliedOrigin, 'content-type': 'application/x-www-form-urlencoded' },
+      body: new URLSearchParams({ name: 'Alex Rivera', email: 'Alex@example.com', password: 'a very long password', token: 'proof', csrf: session.csrf, ...values }),
+    }));
+  }
+  return { db, count, form, post };
+}
+
+test('only successful verification creates a durable, hashed account; nonce replay fails', async () => {
+  let calls = 0;
+  const s = setup(async input => { calls++; assert.equal(input.expectedAudience, origin); assert.equal(input.expectedNonce.length, 43); });
+  const session = await s.form();
+  const response = await s.post(session);
+  assert.equal(response.status, 200);
+  assert.match(await response.text(), /Your email is verified/);
+  assert.equal(s.count(), 1);
+  const account = s.db.prepare('SELECT * FROM rewards_accounts').get();
+  assert.match(account.password_hash, /^[a-f0-9]{32}:[a-f0-9]{128}$/);
+  assert(account.email_verified_at);
+  assert.equal((await s.post(session)).status, 400);
+  assert.equal(calls, 1);
+  s.db.close();
+});
+
+test('missing and rejected proofs never create accounts and get fresh retry forms', async () => {
+  const s = setup(async () => { throw new Error('bad proof'); });
+  for (const token of ['', 'forged']) {
+    const session = await s.form();
+    const response = await s.post(session, { token, name: '<script>alert(1)</script>' });
+    assert.equal(response.status, 422);
+    const html = await response.text();
+    assert.match(html, /No email has been sent; no account was created/);
+    assert(!html.includes('<script>alert(1)</script>'));
+    assert(html.includes('&lt;script&gt;'));
+    assert(!html.includes('a very long password'));
+    assert.equal((await s.post(session)).status, 400);
+  }
+  assert.equal(s.count(), 0);
+  s.db.close();
+});
+
+test('CSRF, expired challenges, invalid fields and cross-origin requests are rejected', async () => {
+  const s = setup(async () => assert.fail('verification must not run'));
+  assert.equal((await s.post(await s.form(), { csrf: 'wrong' })).status, 400);
+  assert.equal((await s.post(await s.form(), { password: 'short' })).status, 400);
+  assert.equal((await s.post(await s.form(), {}, 'https://attacker.example')).status, 403);
+  const expired = await s.form();
+  s.db.prepare('UPDATE signup_sessions SET expires = 0').run();
+  assert.equal((await s.post(expired)).status, 400);
+  assert.equal(s.count(), 0);
+  s.db.close();
+});
+
+test('duplicate verified emails compare case-insensitively', async () => {
+  const s = setup();
+  assert.equal((await s.post(await s.form())).status, 200);
+  assert.equal((await s.post(await s.form(), { email: 'alex@EXAMPLE.COM' })).status, 409);
+  assert.equal(s.count(), 1);
+  s.db.close();
+});
+
+// Real signatures and SD-JWT key binding, with no listener or external requests.
+const issuer = 'https://accounts.google.com';
+const issuerKeys = await generateKeyPair('ES256');
+const extraIssuerKey = await generateKeyPair('ES256');
+const holderKeys = await generateKeyPair('ES256');
+const holderJwk = { ...await exportJWK(holderKeys.publicKey), alg: 'ES256' };
+const jwks = createLocalJWKSet({ keys: [await exportJWK(extraIssuerKey.publicKey), await exportJWK(issuerKeys.publicKey)] });
+async function presentation({ email = 'alex@example.com', verified = true, nonce = 'session-nonce', aud = origin,
+    age = 0, sdHash, signedBy = issuerKeys.privateKey } = {}) {
+  const iat = Math.floor(Date.now() / 1000) - age;
+  const evt = await new SignJWT({ iss: issuer, email, email_verified: verified, iat, exp: iat + 300, cnf: { jwk: holderJwk } })
+    .setProtectedHeader({ alg: 'ES256', typ: 'ev+sd-jwt' }).sign(signedBy);
+  const sd = `${evt}~`;
+  const kb = await new SignJWT({ iat, aud, nonce, sd_hash: sdHash || createHash('sha256').update(sd).digest('base64url') })
+    .setProtectedHeader({ alg: 'ES256', typ: 'kb+jwt' }).sign(holderKeys.privateKey);
+  return `${sd}${kb}`;
+}
+const verifier = (record = 'iss=accounts.google.com') => createEmailVerifier({
+  lookup: async () => [[record]],
+  fetchMetadata: async () => Response.json({ issuer, jwks_uri: 'https://www.googleapis.com/keys' }),
+  loadKeys: () => jwks,
+});
+const check = (verify, rawToken, options = {}) => verify({ rawToken, submittedEmail: 'Alex@EXAMPLE.COM', expectedNonce: 'session-nonce', expectedAudience: origin, ...options });
+
+test('valid signatures, case-insensitive email and missing-kid multiple-key JWKS work', async () => {
+  await check(verifier(), await presentation());
+});
+
+test('cryptographic verification rejects wrong nonce, audience, email, delegation, freshness, binding and signatures', async () => {
+  for (const options of [{ nonce: 'other' }, { aud: 'https://attacker.example' }, { email: 'other@example.com' },
+    { verified: false }, { age: 900 }, { sdHash: 'invalid' }, { signedBy: holderKeys.privateKey }]) {
+    await assert.rejects(check(verifier(), await presentation(options)));
+  }
+  await assert.rejects(check(verifier('iss=attacker.example'), await presentation()));
+  const rawToken = await presentation();
+  await assert.rejects(check(verifier(), rawToken.split('~')[0] + '~'));
+  await assert.rejects(check(verifier(), rawToken, { expectedNonce: '' }));
+});
+
+test('untrusted metadata keys are never fetched', async () => {
+  const verify = createEmailVerifier({ lookup: async () => [['iss=accounts.google.com']],
+    fetchMetadata: async () => Response.json({ issuer, jwks_uri: 'https://127.0.0.1/keys' }),
+    loadKeys: () => assert.fail('must not fetch private host'),
+  });
+  await assert.rejects(check(verify, await presentation()));
+});

