+import { DatabaseSync } from 'node:sqlite';
+export function createStore(filename) {
+  const db = new DatabaseSync(filename);
+  db.exec(`PRAGMA journal_mode=WAL;
+    CREATE TABLE IF NOT EXISTS members (
+      id INTEGER PRIMARY KEY, google_subject TEXT NOT NULL UNIQUE, email TEXT NOT NULL UNIQUE,
+      first_name TEXT NOT NULL, last_name TEXT NOT NULL, marketing INTEGER NOT NULL,
+      created_at INTEGER NOT NULL, email_verified_at INTEGER NOT NULL
+    );
+    CREATE TABLE IF NOT EXISTS sessions (
+      token_hash TEXT PRIMARY KEY, member_id INTEGER NOT NULL REFERENCES members(id), expires_at INTEGER NOT NULL
+    );`);
+  return {
+    register(member) {
+      db.exec('BEGIN IMMEDIATE');
+      try {
+        if (db.prepare('SELECT id FROM members WHERE email = ? OR google_subject = ?').get(member.email, member.subject)) {
+          const error = new Error('Already registered'); error.code = 'ACCOUNT_EXISTS'; throw error;
+        }
+        const result = db.prepare('INSERT INTO members (google_subject,email,first_name,last_name,marketing,created_at,email_verified_at) VALUES (?,?,?,?,?,?,?)').run(member.subject, member.email, member.firstName, member.lastName, Number(member.marketing), member.createdAt, member.createdAt);
+        db.prepare('DELETE FROM sessions WHERE expires_at < ?').run(member.createdAt);
+        db.prepare('INSERT INTO sessions VALUES (?,?,?)').run(member.sessionHash, result.lastInsertRowid, member.createdAt + 30 * 86400_000);
+        db.exec('COMMIT');
+        return member;
+      } catch (error) { db.exec('ROLLBACK'); throw error; }
+    },
+    close: () => db.close()
+  };
+}
