@@ -0,0 +1,76 @@
+import { randomBytes, createHash } from 'node:crypto';
+import { OAuth2Client } from 'google-auth-library';
+
+const google = new OAuth2Client();
+const token = () => randomBytes(32).toString('hex');
+export const hash = value => createHash('sha256').update(value).digest('hex');
+
+export function createApp({ clientId, origin, store, verifyToken = async credential => {
+  const ticket = await google.verifyIdToken({ idToken: credential, audience: clientId });
+  return ticket.getPayload();
+}, now = Date.now }) {
+  const pending = new Map();
+  const limits = new Map();
+  const secure = origin.startsWith('https:') ? '; Secure' : '';
+  const cookie = (name, value, age) => `${name}=${value}; Path=/; HttpOnly; SameSite=Strict; Max-Age=${age}${secure}`;
+  const json = (body, status = 200, headers = {}) => new Response(JSON.stringify(body), {
+    status, headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store', ...headers }
+  });
+  return async function handleApi(request, remoteAddress = 'local') {
+    const url = new URL(request.url);
+    if (!['/api/auth/config', '/api/verify-email', '/api/rewards/signup'].includes(url.pathname)) return json({ error: 'Not found.' }, 404);
+    if (request.method !== (url.pathname === '/api/auth/config' ? 'GET' : 'POST')) return json({ error: 'Method not allowed.' }, 405);
+    if (request.headers.get('sec-fetch-site') === 'cross-site' || (request.method === 'POST' && request.headers.get('origin') !== origin)) return json({ error: 'Request origin is not allowed.' }, 403);
+    for (const [key, value] of pending) if (value.expires <= now()) pending.delete(key);
+    for (const [key, value] of limits) if (value.until <= now()) limits.delete(key);
+    const limit = limits.get(remoteAddress) || { count: 0, until: now() + 60_000 };
+    limits.set(remoteAddress, limit);
+    if (++limit.count > 30) return json({ error: 'Too many attempts. Please try again in a minute.' }, 429, { 'Retry-After': '60' });
+    if (!clientId) return json({ error: 'Email verification is temporarily unavailable. Please try again later.' }, 503);
+    if (url.pathname === '/api/auth/config') {
+      const id = token(), nonce = token();
+      pending.set(id, { nonce, expires: now() + 10 * 60_000 });
+      return json({ clientId, nonce }, 200, { 'Set-Cookie': cookie('dg_signup', id, 600) });
+    }
+    const id = request.headers.get('cookie')?.match(/(?:^|;\s*)dg_signup=([a-f0-9]{64})(?:;|$)/)?.[1];
+    const state = pending.get(id);
+    if (!state || state.expires <= now()) return json({ error: 'Your verification session expired. Please verify your email again.', reset: true }, 401);
+    if (!request.headers.get('content-type')?.startsWith('application/json')) return json({ error: 'JSON is required.' }, 415);
+    let body;
+    try {
+      const raw = await request.text();
+      if (raw.length > 16_384) return json({ error: 'Request is too large.' }, 413);
+      body = JSON.parse(raw);
+      if (!body || typeof body !== 'object' || Array.isArray(body)) throw new Error();
+    } catch { return json({ error: 'Invalid request.' }, 400); }
+    if (url.pathname === '/api/verify-email') {
+      if (typeof body.credential !== 'string' || body.credential.length > 12_000) return json({ error: 'A Google credential is required.' }, 400);
+      let payload;
+      try { payload = await verifyToken(body.credential); } catch { return json({ error: 'Google could not verify this account. Please try again.' }, 401); }
+      if (!payload || !['accounts.google.com', 'https://accounts.google.com'].includes(payload.iss) || payload.aud !== clientId || payload.exp * 1000 <= now() || !Number.isFinite(payload.exp) || payload.nonce !== state.nonce || payload.email_verified !== true || typeof payload.sub !== 'string' || !payload.sub || typeof payload.email !== 'string') return json({ error: 'This Google credential is invalid or expired.' }, 401);
+      const email = payload.email.toLowerCase();
+      if (!email.endsWith('@gmail.com') && !(typeof payload.hd === 'string' && payload.hd)) return json({ error: 'Please use a Gmail or Google Workspace address. Other email providers cannot be verified here without an email challenge.' }, 422);
+      if (typeof body.email !== 'string' || body.email.trim().toLowerCase() !== email) return json({ error: 'Choose the Google account that matches the email address you entered.' }, 422);
+      state.verified = { subject: payload.sub, email };
+      state.nonce = token(); // A credential can be consumed only once.
+      return json({ verified: true, email });
+    }
+    if (!state.verified) return json({ error: 'Please verify your email with Google before joining.' }, 403);
+    const firstName = typeof body.firstName === 'string' ? body.firstName.trim() : '';
+    const lastName = typeof body.lastName === 'string' ? body.lastName.trim() : '';
+    if (!firstName || !lastName || firstName.length > 60 || lastName.length > 60 || /[\x00-\x1f]/.test(firstName + lastName) || typeof body.marketing !== 'boolean') return json({ error: 'Please enter your first and last name and a valid email preference.' }, 400);
+    if (typeof body.email !== 'string' || body.email.trim().toLowerCase() !== state.verified.email) return json({ error: 'Your email changed. Please verify it again.' }, 422);
+    try {
+      const session = token();
+      const member = store.register({ ...state.verified, firstName, lastName, marketing: body.marketing, sessionHash: hash(session), createdAt: now() });
+      pending.delete(id);
+      const response = json({ created: true, firstName: member.firstName, email: member.email }, 201);
+      response.headers.append('Set-Cookie', cookie('dg_session', session, 60 * 60 * 24 * 30));
+      response.headers.append('Set-Cookie', cookie('dg_signup', '', 0));
+      return response;
+    } catch (error) {
+      if (error.code === 'ACCOUNT_EXISTS') return json({ error: 'You’re already a member! This email is registered with Daily Grind.' }, 409);
+      return json({ error: 'We couldn’t create your account. Please try again.' }, 500);
+    }
+  };
+}
