+import { createServer } from 'node:http';
+import { readFile } from 'node:fs/promises';
+import { mkdirSync } from 'node:fs';
+import { createApp } from './app.mjs';
+import { createStore } from './account-store.mjs';
+
+const port = Number(process.env.PORT || 11222);
+const origin = new URL(process.env.APP_ORIGIN || `http://localhost:${port}`).origin;
+mkdirSync('data', { recursive: true });
+const api = createApp({ clientId: process.env.GOOGLE_CLIENT_ID, origin, store: createStore(process.env.DATABASE_PATH || 'data/rewards.sqlite') });
+const files = { '/': ['index.html', 'text/html; charset=utf-8'], '/styles.css': ['styles.css', 'text/css; charset=utf-8'], '/signup.js': ['signup.js', 'text/javascript; charset=utf-8'] };
+createServer(async (req, res) => {
+  res.setHeader('X-Content-Type-Options', 'nosniff');
+  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
+  res.setHeader('Cross-Origin-Opener-Policy', 'same-origin-allow-popups');
+  try {
+    const url = new URL(req.url, origin);
+    if (url.pathname.startsWith('/api/')) {
+      let size = 0;
+      const chunks = [];
+      for await (const chunk of req) {
+        size += chunk.length;
+        if (size > 16_384) { res.writeHead(413); res.end('Request too large'); return; }
+        chunks.push(chunk);
+      }
+      const request = new Request(url, { method: req.method, headers: req.headers, ...(['GET','HEAD'].includes(req.method) ? {} : { body: Buffer.concat(chunks) }) });
+      const result = await api(request, req.socket.remoteAddress);
+      const headers = Object.fromEntries([...result.headers].filter(([name]) => name !== 'set-cookie'));
+      const cookies = result.headers.getSetCookie();
+      if (cookies.length) headers['Set-Cookie'] = cookies;
+      res.writeHead(result.status, headers);
+      res.end(await result.text());
+    } else if (files[url.pathname] && ['GET','HEAD'].includes(req.method)) {
+      const [file, type] = files[url.pathname];
+      const contents = await readFile(new URL(file, import.meta.url));
+      res.writeHead(200, { 'Content-Type': type });
+      res.end(req.method === 'HEAD' ? undefined : contents);
+    } else { res.writeHead(404); res.end('Not found'); }
+  } catch { res.writeHead(500); res.end('Something went wrong. Please try again.'); }
+}).listen(port, '0.0.0.0', () => console.log(`Daily Grind listening on ${port}`));
