@@ -0,0 +1,99 @@
+const form = document.querySelector('#signup-form');
+const emailInput = form.elements.email;
+const status = document.querySelector('#form-status');
+const verifyButton = document.querySelector('#verify-button');
+const joinButton = document.querySelector('#join-button');
+let verifiedEmail = '';
+let googleLoading;
+let busy = false;
+function showStatus(message) { status.textContent = message; }
+function resetVerification() {
+  verifiedEmail = '';
+  document.querySelector('#verified-label').hidden = true;
+  verifyButton.querySelector('span').textContent = 'Verify email with Google';
+  document.querySelector('#google-button').hidden = true;
+}
+emailInput.addEventListener('input', () => { resetVerification(); showStatus(''); });
+async function api(path, body) {
+  let response;
+  try { response = await fetch(path, { method: body ? 'POST' : 'GET', headers: body ? { 'Content-Type': 'application/json' } : {}, credentials: 'same-origin', ...(body ? { body: JSON.stringify(body) } : {}) }); }
+  catch { throw new Error('We couldn’t connect. Check your connection and try again.'); }
+  let data;
+  try { data = await response.json(); } catch { throw new Error('Email verification is temporarily unavailable. Please try again later.'); }
+  if (!response.ok) {
+    if (data.reset) resetVerification();
+    throw new Error(data.error || 'Something went wrong. Please try again.');
+  }
+  return data;
+}
+function loadGoogle() {
+  if (window.google?.accounts?.id) return Promise.resolve();
+  if (googleLoading) return googleLoading;
+  googleLoading = new Promise((resolve, reject) => {
+    const script = document.createElement('script');
+    const timer = setTimeout(() => { script.remove(); googleLoading = null; reject(new Error('Google sign-in could not load. Check your connection and try again.')); }, 15000);
+    script.src = 'https://accounts.google.com/gsi/client';
+    script.async = true;
+    script.onload = () => { clearTimeout(timer); resolve(); };
+    script.onerror = () => { clearTimeout(timer); script.remove(); googleLoading = null; reject(new Error('Google sign-in could not load. Please try again.')); };
+    document.head.append(script);
+  });
+  return googleLoading;
+}
+async function startVerification() {
+  if (busy) return;
+  if (!emailInput.reportValidity()) return;
+  busy = true; verifyButton.disabled = true;
+  showStatus('Preparing secure email verification…');
+  try {
+    const config = await api('/api/auth/config');
+    await loadGoogle();
+    const chosenEmail = emailInput.value.trim().toLowerCase();
+    google.accounts.id.initialize({ client_id: config.clientId, nonce: config.nonce, auto_select: false, callback: async result => {
+      verifyButton.disabled = true;
+      showStatus('Verifying your email securely…');
+      try {
+        const data = await api('/api/verify-email', { credential: result.credential, email: chosenEmail });
+        if (emailInput.value.trim().toLowerCase() !== data.email) throw new Error('Your email changed. Please verify it again.');
+        verifiedEmail = data.email;
+        document.querySelector('#verified-label').hidden = false;
+        document.querySelector('#google-button').hidden = true;
+        verifyButton.querySelector('span').textContent = 'Email verified with Google';
+        showStatus('Email verified. You’re ready to create your account.');
+      } catch (error) { resetVerification(); showStatus(error.message); }
+      finally { verifyButton.disabled = false; }
+    } });
+    const container = document.querySelector('#google-button');
+    container.hidden = false;
+    google.accounts.id.renderButton(container, { theme: 'outline', size: 'large', text: 'continue_with', width: Math.min(360, container.clientWidth) });
+    showStatus('Continue with Google below and choose the account matching your email.');
+  } catch (error) { showStatus(error.message); }
+  finally { busy = false; verifyButton.disabled = false; }
+}
+verifyButton.addEventListener('click', startVerification);
+form.addEventListener('submit', async event => {
+  event.preventDefault();
+  if (busy) return;
+  if (!verifiedEmail || verifiedEmail !== emailInput.value.trim().toLowerCase()) { await startVerification(); return; }
+  busy = true; joinButton.disabled = true;
+  joinButton.firstChild.textContent = 'Creating your account… ';
+  showStatus('');
+  try {
+    const data = await api('/api/rewards/signup', { firstName: form.elements.firstName.value, lastName: form.elements.lastName.value, email: emailInput.value, marketing: form.elements.marketing.checked });
+    form.hidden = true;
+    document.querySelector('#success-message').textContent = `Welcome, ${data.firstName}! Your rewards account is ready, and ${data.email} is verified. Here’s to your next good cup.`;
+    const success = document.querySelector('#success');
+    success.hidden = false;
+    success.setAttribute('tabindex', '-1');
+    success.focus();
+  } catch (error) { showStatus(error.message); }
+  finally { busy = false; joinButton.disabled = false; joinButton.firstChild.textContent = 'Create my free account '; }
+});
+const dialog = document.querySelector('#policy-dialog');
+document.querySelectorAll('[data-policy]').forEach(button => button.addEventListener('click', () => {
+  const privacy = button.dataset.policy === 'privacy';
+  document.querySelector('#policy-title').textContent = privacy ? 'Your privacy' : 'Rewards membership';
+  document.querySelector('#policy-content').textContent = privacy ? 'We store your name, verified email address, Google account identifier, and email preferences to manage your rewards membership. We never receive your Google password. Optional offers are sent only if you choose to receive them. We do not sell your personal information.' : 'Daily Grind Rewards membership is free. Your account must use a verified Gmail or Google Workspace email address. Rewards and member offers are subject to availability at participating locations. Points are earned on qualifying purchases; individual offer conditions apply.';
+  dialog.showModal();
+}));
+document.querySelector('#close-dialog').addEventListener('click', () => dialog.close());
