+import test from 'node:test';
+import assert from 'node:assert/strict';
+import { createApp } from '../app.mjs';
+import { createStore } from '../account-store.mjs';
+const origin = 'https://dailygrind.example';
+async function fixture(overrides = {}) {
+  const store = createStore(':memory:');
+  let claims;
+  let time = 1_800_000_000_000;
+  const app = createApp({ clientId: 'client-id', origin, store, verifyToken: async credential => {
+    if (credential === 'invalid') throw Error('Invalid signature');
+    return claims;
+  }, now: () => time });
+  const config = await app(new Request(origin + '/api/auth/config'));
+  const { nonce } = await config.json();
+  const cookie = config.headers.getSetCookie()[0].split(';')[0];
+  claims = { iss: 'https://accounts.google.com', aud: 'client-id', exp: time / 1000 + 600, nonce, sub: 'google-123', email: 'alex@gmail.com', email_verified: true, ...overrides };
+  const post = (path, body, custom = {}) => app(new Request(origin + path, { method: 'POST', headers: { origin, cookie, 'Content-Type': 'application/json', ...custom }, body: JSON.stringify(body) }));
+  const verify = () => post('/api/verify-email', { credential: 'signed-token', email: claims.email });
+  const signup = (extra = {}) => post('/api/rewards/signup', { firstName: 'Alex', lastName: 'Morgan', email: claims.email, marketing: false, ...extra });
+  return { app, store, post, verify, signup, expire: () => { time += 601_000; } };
+}
+test('verified account persists, session is secure, signup proof is single use', async () => {
+  const f = await fixture();
+  try {
+    assert.equal((await f.signup()).status, 403);
+    assert.equal((await f.verify()).status, 200);
+    assert.equal((await f.verify()).status, 401);
+    const result = await f.signup();
+    assert.equal(result.status, 201);
+    assert.equal((await result.json()).email, 'alex@gmail.com');
+    assert.match(result.headers.getSetCookie()[0], /HttpOnly; SameSite=Strict; Max-Age=2592000; Secure/);
+    assert.equal((await f.signup()).status, 401);
+  } finally { f.store.close(); }
+});
+for (const [name, claims, expected] of [
+  ['wrong audience', { aud: 'another-client' }, 401],
+  ['wrong issuer', { iss: 'https://attacker.example' }, 401],
+  ['unverified email', { email_verified: false }, 401],
+  ['expired token', { exp: 1 }, 401],
+  ['missing expiry', { exp: undefined }, 401],
+  ['wrong nonce', { nonce: 'attacker' }, 401],
+  ['third party email', { email: 'alex@outlook.com' }, 422],
+  ['workspace email', { email: 'alex@company.example', hd: 'company.example' }, 200]
+]) test(name, async () => {
+  const f = await fixture(claims);
+  try { assert.equal((await f.verify()).status, expected); } finally { f.store.close(); }
+});
+test('rejects forged credentials, mismatched email, cross origin, changed email and expired session', async () => {
+  const f = await fixture();
+  try {
+    assert.equal((await f.post('/api/verify-email', { credential: 'invalid', email: 'alex@gmail.com' })).status, 401);
+    assert.equal((await f.post('/api/verify-email', { credential: 'signed', email: 'attacker@gmail.com' })).status, 422);
+    assert.equal((await f.post('/api/verify-email', { credential: 'signed', email: 'alex@gmail.com' }, { origin: 'https://attacker.example' })).status, 403);
+    await f.verify();
+    assert.equal((await f.signup({ email: 'changed@gmail.com' })).status, 422);
+    assert.equal((await f.signup({ firstName: ' ' })).status, 400);
+    f.expire();
+    assert.equal((await f.signup()).status, 401);
+  } finally { f.store.close(); }
+});
+test('missing configuration fails closed', async () => {
+  const app = createApp({ origin });
+  assert.equal((await app(new Request(origin + '/api/auth/config'))).status, 503);
+});
+test('store prevents duplicate accounts', () => {
+  const store = createStore(':memory:');
+  try {
+    const member = { subject: '123', email: 'alex@gmail.com', firstName: 'Alex', lastName: 'Morgan', marketing: false, sessionHash: 'hash', createdAt: Date.now() };
+    store.register(member);
+    assert.throws(() => store.register({ ...member, sessionHash: 'hash2' }), { code: 'ACCOUNT_EXISTS' });
+  } finally { store.close(); }
+});

