+import { readFile } from 'node:fs/promises';
+import assert from 'node:assert/strict';
+import { test } from 'node:test';
+import { Window } from 'happy-dom';
+
+const window = new Window();
+for (const key of ['window', 'document', 'HTMLElement', 'HTMLAnchorElement', 'customElements']) {
+  globalThis[key] = key === 'window' ? window : window[key];
+}
+const media = new window.EventTarget();
+media.matches = true;
+window.matchMedia = () => media;
+await import('../components/daily-grind.js');
+
+function navigation(markup = '') {
+  document.body.innerHTML = `<grind-navigation ${markup}><span slot="brand">Brand</span><a href="#coffee">Coffee</a></grind-navigation>`;
+  const host = document.querySelector('grind-navigation');
+  return { host, button: host.shadowRoot.querySelector('button'), links: host.shadowRoot.querySelector('#links') };
+}
+
+test('cards have separate shadow trees and project semantic content without copying it', () => {
+  document.body.innerHTML = '<coffee-card><h3 slot="heading">Coffee</h3><p>Description</p><a slot="action" href="/coffee">Details</a></coffee-card><coffee-card></coffee-card>';
+  const [first, second] = document.querySelectorAll('coffee-card');
+  assert.notEqual(first.shadowRoot.querySelector('article'), second.shadowRoot.querySelector('article'));
+  assert.equal(first.shadowRoot.querySelector('slot[name="heading"]').assignedElements()[0], first.querySelector('h3'));
+  assert.equal(first.shadowRoot.querySelector('slot[name="action"]').assignedElements()[0].getAttribute('href'), '/coffee');
+  assert.equal(first.hasAttribute('tabindex'), false);
+});
+
+test('compact navigation exposes matching disclosure state and closes on Escape with focus restored', () => {
+  media.matches = true;
+  const { host, button, links } = navigation();
+  assert.equal(button.hidden, false);
+  assert.equal(links.hidden, true);
+  assert.equal(button.getAttribute('aria-controls'), links.id);
+  assert.equal(button.getRootNode(), links.getRootNode());
+  button.click();
+  assert.equal(host.open, true);
+  assert.equal(button.getAttribute('aria-expanded'), 'true');
+  assert.equal(links.hidden, false);
+  host.querySelector('a').focus();
+  host.querySelector('a').dispatchEvent(new window.KeyboardEvent('keydown', { key: 'Escape', bubbles: true, composed: true }));
+  assert.equal(host.open, false);
+  assert.equal(links.hidden, true);
+  assert.equal(host.shadowRoot.activeElement, button);
+});
+
+test('markup, attribute changes, and properties stay synchronized without replacing controls', () => {
+  const { host, button, links } = navigation('open');
+  assert.equal(links.hidden, false);
+  host.removeAttribute('open');
+  assert.equal(button.getAttribute('aria-expanded'), 'false');
+  host.open = true;
+  assert.equal(host.hasAttribute('open'), true);
+  assert.equal(host.shadowRoot.querySelector('button'), button);
+});
+
+test('responsive changes keep navigation reachable and move focus out of hidden controls', () => {
+  const { host, button, links } = navigation();
+  media.matches = false;
+  media.dispatchEvent(new window.Event('change'));
+  assert.equal(button.hidden, true);
+  assert.equal(links.hidden, false);
+  host.querySelector('a').focus();
+  media.matches = true;
+  media.dispatchEvent(new window.Event('change'));
+  assert.equal(links.hidden, true);
+  assert.equal(host.shadowRoot.activeElement, button);
+  media.matches = false;
+  media.dispatchEvent(new window.Event('change'));
+  assert.equal(document.activeElement, host.querySelector('a'));
+});
+
+test('disconnect removes the media listener and reconnect retains a single working control', () => {
+  media.matches = true;
+  const { host, button, links } = navigation();
+  host.remove();
+  media.matches = false;
+  media.dispatchEvent(new window.Event('change'));
+  assert.equal(links.hidden, true);
+  document.body.append(host);
+  assert.equal(links.hidden, false);
+  media.matches = true;
+  media.dispatchEvent(new window.Event('change'));
+  button.click();
+  assert.equal(host.open, true);
+  assert.equal(links.hidden, false);
+  host.querySelector('a').addEventListener('click', event => event.preventDefault());
+  host.querySelector('a').click();
+  assert.equal(host.open, false);
+});
+
+test('homepage retains readable content and native route links before enhancement', async () => {
+  const fallback = new Window();
+  fallback.document.write(await readFile(new URL('../index.html', import.meta.url), 'utf8'));
+  const page = fallback.document;
+  assert.equal(page.querySelectorAll('coffee-card').length, 3);
+  assert.equal(page.querySelector('h1').textContent, 'Wake Up Your Senses');
+  for (const card of page.querySelectorAll('coffee-card')) {
+    assert.ok(card.querySelector('h3').textContent);
+    assert.ok(card.querySelector('a').getAttribute('href').startsWith('/menu/'));
+    assert.ok(card.querySelector('a').getAttribute('aria-label').includes(card.querySelector('h3').textContent));
+  }
+  assert.ok(page.querySelector('.skip-link').hash === '#main-content');
+  assert.equal(page.querySelectorAll('grind-navigation a').length, 5);
+  assert.equal(page.querySelector('coffee-hero a').getAttribute('href'), '/order-online');
+  fallback.happyDOM.abort();
+});

