+  <script>
+    (() => {
+      const menu = new Map([
+        ['maple-oat-latte', 'Maple Oat Latte'],
+        ['dark-roast-espresso', 'Dark Roast Espresso'],
+        ['cold-brew', 'Cold Brew'],
+      ]);
+      const order = new Map();
+      const items = document.getElementById('order-items');
+      const status = document.getElementById('order-status');
+      const clearButton = document.getElementById('clear-order');
+
+      function getOrder() {
+        const entries = Array.from(order, ([coffee, quantity]) => ({
+          coffee, name: menu.get(coffee), quantity,
+        }));
+        return {
+          items: entries,
+          totalDrinks: entries.reduce((total, item) => total + item.quantity, 0),
+        };
+      }
+
+      function renderOrder(message) {
+        const snapshot = getOrder();
+        items.replaceChildren();
+        for (const item of snapshot.items) {
+          const row = document.createElement('li');
+          const label = document.createElement('span');
+          label.textContent = `${item.quantity} × ${item.name}`;
+          const remove = document.createElement('button');
+          remove.type = 'button';
+          remove.className = 'remove-item';
+          remove.textContent = 'Remove';
+          remove.setAttribute('aria-label', `Remove ${item.name} from order`);
+          remove.addEventListener('click', () => {
+            removeCoffee({ coffee: item.coffee });
+            // The activated button was removed; keep keyboard focus in the order.
+            const next = items.querySelector('button');
+            (next || document.querySelector('.order-form button')).focus();
+          });
+          row.append(label, remove);
+          items.append(row);
+        }
+        document.getElementById('empty-order').hidden = snapshot.items.length > 0;
+        document.getElementById('order-total').textContent =
+          `Total: ${snapshot.totalDrinks} ${snapshot.totalDrinks === 1 ? 'drink' : 'drinks'}`;
+        clearButton.hidden = snapshot.items.length === 0;
+        status.textContent = message;
+        return snapshot;
+      }
+
+      function validateInput(input, allowedKeys) {
+        if (!input || typeof input !== 'object' || Array.isArray(input) ||
+            Object.keys(input).some(key => !allowedKeys.includes(key))) {
+          return { error: 'Pass an object containing only the documented fields.' };
+        }
+        if (!menu.has(input.coffee)) {
+          return { error: 'Choose a coffee from the seasonal menu.', availableCoffees: [...menu.keys()] };
+        }
+      }
+
+      function orderCoffee(input) {
+        const invalid = validateInput(input, ['coffee', 'quantity']);
+        if (invalid) return invalid;
+        const quantity = input.quantity === undefined ? 1 : input.quantity;
+        if (!Number.isInteger(quantity) || quantity < 1 || quantity > 10) {
+          return { error: 'Quantity must be a whole number from 1 to 10.' };
+        }
+        const total = (order.get(input.coffee) || 0) + quantity;
+        if (total > 10) {
+          return { error: 'Each coffee is limited to 10 drinks per order.', order: getOrder() };
+        }
+        order.set(input.coffee, total);
+        return renderOrder(`Added ${quantity} × ${menu.get(input.coffee)} to your order.`);
+      }
+
+      function removeCoffee(input) {
+        const invalid = validateInput(input, ['coffee']);
+        if (invalid) return invalid;
+        if (!order.delete(input.coffee)) {
+          return { error: 'That coffee is not in your order.', order: getOrder() };
+        }
+        return renderOrder(`Removed ${menu.get(input.coffee)} from your order.`);
+      }
+
+      function clearOrder() {
+        order.clear();
+        return renderOrder('Your order has been cleared.');
+      }
+
+      document.querySelectorAll('.order-form').forEach(form => {
+        form.addEventListener('submit', event => {
+          event.preventDefault();
+          const result = orderCoffee({
+            coffee: form.dataset.coffee,
+            quantity: form.elements.quantity.valueAsNumber,
+          });
+          if (result.error) status.textContent = result.error;
+        });
+        form.querySelector('button').disabled = false;
+      });
+      clearButton.addEventListener('click', () => {
+        clearOrder();
+        document.querySelector('.order-form button').focus();
+      });
+
+      // Native WebMCP discovery; regular ordering works without this preview API.
+      const modelContext = document.modelContext || navigator.modelContext;
+      if (!modelContext || typeof modelContext.registerTool !== 'function') return;
+      const coffeeSchema = {
+        type: 'string',
+        enum: [...menu.keys()],
+        description: 'The seasonal coffee to add or remove.',
+      };
+      const emptySchema = { type: 'object', properties: {}, additionalProperties: false };
+      const tools = [
+        {
+          name: 'order_coffee',
+          description: 'Add a seasonal coffee to the visible local order. Use when the user wants a coffee. The order lasts until reload and does not submit a purchase.',
+          inputSchema: {
+            type: 'object',
+            properties: {
+              coffee: coffeeSchema,
+              quantity: { type: 'integer', minimum: 1, maximum: 10, default: 1,
+                description: 'Drinks to add; each coffee has a cumulative order limit of ten.' },
+            },
+            required: ['coffee'],
+            additionalProperties: false,
+          },
+          execute: orderCoffee,
+          annotations: { readOnlyHint: false },
+        },
+        {
+          name: 'get_coffee_order',
+          description: 'Read the current coffee order and total drink count.',
+          inputSchema: emptySchema,
+          execute: getOrder,
+          annotations: { readOnlyHint: true },
+        },
+        {
+          name: 'remove_coffee_from_order',
+          description: 'Remove all drinks of a selected coffee from the visible local order.',
+          inputSchema: { type: 'object', properties: { coffee: coffeeSchema },
+            required: ['coffee'], additionalProperties: false },
+          execute: removeCoffee,
+          annotations: { readOnlyHint: false },
+        },
+        {
+          name: 'clear_coffee_order',
+          description: 'Empty the visible local coffee order.',
+          inputSchema: emptySchema,
+          execute: clearOrder,
+          annotations: { readOnlyHint: false },
+        },
