+import { useWebMCP } from 'use-webmcp-tool';
+import { errorResult, type Article } from '../lib/browser-tools';
+
+const emptySchema = { type: 'object', properties: {}, additionalProperties: false };
+
+// Preserve HTTP diagnostics: these demo endpoints intentionally include failures.
+export async function fetchArticleUtility(path: string, signal: AbortSignal) {
+  try {
+    const response = await fetch(`${import.meta.env.BASE_URL}api/${path}`, { signal });
+    const text = await response.text();
+    let data: unknown = text;
+    try { data = JSON.parse(text); } catch { /* Redirect destinations may return HTML. */ }
+    return {
+      ok: response.ok,
+      status: response.status,
+      redirected: response.redirected,
+      url: response.url,
+      ...(response.ok ? {} : { error: `Request failed (${response.status} ${response.statusText}).` }),
+      data,
+    };
+  } catch (error) {
+    if (signal.aborted) throw error;
+    return errorResult(error);
+  }
+}
+
+export default function ArticleTools({ articles, currentSlug }: { articles: Article[]; currentSlug?: string }) {
+  const currentArticle = articles.find(article => article.slug === currentSlug);
+
+  useWebMCP<{ slug: string }, unknown>({
+    name: 'get_article',
+    description: 'Get a story’s title, summary, and URL. Includes the article text when that story is currently open.',
+    inputSchema: {
+      type: 'object',
+      properties: { slug: { type: 'string', description: 'Article identifier returned by article search.' } },
+      required: ['slug'],
+      additionalProperties: false,
+    },
+    execute: (input) => {
+      if (typeof input?.slug !== 'string') return { error: 'Provide an article slug from search results.' };
+      const article = articles.find(article => article.slug === input.slug);
+      if (!article) return { error: 'Article not found. Use search_articles to find an article slug.' };
+      return {
+        ...article,
+        url: `${import.meta.env.BASE_URL}articles/${article.slug}`,
+        ...(article.slug === currentSlug ? { text: document.querySelector('[data-article-body]')?.textContent?.trim() ?? '' } : {}),
+      };
+    },
+    annotations: { readOnlyHint: true },
+  });
+
+  useWebMCP<{ id?: string }, unknown>({
+    name: 'get_article_popularity',
+    description: 'Fetch popularity and trending statistics for the open Super Bowl article.',
+    enabled: currentSlug === 'super-bowl-lx',
+    inputSchema: {
+      type: 'object',
+      properties: { id: { type: 'string', default: currentSlug, description: 'Article identifier used by the popularity service.' } },
+      additionalProperties: false,
+    },
+    execute: (input, { signal }) => {
+      const id = input?.id ?? currentArticle?.slug;
+      if (typeof id !== 'string' || !id.trim()) return { error: 'Provide a non-empty article identifier.' };
+      return fetchArticleUtility(`article-popularity?id=${encodeURIComponent(id)}`, signal);
+    },
+    annotations: { readOnlyHint: true },
+  });
+
+  useWebMCP({
+    name: 'get_tide_levels',
+    description: 'Fetch the coastal article’s tide-level utility and report any redirect or HTTP failure.',
+    enabled: currentSlug === 'coastal-pulse',
+    inputSchema: emptySchema,
+    execute: (_input, { signal }) => fetchArticleUtility('tide-levels', signal),
+    annotations: { readOnlyHint: true },
+  });
+
+  useWebMCP({
+    name: 'get_coffee_brew',
+    description: 'Fetch the coffee article’s brewing statistics and report service errors.',
+    enabled: currentSlug === 'coffee-alchemy',
+    inputSchema: emptySchema,
+    execute: (_input, { signal }) => fetchArticleUtility('coffee-brew', signal),
+    annotations: { readOnlyHint: true },
+  });
+
+  useWebMCP({
+    name: 'get_plant_stats',
+    description: 'Fetch the plant article’s flora and carbon-offset statistics and report HTTP failures.',
+    enabled: currentSlug === 'silent-architects',
+    inputSchema: emptySchema,
+    execute: (_input, { signal }) => fetchArticleUtility('plant-stats', signal),
+    annotations: { readOnlyHint: true },
+  });
+
+  return null;
+}
