diff --git a/src/lib/browser-tools.ts b/src/lib/browser-tools.ts
new file mode 100644
index 0000000..ffaadff
--- /dev/null
+++ b/src/lib/browser-tools.ts
@@ -0,0 +1,43 @@
+import type React from 'react';
+
+export interface Article {
+  slug: string;
+  title: string;
+  summary: string;
+  image?: string;
+}
+
+export async function fetchJSON<T>(path: string, options: RequestInit = {}): Promise<T> {
+  const response = await fetch(`${import.meta.env.BASE_URL}${path}`, options);
+  if (!response.ok) throw new Error(`Request failed (${response.status} ${response.statusText}).`);
+  return response.json();
+}
+
+// Read form values from the DOM: agent-filled controls need not fire React onChange.
+export function respondToAgent(event: React.FormEvent<HTMLFormElement>, result: Promise<unknown>) {
+  const submit = event.nativeEvent as SubmitEvent & {
+    agentInvoked?: boolean;
+    respondWith?: (result: Promise<string>) => void;
+  };
+  if (submit.agentInvoked && submit.respondWith) {
+    submit.respondWith(result.then(value => JSON.stringify(value)));
+  }
+}
+
+export function errorResult(error: unknown) {
+  return { error: error instanceof Error ? error.message : String(error) };
+}
+
+export const readingListChanged = 'devtools-times:reading-list-changed';
+
+export async function updateReadingList(slug: string, saved: boolean) {
+  const current = await fetchJSON<{ readingList: string[] }>('api/reading-list.json');
+  const result = current.readingList.includes(slug) === saved ? current :
+    await fetchJSON<{ readingList: string[] }>('api/reading-list.json', {
+      method: 'POST',
+      headers: { 'Content-Type': 'application/json' },
+      body: JSON.stringify({ slug }),
+    });
+  window.dispatchEvent(new CustomEvent(readingListChanged, { detail: result.readingList }));
+  return result;
+}
