@@ -0,0 +1,47 @@
+export interface Article {
+  slug: string;
+  title: string;
+  summary: string;
+  image?: string;
+}
+
+const base = import.meta.env.BASE_URL;
+
+async function request<T>(path: string, init?: RequestInit): Promise<T> {
+  const response = await fetch(`${base}${path}`, init);
+  if (!response.ok) throw new Error(`Request failed (${response.status})`);
+  return response.json();
+}
+
+export function getArticles(signal?: AbortSignal): Promise<Article[]> {
+  return request('api/articles.json', { signal });
+}
+
+export function searchArticles(articles: Article[], query: string): Article[] {
+  const term = query.trim().toLowerCase();
+  return term ? articles.filter(article =>
+    article.title.toLowerCase().includes(term) || article.summary.toLowerCase().includes(term)
+  ) : [];
+}
+
+export function articleUrl(slug: string): string {
+  return `${base}articles/${encodeURIComponent(slug)}`;
+}
+
+export async function getReadingList(signal?: AbortSignal): Promise<string[]> {
+  const data = await request<{ readingList: string[] }>('api/reading-list.json', { signal });
+  return data.readingList;
+}
+
+export async function updateReadingList(slug: string, action: 'add' | 'remove' | 'toggle'): Promise<string[]> {
+  const current = await getReadingList();
+  const included = current.includes(slug);
+  if ((action === 'add' && included) || (action === 'remove' && !included)) return current;
+  const data = await request<{ readingList: string[] }>('api/reading-list.json', {
+    method: 'POST',
+    headers: { 'Content-Type': 'application/json' },
+    body: JSON.stringify({ slug }),
+  });
+  window.dispatchEvent(new CustomEvent('reading-list-changed', { detail: data.readingList }));
+  return data.readingList;
+}
