new file mode 100644
index 0000000..1d555f9
--- /dev/null
+++ b/src/utils/browser-tools.ts
@@ -0,0 +1,55 @@
+export interface BrowserTool {
+  name: string;
+  description: string;
+  inputSchema: Record<string, unknown>;
+  annotations?: { readOnlyHint: boolean };
+  execute: (input: Record<string, unknown>, context?: { signal?: AbortSignal }) => Promise<unknown>;
+}
+
+interface ModelContext {
+  registerTool(tool: BrowserTool, options?: { signal: AbortSignal }): void | Promise<void>;
+  unregisterTool?(name: string): void;
+}
+
+export interface AgentSubmitEvent extends SubmitEvent {
+  agentInvoked?: boolean;
+  respondWith?: (result: Promise<unknown>) => void;
+}
+
+// Support the original preview API as well as its current document-based home.
+export function registerBrowserTools(tools: BrowserTool[]): () => void {
+  const context = (document as Document & { modelContext?: ModelContext }).modelContext
+    ?? (navigator as Navigator & { modelContext?: ModelContext }).modelContext;
+  if (!context?.registerTool) return () => {};
+  const controller = new AbortController();
+  let disposed = false;
+  const registered = new Set<string>();
+  for (const tool of tools) {
+    try {
+      const registration = context.registerTool(tool, { signal: controller.signal });
+      if (registration) {
+        registration.then(() => {
+          if (!disposed) registered.add(tool.name);
+        }).catch(error => {
+          if (!disposed) console.warn(`Could not register browser tool ${tool.name}`, error);
+        });
+      } else {
+        registered.add(tool.name);
+      }
+    } catch (error) {
+      console.warn(`Could not register browser tool ${tool.name}`, error);
+    }
+  }
+  return () => {
+    if (disposed) return;
+    disposed = true;
+    // Earlier previews require explicit unregistration.
+    for (const name of registered) context.unregisterTool?.(name);
+    controller.abort();
+  };
+}
+
+export function respondToAgent(event: Event, result: Promise<unknown>): void {
+  const submission = event as AgentSubmitEvent;
+  if (submission.agentInvoked && submission.respondWith) submission.respondWith(result);
+}
