@@ -0,0 +1,51 @@
+import { articleUrl, getArticles, getReadingList } from './article-client';
+import { registerBrowserTools } from './browser-tools';
+
+export function registerSiteTools() {
+  return registerBrowserTools([
+    {
+      name: 'list_articles',
+      description: 'List DevTools Times articles with slugs, titles, summaries and URLs.',
+      inputSchema: { type: 'object', properties: {}, additionalProperties: false },
+      annotations: { readOnlyHint: true },
+      execute: async (_input, context) => (await getArticles(context?.signal)).map(article => ({
+        ...article, url: articleUrl(article.slug),
+      })),
+    },
+    {
+      name: 'read_article',
+      description: 'Read a DevTools Times article by its slug without navigating away. Returns title, summary, URL and article text.',
+      inputSchema: {
+        type: 'object', properties: { slug: { type: 'string', description: 'Article slug from list_articles or search_articles.' } },
+        required: ['slug'], additionalProperties: false,
+      },
+      annotations: { readOnlyHint: true },
+      execute: async ({ slug }, context) => {
+        if (typeof slug !== 'string' || !slug.trim()) throw new Error('An article slug is required.');
+        const article = (await getArticles(context?.signal)).find(item => item.slug === slug);
+        if (!article) throw new Error('Article not found.');
+        const url = articleUrl(slug);
+        const response = await fetch(url, { signal: context?.signal });
+        if (!response.ok) throw new Error(`Article request failed (${response.status})`);
+        // Parsing fetched HTML does not execute article scripts or load its assets.
+        const page = new DOMParser().parseFromString(await response.text(), 'text/html');
+        const body = page.querySelector('[data-article-body]');
+        if (!body) throw new Error('Article text is unavailable.');
+        body.querySelectorAll('script, style').forEach(node => node.remove());
+        return { ...article, url, text: body.textContent?.trim() ?? '' };
+      },
+    },
+    {
+      name: 'get_reading_list',
+      description: 'Retrieve the current session reading list with saved article details and URLs.',
+      inputSchema: { type: 'object', properties: {}, additionalProperties: false },
+      annotations: { readOnlyHint: true },
+      execute: async (_input, context) => {
+        const [articles, slugs] = await Promise.all([getArticles(context?.signal), getReadingList(context?.signal)]);
+        return { readingList: slugs, articles: articles.filter(article => slugs.includes(article.slug)).map(article => ({
+          ...article, url: articleUrl(article.slug),
+        })) };
+      },
+    },
+  ]);
+}
