+import assert from 'node:assert/strict';
+import { test } from 'node:test';
+import { readFile } from 'node:fs/promises';
+import { stripTypeScriptTypes } from 'node:module';
+import { registerBrowserTools, respondToAgent } from '../src/utils/browser-tools.ts';
+
+const tool = { name: 'example', description: 'Example', inputSchema: {}, execute: async () => 'done' };
+const setContext = (documentContext, navigatorContext) => {
+  globalThis.document = { modelContext: documentContext };
+  Object.defineProperty(globalThis, 'navigator', { value: { modelContext: navigatorContext }, configurable: true });
+};
+
+test('unsupported browsers are a no-op; legacy registrations clean up synchronously', () => {
+  setContext();
+  registerBrowserTools([tool])();
+  const tools = new Map();
+  setContext(undefined, {
+    registerTool: value => { tools.set(value.name, value); },
+    unregisterTool: name => { tools.delete(name); },
+  });
+  const cleanup = registerBrowserTools([tool]);
+  assert.equal(tools.get('example'), tool);
+  cleanup();
+  cleanup();
+  assert.equal(tools.size, 0);
+});
+
+test('modern registrations abort on cleanup, including pending registration', async () => {
+  let signal;
+  let resolve;
+  setContext({ registerTool: (_tool, options) => {
+    signal = options.signal;
+    return new Promise(done => { resolve = done; });
+  } });
+  const cleanup = registerBrowserTools([tool]);
+  assert.equal(signal.aborted, false);
+  cleanup();
+  assert.equal(signal.aborted, true);
+  resolve();
+  await Promise.resolve();
+});
+
+test('agent submissions receive the result promise; normal submissions do not', async () => {
+  const result = Promise.resolve({ articles: [] });
+  let response;
+  const respondWith = promise => { response = promise; };
+  respondToAgent({ agentInvoked: false, respondWith }, result);
+  assert.equal(response, undefined);
+  respondToAgent({ agentInvoked: true, respondWith }, result);
+  assert.equal(response, result);
+  assert.deepEqual(await response, { articles: [] });
+});
+
+// Substitute the Vite build constant only; run the actual client utility code.
+const source = await readFile(new URL('../src/utils/article-client.ts', import.meta.url), 'utf8');
+const compiled = stripTypeScriptTypes(source.replace('import.meta.env.BASE_URL', JSON.stringify('/devtools-times/')));
+const { searchArticles, getArticles, updateReadingList } = await import(`data:text/javascript;base64,${Buffer.from(compiled).toString('base64')}`);
+
+test('search matches title and summary, trims input, and handles empty queries', () => {
+  const articles = [{ slug: 'coffee', title: 'Coffee', summary: 'Roasted beans' }];
+  assert.deepEqual(searchArticles(articles, ' BEANS '), articles);
+  assert.deepEqual(searchArticles(articles, 'coffee'), articles);
+  assert.deepEqual(searchArticles(articles, '   '), []);
+});
+
+test('reading list add/remove is idempotent and notifies other UI components', async () => {
+  let saved = [];
+  const requests = [];
+  const notifications = [];
+  globalThis.window = { dispatchEvent: event => notifications.push(event.detail) };
+  globalThis.fetch = async (url, options = {}) => {
+    requests.push({ url, options });
+    if (options.method === 'POST') {
+      const { slug } = JSON.parse(options.body);
+      saved = saved.includes(slug) ? saved.filter(item => item !== slug) : [...saved, slug];
+    }
+    return Response.json({ readingList: saved });
+  };
+  assert.deepEqual(await updateReadingList('coffee', 'add'), ['coffee']);
+  assert.deepEqual(await updateReadingList('coffee', 'add'), ['coffee']);
+  assert.deepEqual(await updateReadingList('coffee', 'remove'), []);
+  assert.deepEqual(await updateReadingList('coffee', 'remove'), []);
+  assert.equal(requests.filter(request => request.options.method === 'POST').length, 2);
+  assert.ok(requests.every(request => request.url === '/devtools-times/api/reading-list.json'));
+  assert.deepEqual(notifications, [['coffee'], []]);
+});
+
+test('failed API requests reject instead of reporting success', async () => {
+  globalThis.fetch = async () => new Response('Unavailable', { status: 503 });
+  await assert.rejects(getArticles(), /503/);
+  await assert.rejects(updateReadingList('coffee', 'add'), /503/);
+});
